package main

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net"
	"net/http"
	"syscall"
	"time"

	"github.com/gablooge/lawang/internal/appversion"
	"github.com/gablooge/lawang/internal/config"
)

const shutdownGrace = 15 * time.Second

// serve runs the HTTP role until ctx is cancelled. For now it carries only /healthz. When the
// webhook edge lands (B07 wires it, because it needs a hub), this mux goes away: ingress.New
// builds the routing table, takes /healthz as an ingress.Route and returns the handler to serve,
// so that no route is behind a mux that answers redirects.
func serve(ctx context.Context, cfg config.Config, logger *slog.Logger) error {
	var lc net.ListenConfig
	ln, err := lc.Listen(ctx, "tcp", cfg.ListenAddr)
	if err != nil {
		return listenError(ctx, err)
	}
	return serveOn(ctx, ln, logger)
}

// listenError turns a listen failure into an error that is safe to log.
//
// The error from net quotes the address it was given ("listen tcp 10.0.0.5:8080: bind: ...",
// "lookup some-host: no such host"), and config.Load only vouches for the port half of that
// address. A value pasted into the wrong variable can still sit in the host half. So the original
// error is never returned, wrapped or formatted: only the parts of it that cannot carry the address
// are kept, which is enough to tell "in use" from "not permitted" from "does not resolve".
func listenError(ctx context.Context, err error) error {
	const prefix = "LAWANG_LISTEN_ADDR: cannot listen"

	// An errno's text comes from the operating system's table ("address already in use",
	// "permission denied", "can't assign requested address"), never from the input. Wrapping it
	// alone keeps errors.Is(err, syscall.EADDRINUSE) working for callers.
	var errno syscall.Errno
	if errors.As(err, &errno) {
		return fmt.Errorf("%s: %w", prefix, errno)
	}
	// Cancelled or out of time before the socket was bound, for example during a slow lookup.
	if ctxErr := ctx.Err(); ctxErr != nil {
		return fmt.Errorf("%s: %w", prefix, ctxErr)
	}
	var dnsErr *net.DNSError
	if errors.As(err, &dnsErr) {
		// DNSError.Error() quotes the name, so only its classification is used.
		switch {
		case dnsErr.IsNotFound:
			return errors.New(prefix + ": the host name does not resolve")
		case dnsErr.IsTimeout:
			return errors.New(prefix + ": the host name lookup timed out")
		default:
			return errors.New(prefix + ": the host name lookup failed")
		}
	}
	return errors.New(prefix + ": the address is not valid for a TCP listener")
}

// The timeouts every request on this server is held to. They are what stops a slow-loris client
// from holding a connection, and they matter most for the webhook edge, which faces the public
// internet: readHeaderTimeout cuts a client that dribbles headers and readTimeout one that
// dribbles a body, whatever the path.
//
// readTimeout covers the headers and the body together, so it is the larger of the two.
// writeTimeout is above the accept path's own bound (ingress.DefaultAcceptTimeout), so a slow
// accept is answered by the handler with a status a provider understands rather than cut off
// mid-response.
const (
	readHeaderTimeout = 5 * time.Second
	readTimeout       = 15 * time.Second
	writeTimeout      = 30 * time.Second
	idleTimeout       = 60 * time.Second
)

// newServer builds the HTTP server every role shares, so the timeouts are written once.
func newServer(handler http.Handler) *http.Server {
	return &http.Server{
		Handler:           handler,
		ReadHeaderTimeout: readHeaderTimeout,
		ReadTimeout:       readTimeout,
		WriteTimeout:      writeTimeout,
		IdleTimeout:       idleTimeout,
	}
}

func serveOn(ctx context.Context, ln net.Listener, logger *slog.Logger) error {
	srv := newServer(newMux())

	errc := make(chan error, 1)
	go func() { errc <- srv.Serve(ln) }()
	logger.Info("listening", "addr", ln.Addr().String(), "version", appversion.String())

	select {
	case err := <-errc:
		return err
	case <-ctx.Done():
	}

	logger.Info("shutting down")
	shutdownCtx, cancel := context.WithTimeout(context.Background(), shutdownGrace)
	defer cancel()
	if err := srv.Shutdown(shutdownCtx); err != nil {
		// The grace ran out with connections still open. Drop them so nothing outlives serveOn.
		_ = srv.Close()
		return err
	}
	if err := <-errc; !errors.Is(err, http.ErrServerClosed) {
		return err
	}
	return nil
}

func newMux() *http.ServeMux {
	mux := http.NewServeMux()
	// Liveness only: the process is up. Readiness (/readyz, which checks Postgres) is separate.
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "text/plain; charset=utf-8")
		_, _ = w.Write([]byte("ok\n"))
	})
	return mux
}

package main

import (
	"bufio"
	"errors"
	"io"
	"net"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	"github.com/gablooge/lawang/internal/ingress"
)

// TestTheServerTimeoutsAreSetAndOrdered. The webhook edge mounts on this server, so the numbers
// here are the ones that decide how long a stranger can hold a connection open. A zero is no
// timeout at all, which is the defect this guards against.
func TestTheServerTimeoutsAreSetAndOrdered(t *testing.T) {
	t.Parallel()

	srv := newServer(newMux())
	switch {
	case srv.ReadHeaderTimeout <= 0:
		t.Fatal("ReadHeaderTimeout is not set: a client could dribble headers forever")
	case srv.ReadTimeout <= 0:
		t.Fatal("ReadTimeout is not set: a client could dribble a body forever")
	case srv.WriteTimeout <= 0:
		t.Fatal("WriteTimeout is not set")
	case srv.IdleTimeout <= 0:
		t.Fatal("IdleTimeout is not set")
	}
	if srv.ReadTimeout < srv.ReadHeaderTimeout {
		t.Fatalf("ReadTimeout (%v) covers the headers too, so it cannot be under ReadHeaderTimeout (%v)",
			srv.ReadTimeout, srv.ReadHeaderTimeout)
	}
	// A request that is cut off while the accept path is still deciding would be answered by
	// nothing at all, and the provider would see a reset instead of a status.
	if srv.WriteTimeout <= ingress.DefaultAcceptTimeout {
		t.Fatalf("WriteTimeout (%v) must be above the accept timeout (%v)",
			srv.WriteTimeout, ingress.DefaultAcceptTimeout)
	}
}

// TestASlowClientIsCutOff proves the mechanism rather than the production durations, which would
// make the test wait five seconds. The server is the one newServer builds, with the two read
// timeouts shortened; a client that stalls in the headers and a client that stalls in the body
// must both be dropped, on a path shaped like the webhook edge.
func TestASlowClientIsCutOff(t *testing.T) {
	t.Parallel()

	cases := map[string]string{
		// Headers that never end.
		"slow headers": "POST /ingress/fake HTTP/1.1\r\nHost: x\r\nX-A: 1\r\n",
		// Headers complete, then a body that stops short of its Content-Length.
		"slow body": "POST /ingress/fake HTTP/1.1\r\nHost: x\r\nContent-Length: 4096\r\n\r\nab",
	}
	for name, request := range cases {
		t.Run(name, func(t *testing.T) {
			t.Parallel()

			ln, err := net.Listen("tcp", "127.0.0.1:0")
			if err != nil {
				t.Fatalf("listen: %v", err)
			}
			srv := newServer(newMux())
			srv.ReadHeaderTimeout = 100 * time.Millisecond
			srv.ReadTimeout = 200 * time.Millisecond
			go func() { _ = srv.Serve(ln) }()
			t.Cleanup(func() { _ = srv.Close() })

			conn, err := net.DialTimeout("tcp", ln.Addr().String(), 5*time.Second)
			if err != nil {
				t.Fatalf("dial: %v", err)
			}
			t.Cleanup(func() { _ = conn.Close() })
			// The deadline is the test's own failure mode: without it a server that never cuts
			// the client off would hang the run instead of failing it.
			if err := conn.SetDeadline(time.Now().Add(10 * time.Second)); err != nil {
				t.Fatalf("SetDeadline: %v", err)
			}
			if _, err := io.WriteString(conn, request); err != nil {
				t.Fatalf("write: %v", err)
			}

			// The server either closes the connection or answers 408. Either ends the stall.
			resp, err := http.ReadResponse(bufio.NewReader(conn), nil)
			if err == nil {
				defer func() { _ = resp.Body.Close() }()
				if resp.StatusCode/100 == 2 {
					t.Fatalf("a stalled client got %d", resp.StatusCode)
				}
				return
			}
			// Any other error is the server having closed the connection, which is the point.
			// The one failure is this test's own deadline running out: that would mean the
			// stall worked.
			var netErr net.Error
			if errors.As(err, &netErr) && netErr.Timeout() {
				t.Fatalf("the connection was still open after the read timeout: %v", err)
			}
		})
	}
}

// TestHealthzStillAnswers keeps the refactor of serveOn honest: the mux newServer is handed is the
// one that serves.
func TestHealthzStillAnswers(t *testing.T) {
	t.Parallel()

	rec := httptest.NewRecorder()
	newMux().ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/healthz", nil))
	if rec.Code != http.StatusOK || rec.Body.String() != "ok\n" {
		t.Fatalf("status = %d, body = %q", rec.Code, rec.Body.String())
	}
}

// Package appversion reports what build is running.
package appversion

import "runtime/debug"

// Version is set at release time with -ldflags "-X .../internal/appversion.Version=v0.1.0".
var Version = ""

// revisionLen is how much of the VCS revision a development build shows.
const revisionLen = 12

// String returns the release version, or the VCS revision for a development build.
func String() string {
	return describe(Version, buildSettings())
}

// buildSettings returns what the toolchain recorded about this build, or nil when it recorded
// nothing.
func buildSettings() []debug.BuildSetting {
	info, ok := debug.ReadBuildInfo()
	if !ok {
		return nil
	}
	return info.Settings
}

// describe is String without its inputs, so that every case can be tested: a binary under test
// carries no VCS settings and would only ever show "dev".
//
//   - a release version wins over everything else
//   - otherwise "dev-" and the first 12 characters of the revision, with "-dirty" when the tree had
//     uncommitted changes
//   - "dev" alone when there is no revision to show
func describe(version string, settings []debug.BuildSetting) string {
	if version != "" {
		return version
	}
	rev, dirty := "", false
	for _, s := range settings {
		switch s.Key {
		case "vcs.revision":
			rev = s.Value
		case "vcs.modified":
			dirty = s.Value == "true"
		}
	}
	if rev == "" {
		return "dev"
	}
	if len(rev) > revisionLen {
		rev = rev[:revisionLen]
	}
	if dirty {
		rev += "-dirty"
	}
	return "dev-" + rev
}

package appversion

import (
	"runtime/debug"
	"testing"
)

func TestDescribe(t *testing.T) {
	const rev = "0123456789abcdef0123456789abcdef01234567"
	vcs := func(revision, modified string) []debug.BuildSetting {
		return []debug.BuildSetting{
			{Key: "-buildmode", Value: "exe"},
			{Key: "vcs", Value: "git"},
			{Key: "vcs.revision", Value: revision},
			{Key: "vcs.time", Value: "2026-09-19T00:00:00Z"},
			{Key: "vcs.modified", Value: modified},
		}
	}

	tests := []struct {
		name     string
		version  string
		settings []debug.BuildSetting
		want     string
	}{
		{"a release version wins over the revision", "v0.1.0", vcs(rev, "false"), "v0.1.0"},
		{"a release version wins over a dirty tree", "v0.1.0", vcs(rev, "true"), "v0.1.0"},
		{"a release version needs no build info", "v0.1.0", nil, "v0.1.0"},
		{"a clean revision is cut to 12 characters", "", vcs(rev, "false"), "dev-0123456789ab"},
		{"a modified tree says so", "", vcs(rev, "true"), "dev-0123456789ab-dirty"},
		{"only the word true means modified", "", vcs(rev, "TRUE"), "dev-0123456789ab"},
		{"exactly 12 characters are kept whole", "", vcs("0123456789ab", "false"), "dev-0123456789ab"},
		{"13 characters lose one", "", vcs("0123456789abc", "false"), "dev-0123456789ab"},
		{"a short revision is kept whole", "", vcs("abc123", "false"), "dev-abc123"},
		{"a short modified revision", "", vcs("abc123", "true"), "dev-abc123-dirty"},
		{"no build info at all", "", nil, "dev"},
		{"an empty revision", "", vcs("", "false"), "dev"},
		{"modified without a revision is still just dev", "", vcs("", "true"), "dev"},
		{"settings with no vcs keys, as under go test", "", []debug.BuildSetting{{Key: "-buildmode", Value: "exe"}}, "dev"},
		{
			"modified listed before the revision", "",
			[]debug.BuildSetting{{Key: "vcs.modified", Value: "true"}, {Key: "vcs.revision", Value: rev}},
			"dev-0123456789ab-dirty",
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := describe(tt.version, tt.settings); got != tt.want {
				t.Errorf("describe(%q, ...) = %q, want %q", tt.version, got, tt.want)
			}
		})
	}
}

func TestStringUsesTheLinkerVersion(t *testing.T) {
	// String is describe over the real inputs. The one thing describe cannot show is that the
	// variable the linker sets is the one String reads.
	old := Version
	t.Cleanup(func() { Version = old })

	Version = "v9.9.9-test"
	if got := String(); got != "v9.9.9-test" {
		t.Errorf("String() = %q with Version set, want the version", got)
	}

	Version = ""
	if got, want := String(), describe("", buildSettings()); got != want {
		t.Errorf("String() = %q, want %q from the build settings", got, want)
	}
	if got := String(); got == "" {
		t.Error("String() is empty for a development build")
	}
}

// Package config reads Lawang's configuration from the environment.
//
// Defaults fail closed: an unset LAWANG_ENV means production, and production refuses to start
// on anything it would otherwise have to guess.
package config

import (
	"errors"
	"fmt"
	"log/slog"
	"net"
	"net/url"
	"path"
	"slices"
	"strconv"
	"strings"
)

// Env is the deployment environment.
type Env string

// Production is the default. Development has to be asked for by name.
const (
	Production  Env = "production"
	Development Env = "development"
)

// devDatabaseURL is where the compose stack of backlog item B27 will put Postgres. Until that item
// lands nothing in this repository starts such a database. It is only ever used when development
// is explicit.
const devDatabaseURL = "postgres://lawang:lawang@localhost:5432/lawang?sslmode=disable" //nolint:gosec // local development only, never reachable in production

// Config is the full process configuration.
type Config struct {
	Env         Env
	DatabaseURL string
	ListenAddr  string
	LogLevel    slog.Level
	LogFormat   string // "json" or "text"

	// PublicBaseURL is the scheme, host and any stripped path prefix that a provider reaches
	// /ingress/{provider} at from the public internet, with no trailing slash, or the empty
	// string when the deployment did not configure one. It is what the webhook edge builds the
	// URL a signature covers out of (ingress.Options.PublicBaseURL, architecture 4); backlog
	// item B07 wires it, because the edge is not mounted until a hub exists.
	PublicBaseURL string
}

// defaultListenAddr is where serve listens when LAWANG_LISTEN_ADDR is unset.
const defaultListenAddr = ":8080"

// The values of the enumerated variables. Load validates against these slices and Variables
// publishes the same slices, so a value added here is accepted and documented in one step.
var (
	envValues       = []string{string(Production), string(Development)}
	logLevelValues  = []string{"debug", "info", "warn", "error"}
	logFormatValues = []string{"json", "text"}
)

// Variable documents one environment variable that Load reads.
type Variable struct {
	Name    string
	Doc     string
	Values  []string // every value Load accepts, or nil when the variable is not an enumeration
	Default string   // what Load uses when the variable is unset, in words an operator can act on
}

// Variables lists every variable Load reads, in the order an operator should think about them.
// The command's usage text is built from it, so the binary documents its own configuration, and
// tests hold it to what Load really reads, to the defaults Load really applies, and to the values
// Load really accepts.
//
// The development database URL is described, not printed: it is a URL with a password in it, and
// usage text ends up in logs and tickets. Its host, port and database name are not secret.
func Variables() []Variable {
	return []Variable{
		{
			Name:    "LAWANG_ENV",
			Doc:     "The deployment environment. Anything unrecognized is refused, never treated as development.",
			Values:  slices.Clone(envValues),
			Default: string(Production),
		},
		{
			Name: "LAWANG_DATABASE_URL",
			Doc: "Postgres URL (postgres:// or postgresql://) of the non-superuser application role. " +
				"Pool and connection settings travel in the URL: pool_max_conns (the default is " +
				"max(4, NumCPU), shared by every in-flight webhook and worker row), pool_min_conns, " +
				"pool_max_conn_lifetime and connect_timeout (seconds).",
			Default: "none, it is required in production. Development connects to localhost:5432, database lawang.",
		},
		{
			Name:    "LAWANG_LISTEN_ADDR",
			Doc:     "host:port or :port for serve. The port is a number from 0 to 65535, not a service name.",
			Default: defaultListenAddr,
		},
		{
			Name: "LAWANG_PUBLIC_BASE_URL",
			Doc: "The absolute URL providers reach this deployment at, scheme and host and any " +
				"path prefix a reverse proxy strips before forwarding (https://lawang.example.com). " +
				"No query, no fragment, no credentials, no trailing slash. The host is named in " +
				"ASCII, an internationalized name in its punycode (xn--) form, which is the " +
				"spelling a provider's dashboard holds. It is configuration and " +
				"never a header on purpose: a signature scheme that covers the request URL " +
				"(HubSpot v3) is checked against this, and Host, X-Forwarded-Host and " +
				"X-Forwarded-Proto are all chosen by whoever sent the request, so building the " +
				"signed URL from them would let a sender pick part of what it signed.",
			Default: "none. The edge still serves, and a provider whose signature covers the URL " +
				"refuses every delivery rather than verify against a URL Lawang guessed.",
		},
		{
			Name:    "LAWANG_LOG_LEVEL",
			Doc:     "The lowest level that is logged. Case does not matter.",
			Values:  slices.Clone(logLevelValues),
			Default: strings.ToLower(slog.LevelInfo.String()),
		},
		{
			Name:    "LAWANG_LOG_FORMAT",
			Doc:     "The encoding of the log on stderr. Case does not matter.",
			Values:  slices.Clone(logFormatValues),
			Default: "json in production, text in development",
		},
	}
}

// notOneOf is the refusal for an enumerated variable. It lists what is accepted and, like every
// error here, never what was received.
func notOneOf(name string, values []string) error {
	return fmt.Errorf("%s: must be one of: %s", name, strings.Join(values, ", "))
}

const redacted = "[redacted]"

// LogValue keeps the database URL, which carries a password, out of structured logs.
func (c Config) LogValue() slog.Value {
	return slog.GroupValue(
		slog.String("env", string(c.Env)),
		slog.String("database_url", redacted),
		slog.String("listen_addr", c.ListenAddr),
		slog.String("log_level", c.LogLevel.String()),
		slog.String("log_format", c.LogFormat),
		// Not redacted: it is a public hostname, it is what a provider posts to, and an operator
		// debugging a signature failure needs to see the spelling the process actually holds.
		slog.String("public_base_url", c.PublicBaseURL),
	)
}

// String covers %v, %+v and %s, so printing a Config cannot leak the database URL either.
func (c Config) String() string {
	return fmt.Sprintf("{Env:%s DatabaseURL:%s ListenAddr:%s LogLevel:%s LogFormat:%s PublicBaseURL:%s}",
		c.Env, redacted, c.ListenAddr, c.LogLevel, c.LogFormat, c.PublicBaseURL)
}

// GoString covers %#v.
func (c Config) GoString() string { return "config.Config" + c.String() }

// Load builds a Config from getenv (os.Getenv in production, a map lookup in tests). It reports
// every problem at once so a misconfigured deploy is fixed in one pass.
//
// No error echoes a received value, for any variable. Load cannot know which variable a secret was
// pasted into: a manifest with two entries swapped puts the database URL, password included, into
// LAWANG_ENV, and the refusal is printed to the container log.
func Load(getenv func(string) string) (Config, error) {
	var errs []error

	cfg := Config{
		Env:        Production,
		ListenAddr: defaultListenAddr,
		LogLevel:   slog.LevelInfo,
	}

	if v := getenv("LAWANG_ENV"); v != "" {
		if slices.Contains(envValues, v) {
			cfg.Env = Env(v)
		} else {
			// An unrecognized value stays production. A typo must never relax anything.
			errs = append(errs, notOneOf("LAWANG_ENV", envValues))
		}
	}

	cfg.DatabaseURL = getenv("LAWANG_DATABASE_URL")
	switch {
	case cfg.DatabaseURL != "":
		if err := checkDatabaseURL(cfg.DatabaseURL); err != nil {
			errs = append(errs, fmt.Errorf("LAWANG_DATABASE_URL: %w", err))
		}
	case cfg.Env == Development:
		cfg.DatabaseURL = devDatabaseURL
	default:
		errs = append(errs, errors.New("LAWANG_DATABASE_URL: required in production"))
	}

	if v := getenv("LAWANG_LISTEN_ADDR"); v != "" {
		if err := checkListenAddr(v); err != nil {
			errs = append(errs, fmt.Errorf("LAWANG_LISTEN_ADDR: %w", err))
		} else {
			cfg.ListenAddr = v
		}
	}

	if v := getenv("LAWANG_PUBLIC_BASE_URL"); v != "" {
		base, err := NormalizePublicBaseURL(v)
		if err != nil {
			errs = append(errs, fmt.Errorf("LAWANG_PUBLIC_BASE_URL: %w", err))
		} else {
			cfg.PublicBaseURL = base
		}
	}

	if v := strings.ToLower(getenv("LAWANG_LOG_LEVEL")); v != "" {
		// Only the documented names. slog on its own would also take offsets such as "info+2",
		// which the usage text does not list. Its parse error quotes its input, so it is
		// deliberately not wrapped.
		if !slices.Contains(logLevelValues, v) || cfg.LogLevel.UnmarshalText([]byte(v)) != nil {
			errs = append(errs, notOneOf("LAWANG_LOG_LEVEL", logLevelValues))
		}
	}

	cfg.LogFormat = "json"
	if cfg.Env == Development {
		cfg.LogFormat = "text"
	}
	if v := strings.ToLower(getenv("LAWANG_LOG_FORMAT")); v != "" {
		if slices.Contains(logFormatValues, v) {
			cfg.LogFormat = v
		} else {
			errs = append(errs, notOneOf("LAWANG_LOG_FORMAT", logFormatValues))
		}
	}

	if len(errs) > 0 {
		return Config{}, errors.Join(errs...)
	}
	return cfg, nil
}

// checkListenAddr requires host:port or :port with a numeric port. It is checked in Load because
// the listener's own error quotes the address it was given, and that error ends up in the log.
//
// net.SplitHostPort only checks the shape, so on its own it lets through anything with exactly one
// colon: a user:password pair, or a database URL with no password and no port. Either would then
// be looked up as a service name and quoted by the lookup error. Requiring a numeric port closes
// that, and deliberately stops accepting service names such as ":http", which nothing here needs.
//
// The host half is not checked: "localhost" is legitimate, and so is any name the deployment
// resolves. serve keeps the listener's error text out of the log for that half.
func checkListenAddr(raw string) error {
	_, port, err := net.SplitHostPort(raw)
	if err != nil {
		// Not wrapped: the net.AddrError quotes its input.
		return errors.New("must be host:port or :port")
	}
	// ParseUint takes ASCII digits only (no sign, no spaces), and 16 bits is exactly 0 to 65535.
	// Its error quotes the input too, so it is not wrapped either.
	if _, err := strconv.ParseUint(port, 10, 16); err != nil {
		return errors.New("port must be a number from 0 to 65535 (service names are not accepted)")
	}
	return nil
}

// NormalizePublicBaseURL checks LAWANG_PUBLIC_BASE_URL and returns it in the one spelling the
// webhook edge concatenates a request path onto: scheme, host, an optional path prefix, and no
// trailing slash. The empty string is not passed here; an unset variable is handled by the caller.
//
// It is exported and not private because internal/ingress checks the same value again in
// ingress.New, by calling this function rather than by carrying a copy of the rules. The string
// ends up inside a signature base string, so the two must agree to the byte: a base URL that Load
// accepted and the edge spelled differently would make every signature fail with nothing to see.
//
// # Normalizing the result again must return it unchanged
//
// The same value goes through this function more than once in a running deployment: Load
// normalizes the variable, ingress.New normalizes what Load stored, and a Registrar (B13, B18)
// registers what Load stored with the provider. If a second pass moved the string, the URL the
// provider signs and the URL the edge verifies against would be different strings and every
// delivery would be a 401 with nothing to see. So every rule here is idempotent in itself: what
// it rewrites, it rewrites to a fixed point (trailing slashes are removed, all of them, so the
// result has none), and everything else it either leaves alone or refuses. A refusal is a fixed
// point too, since a refused value never becomes anyone's output.
// TestNormalizingTheResultAgainChangesNothing asserts that as a property over a corpus rather
// than over the table rows somebody happened to write.
//
// # What it deliberately does not touch
//
// The host is passed through exactly as written: its case is kept, and so is a default port
// (https://EXAMPLE.com:443 stays as it is). That looks like an omission and is not. This string
// has to match, byte for byte, the URL the operator gave the provider, which they copied from or
// pasted into the provider's own dashboard. Lowercasing a host or dropping :443 would create that
// mismatch rather than remove it, and the mismatch is invisible until every delivery answers 401.
// The scheme is the exception: url.Parse lowercases it before this function sees it, and no
// dashboard spells it differently.
//
// No error echoes the value. Load cannot know which variable a secret was pasted into, and a
// manifest with two entries swapped puts the database URL here.
func NormalizePublicBaseURL(raw string) (string, error) {
	u, err := url.Parse(raw)
	if err != nil {
		// Not wrapped: the url.Error quotes the whole input.
		return "", errors.New("not a valid URL")
	}
	if u.Scheme != "http" && u.Scheme != "https" {
		return "", errors.New("scheme must be http or https, and the URL must be absolute")
	}
	// u.Host carries the port, so an empty u.Host is not the only way to arrive naming no
	// machine: "http://:8080" parses with a host of ":8080", which is not empty, and the edge
	// would then sign "http://:8080/ingress/hubspot" while the provider signed the real public
	// URL. That is the silent 401 this whole function exists to prevent, and it is an easy thing
	// to write, because LAWANG_LISTEN_ADDR two entries above it in the usage text takes exactly
	// that spelling. u.Hostname is the half that names a machine, and no rule here can see the
	// problem otherwise: "http://:8080" parses, normalizes to itself, and is a fixed point.
	if u.Hostname() == "" {
		return "", errors.New("missing host")
	}
	// The same silent mismatch from the other side: "http://x:" keeps a colon no dashboard holds,
	// and it too is a fixed point of every other rule here.
	if strings.HasSuffix(u.Host, ":") {
		return "", errors.New("the host must not end in a colon with no port")
	}
	// The host is ASCII, and an internationalized name belongs here in its punycode (xn--) form.
	// Go does not convert one to the other, so "https://café.example" would go into a signature
	// base string as those bytes, while DNS, the provider's dashboard and therefore the URL the
	// provider signed all carry "xn--caf-dma.example": the same 401 with nothing to see. The path
	// prefix is refused outside ASCII a few lines below, for a related reason, and refusing both
	// keeps one answer for one question.
	//
	// 0x80 is the definition of ASCII and not a boundary any test can pin: every byte of a
	// non-ASCII character in valid UTF-8 starts a sequence with a lead byte of 0xC2 or more, so
	// no input this function can be given tells 0x80 from 0xC0 or from 0xC2. Nothing here is
	// weaker for it, and nobody should "tighten" it believing a test would notice.
	for _, b := range []byte(u.Host) {
		if b >= 0x80 {
			return "", errors.New("the host must be written in ASCII, and an internationalized name in its punycode (xn--) form")
		}
	}
	// url.Parse decodes percent-escapes in the host, so "http://%25" parses with a host of "%",
	// which is not a host any second pass can read back (FuzzNormalizePublicBaseURL found this
	// one). The only escape a host legitimately carries is an IPv6 zone id, which a public base
	// URL has no use for, so the whole shape is refused rather than re-encoded.
	if strings.Contains(u.Host, "%") {
		return "", errors.New("the host must be written plainly, with no percent-escape")
	}
	if u.User != nil {
		return "", errors.New("must not carry credentials")
	}
	if u.RawQuery != "" || u.ForceQuery || u.Fragment != "" {
		return "", errors.New("must not carry a query or a fragment")
	}
	// The path prefix must already be its own escaped form. The edge appends the request's own
	// escaped path to this string, so a prefix that is not escaped the same way would make the
	// signed URL depend on which spelling happened to be registered.
	//
	// Comparing EscapedPath with Path is what catches every escape, not only the ones Go
	// re-spells: %2F and %2e differ once url.Parse has canonicalized them, but %20, %23 and %3F
	// re-encode to themselves, so a RawPath check lets them through and the value comes back with
	// a literal space, hash or question mark in it. Those are exactly the shapes a second pass
	// then refuses. A prefix outside ASCII is refused here too, for the same reason: the edge
	// would be concatenating an unescaped prefix onto an escaped path.
	if u.EscapedPath() != u.Path {
		return "", errors.New("the path prefix must be written plainly, with no percent-escape and no character that needs one")
	}
	// Every trailing slash, not one: TrimSuffix would leave "//" as "/", which path.Clean calls
	// clean and which is the trailing slash this function promises to remove. What is left must
	// already be clean, so a doubled or relative segment inside the prefix is refused rather than
	// quietly rewritten into a URL the operator never registered.
	p := strings.TrimRight(u.Path, "/")
	if p != "" && path.Clean(p) != p {
		return "", errors.New("the path prefix must be a clean absolute path, for example /lawang")
	}
	// Written out rather than handed to url.URL.String, which escapes a path byte for byte by its
	// own rules and not by the ones url.Parse accepted: String turns the "!" in "/!a", which
	// parses and comes back unchanged here, into "%21", and the next pass then refuses the
	// escape. (FuzzNormalizePublicBaseURL found that within a second.) Concatenating the three
	// parts that were just checked keeps the operator's own spelling, which is the whole point,
	// and url.Parse reads the result back as the same scheme, host and path: the host cannot hold
	// a slash, a question mark or a hash, since url.Parse would have split the URL there, and a
	// path that is not absolute and clean was refused above.
	return u.Scheme + "://" + u.Host + p, nil
}

// checkDatabaseURL rejects anything that is not a Postgres URL. The error never echoes the value,
// because a database URL carries a password. In particular the url.Parse error is never wrapped or
// returned: it quotes the whole input.
func checkDatabaseURL(raw string) error {
	u, err := url.Parse(raw)
	if err != nil {
		return errors.New("not a valid URL")
	}
	if u.Scheme != "postgres" && u.Scheme != "postgresql" {
		return errors.New("scheme must be postgres or postgresql")
	}
	if u.Host == "" {
		return errors.New("missing host")
	}
	return nil
}

package config

import (
	"bytes"
	"fmt"
	"log/slog"
	"maps"
	"net/url"
	"strings"
	"testing"
)

func env(m map[string]string) func(string) string {
	return func(k string) string { return m[k] }
}

func TestLoadUnsetEnvironmentIsProduction(t *testing.T) {
	cfg, err := Load(env(map[string]string{
		"LAWANG_DATABASE_URL": "postgres://app@db:5432/lawang",
	}))
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if cfg.Env != Production {
		t.Errorf("Env = %q, want %q", cfg.Env, Production)
	}
	if cfg.LogFormat != "json" {
		t.Errorf("LogFormat = %q, want json", cfg.LogFormat)
	}
	if cfg.ListenAddr != ":8080" {
		t.Errorf("ListenAddr = %q, want :8080", cfg.ListenAddr)
	}
}

func TestLoadProductionRequiresDatabaseURL(t *testing.T) {
	for _, e := range []string{"", "production"} {
		_, err := Load(env(map[string]string{"LAWANG_ENV": e}))
		if err == nil || !strings.Contains(err.Error(), "LAWANG_DATABASE_URL") {
			t.Errorf("LAWANG_ENV=%q: err = %v, want a LAWANG_DATABASE_URL error", e, err)
		}
	}
}

func TestLoadDevelopmentDefaults(t *testing.T) {
	cfg, err := Load(env(map[string]string{"LAWANG_ENV": "development"}))
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if cfg.Env != Development {
		t.Errorf("Env = %q, want %q", cfg.Env, Development)
	}
	if cfg.DatabaseURL != devDatabaseURL {
		t.Errorf("DatabaseURL = %q, want the development default", cfg.DatabaseURL)
	}
	if cfg.LogFormat != "text" {
		t.Errorf("LogFormat = %q, want text", cfg.LogFormat)
	}
}

func TestLoadUnknownEnvironmentIsAnError(t *testing.T) {
	// "dev" is the likely typo. It must not be read as development, and must not pass silently.
	_, err := Load(env(map[string]string{
		"LAWANG_ENV":          "dev",
		"LAWANG_DATABASE_URL": "postgres://app@db:5432/lawang",
	}))
	if err == nil || !strings.Contains(err.Error(), "LAWANG_ENV") {
		t.Fatalf("err = %v, want a LAWANG_ENV error", err)
	}
}

// secretFragments are the distinctive pieces of the URLs below. None may appear in any error.
var secretFragments = []string{"hunter2", "leakuser", "leakhost", "leakdb"}

func assertNoSecret(t *testing.T, what, got string) {
	t.Helper()
	for _, frag := range secretFragments {
		if strings.Contains(got, frag) {
			t.Errorf("%s leaks %q: %s", what, frag, got)
		}
	}
}

func TestLoadDatabaseURLErrorsNeverEchoTheValue(t *testing.T) {
	// One case per return in checkDatabaseURL. The unparseable one matters most: url.Parse quotes
	// its whole input in the error, and a password with a bare "%" is the ordinary way a Postgres
	// URL fails to parse.
	for name, raw := range map[string]string{
		"unparseable":  "postgres://leakuser:hunter2%zz@leakhost:5432/leakdb",
		"wrong scheme": "mysql://leakuser:hunter2@leakhost:3306/leakdb",
		"missing host": "postgres://leakuser:hunter2@/leakdb",
	} {
		t.Run(name, func(t *testing.T) {
			_, err := Load(env(map[string]string{"LAWANG_DATABASE_URL": raw}))
			if err == nil {
				t.Fatal("Load accepted a bad database URL")
			}
			if !strings.Contains(err.Error(), "LAWANG_DATABASE_URL") {
				t.Errorf("error does not name the variable: %v", err)
			}
			assertNoSecret(t, "error", err.Error())
		})
	}
}

func TestLoadErrorsNeverEchoAnyValue(t *testing.T) {
	// A manifest with two entries swapped puts the database URL into some other variable. Load
	// cannot know which, so no variable's error may repeat what it received.
	const secret = "postgres://leakuser:hunter2@leakhost:5432/leakdb"
	validated := []string{
		"LAWANG_ENV",
		"LAWANG_LISTEN_ADDR",
		"LAWANG_LOG_LEVEL",
		"LAWANG_LOG_FORMAT",
		"LAWANG_PUBLIC_BASE_URL",
	}

	for _, name := range validated {
		t.Run(name, func(t *testing.T) {
			_, err := Load(env(map[string]string{
				"LAWANG_DATABASE_URL": "postgres://app@db:5432/lawang",
				name:                  secret,
			}))
			if err == nil {
				t.Fatalf("Load accepted a database URL as %s", name)
			}
			if !strings.Contains(err.Error(), name) {
				t.Errorf("error does not name %s: %v", name, err)
			}
			assertNoSecret(t, "error", err.Error())
		})
	}

	t.Run("all at once", func(t *testing.T) {
		all := map[string]string{"LAWANG_DATABASE_URL": "mysql://leakuser:hunter2@leakhost:3306/leakdb"}
		for _, name := range validated {
			all[name] = secret
		}
		_, err := Load(env(all))
		if err == nil {
			t.Fatal("Load accepted an invalid environment")
		}
		assertNoSecret(t, "joined error", err.Error())
	})
}

func TestLoadRefusesABadListenAddress(t *testing.T) {
	for _, addr := range []string{
		// The wrong shape: no colon, or too many.
		"8080", "localhost", "http://localhost:8080",
		// Exactly one colon, so net.SplitHostPort alone is satisfied. Each of these used to reach
		// the listener, whose error then quoted it: a user:password pair in the wrong variable,
		// and a database URL with no password and no port.
		"leakuser:hunter2",
		"postgres://leakuser@leakhost/leakdb",
		// A port that is not a number from 0 to 65535. Service names are refused on purpose.
		"leakhost:99999", "leakhost:65536", ":http", "localhost:http", "leakhost:",
		":-1", ":+80", ": 80", ":80 ", ":0x50", ":8_0",
	} {
		_, err := Load(env(map[string]string{
			"LAWANG_DATABASE_URL": "postgres://app@db:5432/lawang",
			"LAWANG_LISTEN_ADDR":  addr,
		}))
		if err == nil || !strings.Contains(err.Error(), "LAWANG_LISTEN_ADDR") {
			t.Errorf("LAWANG_LISTEN_ADDR=%q: err = %v, want a LAWANG_LISTEN_ADDR error", addr, err)
			continue
		}
		assertNoSecret(t, "error", err.Error())
		// The port half is just as likely to be the pasted secret as the host half.
		if _, port, ok := strings.Cut(addr, ":"); ok && len(port) > 1 && strings.Contains(err.Error(), port) {
			t.Errorf("LAWANG_LISTEN_ADDR=%q: error repeats the port %q: %v", addr, port, err)
		}
	}
}

func TestLoadAcceptsEveryOrdinaryListenAddress(t *testing.T) {
	// The numeric port rule must not cost any address a deployment would really use.
	for _, addr := range []string{
		":8080", ":0", ":65535", "[::1]:8080", "localhost:8080", "0.0.0.0:0", "[::1%lo0]:0",
		"127.0.0.1:9000", "[::]:8080",
	} {
		cfg, err := Load(env(map[string]string{
			"LAWANG_DATABASE_URL": "postgres://app@db:5432/lawang",
			"LAWANG_LISTEN_ADDR":  addr,
		}))
		if err != nil {
			t.Errorf("LAWANG_LISTEN_ADDR=%q: %v", addr, err)
			continue
		}
		if cfg.ListenAddr != addr {
			t.Errorf("LAWANG_LISTEN_ADDR=%q: ListenAddr = %q", addr, cfg.ListenAddr)
		}
	}
}

func TestConfigNeverPrintsTheDatabaseURL(t *testing.T) {
	cfg, err := Load(env(map[string]string{
		"LAWANG_DATABASE_URL": "postgres://leakuser:hunter2@leakhost:5432/leakdb",
	}))
	if err != nil {
		t.Fatalf("Load: %v", err)
	}

	for _, verb := range []string{"%v", "%+v", "%s", "%#v"} {
		assertNoSecret(t, verb, fmt.Sprintf(verb, cfg))
		assertNoSecret(t, verb+" of a pointer", fmt.Sprintf(verb, &cfg))
	}

	var buf bytes.Buffer
	logger := slog.New(slog.NewJSONHandler(&buf, nil))
	logger.Info("config", "cfg", cfg, "ptr", &cfg)
	assertNoSecret(t, "slog output", buf.String())
	if !strings.Contains(buf.String(), `"listen_addr":":8080"`) {
		t.Errorf("slog output lost the fields that are safe to print: %s", buf.String())
	}
}

func TestLoadReportsEveryProblemAtOnce(t *testing.T) {
	_, err := Load(env(map[string]string{
		"LAWANG_LOG_LEVEL":  "loud",
		"LAWANG_LOG_FORMAT": "xml",
	}))
	if err == nil {
		t.Fatal("Load accepted an invalid environment")
	}
	for _, want := range []string{"LAWANG_DATABASE_URL", "LAWANG_LOG_LEVEL", "LAWANG_LOG_FORMAT"} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("error does not mention %s: %v", want, err)
		}
	}
}

func TestLoadOverrides(t *testing.T) {
	cfg, err := Load(env(map[string]string{
		"LAWANG_DATABASE_URL": "postgresql://app@db/lawang",
		"LAWANG_LISTEN_ADDR":  "127.0.0.1:9000",
		"LAWANG_LOG_LEVEL":    "debug",
		"LAWANG_LOG_FORMAT":   "TEXT",
	}))
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if cfg.ListenAddr != "127.0.0.1:9000" {
		t.Errorf("ListenAddr = %q", cfg.ListenAddr)
	}
	if cfg.LogLevel != slog.LevelDebug {
		t.Errorf("LogLevel = %v, want debug", cfg.LogLevel)
	}
	if cfg.LogFormat != "text" {
		t.Errorf("LogFormat = %q, want text", cfg.LogFormat)
	}
}

// readBy records every name Load asks getenv for, under base.
func readBy(base map[string]string) map[string]bool {
	read := make(map[string]bool)
	_, _ = Load(func(k string) string {
		read[k] = true
		return base[k]
	})
	return read
}

// validSamples are values Load accepts for the variables that are not enumerations. An enumerated
// variable needs none: its states come from Variable.Values.
var validSamples = map[string][]string{
	"LAWANG_DATABASE_URL":    {"postgres://app@db/lawang", "postgresql://app@db:5432/lawang"},
	"LAWANG_LISTEN_ADDR":     {":9000", "127.0.0.1:9000"},
	"LAWANG_PUBLIC_BASE_URL": {"https://lawang.example.test", "https://lawang.example.test/prefix"},
}

// recordingBases is the full cross product of the states of every documented variable: unset,
// each accepted value (or each valid sample), and one refused value. It is a product and not a
// hand-picked list because a hand-picked list is exactly where a read behind two conditions hid
// (development together with an explicit database URL).
func recordingBases(t *testing.T) []map[string]string {
	t.Helper()
	bases := []map[string]string{{}}
	for _, v := range Variables() {
		accepted := v.Values
		if accepted == nil {
			accepted = validSamples[v.Name]
		}
		if len(accepted) == 0 {
			t.Fatalf("%s has neither Values nor an entry in validSamples, so no base would ever set it to something Load accepts", v.Name)
		}
		// A state only drives the path it is named for if Load really takes it that way. A sample
		// that has rotted into a refused value would silently leave the accepted path undriven.
		for _, state := range accepted {
			if _, err := Load(env(map[string]string{"LAWANG_DATABASE_URL": "postgres://app@db/lawang", v.Name: state})); err != nil {
				t.Fatalf("%s: Load refuses the state %q that stands for an accepted value: %v", v.Name, state, err)
			}
		}
		if _, err := Load(env(map[string]string{"LAWANG_DATABASE_URL": "postgres://app@db/lawang", v.Name: "x"})); err == nil {
			t.Fatalf("%s: Load accepts \"x\", which stands for a refused value", v.Name)
		}
		states := append([]string{"", "x"}, accepted...)

		var next []map[string]string
		for _, base := range bases {
			for _, state := range states {
				m := maps.Clone(base)
				if state != "" {
					m[v.Name] = state
				}
				next = append(next, m)
			}
		}
		bases = next
	}
	return bases
}

func TestVariablesAreExactlyWhatLoadReads(t *testing.T) {
	// Variables is the operator's documentation, by way of the usage text. A variable Load reads
	// and Variables omits is undocumented; one Variables lists and Load ignores is a promise the
	// binary does not keep.
	//
	// Recording can only see the paths it drives. It drives every combination of {unset, each
	// accepted value, one refused value} over the documented variables, so a read behind any
	// conjunction of those states is seen. What it cannot see: a read behind a condition that is
	// none of those states, such as one particular host in the database URL, or a second variable
	// that is itself undocumented and so is never set here. A new kind of branch in Load needs a
	// new state in recordingBases.
	bases := recordingBases(t)
	if len(bases) < 1000 {
		t.Fatalf("only %d bases, the cross product has collapsed", len(bases))
	}
	read := make(map[string]bool)
	for _, base := range bases {
		for k := range readBy(base) {
			read[k] = true
		}
	}

	documented := make(map[string]bool)
	for _, v := range Variables() {
		if documented[v.Name] {
			t.Errorf("%s is listed twice", v.Name)
		}
		documented[v.Name] = true
		if !read[v.Name] {
			t.Errorf("%s is documented, but Load never reads it", v.Name)
		}
		if v.Doc == "" || v.Default == "" {
			t.Errorf("%s has no description or no default: %+v", v.Name, v)
		}
	}
	for k := range read {
		if !documented[k] {
			t.Errorf("Load reads %s, but Variables does not document it", k)
		}
	}
}

func TestVariablesStateTheDefaultsLoadApplies(t *testing.T) {
	// The documented default is compared with what Load does with the variable unset, so the two
	// cannot drift. The database URL is the only thing set, because production has no default for it.
	doc := make(map[string]string)
	for _, v := range Variables() {
		doc[v.Name] = v.Default
	}

	prod, err := Load(env(map[string]string{"LAWANG_DATABASE_URL": "postgres://app@db/lawang"}))
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	dev, err := Load(env(map[string]string{"LAWANG_ENV": "development"}))
	if err != nil {
		t.Fatalf("Load: %v", err)
	}

	if got := doc["LAWANG_ENV"]; got != string(prod.Env) {
		t.Errorf("LAWANG_ENV: documented default %q, Load applies %q", got, prod.Env)
	}
	if got := doc["LAWANG_LISTEN_ADDR"]; got != prod.ListenAddr {
		t.Errorf("LAWANG_LISTEN_ADDR: documented default %q, Load applies %q", got, prod.ListenAddr)
	}
	if got, want := doc["LAWANG_LOG_LEVEL"], strings.ToLower(prod.LogLevel.String()); got != want {
		t.Errorf("LAWANG_LOG_LEVEL: documented default %q, Load applies %q", got, want)
	}
	wantFormat := prod.LogFormat + " in production, " + dev.LogFormat + " in development"
	if got := doc["LAWANG_LOG_FORMAT"]; got != wantFormat {
		t.Errorf("LAWANG_LOG_FORMAT: documented default %q, Load applies %q", got, wantFormat)
	}
	if got := doc["LAWANG_DATABASE_URL"]; !strings.Contains(got, "required in production") {
		t.Errorf("LAWANG_DATABASE_URL: the documented default %q does not say production has none", got)
	}
	// The public base URL has no default on purpose, and the documented default says what an
	// unset one costs rather than naming a value. Guessing one would put a URL Lawang invented
	// into a signature base string, which is a check that proves nothing.
	if prod.PublicBaseURL != "" || dev.PublicBaseURL != "" {
		t.Errorf("LAWANG_PUBLIC_BASE_URL unset gave %q in production and %q in development, want empty in both",
			prod.PublicBaseURL, dev.PublicBaseURL)
	}
	if got := doc["LAWANG_PUBLIC_BASE_URL"]; !strings.Contains(got, "none") || !strings.Contains(got, "refuses") {
		t.Errorf("LAWANG_PUBLIC_BASE_URL: the documented default %q does not say there is none and what that costs", got)
	}

	// The development fallback is a URL with a password in it. It is described, never printed.
	// The description names where the process will connect, which is not secret, and nothing else.
	u, err := url.Parse(dev.DatabaseURL)
	if err != nil {
		t.Fatal("the development database URL does not parse")
	}
	password, _ := u.User.Password()
	if password == "" {
		t.Fatal("the development database URL has no password, so the check below proves nothing")
	}
	where := u.Host + ", database " + strings.TrimPrefix(u.Path, "/")
	if got := doc["LAWANG_DATABASE_URL"]; !strings.Contains(got, where) {
		t.Errorf("LAWANG_DATABASE_URL: the documented default %q does not say development connects to %q", got, where)
	}
	for _, v := range Variables() {
		if strings.Contains(v.Doc+v.Default, dev.DatabaseURL) || strings.Contains(v.Doc+v.Default, "@") ||
			strings.Contains(v.Doc+v.Default, u.User.String()) {
			t.Errorf("%s: the documentation prints a URL with credentials: %+v", v.Name, v)
		}
	}
}

func TestVariablesStateTheValuesLoadAccepts(t *testing.T) {
	// Values is the very slice Load validates against, so the two agree by construction. This
	// holds the construction in place from the outside: every listed value is accepted, the
	// refusal lists exactly the listed values, and a handful of plausible unlisted ones are
	// refused. The last part is a sample: no test can try every string, so a value that Load
	// accepts by some route other than the slice, and that nobody thought to list below, would
	// still get through.
	const dbURL = "postgres://app@db/lawang"
	unlisted := []string{"x", "dev", "staging", "test", "prod", "trace", "fatal", "info+2", "logfmt", "console", "pretty"}

	enumerated := make(map[string]bool)
	for _, v := range Variables() {
		if v.Values == nil {
			continue
		}
		enumerated[v.Name] = true
		for _, value := range v.Values {
			if _, err := Load(env(map[string]string{"LAWANG_DATABASE_URL": dbURL, v.Name: value})); err != nil {
				t.Errorf("%s=%s is documented as accepted, but Load refuses it: %v", v.Name, value, err)
			}
		}
		for _, value := range unlisted {
			_, err := Load(env(map[string]string{"LAWANG_DATABASE_URL": dbURL, v.Name: value}))
			if err == nil {
				t.Errorf("%s=%s is not documented, but Load accepts it", v.Name, value)
				continue
			}
			if want := v.Name + ": must be one of: " + strings.Join(v.Values, ", "); err.Error() != want {
				t.Errorf("%s=%s: the refusal is %q, want %q", v.Name, value, err, want)
			}
		}
	}
	for _, name := range []string{"LAWANG_ENV", "LAWANG_LOG_LEVEL", "LAWANG_LOG_FORMAT"} {
		if !enumerated[name] {
			t.Errorf("%s is an enumeration in Load, but Variables does not list its values", name)
		}
	}

	// Variables hands out copies: a caller that edits one must not change what Load accepts.
	// The edit is undone at the end, so that a failure here does not spill into the other tests.
	values := Variables()[0].Values
	original := values[0]
	values[0] = "edited"
	defer func() { values[0] = original }()
	if _, err := Load(env(map[string]string{"LAWANG_DATABASE_URL": dbURL, "LAWANG_ENV": "edited"})); err == nil {
		t.Error("editing the result of Variables changed what Load accepts")
	}
}

// TestThePublicBaseURLIsNormalizedAndNeverGuessed covers the variable a signature base string is
// built from. The edge concatenates a request path onto this string and a provider's HMAC is
// taken over the result, so an accepted value must come back in exactly one spelling, and
// anything the edge could not concatenate onto safely must be refused at start rather than turned
// into a signature that never verifies.
// acceptedBaseURLs is what NormalizePublicBaseURL takes, and the one spelling it returns.
//
// It is a package-level table because two tests read it: the one below, which checks each answer,
// and TestNormalizingTheResultAgainChangesNothing, which checks the property that would have
// caught the shapes nobody thought to put in a table.
var acceptedBaseURLs = map[string]string{
	"https://lawang.example.test":         "https://lawang.example.test",
	"https://lawang.example.test/":        "https://lawang.example.test",
	"https://lawang.example.test:8443":    "https://lawang.example.test:8443",
	"http://localhost:8080":               "http://localhost:8080",
	"https://lawang.example.test/lawang":  "https://lawang.example.test/lawang",
	"https://lawang.example.test/lawang/": "https://lawang.example.test/lawang",
	"https://lawang.example.test/a/b":     "https://lawang.example.test/a/b",
	"HTTPS://lawang.example.test":         "https://lawang.example.test",
	// A default port and the host's case are deliberately kept: this string has to match the URL
	// the operator registered with the provider, which they copied from its dashboard.
	"https://EXAMPLE.com:443": "https://EXAMPLE.com:443",
	"https://[::1]:8443/":     "https://[::1]:8443",
	// An internationalized host, in the one spelling a provider's dashboard holds. The kanji
	// spelling of the same name is refused, so that an operator hears about it at start rather
	// than as a 401 per delivery.
	"https://xn--80ak6aa92e.com":       "https://xn--80ak6aa92e.com",
	"https://xn--caf-dma.example/a/b/": "https://xn--caf-dma.example/a/b",
	// Trailing slashes, however many. TrimSuffix would leave "https://x//" as "https://x/", which
	// keeps the trailing slash the function promises to remove, and the second pass then removes
	// it: Load and ingress.New would hold two different strings for one variable and every
	// signature over the URL would fail.
	"https://lawang.example.test//":         "https://lawang.example.test",
	"https://lawang.example.test///":        "https://lawang.example.test",
	"https://lawang.example.test/lawang//":  "https://lawang.example.test/lawang",
	"https://lawang.example.test:8443//":    "https://lawang.example.test:8443",
	"HTTPS://lawang.example.test/lawang///": "https://lawang.example.test/lawang",
	// A sub-delimiter url.Parse leaves alone in a path. Rebuilding the answer with
	// url.URL.String escaped it to %21, which the next pass refused: the fuzzer found this in
	// under a second, and testdata/fuzz keeps it as a seed.
	"https://lawang.example.test/a!b": "https://lawang.example.test/a!b",
}

// refusedBaseURLs is what NormalizePublicBaseURL refuses, by the name of the shape.
var refusedBaseURLs = map[string]string{
	"no scheme":                "lawang.example.test",
	"a scheme-relative URL":    "//lawang.example.test",
	"a path only":              "/ingress",
	"an unsupported scheme":    "ftp://lawang.example.test",
	"a postgres URL":           "postgres://app:hunter2@db:5432/lawang",
	"no host":                  "https://",
	"credentials":              "https://user:pass@lawang.example.test",
	"a query":                  "https://lawang.example.test?x=1",
	"a bare question mark":     "https://lawang.example.test?",
	"a fragment":               "https://lawang.example.test#f",
	"a percent-encoded prefix": "https://lawang.example.test/a%2Fb",
	"a relative segment":       "https://lawang.example.test/a/../b",
	"a doubled slash":          "https://lawang.example.test/a//b",
	"a leading doubled slash":  "https://lawang.example.test//a",
	"a control character":      "https://lawang.example.test/\x00",
	"not a URL at all":         "://",
	"just a word":              "x",
	// The escapes Go re-spells to themselves, which a RawPath check does not see. Each one used
	// to be accepted and decoded, and the decoded value was then refused by the next pass: an
	// escaped space came back with a literal space in it, an escaped hash became a fragment and
	// an escaped question mark became a query.
	"an escaped space":         "https://lawang.example.test/a%20b",
	"an escaped hash":          "https://lawang.example.test/a%23b",
	"an escaped question mark": "https://lawang.example.test/a%3Fb",
	"an escaped dot":           "https://lawang.example.test/%2e",
	"a literal space":          "https://lawang.example.test/a b",
	"a prefix outside ASCII":   "https://lawang.example.test/café",
	"a single dot segment":     "https://lawang.example.test/.",
	"a parent segment":         "https://lawang.example.test/..",
	// url.Parse decodes escapes in the host, so this one parses with a host of "%" and the
	// answer was a string no second pass could read back. The fuzzer found it, and
	// testdata/fuzz keeps it as a seed.
	"a percent-escape in the host": "http://%25",
	"an IPv6 zone id":              "http://[fe80::1%25eth0]:8080",
	// A URL that names a port and no machine. u.Host is ":8080", which is not empty, so the
	// check that catches "https://" does not catch this one, and neither can the idempotence
	// property: it parses, and it is its own normal form. LAWANG_LISTEN_ADDR takes exactly this
	// spelling, which is how it gets written here.
	"a port and no host":    "http://:8080",
	"a colon and no host":   "http://:",
	"an empty port":         "http://lawang.example.test:",
	"a host outside ASCII":  "https://café.example",
	"an IDN host in kanji":  "http://例え.jp",
	"an IDN host with path": "https://café.example/lawang",
}

func TestThePublicBaseURLIsNormalizedAndNeverGuessed(t *testing.T) {
	t.Parallel()

	accepted := acceptedBaseURLs
	for raw, want := range accepted {
		t.Run("accepts "+raw, func(t *testing.T) {
			t.Parallel()
			got, err := NormalizePublicBaseURL(raw)
			if err != nil {
				t.Fatalf("NormalizePublicBaseURL(%q): %v", raw, err)
			}
			if got != want {
				t.Fatalf("NormalizePublicBaseURL(%q) = %q, want %q", raw, got, want)
			}
		})
	}

	refused := refusedBaseURLs
	for name, raw := range refused {
		t.Run("refuses "+name, func(t *testing.T) {
			t.Parallel()
			got, err := NormalizePublicBaseURL(raw)
			if err == nil {
				t.Fatalf("NormalizePublicBaseURL(%q) = %q, want a refusal", raw, got)
			}
			if got != "" {
				t.Fatalf("a refusal returned %q as well", got)
			}
			// No refusal echoes the value: Load cannot know which variable a secret was pasted
			// into, and the refusal is printed to a container log.
			if strings.Contains(err.Error(), raw) {
				t.Fatalf("the refusal quotes what it was given: %v", err)
			}
		})
	}
}

// baseURLCorpus is what the idempotence property is checked over: every input either table
// already holds, plus every combination of a scheme, a host and a path shape that has ever been
// interesting here. Two more tables would only cover what somebody thought of; this covers the
// product, which is where "https://x//" was hiding.
func baseURLCorpus() []string {
	var corpus []string
	for raw := range acceptedBaseURLs {
		corpus = append(corpus, raw)
	}
	for _, raw := range refusedBaseURLs {
		corpus = append(corpus, raw)
	}
	schemes := []string{"http://", "https://", "HTTPS://", "ftp://", ""}
	hosts := []string{"x", "x:443", "x:8443", "EXAMPLE.com", "[::1]:8443", "localhost", ""}
	paths := []string{
		"", "/", "//", "///", "/a", "/a/", "/a//", "//a", "/a//b", "/a/b", "/a/b/",
		"/a/../b", "/a/./b", "/.", "/..", "/a%20b", "/a%2Fb", "/a%2e", "/a b", "/café",
		"/a%23b", "/a%3Fb", "/a\x00", "/a?b", "/a#b", "/A/B",
	}
	for _, s := range schemes {
		for _, h := range hosts {
			for _, p := range paths {
				corpus = append(corpus, s+h+p)
			}
		}
	}
	return corpus
}

// TestNormalizingTheResultAgainChangesNothing is the property the tables cannot state. The same
// value is normalized more than once in a running deployment (Load normalizes the variable,
// ingress.New normalizes what Load stored, and a Registrar registers what Load stored), and the
// spellings meet inside an HMAC base string. A rule that moves a value on the second pass makes
// the edge sign one string while the provider signed another, which is a 401 on every delivery
// and reads as a forgery.
func TestNormalizingTheResultAgainChangesNothing(t *testing.T) {
	t.Parallel()

	accepted := 0
	for _, raw := range baseURLCorpus() {
		got, err := NormalizePublicBaseURL(raw)
		if err != nil {
			// A refusal is a fixed point of nothing: a refused value never becomes an output.
			continue
		}
		accepted++
		checkNormalizedFixedPoint(t, raw, got)
	}
	// A guard against the corpus quietly becoming all refusals, which would make this test pass
	// while proving nothing.
	if accepted < 50 {
		t.Fatalf("only %d of the corpus was accepted: the property is not being exercised", accepted)
	}
}

// checkNormalizedFixedPoint holds one accepted answer to everything the doc comment promises:
// a second pass returns it unchanged, and the result really is the shape the edge concatenates
// onto.
func checkNormalizedFixedPoint(t *testing.T, raw, got string) {
	t.Helper()

	again, err := NormalizePublicBaseURL(got)
	if err != nil {
		t.Errorf("NormalizePublicBaseURL(%q) = %q, and that answer is then refused: %v", raw, got, err)
		return
	}
	if again != got {
		t.Errorf("not idempotent: %q normalizes to %q, which normalizes to %q", raw, got, again)
		return
	}
	if strings.HasSuffix(got, "/") {
		t.Errorf("NormalizePublicBaseURL(%q) = %q, which keeps a trailing slash", raw, got)
	}
	u, err := url.Parse(got)
	if err != nil {
		t.Errorf("NormalizePublicBaseURL(%q) = %q, which is not a URL: %v", raw, got, err)
		return
	}
	if u.Host == "" || (u.Scheme != "http" && u.Scheme != "https") {
		t.Errorf("NormalizePublicBaseURL(%q) = %q, which has no host or no usable scheme", raw, got)
	}
	if u.EscapedPath() != u.Path {
		t.Errorf("NormalizePublicBaseURL(%q) = %q, whose path is not its own escaped form", raw, got)
	}
	// The premise of the function dropping its old "must be absolute" check on the path: with a
	// host present, url.Parse never produces a relative path. If this ever fires, that check has
	// to come back, because the edge concatenates a request path straight onto this string.
	if u.Path != "" && !strings.HasPrefix(u.Path, "/") {
		t.Errorf("NormalizePublicBaseURL(%q) = %q, whose path is relative", raw, got)
	}
}

// FuzzNormalizePublicBaseURL keeps the property open-ended: go test runs the seeds, and go test
// -fuzz runs whatever the fuzzer invents. Nothing here asserts what the answer should be, only
// that an accepted answer is one this function would return again unchanged.
func FuzzNormalizePublicBaseURL(f *testing.F) {
	for _, raw := range baseURLCorpus() {
		f.Add(raw)
	}
	f.Fuzz(func(t *testing.T, raw string) {
		got, err := NormalizePublicBaseURL(raw)
		if err != nil {
			if got != "" {
				t.Errorf("a refusal of %q returned %q as well", raw, got)
			}
			return
		}
		checkNormalizedFixedPoint(t, raw, got)
	})
}

// TestLoadCarriesThePublicBaseURLThrough holds Load to the same rules, since the edge is handed
// Config.PublicBaseURL and not the raw variable.
func TestLoadCarriesThePublicBaseURLThrough(t *testing.T) {
	t.Parallel()

	const dbURL = "postgres://app@db/lawang"
	cfg, err := Load(env(map[string]string{
		"LAWANG_DATABASE_URL":    dbURL,
		"LAWANG_PUBLIC_BASE_URL": "https://lawang.example.test/",
	}))
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if cfg.PublicBaseURL != "https://lawang.example.test" {
		t.Fatalf("PublicBaseURL = %q, want the normalized form", cfg.PublicBaseURL)
	}

	_, err = Load(env(map[string]string{
		"LAWANG_DATABASE_URL":    dbURL,
		"LAWANG_PUBLIC_BASE_URL": "postgres://app:hunter2@db:5432/lawang",
	}))
	if err == nil {
		t.Fatal("Load accepted a public base URL that is not one")
	}
	if strings.Contains(err.Error(), "hunter2") || strings.Contains(err.Error(), "db:5432") {
		t.Fatalf("the refusal echoes the value, which may be a database URL pasted into the wrong variable: %v", err)
	}
	if !strings.Contains(err.Error(), "LAWANG_PUBLIC_BASE_URL") {
		t.Fatalf("the refusal does not name the variable: %v", err)
	}
}

package ids

import (
	"go/ast"
	"go/parser"
	"go/token"
	"io/fs"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
)

const (
	// recordPackage is the one package that may call RecordID: record.Seal hashes the scope the
	// record carries, and no other.
	recordPackage = "internal/record"
	// idsPackage is this package, where RecordID may be said once: where it is declared.
	idsPackage = "internal/ids"
)

// idsImportPath is the import path of this package, read from go.mod rather than written here.
//
// It used to be a literal, and that is how this whole scan went blind once: the rename of
// 2026-09-20 changed the module path, the literal kept the old one, and every reference the scan
// looked for resolved to nothing. The meta-test below builds its synthetic sources from the same
// value, so it agreed with the mistake and stayed green while a real second caller existed. A
// derived path cannot disagree with the module it belongs to.
var idsImportPath = modulePath() + "/" + idsPackage

// modulePath reads the module line of go.mod at the repository root.
func modulePath() string {
	b, err := os.ReadFile(filepath.Join("..", "..", "go.mod"))
	if err != nil {
		panic("callers_test: cannot read go.mod: " + err.Error())
	}
	for line := range strings.Lines(string(b)) {
		if rest, ok := strings.CutPrefix(strings.TrimSpace(line), "module "); ok {
			return strings.TrimSpace(rest)
		}
	}
	panic("callers_test: go.mod has no module line")
}

// TestTheImportPathNamesAPackageSomethingImports is the other half of the lesson above. Deriving
// the path stops it from going stale, and this stops it from being derived wrongly: if the value
// names no package that this repository imports, the scan would find nothing and say so by
// passing. One importer is enough, and record is always one, because record.Seal is the only
// caller there is meant to be.
func TestTheImportPathNamesAPackageSomethingImports(t *testing.T) {
	var importers []string
	err := filepath.WalkDir(filepath.Join("..", ".."), func(path string, d fs.DirEntry, err error) error {
		switch {
		case err != nil:
			return err
		case d.IsDir():
			if name := d.Name(); name == ".git" || name == ".claude" {
				return fs.SkipDir
			}
			return nil
		case !strings.HasSuffix(path, ".go"):
			return nil
		}
		// A file this cannot parse is the other test's problem, not this one: it only needs one
		// file that does import the path, and a broken file cannot be that.
		if f, err := parser.ParseFile(token.NewFileSet(), path, nil, parser.ImportsOnly); err == nil {
			for _, spec := range f.Imports {
				if p, err := strconv.Unquote(spec.Path.Value); err == nil && p == idsImportPath {
					importers = append(importers, path)
				}
			}
		}
		return nil
	})
	if err != nil {
		t.Fatalf("walking the repository: %v", err)
	}
	if len(importers) == 0 {
		t.Fatalf("no file imports %q, so the caller scan is looking for a package that does not "+
			"exist and would pass however many callers there were", idsImportPath)
	}
}

// RecordID is exported because record.Seal is in another package, and it takes any string as the
// scope. A second caller could mint an id for a scope the record does not carry, and the promise
// made to sinks, that one id never appears with two scopes (ADR 4), would rest on nobody doing
// that. This fails when any file that is not a test refers to RecordID, outside internal/record
// and outside the declaration itself. Inside this package that includes a wrapper, which would
// hand the recipe to every package under another name, and anywhere it includes a go:linkname
// directive, which needs no reference at all.
//
// This scan is a tripwire, not the guard. It reads source text, and source text can always be
// arranged so that a scan does not see it (a build tag this run does not set, generated code,
// an assembly stub). The guard is the seal in record.MarshalJSON: whatever mints an id, a Record
// that was not sealed by record.Seal, for the fields it carries, cannot be marshalled. The scan
// exists so that an honest second caller is told at once, by name, why there must not be one.
func TestRecordIDHasNoCallerOutsideRecord(t *testing.T) {
	found, files := recordIDReferences(t, filepath.Join("..", ".."))
	for _, what := range found {
		t.Errorf("%s: a record id is minted by record.Seal and by nothing else", what)
	}
	if files < 10 {
		t.Errorf("only %d Go files were read, the walk is not seeing the repository", files)
	}
}

// The scan itself has to have teeth: it must see a plain call, an aliased import, a dot import
// and a function value, and must leave tests and the record package alone.
func TestTheRecordIDScanSeesEveryKindOfReference(t *testing.T) {
	tests := []struct {
		name, path, src string
		want            bool
	}{
		{"a call", "internal/worker/a.go", `package worker
import "` + idsImportPath + `"
var _, _ = ids.RecordID("p", "e", "v", "s", "t")`, true},
		{"an aliased import", "internal/worker/b.go", `package worker
import keys "` + idsImportPath + `"
var _, _ = keys.RecordID("p", "e", "v", "s", "t")`, true},
		{"a function value", "internal/worker/c.go", `package worker
import "` + idsImportPath + `"
var mint = ids.RecordID`, true},
		{"a dot import", "internal/worker/d.go", `package worker
import . "` + idsImportPath + `"
var _ = New()`, true},
		{"another function of the package", "internal/worker/e.go", `package worker
import "` + idsImportPath + `"
var _ = ids.New()`, false},
		{"a method of the same name on something else", "internal/worker/f.go", `package worker
type ledger struct{}
func (ledger) RecordID() string { return "" }
var ids ledger
var _ = ids.RecordID()`, false},
		{"a wrapper in this package, in a file of its own", "internal/ids/mint.go", `package ids
func MintAny(p, e, v, s, t string) (string, error) { return RecordID(p, e, v, s, t) }`, true},
		{"a function value in this package", "internal/ids/mint.go", `package ids
var Mint = RecordID`, true},
		{"a wrapper in the defining file", "internal/ids/ids.go", `package ids
func RecordID(p, e, v, s, t string) (string, error) { return "", nil }
func MintAny(p, e, v, s, t string) (string, error) { return RecordID(p, e, v, s, t) }`, true},
		{"the declaration alone, with its name in its own doc comment", "internal/ids/ids.go", `package ids
// RecordID is the recipe.
func RecordID(p, e, v, s, t string) (string, error) { return "", nil }`, false},
		{"another file of this package that leaves it alone", "internal/ids/other.go", `package ids
func Other() string { return New() }`, false},
		{"a linkname that pulls the recipe", "internal/worker/g.go", `package worker
import _ "unsafe"
//go:linkname mint ` + idsImportPath + `.RecordID
func mint(p, e, v, s, t string) (string, error)`, true},
		{"a linkname that pulls anything else out of this package", "internal/worker/h.go", `package worker
import _ "unsafe"
//go:linkname part ` + idsImportPath + `.checkPart
func part(name, value string) error`, true},
		{"a linkname in this package, which can push the recipe out", "internal/ids/push.go", `package ids
import _ "unsafe"
//go:linkname New ` + modulePath() + `/internal/worker.mint`, true},
		{"a linkname to something else", "internal/worker/i.go", `package worker
import _ "unsafe"
//go:linkname nanotime runtime.nanotime
func nanotime() int64`, false},
		{"the word in an ordinary comment", "internal/worker/j.go", `package worker
// go:linkname is how one would reach ` + idsImportPath + `.RecordID, and this is prose.
var _ = 1`, false},
	}
	for _, tt := range tests {
		got, err := refersToRecordID(tt.path, tt.path, tt.src)
		if err != nil {
			t.Fatalf("%s: %v", tt.name, err)
		}
		if (got != "") != tt.want {
			t.Errorf("%s: found = %q, want a finding = %v", tt.name, got, tt.want)
		}
	}
	for path, want := range map[string]bool{
		"internal/worker/ledger.go":      true,
		"cmd/lawang/main.go":             true,
		"internal/worker/ledger_test.go": false,
		"internal/record/record.go":      false,
		"internal/ids/ids.go":            true,
		"internal/ids/mint.go":           true,
		"internal/ids/ids_test.go":       false,
		"internal/recordings/x.go":       true,
		"internal/outbox/bin/x.go":       true,
	} {
		if got := scanned(path); got != want {
			t.Errorf("scanned(%q) = %v, want %v", path, got, want)
		}
	}
	// Only what the Go tool itself does not build is skipped, and the repository's own bin/. A
	// package directory that happens to be called bin is a package like any other.
	for dir, want := range map[string]bool{
		"bin":                    true,
		"internal/outbox/bin":    false,
		"cmd/bin":                false,
		".git":                   true,
		".claude":                true,
		"internal/ids/testdata":  true,
		"internal/record":        false,
		"internal/ids":           false,
		"internal/outbox/binary": false,
	} {
		if got := skippedDir(dir); got != want {
			t.Errorf("skippedDir(%q) = %v, want %v", dir, got, want)
