// TestTheSignedURLComesFromConfigurationAndNeverFromTheRequest is the security decision behind
// provider.Request.URL. HubSpot v3 signs the method, the full public request URL, the body and a
// timestamp, and the public URL is the tunnel's or the proxy's, not the one this process sees.
//
// The tempting source is Host, X-Forwarded-Host and X-Forwarded-Proto, and it is the wrong one:
// all three are written by whoever sent the request, and a Cloudflare Tunnel passes Host straight
// through. A sender that picks part of its own signed input can make a signature verify over
// content of its choosing, which is not a check at all. So the scheme, the host and any stripped
// prefix come from configuration and nothing else.
func TestTheSignedURLComesFromConfigurationAndNeverFromTheRequest(t *testing.T) {
	t.Parallel()

	const base = "https://lawang.example.test"
	cases := []struct {
		name   string
		base   string
		target string
		want   string
	}{
		{"the plain path", base, "/ingress/fake", base + "/ingress/fake"},
		{"a query is part of what was signed", base, "/ingress/fake?a=1&b=two",
			base + "/ingress/fake?a=1&b=two"},
		{"an escaped query survives", base, "/ingress/fake?t=a%2Bb%20c",
			base + "/ingress/fake?t=a%2Bb%20c"},
		{"a configured prefix is kept", base + "/lawang", "/ingress/fake",
			base + "/lawang/ingress/fake"},
		{"a trailing slash on the base is not doubled", base + "/", "/ingress/fake",
			base + "/ingress/fake"},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			t.Parallel()
			hub := &testHub{}
			mux, _ := edge(t, hub, ingress.Options{PublicBaseURL: c.base})

			r := httptest.NewRequest(http.MethodPost, c.target, strings.NewReader(delivery))
			// Everything a sender could hope to steer the signed URL with, all at once.
			r.Host = "attacker.example"
			r.Header.Set("Host", "attacker.example")
			r.Header.Set("X-Forwarded-Host", "attacker.example")
			r.Header.Set("X-Forwarded-Proto", "http")
			r.Header.Set("X-Forwarded-For", "203.0.113.1")
			r.Header.Set("Forwarded", "host=attacker.example;proto=http")
			r.Header.Set(fake.SignatureHeader, fake.Sign([]byte(secret), []byte(delivery)))
			mux.ServeHTTP(httptest.NewRecorder(), r)

			calls := hub.recorded()
			if len(calls) != 1 {
				t.Fatalf("hub called %d times", len(calls))
			}
			if got := calls[0].req.URL; got != c.want {
				t.Fatalf("Request.URL = %q, want %q", got, c.want)
			}
			if strings.Contains(calls[0].req.URL, "attacker.example") {
				t.Fatal("a header reached the URL a signature is checked over")
			}
			if calls[0].req.Method != http.MethodPost {
				t.Fatalf("Request.Method = %q", calls[0].req.Method)
			}
			if calls[0].req.Header.Get(fake.SignatureHeader) != r.Header.Get(fake.SignatureHeader) {
				t.Fatal("the headers did not travel")
			}
		})
	}
}

// TestWithNoPublicBaseURLTheEdgeServesAndAURLSigningProviderRefuses is the fail-closed half of the
// same decision. The edge cannot know what URL a provider posted to unless it is told, and a
// signature verified against a URL Lawang invented proves nothing, so a deployment that
// configured none gets an empty Request.URL and a provider that needs it refuses the delivery.
// The edge still serves, because every scheme that does not sign the URL is unaffected.
func TestWithNoPublicBaseURLTheEdgeServesAndAURLSigningProviderRefuses(t *testing.T) {
	t.Parallel()

	// This stands for a HubSpot-shaped scheme: it signs the URL, so an empty one is a refusal and
	// never a pass.
	signsTheURL := func(req provider.Request) bool { return req.URL != "" }

	for _, c := range []struct {
		name string
		base string
		want int
	}{
		{"configured", "https://lawang.example.test", http.StatusAccepted},
		{"not configured", "", http.StatusUnauthorized},
	} {
		t.Run(c.name, func(t *testing.T) {
			t.Parallel()
			hub := &testHub{fn: func(_ context.Context, _ provider.Entry, req provider.Request) (ingress.Verdict, error) {
				if !signsTheURL(req) {
					return ingress.Unverified, nil
				}
				return ingress.Stored, nil
			}}
			mux, _ := edge(t, hub, ingress.Options{PublicBaseURL: c.base})
			rec := httptest.NewRecorder()
			mux.ServeHTTP(rec, signedRequest(delivery))

			if rec.Code != c.want {
				t.Fatalf("status = %d, want %d", rec.Code, c.want)
			}
			calls := hub.recorded()
			if len(calls) != 1 {
				t.Fatalf("hub called %d times: the edge must still serve", len(calls))
			}
			if c.base == "" && calls[0].req.URL != "" {
				t.Fatalf("Request.URL = %q, want empty when nothing is configured", calls[0].req.URL)
			}
		})
	}
}

// TestAnUnsetPublicBaseURLIsSaidOutLoudAtStart is the operator's only signal for the one variable
// whose absence is otherwise completely silent.
//
// Unset, the edge serves, provider.Request.URL is empty, and a scheme that signs the URL refuses
// every delivery: 401, the status the contract reserves for a forged signature, on the provider's
// dashboard and nowhere else. Nothing else in the process mentions it, so New says it once, at a
// level an operator's handler passes, and names the variable.
func TestAnUnsetPublicBaseURLIsSaidOutLoudAtStart(t *testing.T) {
	t.Parallel()

	reg, err := provider.NewRegistry(fake.New(fake.DefaultKey))
	if err != nil {
		t.Fatalf("NewRegistry: %v", err)
	}
	newEdge := func(t *testing.T, base string) string {
		t.Helper()
		logs := &safeBuffer{}
		// Warn level, so this asserts an operator at the default level sees it, not that it is
		// somewhere in a debug stream.
		opts := ingress.Options{
			PublicBaseURL: base,
			Logger:        slog.New(slog.NewTextHandler(logs, &slog.HandlerOptions{Level: slog.LevelWarn})),
		}
		if _, err := ingress.New(reg, &testHub{}, opts); err != nil {
			t.Fatalf("ingress.New: %v", err)
		}
		return logs.String()
	}

	said := newEdge(t, "")
	if !strings.Contains(said, "LAWANG_PUBLIC_BASE_URL") {
		t.Fatalf("New said nothing about the unset variable: %q", said)
	}
	if !strings.Contains(said, "401") {
		t.Fatalf("the warning does not say what it costs: %q", said)
	}

	// Configured, there is nothing to warn about, and a line every start would train an operator
	// to ignore the one that matters.
	if quiet := newEdge(t, "https://lawang.example.test"); quiet != "" {
		t.Fatalf("New warned about a base URL that is configured: %q", quiet)
	}
}

// TestNewRefusesAPublicBaseURLItCannotUse keeps a broken base URL from becoming a signature that
// never verifies with nothing to see. The rules are config's own, called and not copied, so this
// also pins that ingress.New really calls that function.
func TestNewRefusesAPublicBaseURLItCannotUse(t *testing.T) {
	t.Parallel()

	reg, err := provider.NewRegistry(fake.New(fake.DefaultKey))
	if err != nil {
		t.Fatalf("NewRegistry: %v", err)
	}
	for name, base := range map[string]string{
		"no scheme":      "lawang.example.test",
		"a path only":    "/ingress",
		"a query":        "https://lawang.example.test?x=1",
		"credentials":    "https://user:pass@lawang.example.test",
		"a postgres URL": "postgres://app:hunter2@db:5432/lawang",
		"no host":        "https://",
		// A port and no machine, which is what LAWANG_LISTEN_ADDR takes and is easy to write
		// here by mistake. The edge inherits the refusal from config rather than carrying its
		// own copy of the rules, and this row is what says so.
		"a port and no host": "http://:8080",
		"an IDN host":        "https://café.example",
	} {
		t.Run(name, func(t *testing.T) {
			t.Parallel()
			h, err := ingress.New(reg, &testHub{}, ingress.Options{PublicBaseURL: base})
			if err == nil {
				t.Fatalf("New accepted %q", base)
			}
			if h != nil {
				t.Fatal("New returned a handler with its error")
			}
			if strings.Contains(err.Error(), base) {
				t.Fatalf("the refusal quotes the value, which may be a secret pasted into the wrong variable: %v", err)
			}
			if !strings.Contains(err.Error(), "PublicBaseURL") {
				t.Fatalf("the refusal does not name the option: %v", err)
			}
		})
	}

	// And it normalizes what it accepts, so New and config.Load hold the same spelling. The
	// trailing slash is the case that would otherwise double in every signed URL.
	h, err := ingress.New(reg, &testHub{}, ingress.Options{PublicBaseURL: "https://lawang.example.test/"})
	if err != nil || h == nil {
		t.Fatalf("New refused a good base URL: %v", err)
	}
}

package outbox

import (
	"fmt"
	"strings"
)

// Class says what kind of failure stopped an attempt. The classes follow the failure table in
// docs/architecture.md section 11. A later item that meets a failure of another kind adds a class
// here, with its text: it does not get a way to pass text in.
type Class uint8

// The classes of failure.
const (
	// ClassUnclassified is the zero value: a Cause that was never given a class.
	ClassUnclassified Class = iota
	// ClassNormalizer: the stored body could not be parsed or normalized. Not retryable.
	ClassNormalizer
	// ClassProviderUnavailable: the provider's API timed out, refused the connection, rate limited
	// the call or answered 5xx.
	ClassProviderUnavailable
	// ClassSinkUnavailable: the sink timed out, refused the connection or answered 5xx.
	ClassSinkUnavailable
	// ClassSinkRejected: the sink refused the record itself. Not retryable.
	ClassSinkRejected
	// ClassSinkUnauthorized: the sink refused the credential (401) or lacks a grant (403).
	ClassSinkUnauthorized
	// ClassVaultUnavailable: a secret could not be read, so nothing may be delivered.
	ClassVaultUnavailable
	// ClassInternal: a failure of Lawang's own, such as its database.
	ClassInternal
)

var classText = map[Class]string{
	ClassUnclassified:        "unclassified failure",
	ClassNormalizer:          "normalizer failed",
	ClassProviderUnavailable: "provider unavailable",
	ClassSinkUnavailable:     "sink unavailable",
	ClassSinkRejected:        "sink rejected the record",
	ClassSinkUnauthorized:    "sink refused the credential",
	ClassVaultUnavailable:    "vault unavailable",
	ClassInternal:            "internal error",
}

// maxCodeLen bounds a provider's or sink's error code.
const maxCodeLen = 64

// codeWithheld stands in for a code that did not look like one.
const codeWithheld = "withheld"

// Cause is why an attempt failed, in the only form the outbox stores. It ends up in last_error, a
// plain text column that operators read and every backup carries, so it must never hold token
// material, and the way to be sure of that is to never let text from outside in.
//
// The accident this prevents is the obvious call: recording err.Error(). The error of an HTTP
// client is a *url.Error, and its text quotes the request URL with its query string, which for
// many webhook sinks and provider APIs is where the API key travels. So a Cause is built from a
// Class, which is one of this package's own texts, and at most two facts about the response: its
// HTTP status, a number, and the remote system's error code, which is kept only if it looks like
// one. There is deliberately no constructor that takes an error or a message.
//
// The zero Cause is valid and reads "unclassified failure".
type Cause struct {
	class  Class
	status int
	code   string
}

// NewCause returns a Cause of the given class.
func NewCause(class Class) Cause { return Cause{class: class} }

// WithStatus adds the HTTP status of the response that failed. A number that is not a status
// (outside 100 to 599) is left out.
func (c Cause) WithStatus(status int) Cause {
	if status >= 100 && status <= 599 {
		c.status = status
	}
	return c
}

// WithCode adds the error code the remote system gave, such as "rate_limited" or "invalid_grant".
// It is kept only if it is at most 64 bytes of ASCII letters, digits, '_', '-' and '.', which a
// message, a URL, a header or a JSON fragment never is. Anything else is recorded as "withheld",
// so that an operator can see there was a code and that Lawang chose not to store it.
//
// This stops text that carries a secret by accident. It cannot stop a caller that passes a secret
// as the code: a bare token looks like a code. Pass the field of the response that the remote
// system documents as its error code, and nothing else.
func (c Cause) WithCode(code string) Cause {
	if code == "" {
		return c
	}
	c.code = codeWithheld
	if len(code) <= maxCodeLen && strings.IndexFunc(code, notCodeChar) < 0 {
		c.code = code
	}
	return c
}

func notCodeChar(r rune) bool {
	switch {
	case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r >= '0' && r <= '9', r == '_', r == '-', r == '.':
		return false
	}
	return true
}

// String is the text that is stored, for example "sink unavailable (status 503, code overloaded)".
func (c Cause) String() string {
	text, ok := classText[c.class]
	if !ok {
		text = classText[ClassUnclassified]
	}
	switch {
	case c.status != 0 && c.code != "":
		return fmt.Sprintf("%s (status %d, code %s)", text, c.status, c.code)
	case c.status != 0:
		return fmt.Sprintf("%s (status %d)", text, c.status)
	case c.code != "":
		return fmt.Sprintf("%s (code %s)", text, c.code)
	}
	return text
}

package outbox_test

import (
	"strings"
	"testing"
	"unicode/utf8"

	"github.com/gablooge/lawang/internal/outbox"
)

func TestCauseText(t *testing.T) {
	for want, cause := range map[string]outbox.Cause{
		"unclassified failure":                           {},
		"unclassified failure (status 500)":              outbox.NewCause(outbox.Class(200)).WithStatus(500),
		"normalizer failed":                              outbox.NewCause(outbox.ClassNormalizer),
		"sink unavailable (status 503)":                  outbox.NewCause(outbox.ClassSinkUnavailable).WithStatus(503),
		"provider unavailable (status 429, code slow.1)": outbox.NewCause(outbox.ClassProviderUnavailable).WithStatus(429).WithCode("slow.1"),
		"sink rejected the record (code Bad_Shape-2)":    outbox.NewCause(outbox.ClassSinkRejected).WithCode("Bad_Shape-2"),
		"sink refused the credential (status 401)":       outbox.NewCause(outbox.ClassSinkUnauthorized).WithStatus(401).WithCode(""),
		"vault unavailable":                              outbox.NewCause(outbox.ClassVaultUnavailable).WithStatus(0),
		"internal error":                                 outbox.NewCause(outbox.ClassInternal).WithStatus(99).WithStatus(600).WithStatus(-1),
	} {
		if got := cause.String(); got != want {
			t.Errorf("String() = %q, want %q", got, want)
		}
	}
}

// TestCauseKeepsOnlyWhatLooksLikeACode: the boundary of what WithCode lets through. Everything a
// message, a URL, a header or JSON is made of is outside it.
func TestCauseKeepsOnlyWhatLooksLikeACode(t *testing.T) {
	kept := []string{"a", "rate_limited", "invalid-grant", "E1001", "v2.quota", strings.Repeat("c", 64)}
	for _, code := range kept {
		if got, want := outbox.NewCause(outbox.ClassSinkRejected).WithCode(code).String(), "sink rejected the record (code "+code+")"; got != want {
			t.Errorf("WithCode(%q): %q, want %q", code, got, want)
		}
	}
	withheld := []string{
		strings.Repeat("c", 65), "two words", "a/b", "a?b", "a=b", "a&b", "a:b", "user@host", `"quoted"`, "{}", "a\nb",
		"tab\t", "nul\x00", "\xff", "é", "ｒａｔｅ", "%41", "a+b", "a,b", "a;b", "(a)", "#a", "~a", "a|b", "a\\b", "'a'", "<a>", "*",
	}
	for _, code := range withheld {
		got := outbox.NewCause(outbox.ClassSinkRejected).WithCode(code).String()
		if want := "sink rejected the record (code withheld)"; got != want {
			t.Errorf("WithCode(%q): %q, want %q", code, got, want)
		}
	}
}

// TestClipMakesAnyTextStorable: nothing reaches the two text columns but a Cause today, and a
// Cause is short, valid text by construction. clip stays in front of them all the same, for the day
// something else is written there: Postgres refuses invalid UTF-8 and NUL in text, and a failure
// that cannot be recorded is a row that loops at lease cadence with no backoff and no dead letter.
func TestClipMakesAnyTextStorable(t *testing.T) {
	for name, in := range map[string]string{
		"short":           "sink unavailable (status 503)",
		"exactly 1000":    strings.Repeat("a", 1000),
		"long":            strings.Repeat("a", 5000),
		"long multi-byte": "a" + strings.Repeat("é", 600),           // byte 1000 falls inside a rune
		"long 4-byte":     "ab" + strings.Repeat("\U0001F600", 400), // and here too
		"invalid UTF-8":   "sink said \xff\xfe\xc3",
		"NUL":             "bad\x00byte",
	} {
		got := outbox.Clip(in)
		if len(got) > 1000 || !utf8.ValidString(got) || strings.ContainsRune(got, 0) {
			t.Errorf("%s: clipped to %d bytes, valid UTF-8 %v, NUL %v", name, len(got), utf8.ValidString(got), strings.ContainsRune(got, 0))
		}
		if len(in) <= 1000 && utf8.ValidString(in) && !strings.ContainsRune(in, 0) && got != in {
			t.Errorf("%s: storable text was changed to %q", name, got)
		}
		if len(in) > 1000 && len(got) < 997 {
			t.Errorf("%s: clipped to %d bytes, want it cut at the last whole rune before 1000", name, len(got))
		}
	}
}

package outbox

import "github.com/gablooge/lawang/internal/tenancy"

// AcceptIn is Accept inside a caller's tenant-bound transaction, so that a test can hold an
// accepting transaction open.
var AcceptIn = acceptIn

// MarkDeliveredIn is MarkDelivered inside a caller's tenant-bound transaction, so that a test can
// hold a finishing transaction open.
var MarkDeliveredIn = markDeliveredIn

// WithTenant returns a genuine Claimed aimed at another tenant, token and all, which nothing
// outside this package can build. It is for the test that shows such a value changes nothing.
func WithTenant(c Claimed, tenant tenancy.ID) Claimed {
	c.tenant = tenant
	return c
}

// Clip is clip, the last line of defense in front of the two text columns.
var Clip = clip

package outbox_test

// The interleavings that timing alone cannot produce: each test here holds one transaction at a
// chosen point while another one runs.

import (
	"context"
	"errors"
	"fmt"
	"reflect"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"

	"github.com/gablooge/lawang/internal/outbox"
)

// adminConn is a superuser session that stays open for the whole test.
func (e *env) adminConn() *pgx.Conn {
	e.t.Helper()
	conn, err := pgx.Connect(e.ctx, e.tdb.AdminURL)
	if err != nil {
		e.t.Fatalf("admin connect: %v", err)
	}
	e.t.Cleanup(func() { _ = conn.Close(context.Background()) })
	return conn
}

// The advisory locks of the gates below. gateLock is held by the test while a gate is closed.
// firstLock is taken by the first statement that reaches the claim's gate, so that only that one
// stops, and the claims a test makes inside the window pass through.
const (
	gateLock  = 7001
	firstLock = 7002
)

// Which advisory lock a session is waiting for. A lock taken with one bigint shows up in pg_locks
// split into classid (the high half) and objid (the low half). The lock of an ordering key is a
// 64-bit hash, and none of the keys used here hashes to the gate's number.
const (
	onTheGate       = "(classid = 0 AND objid = 7001)"
	onAnOrderingKey = "NOT (classid = 0 AND objid = 7001)"
)

// waitsOn reports whether an operation ends up waiting for an advisory lock of the given kind
// (true), or finishes without doing so (false).
func (e *env) waitsOn(admin *pgx.Conn, which string, finished func() bool) bool {
	e.t.Helper()
	deadline := time.Now().Add(time.Minute)
	for time.Now().Before(deadline) {
		var waiting int
		var elsewhere *string
		// A transaction's lock belongs to no database in pg_locks, so the database comes from the
		// session that waits.
		err := admin.QueryRow(e.ctx, `
			SELECT count(*) FILTER (WHERE l.locktype = 'advisory' AND `+which+`),
			       min(l.locktype) FILTER (WHERE l.locktype <> 'advisory')
			  FROM pg_locks l JOIN pg_stat_activity a USING (pid)
			 WHERE NOT l.granted AND a.datname = current_database()`).Scan(&waiting, &elsewhere)
		if err != nil {
			e.t.Fatalf("pg_locks: %v", err)
		}
		if waiting > 0 {
			return true
		}
		if elsewhere != nil {
			// Waiting, and for the wrong thing: a row or a transaction, which is what happens
			// when two writers of a key meet without the key's lock. Say so now, not in a minute.
			e.t.Fatalf("waiting for a %s lock, not for an advisory lock: two writers of one key got past the key's lock", *elsewhere)
		}
		if finished() {
			return false
		}
		time.Sleep(10 * time.Millisecond)
	}
	e.t.Fatal("after a minute, neither waiting for an advisory lock nor finished")
	return false
}

// waitForLockWaiter returns once the operation is waiting for an advisory lock of the given kind.
// If it finishes instead, the test fails.
func (e *env) waitForLockWaiter(admin *pgx.Conn, which string, finished func() bool, what string) {
	e.t.Helper()
	if !e.waitsOn(admin, which, finished) {
		e.t.Fatalf("%s finished without waiting", what)
	}
}

// closeGate takes gateLock in a superuser session of its own. The returned function opens it. A
// test that fails with the gate closed does not hang: closing the session opens it too.
func (e *env) closeGate() (admin *pgx.Conn, open func()) {
	e.t.Helper()
	admin = e.adminConn()
	if _, err := admin.Exec(e.ctx, "SELECT pg_advisory_lock($1)", gateLock); err != nil {
		e.t.Fatalf("close the gate: %v", err)
	}
	return admin, func() {
		e.t.Helper()
		if _, err := admin.Exec(e.ctx, "SELECT pg_advisory_unlock($1)", gateLock); err != nil {
			e.t.Fatalf("open the gate: %v", err)
		}
	}
}

// gateClaimOn makes the next Claim stop when it first reads row id: after the statement has taken
// its snapshot, and before it has locked any row. That is the window in which another transaction
// can change a row the snapshot has chosen, and timing alone cannot hit it. The returned function
// lets the claim go on.
//
// The pause is a test-only RESTRICTIVE select policy for the worker role. Its function is always
// true, and waits for the gate when it is shown the gate row. A policy is checked where the table
// is scanned, and the gate row is the first row any scan of the due heads returns (holdFirstInLine),
// so under any plan it is read before the first row is locked: a plan that walks the index of due
// heads reads it first and only then goes on to the rows the test is about, and a plan that scans
// and sorts reads every row before it locks one. The rows read after the pause are still read on
// the snapshot taken before it, which is the point. The tests that use this run under several
// planner settings (see planners), and each of them checks that the row it changes in the window
// was in fact not locked.
//
// Every claim reads the gate row, so only the first one to get there stops (firstLock).
func (e *env) gateClaimOn(id string) (admin *pgx.Conn, open func()) {
	e.t.Helper()
	e.admin(fmt.Sprintf(`
		CREATE FUNCTION lawang.test_gate(row_id text) RETURNS boolean LANGUAGE plpgsql VOLATILE AS $$
		BEGIN
		  IF row_id = '%s' AND pg_try_advisory_xact_lock(%d) THEN
		    PERFORM pg_advisory_xact_lock(%d);
		  END IF;
		  RETURN true;
		END $$;
		CREATE POLICY test_gate ON lawang.outbox AS RESTRICTIVE FOR SELECT TO lawang_worker
		  USING (lawang.test_gate(id));`, id, firstLock, gateLock))
	e.holdFirstInLine(id)
	return e.closeGate()
}

// acceptGateRow accepts the row for gateClaimOn: the head of a key of its own. Until the gate is
// set up it is not due, so the claims a test makes before that do not lease it.
func (e *env) acceptGateRow() string {
	e.t.Helper()
	id := e.accept(tenantA, "gate", 1)
	e.admin("UPDATE lawang.outbox SET next_attempt_at = now() + interval '1 day' WHERE id = '" + id + "'")
	return id
}

// holdFirstInLine makes the gate row due for a year, so that it is the very first row of the index
// the claim walks, and the first row in the claim's order under any other plan. No claim leases
// it, because this holds its row lock until the test ends and the claim skips locked rows: every
// claim in the test still returns only the rows the test is about. It comes after the gate's DDL,
// which needs the table to itself.
func (e *env) holdFirstInLine(id string) {
	e.t.Helper()
	e.admin("UPDATE lawang.outbox SET next_attempt_at = now() - interval '1 year' WHERE id = '" + id + "'")
	holder := e.adminConn() // closing it, when the test ends, ends the transaction and the lock
	if _, err := holder.Exec(e.ctx, "BEGIN"); err != nil {
		e.t.Fatalf("hold the gate row: %v", err)
	}
	if _, err := holder.Exec(e.ctx, "SELECT id FROM lawang.outbox WHERE id = $1 FOR UPDATE", id); err != nil {
		e.t.Fatalf("hold the gate row: %v", err)
	}
}

// planners are the planner settings the gated claim tests run under: each entry lists what is
// turned off. The claim's re-checks have to hold under any plan. With the default settings on a
// small table the candidates come from a scan and a sort, on a large one from a walk of the index
// of due heads, and the claim locks and updates its rows one at a time (the top of the plan is a
// nested loop with the locked subquery on its outer side). Without nested loops that join becomes
// a hash or merge join, and every chosen row is locked before the first one is updated. With
// sequential scans and sorts off, the candidates come from the index walk even on a small table.
var planners = map[string][]string{
	"default":               nil,
	"no nested loop":        {"enable_nestloop"},
	"no index scan":         {"enable_indexscan", "enable_indexonlyscan", "enable_bitmapscan"},
	"no hash or merge join": {"enable_hashjoin", "enable_mergejoin"},
	"no seq scan or sort":   {"enable_seqscan", "enable_sort"},
}

// gateInsertOf makes the INSERT of the row with this body stop in a BEFORE INSERT row trigger:
// after the row has been given its seq (column defaults are computed before the row triggers
// run), and before the statement ends. The returned function lets it go on.
func (e *env) gateInsertOf(body []byte) (admin *pgx.Conn, open func()) {
	e.t.Helper()
	e.admin(fmt.Sprintf(`
		CREATE FUNCTION lawang.test_insert_gate() RETURNS trigger LANGUAGE plpgsql AS $$
		BEGIN
		  IF NEW.raw_body = decode(TG_ARGV[0], 'hex') THEN
		    PERFORM pg_advisory_xact_lock(%d);
		  END IF;
		  RETURN NEW;
		END $$;
		CREATE TRIGGER test_insert_gate BEFORE INSERT ON lawang.outbox
		  FOR EACH ROW EXECUTE FUNCTION lawang.test_insert_gate('%x');`, gateLock, body))
	return e.closeGate()
}

// claimInBackground runs one Claim that is expected to stop at the gate.
func (e *env) claimInBackground() (result <-chan []outbox.Claimed, finished func() bool) {
	ch := make(chan []outbox.Claimed, 1)
	var done atomic.Bool
	go func() {
		got, err := e.ob.Claim(e.ctx, 10, lease)
		if err != nil {
			e.t.Errorf("gated Claim: %v", err)
		}
		done.Store(true)
		ch <- got
	}()
	return ch, done.Load
}

func bodyOf(key string, version int) []byte {
	return fmt.Appendf(nil, `{"key":%q,"v":%d}`, key, version)
}

type accepted struct {
	id  string
	err error
}

// acceptInBackground runs one Accept for tenantA that is expected to wait for something.
func (e *env) acceptInBackground(key string, version int) (result <-chan accepted, finished func() bool) {
	ch := make(chan accepted, 1)
	var done atomic.Bool
	go func() {
		id, _, err := e.ob.Accept(e.ctx, tenantA, outbox.Delivery{
			Provider: "fake", OrderingKey: key, RawBody: bodyOf(key, version),
		})
		done.Store(true)
		ch <- accepted{id, err}
	}()
	return ch, done.Load
}

// acceptAndHold accepts a delivery for tenantA in a transaction that stays open, holding the
// ordering key's lock, until commit is called.
func (e *env) acceptAndHold(key string, version int) (id string, commit func()) {
	e.t.Helper()
	inserted := make(chan string, 1)
	hold := make(chan struct{})
	release := sync.OnceFunc(func() { close(hold) })
	e.t.Cleanup(release) // a failing test must not leave it open, or closing the pool would hang
	done := make(chan error, 1)
	go func() {
		done <- e.db.TenantTx(e.ctx, tenantA, func(tx pgx.Tx) error {
			id, _, err := outbox.AcceptIn(e.ctx, tx, tenantA, outbox.Delivery{
				Provider: "fake", OrderingKey: key, RawBody: bodyOf(key, version),
			})
			inserted <- id
			if err != nil {
				return err
			}
			<-hold
			return nil
		})
	}()
	if id = <-inserted; id == "" {
		e.t.Fatalf("held Accept: %v", <-done)
	}
	return id, func() {
		e.t.Helper()
		release()
		if err := <-done; err != nil {
			e.t.Fatalf("held Accept: %v", err)
		}
	}
}

// deliverAndHold marks a claimed row of tenantA delivered in a transaction that stays open,
// holding the ordering key's lock, until commit is called. The row is finished and the marker
// handed on inside that transaction, and nobody else can see it yet.
func (e *env) deliverAndHold(c outbox.Claimed) (commit func()) {
	e.t.Helper()
	marked := make(chan error, 1)
	hold := make(chan struct{})
	release := sync.OnceFunc(func() { close(hold) })
	e.t.Cleanup(release) // a failing test must not leave it open, or closing the pool would hang
	done := make(chan error, 1)
	go func() {
		done <- e.db.TenantTx(e.ctx, tenantA, func(tx pgx.Tx) error {
			err := outbox.MarkDeliveredIn(e.ctx, tx, c)
			marked <- err
			if err != nil {
				return err
			}
			<-hold
			return nil
		})
	}()
	if err := <-marked; err != nil {
		e.t.Fatalf("held MarkDelivered: %v", err)
	}
	return func() {
		e.t.Helper()
		release()
		if err := <-done; err != nil {
			e.t.Fatalf("held MarkDelivered: %v", err)
		}
	}
}

// headsBroken is the invariant of the head marker, as one statement, so on one snapshot: every
// key with unfinished rows has exactly one head, that head is its earliest unfinished row, and no
// finished row is a head. Writers of one key run one after the other and each of them keeps it, so
// it holds on every snapshot, also in the middle of a concurrent test. It returns the keys that
// break it.
const headsBroken = `
	SELECT coalesce(string_agg(format('%s/%s: %s heads among %s unfinished rows, the earliest %s a head',
	                                  tenant_id, ordering_key, heads, unfinished,
	                                  CASE WHEN first_is_head THEN 'is' ELSE 'is not' END), '; '), '')
	  FROM (
	        SELECT tenant_id, ordering_key,
	               count(*) FILTER (WHERE state IN ('pending', 'prepared')) AS unfinished,
	               count(*) FILTER (WHERE is_head) AS heads,
	               coalesce((array_agg(is_head ORDER BY seq) FILTER (WHERE state IN ('pending', 'prepared')))[1], false) AS first_is_head,
	               bool_or(is_head AND state NOT IN ('pending', 'prepared')) AS finished_head
	          FROM lawang.outbox
	         GROUP BY tenant_id, ordering_key
	       ) k
	 WHERE finished_head OR (unfinished = 0 AND heads <> 0) OR (unfinished > 0 AND (heads <> 1 OR NOT first_is_head))`

// checkHeads fails the test if the head marker's invariant does not hold right now.
func (e *env) checkHeads(admin *pgx.Conn) {
	e.t.Helper()
	var broken string
	if err := admin.QueryRow(e.ctx, headsBroken).Scan(&broken); err != nil {
		e.t.Fatalf("head invariant: %v", err)
	}
	if broken != "" {
		e.t.Fatalf("head invariant broken: %s", broken)
	}
}

// get reads a row of tenantA.
func (e *env) get(id string) outbox.Row {
	e.t.Helper()
	row, err := e.ob.Get(e.ctx, tenantA, id)
	if err != nil {
		e.t.Fatalf("Get(%s): %v", id, err)
	}
	return row
}

func (e *env) isHead(id string) bool {
	e.t.Helper()
	return e.get(id).IsHead
}

func (e *env) seqOf(id string) int64 {
	e.t.Helper()
	return e.get(id).Seq
}

// TestAcceptsOfOneKeyCommitInQueueOrder is the late commit: seq is assigned by the INSERT, not by
// the COMMIT. If v1 could be inserted first and committed last, a claim in between would lease v2,
// and the next one would lease v1 while v2 is still in flight. So the second Accept of a key has
// to wait for the first one's transaction, and it has to wait before it takes its seq.
func TestAcceptsOfOneKeyCommitInQueueOrder(t *testing.T) {
	e := setup(t)
	admin := e.adminConn()

	// T1 accepts v1 and stays open.
	v1, commitT1 := e.acceptAndHold("task:1", 1)

	// T2 accepts v2 of the same entity. It must not get past T1.
	t2, t2Finished := e.acceptInBackground("task:1", 2)
	e.waitForLockWaiter(admin, onAnOrderingKey, t2Finished, "Accept of v2 while v1's transaction is open")

	// Another entity is not held up, and it is all a claim can see.
	other := e.accept(tenantA, "task:2", 1)
	e.claimOne(other)
	if t2Finished() {
		t.Fatal("Accept of v2 finished while v1's transaction is open")
	}

	commitT1()
	second := <-t2
	if second.err != nil || second.id == "" {
		t.Fatalf("T2 = %q, %v", second.id, second.err)
	}
	// The other entity was accepted while T2 was waiting. T2 waits before its INSERT, so it cannot
	// have a seq yet at that point. An Accept that took its seq first and the lock second would
	// wait just the same, and be below the other entity here.
	if v2Seq, otherSeq := e.seqOf(second.id), e.seqOf(other); v2Seq <= otherSeq {
		t.Errorf("v2 has seq %d, and a row accepted while v2 was waiting has %d: v2 took its seq before it took the lock",
			v2Seq, otherSeq)
	}

	c1 := e.claimOne(v1)
	e.claimNone("v1 is in flight, so v2 must wait behind it")
	if err := e.ob.MarkDelivered(e.ctx, c1); err != nil {
		t.Fatal(err)
	}
	e.claimOne(second.id)
}

// TestNoVersionIsClaimableWhileAnEarlierOneIsStillToCommit is the property the ordering key's lock
// exists for, in the one interleaving where the order of the lock and the INSERT decides it. T1's
// INSERT of v1 is stopped after v1 has its seq. With the lock taken first, T1 holds it by then,
// and T2's Accept of v2 waits. With the lock taken after the INSERT, nobody holds it: T2 inserts
// v2 behind v1, locks, commits, and v2 is leased while v1, ahead of it in the queue, has yet to
// appear. When it does, two versions of the entity are unfinished at once, the later one first.
func TestNoVersionIsClaimableWhileAnEarlierOneIsStillToCommit(t *testing.T) {
	e := setup(t)
	admin, open := e.gateInsertOf(bodyOf("task:1", 1))

	t1, t1Finished := e.acceptInBackground("task:1", 1)
	e.waitForLockWaiter(admin, onTheGate, t1Finished, "the gated Accept of v1")

	// v1 has its seq and is not committed. Whatever the Accept of v2 does now, no claim may return
	// v2 before v1 is there to be seen.
	t2, t2Finished := e.acceptInBackground("task:1", 2)
	waited := e.waitsOn(admin, onAnOrderingKey, t2Finished)
	if got := e.claim(); len(got) != 0 {
		t.Fatalf("Claim = %v while v1, which has the lower seq, is still to commit", claimedIDs(got))
	}
	if !waited {
		t.Fatal("Accept of v2 finished while the Accept of v1 is open and already has its seq")
	}

	open()
	first, second := <-t1, <-t2
	if first.err != nil || first.id == "" || second.err != nil || second.id == "" {
		t.Fatalf("T1 = %q, %v, T2 = %q, %v", first.id, first.err, second.id, second.err)
	}
	if v1Seq, v2Seq := e.seqOf(first.id), e.seqOf(second.id); v1Seq >= v2Seq {
		t.Errorf("v1 has seq %d and v2 has seq %d, want v1 first", v1Seq, v2Seq)
	}
	c1 := e.claimOne(first.id)
	e.claimNone("v1 is in flight, so v2 must wait behind it")
	if err := e.ob.MarkDelivered(e.ctx, c1); err != nil {
		t.Fatal(err)
	}
	e.claimOne(second.id)
}

// TestReplayWaitsForAnOpenAcceptOfItsKey: a replay assigns a seq too, so it has the same late
// commit to fear. If it could slip in behind an Accept that is still open, the replayed row would
// have the higher seq but be visible first: it would be leased, and then the accepted row would
// appear ahead of it and be leased as well.
func TestReplayWaitsForAnOpenAcceptOfItsKey(t *testing.T) {
	e := setup(t)
	admin := e.adminConn()
	v1 := e.accept(tenantA, "task:1", 1)
	if err := e.ob.MarkDead(e.ctx, e.claimOne(v1), badShape); err != nil {
		t.Fatal(err)
	}

	v2, commitV2 := e.acceptAndHold("task:1", 2)

	replayed := make(chan error, 1)
	var finished atomic.Bool
	go func() {
		err := e.ob.Replay(e.ctx, tenantA, v1)
		finished.Store(true)
		replayed <- err
	}()
	e.waitForLockWaiter(admin, onAnOrderingKey, finished.Load, "Replay of v1 while an Accept of its key is open")
	e.claimNone("v2 is not committed and v1 is not replayed yet")

	commitV2()
	if err := <-replayed; err != nil {
		t.Fatal(err)
	}
	c2 := e.claimOne(v2)
	e.claimNone("v2 is in flight, and the replayed v1 is behind it")
	if err := e.ob.MarkDelivered(e.ctx, c2); err != nil {
		t.Fatal(err)
	}
	e.claimOne(v1)
}

// adminErr runs one statement as the superuser and returns the server's verdict.
func (e *env) adminErr(sql string) error {
	e.t.Helper()
	_, err := e.adminConn().Exec(e.ctx, sql)
	return err
}

func sqlState(err error) string {
	var pgErr *pgconn.PgError
	if errors.As(err, &pgErr) {
		return pgErr.Code
	}
	return ""
}

// TestAKeyNeverHasTwoHeads pins the second line of defense, which is the database's and not the
// claim's: one head per key, by a unique index. The rows below reach the table the way a writer
// would that took no ordering-key lock and knew nothing of the marker: ahead of a version that is
// already in flight. (Before the head marker this was a NOT EXISTS in the claim, evaluated on the
// snapshot. The index holds at every moment, and for every writer.)
func TestAKeyNeverHasTwoHeads(t *testing.T) {
	e := setup(t)
	v2 := e.accept(tenantA, "task:1", 2)
	e.claimOne(v2)

	const late = `INSERT INTO lawang.outbox (id, seq, tenant_id, provider, delivery_id, ordering_key, raw_body, is_head)
	              OVERRIDING SYSTEM VALUE VALUES ('%s', 0, 'tenant_a', 'fake', '%[1]s', 'task:1', '', %v)`
	if err := e.adminErr(fmt.Sprintf(late, "second-head", true)); sqlState(err) != "23505" {
		t.Fatalf("a second head for a key whose head is in flight: err = %v, want a unique violation", err)
	}
	// Without the marker the row is stored, and is nothing a claim can see.
	if err := e.adminErr(fmt.Sprintf(late, "late", false)); err != nil {
		t.Fatal(err)
	}
	e.claimNone("v2 is in flight, so nothing else of its entity is claimable, not even an earlier row")

	// When v2's lease runs out it is v2 that is taken over. The earlier row is still not a head.
	e.admin("UPDATE lawang.outbox SET lease_until = now() - interval '1 second' WHERE id = '" + v2 + "'")
	c2 := e.claimOne(v2)
	e.claimNone("v2 is in flight again")

	// Finishing the head hands the marker to the earliest unfinished row of the key.
	if err := e.ob.MarkDelivered(e.ctx, c2); err != nil {
		t.Fatal(err)
	}
	if err := e.ob.MarkDelivered(e.ctx, e.claimOne("late")); err != nil {
		t.Fatal(err)
	}

	// And a finished row can never be a head, even of a key that has none.
	err := e.adminErr("UPDATE lawang.outbox SET is_head = true WHERE id = '" + v2 + "'")
	if sqlState(err) != "23514" {
		t.Errorf("making a delivered row a head: err = %v, want a check violation", err)
	}
}

// TestAFinishedRowIsNeverAHead: the claim asks for is_head and does not look at the state, so
// "a finished row is never leased" rests on the table's CHECK, for every writer there is or will
// be. Neither way of finishing a row while keeping its marker gets past it.
func TestAFinishedRowIsNeverAHead(t *testing.T) {
	e := setup(t)
	v1 := e.accept(tenantA, "task:1", 1)
	for _, state := range []string{outbox.StateDelivered, outbox.StateDead} {
		err := e.adminErr(fmt.Sprintf("UPDATE lawang.outbox SET state = '%s', finished_at = now() WHERE id = '%s'", state, v1))
		if sqlState(err) != "23514" {
			t.Errorf("a head made %s and left a head: err = %v, want a check violation", state, err)
		}
	}
	e.claimOne(v1) // and it is still there to be claimed
}

// TestClaimRechecksARowFinishedAfterItsSnapshot: v1's lease has run out, and its slow holder is
// about to finish. A claimer's snapshot sees v1 as a head with an expired lease. The holder's
// MarkDelivered commits before the claimer reaches the row lock. The claimer then looks at the
// new version of the row: no lease, due. Only the state says it is finished, and a claim that
// did not look at it again would hand a delivered row to a worker.
func TestClaimRechecksARowFinishedAfterItsSnapshot(t *testing.T) {
	for name, off := range planners {
		t.Run(name, func(t *testing.T) {
			e := setup(t, off...)
			gate := e.acceptGateRow()
			v1 := e.accept(tenantA, "task:1", 1)
			slow := e.claimOne(v1)
			e.admin("UPDATE lawang.outbox SET lease_until = now() - interval '1 second' WHERE id = '" + v1 + "'")

			admin, open := e.gateClaimOn(gate)
			result, finished := e.claimInBackground()
			e.waitForLockWaiter(admin, onTheGate, finished, "the gated Claim")

			// If the claim had locked v1 already, this would wait for it, and the test would prove
			// nothing.
			ctx, cancel := context.WithTimeout(e.ctx, 30*time.Second)
			defer cancel()
			if err := e.ob.MarkDelivered(ctx, slow); err != nil {
				open()
				t.Fatalf("the slow holder finishing inside the window: %v (a timeout means the paused claim already holds v1's row lock, and this test has lost its window)", err)
			}

			open()
			if got := <-result; len(got) != 0 {
				t.Errorf("Claim = %v, want nothing: v1 was delivered before the claim locked it", claimedIDs(got))
			}
			row, err := e.ob.Get(e.ctx, tenantA, v1)
			if err != nil {
				t.Fatal(err)
			}
			if row.State != outbox.StateDelivered || row.LeaseUntil != nil {
				t.Errorf("v1 = state %q, lease %v, want delivered and unleased", row.State, row.LeaseUntil)
			}
		})
	}
}

// TestClaimRechecksARowLeasedAfterItsSnapshot: a claimer's snapshot sees v1 as a due head. Before
// it reaches the row lock, another claimer leases v1 and commits. The latest version of v1 is
// still a head and still unfinished. Only due_at, which now carries the lease, says it is taken,
// and due_at is a generated column: what is re-checked has to be the value stored with the row
// version the other claimer wrote, not the one the snapshot saw. A claim that judged it on the
// snapshot would lease v1 a second time, and two workers would deliver it.
func TestClaimRechecksARowLeasedAfterItsSnapshot(t *testing.T) {
	for name, off := range planners {
		t.Run(name, func(t *testing.T) {
			e := setup(t, off...)
			gate := e.acceptGateRow()
			v1 := e.accept(tenantA, "task:1", 1)

			admin, open := e.gateClaimOn(gate)
			result, finished := e.claimInBackground()
			e.waitForLockWaiter(admin, onTheGate, finished, "the gated Claim")

			// This claim reads the gate row too, and passes: only the first claim stops there. That
			// it gets v1 also shows the paused claim had not locked it.
			first := e.claimOne(v1)

			open()
			if got := <-result; len(got) != 0 {
				t.Errorf("Claim = %v, want nothing: v1 was leased before the claim locked it", claimedIDs(got))
			}
			if row := e.get(v1); row.Attempts != 1 || row.LeaseUntil == nil {
				t.Errorf("v1 = attempts %d, lease %v, want the one lease of the first claimer", row.Attempts, row.LeaseUntil)
			}
			// The first claimer's token is still the row's: nobody wrote over it.
			if err := e.ob.MarkDelivered(e.ctx, first); err != nil {
				t.Errorf("the first claimer delivering v1: %v", err)
			}
		})
	}
}

// TestClaimRechecksARowGivenABackoffAfterItsSnapshot: as above, but the other claimer has also
// failed v1 and given the lease up by the time the paused claim reaches the row. The latest version
// of v1 is a head, unfinished and UNLEASED. Only its next_attempt_at, through due_at, says it is
// not to be tried for an hour. A claim that leased it would skip the backoff and use up an attempt
// of the ladder, on every poll that happens to race a failure.
func TestClaimRechecksARowGivenABackoffAfterItsSnapshot(t *testing.T) {
	for name, off := range planners {
		t.Run(name, func(t *testing.T) {
			e := setup(t, off...)
			gate := e.acceptGateRow()
			v1 := e.accept(tenantA, "task:1", 1)

			admin, open := e.gateClaimOn(gate)
			result, finished := e.claimInBackground()
			e.waitForLockWaiter(admin, onTheGate, finished, "the gated Claim")

			if err := e.ob.Fail(e.ctx, e.claimOne(v1), outbox.Ladder{time.Hour}, sink503); err != nil {
				t.Fatal(err)
			}
			if row := e.get(v1); row.LeaseUntil != nil || !row.IsHead || row.State != outbox.StatePending {
				t.Fatalf("v1 = lease %v, head %v, state %q: the test wants an unleased, unfinished head in the window",
					row.LeaseUntil, row.IsHead, row.State)
			}

			open()
			if got := <-result; len(got) != 0 {
				t.Errorf("Claim = %v, want nothing: v1 was given a backoff before the claim locked it", claimedIDs(got))
			}
			if row := e.get(v1); row.Attempts != 1 || row.LeaseUntil != nil {
				t.Errorf("v1 = attempts %d, lease %v, want one attempt and no lease: it is backing off", row.Attempts, row.LeaseUntil)
			}
			e.claimNone("v1 is backing off")
		})
	}
}

// TestClaimLeasesARowReplayedOntoAnEmptyKeyAfterItsSnapshot is the one change inside the window
// after which the row is still the claim's to take. v1 is claimed by someone else, dies, and is
// replayed, and its key has nothing else unfinished: the latest version of v1 is the head again,
// and due. It is a different row version with a different seq, and the claim leases it all the
// same, because what it asks of the locked row is what makes a row claimable and nothing more.
func TestClaimLeasesARowReplayedOntoAnEmptyKeyAfterItsSnapshot(t *testing.T) {
	for name, off := range planners {
		t.Run(name, func(t *testing.T) {
			e := setup(t, off...)
			gate := e.acceptGateRow()
			v1 := e.accept(tenantA, "task:1", 1)

			admin, open := e.gateClaimOn(gate)
			result, finished := e.claimInBackground()
			e.waitForLockWaiter(admin, onTheGate, finished, "the gated Claim")

			if err := e.ob.MarkDead(e.ctx, e.claimOne(v1), badShape); err != nil {
				t.Fatal(err)
			}
			if err := e.ob.Replay(e.ctx, tenantA, v1); err != nil {
				t.Fatal(err)
			}
			// As in the test below: a replay that began before the paused claim did.
			e.admin("UPDATE lawang.outbox SET next_attempt_at = now() - interval '1 hour' WHERE id = '" + v1 + "'")

			open()
			got := <-result
			if len(got) != 1 || got[0].ID() != v1 || got[0].Attempt() != 1 {
				t.Fatalf("Claim = %v, want v1 on attempt 1: it is the head of its key again, and due", claimedIDs(got))
			}
			e.checkHeads(admin)
			e.claimNone("v1 is in flight")
			if err := e.ob.MarkDelivered(e.ctx, got[0]); err != nil {
				t.Errorf("delivering v1 under the paused claim's lease: %v", err)
			}
		})
	}
}

// TestClaimSkipsARowSomeoneHasLocked: the claim never waits for a row lock. A row that another
// transaction holds (a finish in progress, another claim) is passed over for this poll, and the
// rest of the batch is leased at once.
func TestClaimSkipsARowSomeoneHasLocked(t *testing.T) {
	e := setup(t)
	held := e.accept(tenantA, "task:1", 1)
	free := e.accept(tenantA, "task:2", 1)
	holder := e.adminConn()
	if _, err := holder.Exec(e.ctx, "BEGIN"); err != nil {
		t.Fatal(err)
	}
	if _, err := holder.Exec(e.ctx, "SELECT id FROM lawang.outbox WHERE id = $1 FOR UPDATE", held); err != nil {
		t.Fatal(err)
	}

	// A claim that waited would wait for as long as the holder likes. This one has five seconds.
	ctx, cancel := context.WithTimeout(e.ctx, 5*time.Second)
	defer cancel()
	got, err := e.ob.Claim(ctx, 10, lease)
	if err != nil {
		t.Fatalf("Claim while a row is locked: %v (a timeout means it waited for the row)", err)
	}
	if ids := claimedIDs(got); !reflect.DeepEqual(ids, []string{free}) {
		t.Errorf("Claim = %v, want only the row nobody holds (%s)", ids, free)
	}
	if _, err := holder.Exec(e.ctx, "ROLLBACK"); err != nil {
		t.Fatal(err)
	}
	e.claimOne(held)
}

// TestClaimRechecksARowReplayedAfterItsSnapshot: a claimer's snapshot sees v1 as the head of its
// key. Before it reaches the row lock, v1 is claimed by someone else and dies, v2 becomes the head
// and goes in flight, and v1 is replayed to the back. The new version of v1 is pending, unleased
// and due, and the head the claimer joined it to is the stale one. Only its seq says it is no
// longer that head.
func TestClaimRechecksARowReplayedAfterItsSnapshot(t *testing.T) {
	for name, off := range planners {
		t.Run(name, func(t *testing.T) {
			e := setup(t, off...)
			gate := e.acceptGateRow()
			v1 := e.accept(tenantA, "task:1", 1)
			v2 := e.accept(tenantA, "task:1", 2)

			admin, open := e.gateClaimOn(gate)
			result, finished := e.claimInBackground()
			e.waitForLockWaiter(admin, onTheGate, finished, "the gated Claim")

			// These claims read the gate row too, and pass: only the first claim stops there. That
			// the first of them gets v1 also shows the paused claim had not locked it.
			c1 := e.claimOne(v1)
			if err := e.ob.MarkDead(e.ctx, c1, badShape); err != nil {
				t.Fatal(err)
			}
			c2 := e.claimOne(v2)
			if err := e.ob.Replay(e.ctx, tenantA, v1); err != nil {
				t.Fatal(err)
			}
			// A replay sets next_attempt_at to the start of its own transaction. Put it before the
			// start of the paused claim's, as for a replay that began first and then waited for
			// the key's lock: otherwise the paused claim drops v1 for not being due, and its seq
			// is never looked at.
			e.admin("UPDATE lawang.outbox SET next_attempt_at = now() - interval '1 hour' WHERE id = '" + v1 + "'")

			open()
			if got := <-result; len(got) != 0 {
				t.Errorf("Claim = %v, want nothing: v1 went to the back of its queue, and v2 is in flight", claimedIDs(got))
			}
			e.claimNone("v2 is in flight")
			if err := e.ob.MarkDelivered(e.ctx, c2); err != nil {
				t.Fatal(err)
			}
			e.claimOne(v1)
		})
	}
}

// The three tests below are the races the head marker brings with it. In each, two writers of one
// key overlap: one decides from what it can see whether a row is a head, the other changes that
// under it. Whichever comes second has to wait for the first to commit, or a row ends up
// unfinished with no head in front of it, and is never delivered.

// isolationDefaults are the database defaults the three tests run under. Waiting for the key's lock
// is only half of what they pin. The writer that waited must also SEE what the one before it
// committed, and it does because its next statement takes a new snapshot, which is READ COMMITTED.
// Under REPEATABLE READ or SERIALIZABLE the snapshot is the transaction's, taken by its first
// statement (the one that binds the tenant, before the wait): the writer waits, as it should, and
// then decides on a picture from before the commit it waited for. The row it writes has no head in
// front of it, no error is raised, and the key is never claimed again. So store asks for READ
// COMMITTED by name, and a default set on the database (one ALTER DATABASE, and some sites set it
// as policy) cannot change it.
var isolationDefaults = map[string][]string{
	"the server's default":        nil,
	"repeatable read by default":  {"default_transaction_isolation = 'repeatable read'"},
	"serializable by default":     {"default_transaction_isolation = 'serializable'"},
	"read committed, spelled out": {"default_transaction_isolation = 'read committed'"},
}

// TestAFinishWaitsForAnOpenAcceptOfItsKey is the lost promotion. The Accept of v2 sees v1
// unfinished and inserts v2 as a non-head. Were the MarkDelivered of v1 to run now, it would not
// see the uncommitted v2, would promote nothing, and v2 would wait forever.
func TestAFinishWaitsForAnOpenAcceptOfItsKey(t *testing.T) {
	for name, settings := range isolationDefaults {
		t.Run(name, func(t *testing.T) {
			e := setupWith(t, settings...)
			admin := e.adminConn()
			v1 := e.accept(tenantA, "task:1", 1)
			c1 := e.claimOne(v1)

			v2, commitV2 := e.acceptAndHold("task:1", 2)

			delivered := make(chan error, 1)
			var finished atomic.Bool
			go func() {
				err := e.ob.MarkDelivered(e.ctx, c1)
				finished.Store(true)
				delivered <- err
			}()
			waited := e.waitsOn(admin, onAnOrderingKey, finished.Load)

			commitV2()
			if err := <-delivered; err != nil {
				t.Fatal(err)
			}
			if !waited {
				t.Error("MarkDelivered of v1 finished while an Accept of its key was open")
			}
			e.checkHeads(admin)
			e.claimOne(v2) // the property: v2 was handed the marker
		})
	}
}

// TestAnAcceptWaitsForAnOpenFinishOfItsKey is the same race from the other side. The MarkDelivered
// of v1 has found nothing to promote and has not committed. Were the Accept of v2 to run now, it
// would still see v1 unfinished and insert v2 as a non-head, behind a row that is about to be gone.
func TestAnAcceptWaitsForAnOpenFinishOfItsKey(t *testing.T) {
	for name, settings := range isolationDefaults {
		t.Run(name, func(t *testing.T) {
			e := setupWith(t, settings...)
			admin := e.adminConn()
			v1 := e.accept(tenantA, "task:2", 1)
			commitV1 := e.deliverAndHold(e.claimOne(v1))

			t2, t2Finished := e.acceptInBackground("task:2", 2)
			waited := e.waitsOn(admin, onAnOrderingKey, t2Finished)

			commitV1()
			second := <-t2
			if second.err != nil || second.id == "" {
				t.Fatalf("Accept of v2 = %q, %v", second.id, second.err)
			}
			if !waited {
				t.Error("Accept of v2 finished while a MarkDelivered of its key was open")
			}
			e.checkHeads(admin)
			if !e.isHead(second.id) {
				t.Error("v2 is not the head of a key with nothing else unfinished")
			}
			e.claimOne(second.id) // the property: v2 can be delivered
		})
	}
}

// TestAReplayWaitsForAnOpenFinishOfItsKey: a replayed row is a head only if its key has nothing
// unfinished, so it has the same race with a finish that an Accept has.
func TestAReplayWaitsForAnOpenFinishOfItsKey(t *testing.T) {
	for name, settings := range isolationDefaults {
		t.Run(name, func(t *testing.T) {
			e := setupWith(t, settings...)
			admin := e.adminConn()
			v1 := e.accept(tenantA, "task:1", 1)
			v2 := e.accept(tenantA, "task:1", 2)
			if err := e.ob.MarkDead(e.ctx, e.claimOne(v1), badShape); err != nil {
				t.Fatal(err)
			}
			commitV2 := e.deliverAndHold(e.claimOne(v2))

			replayed := make(chan error, 1)
			var finished atomic.Bool
			go func() {
				err := e.ob.Replay(e.ctx, tenantA, v1)
				finished.Store(true)
				replayed <- err
			}()
			waited := e.waitsOn(admin, onAnOrderingKey, finished.Load)

			commitV2()
			if err := <-replayed; err != nil {
				t.Fatal(err)
			}
			if !waited {
				t.Error("Replay of v1 finished while a MarkDelivered of its key was open")
			}
			e.checkHeads(admin)
			e.claimOne(v1)
		})
	}
}

// TestAFailedFinishIsNotALostLease is TestAnErrorIsNotALostLease for the statements INSIDE a
// finishing transition, which that test never reaches (it fails before the transaction begins).
// This is where errors happen in production: a finish waits for an open Accept of its entity, so a
// finish with a deadline runs out of time right on the key's lock. Read as ErrLeaseLost, that would
// make the worker drop a row it still holds and has already delivered to the sink, to be delivered
// again when the lease runs out. Each case makes one of the three statements fail, for a reason
// that has nothing to do with the lease, and wants: an error that is not ErrLeaseLost, a row that
// has not changed (the statements before the failed one are rolled back with it), and the same
// lease finishing the row once the obstacle is gone.
func TestAFailedFinishIsNotALostLease(t *testing.T) {
	finishers := map[string]func(*env, context.Context, outbox.Claimed) error{
		"MarkDelivered": func(e *env, ctx context.Context, c outbox.Claimed) error { return e.ob.MarkDelivered(ctx, c) },
		"MarkDead":      func(e *env, ctx context.Context, c outbox.Claimed) error { return e.ob.MarkDead(ctx, c, badShape) },
		"Fail to dead": func(e *env, ctx context.Context, c outbox.Claimed) error {
			return e.ob.Fail(ctx, c, outbox.Ladder{}, sink503)
		},
	}
	// A trigger that refuses one kind of change, as a stand-in for any error of the statement
	// that makes it.
	const refuse = `
		CREATE FUNCTION lawang.test_refuse() RETURNS trigger LANGUAGE plpgsql AS $$
		BEGIN
		  IF %s THEN RAISE EXCEPTION 'test: refused'; END IF;
		  RETURN NEW;
		END $$;
		CREATE TRIGGER test_refuse BEFORE UPDATE ON lawang.outbox
		  FOR EACH ROW EXECUTE FUNCTION lawang.test_refuse();`
	const allow = "DROP TRIGGER test_refuse ON lawang.outbox; DROP FUNCTION lawang.test_refuse();"

	// unchanged runs the finish, which must fail, and reports the error. v1 and v2 must be as before.
	unchanged := func(t *testing.T, e *env, v1, v2 string, finish func() error) error {
		t.Helper()
		before1, before2 := e.get(v1), e.get(v2)
		err := finish()
		if err == nil || errors.Is(err, outbox.ErrLeaseLost) {
			t.Errorf("err = %v, want an error that is not ErrLeaseLost", err)
		}
		if after := e.get(v1); !reflect.DeepEqual(before1, after) {
			t.Errorf("the row changed:\nbefore %+v\nafter  %+v", before1, after)
		}
		if after := e.get(v2); !reflect.DeepEqual(before2, after) {
			t.Errorf("the next row of the key changed:\nbefore %+v\nafter  %+v", before2, after)
		}
		return err
	}
	// afterwards: the lease is as good as it was, and the queue moves on.
	afterwards := func(t *testing.T, e *env, c outbox.Claimed, v2 string, finish func(*env, context.Context, outbox.Claimed) error) {
		t.Helper()
		if err := finish(e, e.ctx, c); err != nil {
			t.Fatalf("the same lease, once the obstacle is gone: %v", err)
		}
		e.checkHeads(e.adminConn())
		e.claimOne(v2)
	}

	for name, finish := range finishers {
		t.Run(name+"/the key's lock", func(t *testing.T) {
			e := setup(t)
			admin := e.adminConn()
			v1 := e.accept(tenantA, "task:7", 1)
			c1 := e.claimOne(v1)
			v2, commitV2 := e.acceptAndHold("task:7", 2)

			// Not a deadline that may or may not fall inside the lock statement: the context ends
			// once the finish is seen waiting for the lock.
			ctx, cancel := context.WithCancel(e.ctx)
			defer cancel()
			before := e.get(v1)
			result := make(chan error, 1)
			var finished atomic.Bool
			go func() {
				err := finish(e, ctx, c1)
				finished.Store(true)
				result <- err
			}()
			e.waitForLockWaiter(admin, onAnOrderingKey, finished.Load, name+" while an Accept of its key is open")
			cancel()
			err := <-result
			if err == nil || errors.Is(err, outbox.ErrLeaseLost) {
				t.Errorf("err = %v, want an error that is not ErrLeaseLost", err)
			}
			if !errors.Is(err, context.Canceled) {
				t.Errorf("err = %v, want it to wrap context.Canceled", err)
			}
			if after := e.get(v1); !reflect.DeepEqual(before, after) {
				t.Errorf("the row changed:\nbefore %+v\nafter  %+v", before, after)
			}

			commitV2()
			afterwards(t, e, c1, v2, finish)
		})

		t.Run(name+"/the state change", func(t *testing.T) {
			e := setup(t)
			v1 := e.accept(tenantA, "task:1", 1)
			v2 := e.accept(tenantA, "task:1", 2)
			c1 := e.claimOne(v1)
			e.admin(fmt.Sprintf(refuse, "NEW.state IN ('delivered', 'dead')"))
			err := unchanged(t, e, v1, v2, func() error { return finish(e, e.ctx, c1) })
			if sqlState(err) != "P0001" {
				t.Errorf("err = %v, want the server's error, still wrapped", err)
			}
			e.admin(allow)
			afterwards(t, e, c1, v2, finish)
		})

		// The finish itself went through, inside the transaction. It must not outlive the failure
		// of the promotion: a finished head with no successor is a key that is never claimed again.
		t.Run(name+"/the promotion", func(t *testing.T) {
			e := setup(t)
			v1 := e.accept(tenantA, "task:1", 1)
			v2 := e.accept(tenantA, "task:1", 2)
			c1 := e.claimOne(v1)
			e.admin(fmt.Sprintf(refuse, "NEW.is_head AND NOT OLD.is_head"))
			err := unchanged(t, e, v1, v2, func() error { return finish(e, e.ctx, c1) })
			if sqlState(err) != "P0001" {
				t.Errorf("err = %v, want the server's error, still wrapped", err)
			}
			e.admin(allow)
			afterwards(t, e, c1, v2, finish)
		})
	}
}

// TestTheMarkerFollowsTheQueue walks one key through every writer and looks at the marker after
// each: it is always on the earliest unfinished row, and nowhere else.
func TestTheMarkerFollowsTheQueue(t *testing.T) {
	e := setup(t)
	admin := e.adminConn()
	heads := func(step string, want map[string]bool) {
		t.Helper()
		e.checkHeads(admin)
		// The detection query agrees with the invariant at every step: nothing is stranded.
		if got, err := e.ob.StrandedKeys(e.ctx, tenantA, 10); err != nil || len(got) != 0 {
			t.Fatalf("%s: StrandedKeys = %q, %v, want none", step, got, err)
		}
		for id, isHead := range want {
			if got := e.isHead(id); got != isHead {
				t.Fatalf("%s: row %s is a head = %v, want %v", step, id, got, isHead)
			}
		}
	}

	v1 := e.accept(tenantA, "task:1", 1)
	v2 := e.accept(tenantA, "task:1", 2)
	v3 := e.accept(tenantA, "task:1", 3)
	heads("accepted", map[string]bool{v1: true, v2: false, v3: false})

	// A retry keeps the marker: the key waits with its head.
	c1 := e.claimOne(v1)
	if err := e.ob.Fail(e.ctx, c1, outbox.Ladder{time.Hour}, sink503); err != nil {
		t.Fatal(err)
	}
	heads("v1 backing off", map[string]bool{v1: true, v2: false, v3: false})
	e.admin("UPDATE lawang.outbox SET next_attempt_at = now() - interval '1 second' WHERE id = '" + v1 + "'")

	// A dead letter gives it up, to the next row and not to the last.
	if err := e.ob.MarkDead(e.ctx, e.claimOne(v1), badShape); err != nil {
		t.Fatal(err)
	}
	heads("v1 dead", map[string]bool{v1: false, v2: true, v3: false})

	// A replay onto a key with unfinished rows joins the back, without the marker.
	if err := e.ob.Replay(e.ctx, tenantA, v1); err != nil {
		t.Fatal(err)
	}
	heads("v1 replayed behind v2 and v3", map[string]bool{v1: false, v2: true, v3: false})

	c2 := e.claimOne(v2)
	if err := e.ob.MarkPrepared(e.ctx, c2); err != nil {
		t.Fatal(err)
	}
	heads("v2 prepared", map[string]bool{v1: false, v2: true, v3: false})
	if err := e.ob.MarkDelivered(e.ctx, c2); err != nil {
		t.Fatal(err)
	}
	heads("v2 delivered", map[string]bool{v1: false, v2: false, v3: true})

	if err := e.ob.MarkDead(e.ctx, e.claimOne(v3), badShape); err != nil {
		t.Fatal(err)
	}
	heads("v3 dead", map[string]bool{v1: true, v2: false, v3: false})
	if err := e.ob.MarkDelivered(e.ctx, e.claimOne(v1)); err != nil {
		t.Fatal(err)
	}
	heads("v1 delivered, nothing unfinished", map[string]bool{v1: false, v2: false, v3: false})

	// A replay onto a key with nothing unfinished is a head at once.
	if err := e.ob.Replay(e.ctx, tenantA, v3); err != nil {
		t.Fatal(err)
	}
	heads("v3 replayed onto an empty queue", map[string]bool{v1: false, v2: false, v3: true})
	e.claimOne(v3)
}

package outbox

import "time"

// Ladder is the retry schedule: element i is the wait after attempt i+1 fails.
type Ladder []time.Duration

// DefaultLadder gives a failing sink about a day to come back before a row is parked.
var DefaultLadder = Ladder{
	5 * time.Second,
	30 * time.Second,
	2 * time.Minute,
	10 * time.Minute,
	time.Hour,
	6 * time.Hour,
	12 * time.Hour,
}

// Next returns how long to wait after the given number of attempts have failed. ok is false when
// the ladder is used up and the row should become a dead letter. An attempt count below 1 is a
// caller bug, and is answered with "give up" so it cannot turn into a free retry loop.
func (l Ladder) Next(attempts int) (delay time.Duration, ok bool) {
	if attempts < 1 || attempts > len(l) {
		return 0, false
	}
	return l[attempts-1], true //nolint:gosec // G602: bounds checked on the line above
}

package outbox

import (
	"testing"
	"time"
)

func TestLadderNext(t *testing.T) {
	l := Ladder{time.Second, time.Minute}
	tests := []struct {
		attempts int
		want     time.Duration
		ok       bool
	}{
		{1, time.Second, true},
		{2, time.Minute, true},
		{3, 0, false}, // used up: dead letter
		{0, 0, false}, // a caller bug must not become a free retry
		{-1, 0, false},
	}
	for _, tt := range tests {
		got, ok := l.Next(tt.attempts)
		if got != tt.want || ok != tt.ok {
			t.Errorf("Next(%d) = %v, %v, want %v, %v", tt.attempts, got, ok, tt.want, tt.ok)
		}
	}
	if _, ok := (Ladder{}).Next(1); ok {
		t.Error("an empty ladder offered a retry")
	}
}

func TestDefaultLadderOnlyClimbs(t *testing.T) {
	for i := 1; i < len(DefaultLadder); i++ {
		if DefaultLadder[i] <= DefaultLadder[i-1] {
			t.Errorf("step %d (%v) does not exceed step %d (%v)", i, DefaultLadder[i], i-1, DefaultLadder[i-1])
		}
	}
}

// Package outbox is Lawang's only queue: a Postgres table whose row states are the retry and
// dead-letter machinery.
//
// A row moves pending -> prepared -> delivered, or to dead. A claim is a lease on the HEAD of an
// ordering key (the unfinished row with the lowest seq for one source entity), so the versions of
// an entity deliver one at a time, in queue order, while different entities proceed in parallel.
//
// Being the head is a stored column, is_head, and not something the claim works out: the claim
// walks an index of due heads and stops at its batch, so a poll costs what it returns, however
// much is waiting behind the heads, in backoff, or leased to other workers. The record of that
// decision, and the full correctness argument, is docs/adr/0010-outbox-head-marker.md. In brief:
//
//   - Safety is the database's. A unique index allows one head per key, a CHECK says a head is
//     unfinished, and the claim re-checks is_head on the row it has locked. An unfinished row keeps
//     the marker until it finishes. So two rows of one key are never in flight together, whatever
//     the callers do.
//   - Liveness and order are the writers'. Every writer that changes which rows of a key are
//     unfinished (Accept, Replay, MarkDelivered, MarkDead) first takes a transaction-scoped
//     advisory lock on the key. Within one key they therefore run one after the other: a lower seq
//     always commits first, a new row knows whether it is the head, and the row that finishes the
//     head hands the marker to the next one, with no window in which the two can miss each other.
//
// Queue order is arrival order, with one exception: a replayed dead letter goes to the back.
package outbox

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"
	"unicode/utf8"

	"github.com/jackc/pgx/v5"

	"github.com/gablooge/lawang/internal/ids"
	"github.com/gablooge/lawang/internal/outbox/outboxdb"
	"github.com/gablooge/lawang/internal/store"
	"github.com/gablooge/lawang/internal/tenancy"
)

// Row states.
const (
	StatePending   = "pending"
	StatePrepared  = "prepared"
	StateDelivered = "delivered"
	StateDead      = "dead"
)

// maxErrorLen bounds what is kept of an error message.
const maxErrorLen = 1000

// MaxOrderingKeyLen is the longest ordering key Accept takes, in bytes. An entity id is a few dozen
// bytes. The bound exists because the key is a column of two indexes, and a btree tuple cannot
// exceed about 2700 bytes: without it, whether a long key can be stored depends on how well it
// compresses. The table has a CHECK for the same number.
const MaxOrderingKeyLen = 512

// MaxBatch is the most rows one Claim leases, whatever it is asked for.
const MaxBatch = 1000

// ErrLeaseLost reports a transition by a worker that no longer holds the row: its lease ran out
// and another worker took over, or the row already finished. The caller must stop working on it.
var ErrLeaseLost = errors.New("outbox: lease lost")

// ErrNotFound reports a row that does not exist for this tenant.
var ErrNotFound = errors.New("outbox: not found")

// ErrBadOrderingKey reports a delivery whose ordering key is not 1 to MaxOrderingKeyLen bytes of
// valid UTF-8 with no NUL byte. (Postgres stores neither a NUL nor invalid UTF-8 in text, and a NUL
// is one JSON escape away from any sender: encoding/json decodes the escape for U+0000 inside an
// entity id into that byte.) Such a key can never be stored, however often it is sent again, so a
// caller that answers a provider must treat it as poison (park it, answer 2xx) and not as a
// failure to retry.
var ErrBadOrderingKey = errors.New("outbox: ordering key must be 1 to 512 bytes of valid UTF-8 with no NUL")

// errBadProvider is deliberately not exported: the provider is the connector's own name for
// itself, a constant of this program and nothing a sender chooses, so a bad one is a bug to fix
// and not a case for a caller to handle. It is still refused here, by name, because the
// alternative is the database's "invalid byte sequence", which names nothing.
var errBadProvider = errors.New("outbox: provider must be valid UTF-8 with no NUL")

// Outbox reads and writes the outbox table.
type Outbox struct {
	db *store.DB
}

// New returns an Outbox on db.
func New(db *store.DB) *Outbox { return &Outbox{db: db} }

// Delivery is one accepted webhook, or one change synthesized by reconciliation.
type Delivery struct {
	// Provider is the internal provider key, and it must be a constant of the program: a key
	// from the provider registry, never text taken from a request (not a path segment, a header
	// or a payload field). Accept refuses a provider that cannot be stored with an error that is
	// deliberately NOT a sentinel, because a bad provider is a bug in the caller, not poison from
	// a sender. A caller that passed request text here would turn a crafted request into a
	// server error, and a provider into a retry storm. Look the provider up in the registry
	// first, and answer an unknown one before reaching the outbox.
	Provider string
	// OrderingKey names the source entity. Rows sharing a key deliver in arrival order.
	OrderingKey string
	// RawBody is stored, and hashed into the delivery id, exactly as received.
	RawBody []byte
}

// Claimed is a leased row, and the only thing that can move it on. It deliberately carries no
// payload: claiming runs across tenants, and the payload is only ever read bound to Tenant.
//
// It can be read and not changed or built: only Claim makes one that any transition accepts. The
// tenant in particular is the one the row was claimed under, because every transition binds
// row-level security to it. (A Claimed aimed at another tenant would change nothing, since that
// tenant cannot see the row. It should not be possible to write one by accident either.)
type Claimed struct {
	id      string
	tenant  tenancy.ID
	attempt int
	token   string
}

// ID is the row's id.
func (c Claimed) ID() string { return c.id }

// Tenant is the tenant that owns the row. Bind to it before reading the payload.
func (c Claimed) Tenant() tenancy.ID { return c.tenant }

// Attempt counts the claims of this row, starting at 1.
func (c Claimed) Attempt() int { return c.attempt }

// Row is a full outbox row, as its own tenant sees it.
type Row = outboxdb.GetRow

// Accept stores a delivery for the tenant that owns the verified subscription. fresh is false for
// a delivery this tenant already has, which makes a provider's re-send a no-op.
//
// Two Accepts for one ordering key run one after the other: the second waits until the first has
// committed, and so does an Accept that meets a MarkDelivered, MarkDead or Replay of its key. See
// LockOrderingKey in queries.sql. The new row is claimable at once if its entity has nothing
// unfinished, and otherwise when the rows ahead of it have finished.
func (o *Outbox) Accept(ctx context.Context, tenant tenancy.ID, d Delivery) (id string, fresh bool, err error) {
	err = o.db.TenantTx(ctx, tenant, func(tx pgx.Tx) (err error) {
		id, fresh, err = acceptIn(ctx, tx, tenant, d)
		return err
	})
	if err != nil {
		return "", false, err
	}
	return id, fresh, nil
}

// acceptIn is Accept inside a transaction already bound to tenant.
func acceptIn(ctx context.Context, tx pgx.Tx, tenant tenancy.ID, d Delivery) (id string, fresh bool, err error) {
	if d.OrderingKey == "" || len(d.OrderingKey) > MaxOrderingKeyLen || !storable(d.OrderingKey) {
		// The length is reported, the key is not, and neither is the byte that is wrong with it:
		// all of it is derived from what a sender sent.
		return "", false, fmt.Errorf("%w, got %d bytes", ErrBadOrderingKey, len(d.OrderingKey))
	}
	deliveryID, err := ids.DeliveryID(d.Provider, d.RawBody) // refuses an empty provider
	if err != nil {
		return "", false, err
	}
	if !storable(d.Provider) {
		return "", false, errBadProvider
	}
	q := outboxdb.New(tx)
	// Before the INSERT, which assigns seq and decides whether the row is the head of its key, and
	// as a statement of its own.
	err = q.LockOrderingKey(ctx, outboxdb.LockOrderingKeyParams{TenantID: tenant.String(), OrderingKey: d.OrderingKey})
	if err != nil {
		return "", false, fmt.Errorf("outbox: accept: %w", err)
	}
	id = ids.New()
	_, err = q.Accept(ctx, outboxdb.AcceptParams{
		ID:          id,
		TenantID:    tenant.String(),
		Provider:    d.Provider,
		DeliveryID:  deliveryID,
		OrderingKey: d.OrderingKey,
		RawBody:     d.RawBody,
	})
	switch {
	case errors.Is(err, pgx.ErrNoRows): // ON CONFLICT DO NOTHING returned nothing
		return "", false, nil
	case err != nil:
		return "", false, fmt.Errorf("outbox: accept: %w", err)
	}
	return id, true, nil
}

// Claim leases up to batch rows for the given duration, across tenants, as the worker role. Rows
// locked by a concurrent claimer are skipped, never waited for.
//
// It never leases more than MaxBatch rows: a larger batch is cut to that, silently, so a caller
// that sizes anything by its batch should not ask for more. A batch or a lease that is not
// positive is refused. (A lease of zero would hand out rows that are claimable again at once, and
// every poll would use up one attempt of the ladder with no delivery ever tried.)
func (o *Outbox) Claim(ctx context.Context, batch int, lease time.Duration) ([]Claimed, error) {
	if batch <= 0 || lease <= 0 {
		return nil, errors.New("outbox: claim needs a positive batch size and lease")
	}
	token := ids.New()
	var claimed []Claimed
	err := o.db.RoleTx(ctx, store.RoleWorker, func(tx pgx.Tx) error {
		rows, err := outboxdb.New(tx).Claim(ctx, outboxdb.ClaimParams{
			LeaseSeconds: lease.Seconds(),
			LeaseToken:   token,
			BatchSize:    int32(min(batch, MaxBatch)), //nolint:gosec // bounded just here
		})
		if err != nil {
			return err
		}
		claimed = make([]Claimed, 0, len(rows))
		for _, r := range rows {
			tenant, err := tenancy.Parse(r.TenantID)
			if err != nil {
				return err
			}
			claimed = append(claimed, Claimed{id: r.ID, tenant: tenant, attempt: int(r.Attempts), token: token})
		}
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("outbox: claim: %w", err)
	}
	return claimed, nil
}

// Get returns a row as its tenant sees it.
func (o *Outbox) Get(ctx context.Context, tenant tenancy.ID, id string) (Row, error) {
	if !storable(id) {
		return Row{}, ErrNotFound // no row has such an id, and the database would not say so
	}
	var row Row
	err := o.db.TenantTx(ctx, tenant, func(tx pgx.Tx) (err error) {
		row, err = outboxdb.New(tx).Get(ctx, id)
		return err
	})
	if errors.Is(err, pgx.ErrNoRows) {
		return Row{}, ErrNotFound
	}
	return row, err
}

// MarkPrepared records that the ledger rows and prepared records are committed. After this, a
// crash re-drains into delivery, not into preparing again.
func (o *Outbox) MarkPrepared(ctx context.Context, c Claimed) error {
	return o.transition(ctx, c, func(tx pgx.Tx) error {
		return held(outboxdb.New(tx).MarkPrepared(ctx, outboxdb.MarkPreparedParams{ID: c.id, LeaseToken: c.token}))
	})
}

// MarkDelivered finishes the row, and makes the next version of its entity claimable.
func (o *Outbox) MarkDelivered(ctx context.Context, c Claimed) error {
	return o.transition(ctx, c, func(tx pgx.Tx) error { return markDeliveredIn(ctx, tx, c) })
}

// markDeliveredIn is MarkDelivered inside a transaction already bound to the row's tenant.
func markDeliveredIn(ctx context.Context, tx pgx.Tx, c Claimed) error {
	return finishIn(ctx, tx, c, func(q *outboxdb.Queries) (string, error) {
		return q.MarkDelivered(ctx, outboxdb.MarkDeliveredParams{ID: c.id, LeaseToken: c.token})
	})
}

// finishIn runs one of the two transitions that finish a row, and hands the head marker on. The
// order is fixed, and each step is a statement of its own:
//
//  1. The ordering key's lock, as in Accept. It comes before any row lock, here as everywhere, so
//     that no two transactions ever wait for each other.
//  2. The lease-guarded state change, which also gives up the marker. No row means the lease was
//     lost: nothing changed, and nothing is promoted.
//  3. The promotion of the key's next unfinished row. Its snapshot is taken after step 1, so it
//     sees every row of the key an earlier lock holder committed, and no Accept or Replay of the
//     key is open while it runs. Without the lock, an Accept that saw this row unfinished would
//     insert a non-head that this statement cannot see yet, and that row would wait forever.
func finishIn(ctx context.Context, tx pgx.Tx, c Claimed, finish func(*outboxdb.Queries) (orderingKey string, err error)) error {
	q := outboxdb.New(tx)
	if err := q.LockOrderingKeyOf(ctx, c.id); err != nil {
		return err
	}
	key, err := finish(q)
	switch {
	case errors.Is(err, pgx.ErrNoRows):
		return ErrLeaseLost
	case err != nil:
		return err
	}
	return q.PromoteNextHead(ctx, outboxdb.PromoteNextHeadParams{TenantID: c.tenant.String(), OrderingKey: key})
}

// Why a row is dead, as stored in dead_reason. Fixed texts: what went wrong is the Cause.
const (
	reasonRetriesExhausted = "retries exhausted"
	reasonNotRetryable     = "not retryable"
)

// Fail handles a retryable failure: it schedules the next attempt from the ladder, or parks the
// row as a dead letter once the ladder is used up. What went wrong is a Cause and never an error
// string: see Cause for why.
func (o *Outbox) Fail(ctx context.Context, c Claimed, ladder Ladder, cause Cause) error {
	delay, ok := ladder.Next(c.attempt)
	if !ok {
		return o.markDead(ctx, c, reasonRetriesExhausted, cause)
	}
	return o.transition(ctx, c, func(tx pgx.Tx) error {
		return held(outboxdb.New(tx).Retry(ctx, outboxdb.RetryParams{
			ID: c.id, LeaseToken: c.token, DelaySeconds: delay.Seconds(), LastError: clip(cause.String()),
		}))
	})
}

// MarkDead parks the row as a dead letter, for failures that retrying cannot fix. A dead row no
// longer holds back newer versions of its entity: the next one becomes claimable. Like Fail, it
// takes a Cause and no text.
func (o *Outbox) MarkDead(ctx context.Context, c Claimed, cause Cause) error {
	return o.markDead(ctx, c, reasonNotRetryable, cause)
}

func (o *Outbox) markDead(ctx context.Context, c Claimed, reason string, cause Cause) error {
	return o.transition(ctx, c, func(tx pgx.Tx) error {
		return finishIn(ctx, tx, c, func(q *outboxdb.Queries) (string, error) {
			return q.MarkDead(ctx, outboxdb.MarkDeadParams{
				ID: c.id, LeaseToken: c.token, DeadReason: reason, LastError: clip(cause.String()),
			})
		})
	})
}

// Replay makes a dead letter claimable again, at the BACK of its entity's queue: a newer version
// may be in flight right now, and the replayed row must not be leased alongside it. It is
// delivered after every version accepted before the replay, as a late arrival of an old version.
// A row that died after it was prepared comes back prepared, and is not prepared again.
func (o *Outbox) Replay(ctx context.Context, tenant tenancy.ID, id string) error {
	if !storable(id) {
		return ErrNotFound // as in Get
	}
	var n int64
	err := o.db.TenantTx(ctx, tenant, func(tx pgx.Tx) (err error) {
		q := outboxdb.New(tx)
		// Before the UPDATE, which assigns the new seq and decides whether the row is the head of
		// its key, and as a statement of its own.
		if err := q.LockOrderingKeyOf(ctx, id); err != nil {
			return err
		}
		n, err = q.Replay(ctx, id)
		return err
	})
	if err != nil {
		return fmt.Errorf("outbox: replay: %w", err)
	}
	if n == 0 {
		return ErrNotFound
	}
	return nil
}

// StrandedKeys returns ordering keys of the tenant that have unfinished rows and no head, in key
// order, at most limit of them and never more than MaxBatch. A limit that is not positive is
// refused. An empty result is the healthy state.
//
// A stranded key is the one way the head marker can be broken without anybody noticing: nothing
// of the key is ever claimed again, and no error is raised anywhere. No writer of this package
// leaves a key like that (docs/adr/0010-outbox-head-marker.md has the argument, and the statement
// that repairs one), so a key returned here was written behind the package's back, or by a bug.
// This is detection only, for a sweep or an operator: nothing in the delivery path calls it. It
// costs the tenant's unfinished rows, not the size of the table (tens of milliseconds for a
// backlog of 100,000), so it is for a sweep that runs now and then, not for every poll.
//
// It is scoped to a tenant because it needs the state and the ordering key of a row, which only
// the row's tenant may read. The worker role, which sees across tenants, sees neither.
func (o *Outbox) StrandedKeys(ctx context.Context, tenant tenancy.ID, limit int) ([]string, error) {
	if limit <= 0 {
		return nil, errors.New("outbox: stranded keys needs a positive limit")
	}
	var keys []string
	err := o.db.TenantTx(ctx, tenant, func(tx pgx.Tx) (err error) {
		keys, err = outboxdb.New(tx).StrandedKeys(ctx, outboxdb.StrandedKeysParams{
			TenantID: tenant.String(),
			MaxKeys:  int32(min(limit, MaxBatch)), //nolint:gosec // bounded just here
		})
		return err
	})
	if err != nil {
		return nil, fmt.Errorf("outbox: stranded keys: %w", err)
	}
	return keys, nil
}

// transition runs one lease-guarded state change bound to the row's own tenant. change returns
// ErrLeaseLost when the guard matched no row, and only then: a database or context error is never
// reported as a lost lease, because the two tell a worker opposite things (stop working on the
// row, or try the transition again while the lease lasts).
func (o *Outbox) transition(ctx context.Context, c Claimed, change func(pgx.Tx) error) error {
	if c.token == "" {
		return ErrLeaseLost
	}
	err := o.db.TenantTx(ctx, c.tenant, change)
	switch {
	case errors.Is(err, ErrLeaseLost):
		return ErrLeaseLost
	case err != nil:
		return fmt.Errorf("outbox: %w", err)
	}
	return nil
}

// held turns the row count of a lease-guarded UPDATE into ErrLeaseLost when it matched nothing.
func held(rows int64, err error) error {
	if err == nil && rows == 0 {
		return ErrLeaseLost
	}
	return err
}

// storable reports whether Postgres takes s as a text value at all: it refuses a NUL byte and
// anything that is not valid UTF-8 with SQLSTATE 22021, which a caller cannot tell from an outage.
// Every text that reaches a statement from outside this package is asked this first.
func storable(s string) bool {
	return utf8.ValidString(s) && strings.IndexByte(s, 0) < 0
}

// clip makes s storable and bounded: valid UTF-8 with no NUL (Postgres rejects both in text, and a
// failure that cannot be recorded is never backed off or parked), and at most maxErrorLen bytes,
// cut between runes.
func clip(s string) string {
	s = strings.ToValidUTF8(s, "�")
	s = strings.ReplaceAll(s, "\x00", "�")
	if len(s) <= maxErrorLen {
		return s
	}
	cut := maxErrorLen
	for cut > 0 && !utf8.RuneStart(s[cut]) {
		cut--
	}
	return s[:cut]
}

package outbox_test

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"reflect"
	"slices"
	"strings"
	"sync"
	"testing"
	"time"
	"unicode/utf8"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"

	"github.com/gablooge/lawang/internal/outbox"
	"github.com/gablooge/lawang/internal/store"
	"github.com/gablooge/lawang/internal/tenancy"
	"github.com/gablooge/lawang/internal/testdb"
)

const (
	tenantA = tenancy.ID("tenant_a")
	tenantB = tenancy.ID("tenant_b")
	lease   = time.Minute
)

// The failures the tests record.
var (
	badShape    = outbox.NewCause(outbox.ClassNormalizer)
	sink503     = outbox.NewCause(outbox.ClassSinkUnavailable).WithStatus(503)
	sinkTimeout = outbox.NewCause(outbox.ClassSinkUnavailable)
)

type env struct {
	t   *testing.T
	ctx context.Context
	db  *store.DB
	ob  *outbox.Outbox
	tdb testdb.Database
}

// setup gives a test its own migrated database. plannerOff names planner settings (enable_nestloop
// and the like) to turn off for every session of that database, for the tests that must hold
// whatever plan the claim gets.
func setup(t *testing.T, plannerOff ...string) *env {
	t.Helper()
	settings := make([]string, len(plannerOff))
	for i, setting := range plannerOff {
		settings[i] = setting + " = off"
	}
	return setupWith(t, settings...)
}

// setupWith is setup for a database with settings of its own, each written as in ALTER DATABASE
// ... SET: "name = value". The database is the test's own, so this changes nothing for any other.
func setupWith(t *testing.T, settings ...string) *env {
	t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
	t.Cleanup(cancel)
	tdb := testdb.New(t)
	for _, setting := range settings { // before the pool opens: a session reads these when it starts
		testdb.Exec(t, tdb.AdminURL, fmt.Sprintf(
			`DO $do$ BEGIN EXECUTE format($f$ALTER DATABASE %%I SET %s$f$, current_database()); END $do$`, setting))
	}
	db, err := store.Open(ctx, tdb.URL)
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	t.Cleanup(db.Close)
	if _, err := db.Migrate(ctx, slog.New(slog.NewTextHandler(io.Discard, nil))); err != nil {
		t.Fatalf("Migrate: %v", err)
	}
	return &env{t: t, ctx: ctx, db: db, ob: outbox.New(db), tdb: tdb}
}

// accept stores a delivery whose body is unique to (key, version).
func (e *env) accept(tenant tenancy.ID, key string, version int) string {
	e.t.Helper()
	id, fresh, err := e.ob.Accept(e.ctx, tenant, outbox.Delivery{
		Provider: "fake", OrderingKey: key, RawBody: fmt.Appendf(nil, `{"key":%q,"v":%d}`, key, version),
	})
	if err != nil || !fresh {
		e.t.Fatalf("Accept(%s, %s, v%d) = fresh %v, err %v", tenant, key, version, fresh, err)
	}
	return id
}

func (e *env) claim() []outbox.Claimed {
	e.t.Helper()
	got, err := e.ob.Claim(e.ctx, 10, lease)
	if err != nil {
		e.t.Fatalf("Claim: %v", err)
	}
	return got
}

func (e *env) claimOne(wantID string) outbox.Claimed {
	e.t.Helper()
	got := e.claim()
	if len(got) != 1 || got[0].ID() != wantID {
		e.t.Fatalf("Claim = %v, want exactly row %s", claimedIDs(got), wantID)
	}
	return got[0]
}

func (e *env) claimNone(why string) {
	e.t.Helper()
	if got := e.claim(); len(got) != 0 {
		e.t.Fatalf("Claim = %v, want nothing: %s", claimedIDs(got), why)
	}
}

// admin changes rows behind the application's back, to move time along.
func (e *env) admin(sql string) { testdb.Exec(e.t, e.tdb.AdminURL, sql) }

func claimedIDs(cs []outbox.Claimed) []string {
	out := make([]string, len(cs))
	for i, c := range cs {
		out[i] = c.ID()
	}
	return out
}

func TestAcceptIsIdempotentPerTenant(t *testing.T) {
	e := setup(t)
	d := outbox.Delivery{Provider: "fake", OrderingKey: "task:1", RawBody: []byte(`{"a":1}`)}

	id, fresh, err := e.ob.Accept(e.ctx, tenantA, d)
	if err != nil || !fresh || id == "" {
		t.Fatalf("first Accept = %q, %v, %v", id, fresh, err)
	}
	again, fresh, err := e.ob.Accept(e.ctx, tenantA, d)
	if err != nil || fresh || again != "" {
		t.Fatalf("re-sent Accept = %q, fresh %v, err %v, want a no-op", again, fresh, err)
	}

	// Two tenants may connect the same provider workspace. The second one's identical delivery is
	// its own, not a duplicate of the first tenant's.
	if _, fresh, err := e.ob.Accept(e.ctx, tenantB, d); err != nil || !fresh {
		t.Fatalf("same bytes for another tenant: fresh %v, err %v, want accepted", fresh, err)
	}

	if got := e.claim(); len(got) != 2 {
		t.Errorf("claimable rows = %d, want 2 (one per tenant)", len(got))
	}
}

func TestAcceptRefusesBadInput(t *testing.T) {
	e := setup(t)
	for name, d := range map[string]outbox.Delivery{
		"no provider":     {OrderingKey: "k", RawBody: []byte("x")},
		"no ordering key": {Provider: "fake", RawBody: []byte("x")},
		// The provider is the connector's own constant, so these are bugs and have no sentinel.
		// They are still refused by this package, in words, and not by the database in bytes.
		"a NUL in the provider":         {Provider: "fa\x00ke", OrderingKey: "k", RawBody: []byte("x")},
		"invalid UTF-8 in the provider": {Provider: "fa\xffke", OrderingKey: "k", RawBody: []byte("x")},
	} {
		_, _, err := e.ob.Accept(e.ctx, tenantA, d)
		if err == nil {
			t.Errorf("%s: accepted", name)
		}
		if sqlState(err) != "" {
			t.Errorf("%s: the refusal came from the database (%v), want it made before the database is asked", name, err)
		}
	}
	if _, _, err := e.ob.Accept(e.ctx, tenancy.ID(""), outbox.Delivery{Provider: "fake", OrderingKey: "k"}); err == nil {
		t.Error("accepted a delivery with no tenant")
	}
}

// TestAcceptRefusesAnOrderingKeyItCannotStore: a key is derived from what a sender sent. One that
// is too long for an index tuple would fail the INSERT, or not, depending on how well it
// compresses, and the caller could not tell that from the database being down. It is refused by
// name instead, so that the ingress can park the delivery as poison and answer 2xx.
func TestAcceptRefusesAnOrderingKeyItCannotStore(t *testing.T) {
	e := setup(t)
	accept := func(key string) error {
		_, _, err := e.ob.Accept(e.ctx, tenantA, outbox.Delivery{Provider: "fake", OrderingKey: key, RawBody: []byte(key)})
		return err
	}
	if err := accept(strings.Repeat("k", outbox.MaxOrderingKeyLen)); err != nil {
		t.Errorf("a key of MaxOrderingKeyLen bytes: %v, want accepted", err)
	}
	unstorable := map[string]string{
		"one byte too long": strings.Repeat("k", outbox.MaxOrderingKeyLen+1),
		// Bytes, not characters: 256 two-byte runes are 512 bytes, 257 are not.
		"one rune too long": strings.Repeat("é", outbox.MaxOrderingKeyLen/2+1),
		// 100,000 of one character compress into an index tuple, and used to be accepted.
		"long but compressible": strings.Repeat("k", 100_000),
		"empty":                 "",
		// Postgres stores neither in text. A NUL is one JSON escape away: encoding/json decodes
		// the escape for U+0000 inside an entity id into this byte without complaint.
		"a NUL":                "task:\x001-secret",
		"only a NUL":           "\x00",
		"a NUL at the end":     "task:12-secret\x00",
		"invalid UTF-8":        "task:\xff\xfe-secret",
		"a truncated rune":     "task:12-secret\xc3",
		"a surrogate, encoded": "task:\xed\xa0\x80-secret",
	}
	for name, key := range unstorable {
		err := accept(key)
		if !errors.Is(err, outbox.ErrBadOrderingKey) {
			t.Errorf("%s: err = %v, want ErrBadOrderingKey", name, err)
		}
		if sqlState(err) != "" {
			t.Errorf("%s: the refusal came from the database (%v), want it made before the database is asked", name, err)
		}
		if err != nil && (len(key) >= 8 && strings.Contains(err.Error(), key[:8]) || strings.Contains(err.Error(), "secret")) {
			t.Errorf("%s: the error quotes the key: %v", name, err)
		}
	}
	// Nothing of the refused deliveries is there, and the queue is as usable as before.
	var stored int
	if err := e.adminConn().QueryRow(e.ctx, "SELECT count(*) FROM lawang.outbox").Scan(&stored); err != nil {
		t.Fatal(err)
	}
	if stored != 1 {
		t.Errorf("%d rows stored, want only the one key that was accepted", stored)
	}
	// What is merely unusual is a key like any other: valid UTF-8 of any script, and control
	// characters other than NUL.
	for name, key := range map[string]string{
		"four-byte runes":   "task:\U0001F600\U0001F600",
		"a control byte":    "task:\x01\x1f\x7f",
		"U+FFFD, as itself": "task:\uFFFD",
	} {
		if err := accept(key); err != nil {
			t.Errorf("%s: %v, want accepted", name, err)
		}
	}
	if err := accept(strings.Repeat("é", outbox.MaxOrderingKeyLen/2)); err != nil {
		t.Errorf("256 two-byte runes, which are 512 bytes: %v, want accepted", err)
	}

	// The table says the same, for a writer that does not come through Accept.
	err := e.adminErr(fmt.Sprintf(`INSERT INTO lawang.outbox (id, tenant_id, provider, delivery_id, ordering_key, raw_body)
	                               VALUES ('x', 'tenant_a', 'fake', 'x', repeat('k', %d), '')`, outbox.MaxOrderingKeyLen+1))
	if sqlState(err) != "23514" {
		t.Errorf("a raw INSERT of a key one byte too long: err = %v, want a check violation", err)
	}
}

