// TestStressOrderingUnderRandomLoad runs every writer of the outbox at once, on a few hot keys:
// acceptors, workers that deliver or dead-letter what they claim, and an operator replaying the
// dead letters. It asserts what the package promises, while it runs and at the end:
//
//   - never two rows of one key in flight together;
//   - each key's rows are claimed in queue order (a replayed row has a fresh seq, at the back);
//   - the head marker's invariant holds on every snapshot, not only once things are quiet;
//   - every row ends up delivered: no row is left behind a marker that was never handed on.
//
// The choices (which key, deliver or dead-letter) come from a seed, logged so that a failure can be
// run again with OUTBOX_STRESS_SEED. The scheduling of goroutines is not reproducible, the mix is.
// A run that stops making progress fails within seconds instead of hanging.
//
// What it is NOT a test of: the claim's re-checks on the row it has locked. The window between a
// claim's snapshot and its row lock is too short for random load to hit. With the is_head re-check
// taken out, this test passed 10 runs of 10 in review, and a missing lock in the finishers gets
// past it about every second run. Those properties belong to the TestClaimRechecks... tests and
// the three lost-promotion tests in interleaving_test.go, which hold a transaction at the exact
// point. This one is for what nobody thought of.
func TestStressOrderingUnderRandomLoad(t *testing.T) {
	const (
		acceptors    = 6
		perAcceptor  = 40
		workers      = 8
		keys         = 4
		deadPercent  = 30
		stallTimeout = 20 * time.Second
	)
	seed := uint64(time.Now().UnixNano()) //nolint:gosec // any 64 bits will do
	if s := os.Getenv("OUTBOX_STRESS_SEED"); s != "" {
		parsed, err := strconv.ParseUint(s, 10, 64)
		if err != nil {
			t.Fatalf("OUTBOX_STRESS_SEED: %v", err)
		}
		seed = parsed
	}
	t.Logf("seed %d (run again with OUTBOX_STRESS_SEED=%d)", seed, seed)

	e := setup(t)
	ctx, stop := context.WithCancel(e.ctx)
	defer stop()
	var failed atomic.Bool
	fail := func(format string, args ...any) {
		t.Helper()
		if failed.CompareAndSwap(false, true) {
			t.Errorf(format, args...)
		}
		stop() // fail fast: everyone else winds down
	}
	running := func() bool { return ctx.Err() == nil }

	type dead struct {
		tenant tenancy.ID
		id     string
	}
	var (
		mu        sync.Mutex
		inFlight  = map[string]string{} // tenant/key -> row id
		lastSeq   = map[string]int64{}
		diedOnce  = map[string]bool{}
		delivered atomic.Int64
		replays   atomic.Int64
		toReplay  = make(chan dead, acceptors*perAcceptor)
		total     = int64(acceptors * perAcceptor)
		all       sync.WaitGroup
	)

	for a := range acceptors {
		all.Go(func() {
			rng := rand.New(rand.NewPCG(seed, uint64(a))) //nolint:gosec // a reproducible mix, not a secret
			for i := 0; i < perAcceptor && running(); i++ {
				// Paced to about the rate the workers drain at, so that the queues stay nearly
				// empty. That is where the marker is at risk: a promotion can only be lost when
				// the row that finishes is the last unfinished row of its key, and an Accept of
				// that key is open at that very moment. Deep queues would hide it.
				time.Sleep(time.Duration(rng.IntN(4000)) * time.Microsecond)
				tenant := tenantA
				if rng.IntN(2) == 1 {
					tenant = tenantB
				}
				_, fresh, err := e.ob.Accept(ctx, tenant, outbox.Delivery{
					Provider:    "fake",
					OrderingKey: fmt.Sprintf("hot:%d", rng.IntN(keys)),
					RawBody:     fmt.Appendf(nil, `{"acceptor":%d,"n":%d}`, a, i),
				})
				if running() && (err != nil || !fresh) {
					fail("Accept: fresh %v, err %v", fresh, err)
				}
			}
		})
	}

	for w := range workers {
		all.Go(func() {
			rng := rand.New(rand.NewPCG(seed, uint64(1000+w))) //nolint:gosec // as above
			for running() && delivered.Load() < total {
				got, err := e.ob.Claim(ctx, 1+rng.IntN(3), lease)
				if err != nil {
					if running() {
						fail("Claim: %v", err)
					}
					return
				}
				if len(got) == 0 {
					time.Sleep(2 * time.Millisecond)
					continue
				}
				// Everything in the batch is in flight from the moment it is claimed.
				keysOf := make([]string, len(got))
				for i, c := range got {
					row, err := e.ob.Get(ctx, c.Tenant(), c.ID())
					if err != nil {
						if running() {
							fail("Get: %v", err)
						}
						return
					}
					key := row.TenantID + "/" + row.OrderingKey
					keysOf[i] = key
					mu.Lock()
					if other, busy := inFlight[key]; busy {
						fail("%s: row %s claimed while %s is still in flight", key, c.ID(), other)
					}
					if row.Seq <= lastSeq[key] {
						fail("%s: seq %d claimed after seq %d", key, row.Seq, lastSeq[key])
					}
					if !row.IsHead {
						fail("%s: row %s was claimed and is not the head of its key", key, c.ID())
					}
					inFlight[key] = c.ID()
					lastSeq[key] = row.Seq
					mu.Unlock()
				}
				for i, c := range got {
					time.Sleep(time.Duration(rng.IntN(1500)) * time.Microsecond) // the work
					mu.Lock()
					dies := !diedOnce[c.ID()] && rng.IntN(100) < deadPercent
					if dies {
						diedOnce[c.ID()] = true
					}
					// No longer in flight from just before the finishing call: the next row of the
					// key is claimable from the moment that call commits, which is before it returns.
					delete(inFlight, keysOf[i])
					mu.Unlock()

					if dies {
						err = e.ob.MarkDead(ctx, c, badShape)
						toReplay <- dead{c.Tenant(), c.ID()}
					} else {
						err = e.ob.MarkDelivered(ctx, c)
						delivered.Add(1)
					}
					if err != nil && running() {
						fail("finishing %s: %v", c.ID(), err)
					}
				}
			}
		})
	}

	// The operator.
	all.Go(func() {
		for running() && delivered.Load() < total {
			select {
			case d := <-toReplay:
				if err := e.ob.Replay(ctx, d.tenant, d.id); err != nil && running() {
					fail("Replay(%s): %v", d.id, err)
				}
				replays.Add(1)
			case <-time.After(5 * time.Millisecond):
			}
		}
	})

	// The invariant, on a snapshot of its own, again and again while everything above runs. And
	// the watchdog: a marker that was not handed on shows as a run that stops delivering.
	all.Go(func() {
		admin := e.adminConn()
		last, lastProgress := int64(-1), time.Now()
		for running() && delivered.Load() < total {
			var broken string
			if err := admin.QueryRow(ctx, headsBroken).Scan(&broken); err != nil {
				if running() {
					fail("head invariant: %v", err)
				}
				return
			}
			if broken != "" {
				fail("head invariant broken while running: %s", broken)
				return
			}
			if now := delivered.Load(); now != last {
				last, lastProgress = now, time.Now()
			} else if time.Since(lastProgress) > stallTimeout {
				fail("no delivery for %v, at %d of %d: some row is unfinished and nothing in front of it is claimable",
					stallTimeout, now, total)
				return
			}
			time.Sleep(10 * time.Millisecond)
		}
	})

	all.Wait()
	if failed.Load() {
		return
	}

	admin := e.adminConn()
	e.checkHeads(admin)
	var unfinished, isDelivered int64
	err := admin.QueryRow(e.ctx, `
		SELECT count(*) FILTER (WHERE state <> 'delivered'), count(*) FILTER (WHERE state = 'delivered')
		  FROM lawang.outbox`).Scan(&unfinished, &isDelivered)
	if err != nil {
		t.Fatal(err)
	}
	if unfinished != 0 || isDelivered != total {
		t.Errorf("%d rows delivered and %d not, want all %d delivered", isDelivered, unfinished, total)
	}
	t.Logf("%d deliveries, %d dead letters replayed", delivered.Load(), replays.Load())
}

// Package fake is a strict test double of a webhook provider. It exists so that the ingress edge,
// the hub and the pipeline can be tested end to end before a real provider lands, and so that
// tests of those packages do not each invent a provider of their own.
//
// It is a package and not a _test.go file because more than one package's tests import it. The
// lawang binary never does: nothing outside a test refers to it, and the provider registry is
// built from a list in main.
//
// It is strict on purpose (architecture principle 5): a lenient double let a whole class of
// mis-routed records pass every end-to-end test in the Python predecessor. So it refuses
// everything a real provider refuses. A body that is not valid UTF-8, is not JSON, carries a
// field it does not know, or is missing one it needs is an error, never a zero value. A missing
// secret, a missing signature, a signature that is not hex, one of the wrong length and one that
// does not match are all a plain false, in constant time. A challenge that is not short printable
// ASCII is answered with a 400 and never echoed.
//
// # The wire shapes
//
// A delivery is a JSON object. A handshake is either the Microsoft Graph shape, a validationToken
// in the query string echoed back as text/plain, or the Slack shape, a challenge in the body
// echoed back inside a JSON object. Both are here because the edge must not assume either.
//
//	{"type":"handshake","challenge":"abc"}
//	{"type":"event","workspace":"W1","subscription":"S1","events":[
//	  {"external_id":"fake:task:1","op":"upsert","version":"2",
//	   "container":"L1","title":"hello","occurred_at":"2026-09-20T10:00:00Z"}]}
//
// A signed delivery carries SignatureHeader: the hex of HMAC-SHA256 over the exact request bytes,
// which Sign computes.
package fake

import (
	"bytes"
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"time"
	"unicode/utf8"

	"github.com/gablooge/lawang/internal/provider"
	"github.com/gablooge/lawang/internal/record"
	"github.com/gablooge/lawang/internal/tenancy"
)

// DefaultKey is the provider key most tests build a fake under. It is a valid provider key
// under ADR 3, so the registry accepts it.
const DefaultKey = "fake"

// SignatureHeader carries the hex HMAC-SHA256 of the raw body.
const SignatureHeader = "X-Fake-Signature"

// ValidationTokenParam is the query parameter of the text/plain handshake, spelled as Microsoft
// Graph spells it.
const ValidationTokenParam = "validationToken"

// maxChallenge bounds what the handshake echoes. A challenge is text a stranger sent, and this is
// the whole reason the double refuses instead of echoing whatever arrives.
const maxChallenge = 256

// maxProviderID bounds the provider's own identifiers on a delivery.
const maxProviderID = 128

// ErrBadDelivery reports a body this provider would not have sent. It never quotes the body.
var ErrBadDelivery = errors.New("fake: bad delivery")

// ErrBadChange reports a Change that did not come from this provider's Parse.
var ErrBadChange = errors.New("fake: bad change")

// Provider is the double. Build one with New and register it like any other provider.
type Provider struct{ key string }

// New returns a fake provider whose Key is exactly key. The key is deliberately not validated or
// defaulted here: the registry owns that rule, and a test that proves the registry refuses a bad
// key needs a provider that offers one.
func New(key string) *Provider { return &Provider{key: key} }

// Key is the provider key.
func (p *Provider) Key() string { return p.key }

// Sign is the signature a delivery of body carries, as SignatureHeader. It is here and not in a
// test so that every test signs the same way Verify checks.
func Sign(secret, body []byte) string {
	mac := hmac.New(sha256.New, secret)
	_, _ = mac.Write(body)
	return hex.EncodeToString(mac.Sum(nil))
}

// Verify reports whether r.Body is signed with secret. It never errors and never panics: every
// refusal is a plain false (architecture principle 1).
//
// This double signs the body alone, the way ClickUp does, so it ignores r.Method and r.URL. A
// double that signed the URL would have to refuse when r.URL is empty, which is what
// provider.Request documents; there is a test of that shape at the edge instead, because the
// point belongs to the edge and not to any one provider.
func (p *Provider) Verify(r provider.Request, secret []byte) bool {
	if len(secret) == 0 {
		return false // fail closed: a missing secret verifies nothing
	}
	sigs := r.Header.Values(SignatureHeader)
	if len(sigs) != 1 {
		// Two signature headers are two claims, and picking one is how a smuggled second value
		// gets its chance.
		return false
	}
	// hmac.Equal already refuses a digest of the wrong length, so the length test here changes no
	// answer: it is the shape of the refusal written down, and no test can tell it from its
	// absence.
	want, err := hex.DecodeString(sigs[0])
	if err != nil || len(want) != sha256.Size {
		return false
	}
	mac := hmac.New(sha256.New, secret)
	_, _ = mac.Write(r.Body)
	return hmac.Equal(mac.Sum(nil), want)
}

// Handshake answers the two challenge shapes this double knows, and reports whether it did.
//
// It reads body, never r.Body, which the edge has already replaced with http.NoBody.
func (p *Provider) Handshake(r *http.Request, body []byte) (provider.Reply, bool) {
	if q := r.URL.Query(); q.Has(ValidationTokenParam) {
		tokens := q[ValidationTokenParam]
		if len(tokens) != 1 || !printableASCII(tokens[0]) || len(tokens[0]) > maxChallenge || tokens[0] == "" {
			return badChallenge(), true
		}
		return provider.Reply{
			ContentType: "text/plain; charset=utf-8",
			Body:        []byte(tokens[0]),
		}, true
	}

	var hs struct {
		Type      string `json:"type"`
		Challenge string `json:"challenge"`
	}
	if err := decodeStrict(body, &hs); err != nil || hs.Type != "handshake" {
		return provider.Reply{}, false // not a handshake, and not this method's business
	}
	if hs.Challenge == "" || len(hs.Challenge) > maxChallenge || !printableASCII(hs.Challenge) {
		return badChallenge(), true
	}
	// Built with encoding/json, so the challenge is escaped and cannot break out of the string.
	reply, err := json.Marshal(struct {
		Challenge string `json:"challenge"`
	}{hs.Challenge})
	if err != nil {
		return badChallenge(), true
	}
	return provider.Reply{ContentType: "application/json", Body: reply}, true
}

func badChallenge() provider.Reply {
	return provider.Reply{Status: http.StatusBadRequest, Body: []byte("bad challenge\n")}
}

// DeliveryKeys reads the workspace and subscription ids out of a delivery.
func (p *Provider) DeliveryKeys(body []byte, _ provider.Header) (provider.DeliveryKeys, error) {
	env, err := parseEnvelope(body)
	if err != nil {
		return provider.DeliveryKeys{}, err
	}
	return provider.DeliveryKeys{Workspace: env.Workspace, Subscription: env.Subscription}, nil
}

// Parse turns a delivery into its changes.
func (p *Provider) Parse(body []byte) ([]provider.Change, error) {
	env, err := parseEnvelope(body)
	if err != nil {
		return nil, err
	}
	if len(env.Events) == 0 {
		return nil, fmt.Errorf("%w: no events", ErrBadDelivery)
	}
	changes := make([]provider.Change, 0, len(env.Events))
	for _, raw := range env.Events {
		ev, err := p.parseEvent(raw)
		if err != nil {
			return nil, err
		}
		changes = append(changes, provider.Change{
			ExternalID: ev.ExternalID,
			Op:         record.Op(ev.Op),
			// The event's own bytes, not a re-serialization: a degraded record is built out of
			// this, and a provider's bytes are the only thing that is certainly faithful.
			Payload: bytes.Clone(raw),
		})
	}
	return changes, nil
}

// Object is what Hydrate returns: this double's stand-in for the full object a real provider
// would have fetched from its API.
type Object struct {
	Event Event
	// Text is what hydration added to what the webhook carried. A real provider fetches it.
	Text string
}

// Hydrate returns the object a Change is about. There is no API to call, so it reads the change's
// own payload back and adds the one field a webhook body would not have carried.
func (p *Provider) Hydrate(ctx context.Context, t tenancy.ID, c provider.Change) (provider.Hydrated, error) {
	if err := ctx.Err(); err != nil {
		return nil, err // a real client would fail here, so the double does too
	}
	if t == "" {
		return nil, fmt.Errorf("%w: no tenant", ErrBadChange) // fail closed
	}
	ev, err := p.parseEvent(c.Payload)
	if err != nil {
		return nil, err
	}
	if ev.ExternalID != c.ExternalID {
		return nil, fmt.Errorf("%w: the payload is not this change's", ErrBadChange)
	}
	return Object{Event: ev, Text: "hydrated " + ev.ExternalID}, nil
}

// Normalize turns a hydrated object into one unsealed record.
func (p *Provider) Normalize(h provider.Hydrated, c provider.Change) ([]record.Record, error) {
	obj, ok := h.(Object)
	if !ok {
		return nil, fmt.Errorf("%w: not a fake.Object", ErrBadChange)
	}
	if obj.Event.ExternalID != c.ExternalID {
		return nil, fmt.Errorf("%w: the object is not this change's", ErrBadChange)
	}
	scope, err := record.ScopeID(p.key, "list", obj.Event.Container)
	if err != nil {
		return nil, fmt.Errorf("%w: %w", ErrBadChange, err)
	}
	return []record.Record{{
		Op:         record.Op(obj.Event.Op),
		Kind:       record.KindTask,
		ExternalID: obj.Event.ExternalID,
		Version:    obj.Event.Version,
		OccurredAt: obj.Event.OccurredAt,
		Title:      obj.Event.Title,
		Text:       obj.Text,
		Container:  record.Container{Kind: "list", ID: obj.Event.Container},
		Visibility: record.Visibility{Scope: scope, Audience: record.AudienceGroup},
	}}, nil
}

// Event is one change on the wire, as this double spells it.
type Event struct {
	ExternalID string    `json:"external_id"`
	Op         string    `json:"op"`
	Version    string    `json:"version"`
	Container  string    `json:"container"`
	Title      string    `json:"title"`
	OccurredAt time.Time `json:"occurred_at"`
}

type envelope struct {
	Type         string            `json:"type"`
	Workspace    string            `json:"workspace"`
	Subscription string            `json:"subscription"`
	Events       []json.RawMessage `json:"events"`
}

// parseEnvelope decodes a delivery and refuses everything this provider would not have sent.
func parseEnvelope(body []byte) (envelope, error) {
	var env envelope
	if err := decodeStrict(body, &env); err != nil {
		return envelope{}, err
	}
	if env.Type != "event" {
		return envelope{}, fmt.Errorf("%w: not an event", ErrBadDelivery)
	}
	if !validProviderID(env.Workspace) {
		return envelope{}, fmt.Errorf("%w: workspace", ErrBadDelivery)
	}
	// The subscription id is optional, as it is for the providers that send none.
	if env.Subscription != "" && !validProviderID(env.Subscription) {
		return envelope{}, fmt.Errorf("%w: subscription", ErrBadDelivery)
	}
	return env, nil
}

func (p *Provider) parseEvent(raw []byte) (Event, error) {
	var ev Event
	if err := decodeStrict(raw, &ev); err != nil {
		return Event{}, err
	}
	switch record.Op(ev.Op) {
	case record.OpUpsert, record.OpDelete:
	default:
		return Event{}, fmt.Errorf("%w: op", ErrBadDelivery)
	}
	// The external id carries the provider key, as the record format requires, so a normalizer
	// never has to add it and Seal never has to refuse it.
	if !bytes.HasPrefix([]byte(ev.ExternalID), []byte(p.key+":")) || len(ev.ExternalID) > maxProviderID {
		return Event{}, fmt.Errorf("%w: external_id", ErrBadDelivery)
	}
	if !validProviderID(ev.Version) || !validProviderID(ev.Container) {
		return Event{}, fmt.Errorf("%w: version or container", ErrBadDelivery)
	}
	if ev.OccurredAt.IsZero() {
		return Event{}, fmt.Errorf("%w: occurred_at", ErrBadDelivery)
	}
	ev.OccurredAt = ev.OccurredAt.UTC() // the record format refuses any other location
	return ev, nil
}

// decodeStrict refuses a body that is not exactly one JSON object of the expected shape. Three
// refusals matter and none of them is the default: bytes that are not UTF-8 (encoding/json would
// quietly rewrite them to U+FFFD and make two different deliveries one), a field the shape does
// not know, and anything after the object.
func decodeStrict(body []byte, into any) error {
	if !utf8.Valid(body) {
		return fmt.Errorf("%w: not UTF-8", ErrBadDelivery)
	}
	dec := json.NewDecoder(bytes.NewReader(body))
	dec.DisallowUnknownFields()
	if err := dec.Decode(into); err != nil {
		// The decoder's message can quote the body, which is a stranger's text.
		return fmt.Errorf("%w: not the expected JSON", ErrBadDelivery)
	}
	if _, err := dec.Token(); !errors.Is(err, io.EOF) {
		return fmt.Errorf("%w: trailing data", ErrBadDelivery)
	}
	return nil
}

// validProviderID is what this double accepts as one of the provider's own identifiers: 1 to
// maxProviderID printable ASCII characters. A real provider's ids are narrower still.
func validProviderID(s string) bool {
	return s != "" && len(s) <= maxProviderID && printableASCII(s)
}

// printableASCII reports whether s is only visible ASCII and spaces: no control character, no
// newline (which forges a log line), no NUL (which truncates in C and cannot be stored in a
// Postgres text column), and nothing above ASCII.
func printableASCII(s string) bool {
	for i := range len(s) {
		if s[i] < 0x20 || s[i] > 0x7E {
			return false
		}
	}
	return true
}

package fake_test

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	"github.com/gablooge/lawang/internal/provider"
	"github.com/gablooge/lawang/internal/provider/fake"
	"github.com/gablooge/lawang/internal/record"
	"github.com/gablooge/lawang/internal/tenancy"
)

const secret = "s3cr3t-for-this-test-only"

// event is deliberately spelled so that re-serializing it produces different bytes: the fields
// are not in the order the Go struct declares them, and there is whitespace inside. A fixture
// that happened to marshal back to itself would let a provider that re-serialized its payload
// pass every test here.
const event = `{"op":"upsert", "external_id":"fake:task:1",  "container":"L1","version":"2",` +
	`"title":"hello","occurred_at":"2026-09-20T10:00:00Z"}`

func delivery() string {
	return `{"type":"event","workspace":"W1","subscription":"S1","events":[` + event + `]}`
}

// request is a delivery as the edge hands it to Verify. The method and the URL are filled in with
// something a real request would carry, so that a Verify which started reading them would not
// silently see zero values here.
func request(body []byte, h http.Header) provider.Request {
	return provider.Request{
		Method: http.MethodPost,
		URL:    "https://lawang.example.test/ingress/" + fake.DefaultKey,
		Header: provider.NewHeader(h),
		Body:   body,
	}
}

func signed(t *testing.T, body string) http.Header {
	t.Helper()
	h := http.Header{}
	h.Set(fake.SignatureHeader, fake.Sign([]byte(secret), []byte(body)))
	return h
}

// TestVerifyRefusesEverythingARealProviderRefuses is architecture principle 5 for the one method
// where a lenient double would hide a real hole: every refusal is a plain false, and a missing
// secret is a refusal and never a pass.
func TestVerifyRefusesEverythingARealProviderRefuses(t *testing.T) {
	t.Parallel()

	p := fake.New(fake.DefaultKey)
	body := []byte(delivery())
	good := fake.Sign([]byte(secret), body)

	if !p.Verify(request(body, signed(t, string(body))), []byte(secret)) {
		t.Fatal("a correctly signed delivery must verify")
	}

	twoSigs := http.Header{}
	twoSigs.Add(fake.SignatureHeader, good)
	twoSigs.Add(fake.SignatureHeader, good)

	cases := []struct {
		name   string
		body   []byte
		header http.Header
		secret []byte
	}{
		{"no secret", body, signed(t, string(body)), nil},
		{"empty secret", body, signed(t, string(body)), []byte{}},
		// The one an absent check would let through: a sender who knows the secret is missing
		// can compute the HMAC of an empty key themselves.
		{"signed with the empty secret", body, headerWith(fake.Sign(nil, body)), nil},
		{"signed with the empty secret, empty given", body, headerWith(fake.Sign([]byte{}, body)), []byte{}},
		{"no signature", body, http.Header{}, []byte(secret)},
		{"two signatures", body, twoSigs, []byte(secret)},
		{"signature is not hex", body, headerWith("nothex" + strings.Repeat("z", 58)), []byte(secret)},
		{"signature is short", body, headerWith(good[:len(good)-2]), []byte(secret)},
		{"signature is long", body, headerWith(good + "ab"), []byte(secret)},
		{"signature is empty", body, headerWith(""), []byte(secret)},
		{"wrong secret", body, signed(t, string(body)), []byte("another secret entirely")},
		{"body changed by one byte", append([]byte{' '}, body...), signed(t, string(body)), []byte(secret)},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			if p.Verify(request(c.body, c.header), c.secret) {
				t.Fatal("verified something it must refuse")
			}
		})
	}
}

func headerWith(sig string) http.Header {
	h := http.Header{}
	h.Set(fake.SignatureHeader, sig)
	return h
}

// TestVerifyIsOverTheExactBytes is principle 1. A re-serialization of the same JSON is a different
// byte string, and must not verify.
func TestVerifyIsOverTheExactBytes(t *testing.T) {
	t.Parallel()

	p := fake.New(fake.DefaultKey)
	raw := []byte(" {\"type\":\"event\",  \"workspace\":\"W1\",\n\"events\":[" + event + "]} ")

	var decoded map[string]any
	if err := json.Unmarshal(raw, &decoded); err != nil {
		t.Fatalf("the fixture must be valid JSON: %v", err)
	}
	reserialized, err := json.Marshal(decoded)
	if err != nil {
		t.Fatalf("Marshal: %v", err)
	}
	if string(reserialized) == string(raw) {
		t.Fatal("the fixture must re-serialize differently, or it proves nothing")
	}

	h := headerWith(fake.Sign([]byte(secret), raw))
	if !p.Verify(request(raw, h), []byte(secret)) {
		t.Fatal("the raw bytes must verify")
	}
	if p.Verify(request(reserialized, h), []byte(secret)) {
		t.Fatal("re-serialized JSON must not verify against a signature over the raw bytes")
	}
}

// TestVerifyIgnoresWhatThisSchemeDoesNotSign holds the double to what it says it is. It signs the
// body alone, like ClickUp, so a different method and an empty URL (which is what
// provider.Request carries when no public base URL is configured) must change no answer. A double
// that quietly started reading them would make the edge's fail-closed behaviour untestable.
func TestVerifyIgnoresWhatThisSchemeDoesNotSign(t *testing.T) {
	t.Parallel()

	p := fake.New(fake.DefaultKey)
	body := []byte(delivery())
	h := headerWith(fake.Sign([]byte(secret), body))

	for _, r := range []provider.Request{
		{Method: http.MethodPost, URL: "", Header: provider.NewHeader(h), Body: body},
		{Method: "PUT", URL: "https://elsewhere.example.test/ingress/fake?x=1", Header: provider.NewHeader(h), Body: body},
		{Method: "", URL: "", Header: provider.NewHeader(h), Body: body},
	} {
		if !p.Verify(r, []byte(secret)) {
			t.Fatalf("a body-only scheme refused over method %q and URL %q", r.Method, r.URL)
		}
	}
}

func TestHandshakeAnswersBothShapesAndIsNotJSONOnly(t *testing.T) {
	t.Parallel()

	p := fake.New(fake.DefaultKey)

	t.Run("text echo in the query", func(t *testing.T) {
		r := httptest.NewRequest(http.MethodPost, "/ingress/fake?validationToken=abc123", nil)
		reply, ok := p.Handshake(r, nil)
		if !ok {
			t.Fatal("a validationToken is a handshake")
		}
		if got := string(reply.Body); got != "abc123" {
			t.Fatalf("body = %q", got)
		}
		if reply.ContentType != "text/plain; charset=utf-8" {
			t.Fatalf("content type = %q, a handshake reply is not always JSON", reply.ContentType)
		}
	})

	t.Run("json challenge in the body", func(t *testing.T) {
		body := []byte(`{"type":"handshake","challenge":"xyz"}`)
		r := httptest.NewRequest(http.MethodPost, "/ingress/fake", nil)
		reply, ok := p.Handshake(r, body)
		if !ok {
			t.Fatal("a challenge body is a handshake")
		}
		if got := string(reply.Body); got != `{"challenge":"xyz"}` {
			t.Fatalf("body = %q", got)
		}
		if reply.ContentType != "application/json" {
			t.Fatalf("content type = %q", reply.ContentType)
		}
	})

	t.Run("an ordinary delivery is not a handshake", func(t *testing.T) {
		r := httptest.NewRequest(http.MethodPost, "/ingress/fake", nil)
		if _, ok := p.Handshake(r, []byte(delivery())); ok {
			t.Fatal("an event body must not be taken for a handshake")
		}
	})
}

// TestHandshakeNeverEchoesWhatItShouldNotEcho keeps the one place that writes a stranger's text
// back out honest: a challenge that is not short printable ASCII is answered with a 400 and the
// text never appears in the reply.
func TestHandshakeNeverEchoesWhatItShouldNotEcho(t *testing.T) {
	t.Parallel()

	p := fake.New(fake.DefaultKey)
	long := strings.Repeat("a", 257)
	cases := []struct {
		name  string
		query string
		body  string
	}{
		{"empty token", "?validationToken=", ""},
		{"token with a newline", "?validationToken=a%0Ab", ""},
		{"token with a NUL", "?validationToken=a%00b", ""},
		{"token above ASCII", "?validationToken=caf%C3%A9", ""},
		{"token too long", "?validationToken=" + long, ""},
		{"two tokens", "?validationToken=a&validationToken=b", ""},
		{"challenge with a control character", "", `{"type":"handshake","challenge":"a\u0000b"}`},
		{"challenge too long", "", `{"type":"handshake","challenge":"` + long + `"}`},
		{"empty challenge", "", `{"type":"handshake","challenge":""}`},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			r := httptest.NewRequest(http.MethodPost, "/ingress/fake"+c.query, nil)
			reply, ok := p.Handshake(r, []byte(c.body))
			if !ok {
				t.Fatal("a malformed challenge is still a handshake, answered with a refusal")
			}
			if reply.Status != http.StatusBadRequest {
				t.Fatalf("status = %d, want 400", reply.Status)
			}
			if string(reply.Body) != "bad challenge\n" {
				t.Fatalf("the reply echoed something: %q", reply.Body)
			}
		})
	}
}

// TestADeliveryThisProviderWouldNotHaveSentIsAnError is the strictness rule: never a zero value,
// always a refusal.
func TestADeliveryThisProviderWouldNotHaveSentIsAnError(t *testing.T) {
	t.Parallel()

	p := fake.New(fake.DefaultKey)
	cases := map[string]string{
		"empty":                     "",
		"not JSON":                  "not json at all",
		"not an object":             `[1,2,3]`,
		"trailing data":             delivery() + `{"type":"event"}`,
		"unknown field":             `{"type":"event","workspace":"W1","extra":1,"events":[]}`,
		"wrong type":                `{"type":"handshake","workspace":"W1","events":[]}`,
		"no workspace":              `{"type":"event","events":[]}`,
		"workspace with a NUL":      `{"type":"event","workspace":"a\u0000b","events":[]}`,
		"workspace too long":        `{"type":"event","workspace":"` + strings.Repeat("w", 129) + `","events":[]}`,
		"subscription with a NUL":   `{"type":"event","workspace":"W1","subscription":"a\u0000b","events":[]}`,
		"events is not an array":    `{"type":"event","workspace":"W1","events":{}}`,
		"workspace is not a string": `{"type":"event","workspace":1,"events":[]}`,
	}
	for name, body := range cases {
		t.Run(name, func(t *testing.T) {
			if _, err := p.DeliveryKeys([]byte(body), provider.Header{}); err == nil {
				t.Fatal("DeliveryKeys accepted it")
			}
			if _, err := p.Parse([]byte(body)); err == nil {
				t.Fatal("Parse accepted it")
			}
		})
	}
}

// TestBytesThatAreNotUTF8AreRefusedBeforeTheDecoder covers the one refusal in decodeStrict that
// encoding/json does not make on its own, and that the first version of this test did not reach:
// it sent {0xff,0xfe,'}'}, which is not JSON at all, so the decoder refused it whether or not
// utf8.Valid was there, and the check survived its own mutation.
//
// Go's JSON scanner accepts any byte above 0x1f inside a string, and the decoder then rewrites
// whatever is not valid UTF-8 to U+FFFD. Two deliveries that differ in one byte therefore become
// one parsed value while their delivery ids (which hash the raw bytes) differ, which is exactly
// the "two different deliveries become one" that this double exists to refuse.
//
// Every case below except the last is valid JSON, asserted here, so utf8.Valid is the only thing
// in the package that can refuse it. The bad byte sits in title, the one field parseEvent does
// not otherwise constrain: workspace, subscription, version and container are printable ASCII
// only, so a bad byte in those is refused twice over and would prove nothing.
func TestBytesThatAreNotUTF8AreRefusedBeforeTheDecoder(t *testing.T) {
	t.Parallel()

	p := fake.New(fake.DefaultKey)
	withTitle := func(title string) []byte {
		return []byte(`{"type":"event","workspace":"W1","subscription":"S1","events":[` +
			`{"op":"upsert","external_id":"fake:task:1","container":"L1","version":"2",` +
			`"title":"` + title + `","occurred_at":"2026-09-20T10:00:00Z"}]}`)
	}
	cases := map[string]struct {
		body      []byte
		validJSON bool
	}{
		"a lone 0xff in a string":           {withTitle("x\xff"), true},
		"a lone 0xfe in a string":           {withTitle("x\xfe"), true},
		"a truncated two byte sequence":     {withTitle("x\xc3("), true},
		"a bare continuation byte":          {withTitle("x\x80"), true},
		"a surrogate half encoded as UTF-8": {withTitle("x\xed\xa0\x80"), true},
		"an overlong encoding of a slash":   {withTitle("x\xc0\xaf"), true},
		"not JSON either":                   {[]byte{'{', 0xff, 0xfe, '}'}, false},
	}
	for name, tc := range cases {
		t.Run(name, func(t *testing.T) {
			t.Parallel()
			if json.Valid(tc.body) != tc.validJSON {
				t.Fatalf("json.Valid = %v, want %v: this fixture no longer isolates the UTF-8 check",
					json.Valid(tc.body), tc.validJSON)
			}
			if _, err := p.Parse(tc.body); err == nil {
				t.Fatal("Parse accepted bytes that are not UTF-8")
			}
			if _, err := p.DeliveryKeys(tc.body, provider.Header{}); err == nil {
				t.Fatal("DeliveryKeys accepted bytes that are not UTF-8")
			}
		})
	}

	// The same delivery with a valid title is accepted, so the cases above are not passing
	// against a Parse that refuses everything.
	if _, err := p.Parse(withTitle("x?")); err != nil {
		t.Fatalf("the same delivery with a valid title was refused: %v", err)
	}
}

func TestParseRefusesAnEventThisProviderWouldNotHaveSent(t *testing.T) {
	t.Parallel()

	p := fake.New(fake.DefaultKey)
	with := func(ev string) string {
		return `{"type":"event","workspace":"W1","events":[` + ev + `]}`
	}
	cases := map[string]string{
		"no events":              `{"type":"event","workspace":"W1","events":[]}`,
		"unknown op":             with(`{"external_id":"fake:task:1","op":"patch","version":"2","container":"L1","occurred_at":"2026-09-20T10:00:00Z"}`),
		"external id unprefixed": with(`{"external_id":"task:1","op":"upsert","version":"2","container":"L1","occurred_at":"2026-09-20T10:00:00Z"}`),
		"another provider's id":  with(`{"external_id":"slack:task:1","op":"upsert","version":"2","container":"L1","occurred_at":"2026-09-20T10:00:00Z"}`),
		"no version":             with(`{"external_id":"fake:task:1","op":"upsert","container":"L1","occurred_at":"2026-09-20T10:00:00Z"}`),
		"no container":           with(`{"external_id":"fake:task:1","op":"upsert","version":"2","occurred_at":"2026-09-20T10:00:00Z"}`),
		"no occurred_at":         with(`{"external_id":"fake:task:1","op":"upsert","version":"2","container":"L1"}`),
		"unknown event field":    with(`{"external_id":"fake:task:1","op":"upsert","version":"2","container":"L1","occurred_at":"2026-09-20T10:00:00Z","extra":1}`),
		// The prefix is right and everything else is valid, so the length bound is the only thing
		// that can refuse this. Without the case, dropping the bound changed nothing in the suite.
		"external id too long": with(`{"external_id":"fake:` + strings.Repeat("x", 129) +
			`","op":"upsert","version":"2","container":"L1","occurred_at":"2026-09-20T10:00:00Z"}`),
	}
	for name, body := range cases {
		t.Run(name, func(t *testing.T) {
			if _, err := p.Parse([]byte(body)); err == nil {
				t.Fatal("Parse accepted it")
			}
		})
	}
}

// TestAnOffsetTimeIsNormalizedToUTC pins the one line of parseEvent that changes a value rather
// than refusing one. encoding/json keeps the offset a delivery was written with, and the record
// format refuses any location but UTC, so without the conversion every delivery from a provider
// that writes local time would fail far from here, in Seal. Every occurred_at fixture elsewhere in
// this package is already spelled with a Z, so nothing else in the suite can see the difference.
func TestAnOffsetTimeIsNormalizedToUTC(t *testing.T) {
	t.Parallel()

	p := fake.New(fake.DefaultKey)
	const offset = `{"type":"event","workspace":"W1","events":[` +
		`{"external_id":"fake:task:1","op":"upsert","version":"2","container":"L1",` +
		`"title":"hello","occurred_at":"2026-09-20T17:00:00+07:00"}]}`

	changes, err := p.Parse([]byte(offset))
	if err != nil {
		t.Fatalf("Parse: %v", err)
	}
	obj, err := p.Hydrate(t.Context(), "t_1", changes[0])
	if err != nil {
		t.Fatalf("Hydrate: %v", err)
	}
	recs, err := p.Normalize(obj, changes[0])
	if err != nil {
		t.Fatalf("Normalize: %v", err)
	}
	if loc := recs[0].OccurredAt.Location(); loc != time.UTC {
		t.Fatalf("OccurredAt location = %v, want UTC", loc)
	}
	if want := time.Date(2026, 9, 20, 10, 0, 0, 0, time.UTC); !recs[0].OccurredAt.Equal(want) {
		t.Fatalf("OccurredAt = %v, want %v", recs[0].OccurredAt, want)
	}
}

// TestThePipelineRoundTripProducesASealableRecord walks the provider interface end to end, so the
// double is known to produce something the record format accepts and not only something that
// compiles.
func TestThePipelineRoundTripProducesASealableRecord(t *testing.T) {
	t.Parallel()

	p := fake.New(fake.DefaultKey)
	body := []byte(delivery())

	keys, err := p.DeliveryKeys(body, provider.Header{})
	if err != nil {
		t.Fatalf("DeliveryKeys: %v", err)
	}
	if keys.Workspace != "W1" || keys.Subscription != "S1" {
		t.Fatalf("keys = %+v", keys)
	}

	changes, err := p.Parse(body)
	if err != nil {
		t.Fatalf("Parse: %v", err)
	}
	if len(changes) != 1 || changes[0].ExternalID != "fake:task:1" || changes[0].Op != record.OpUpsert {
		t.Fatalf("changes = %+v", changes)
	}
	if string(changes[0].Payload) != event {
		t.Fatalf("the payload is not the provider's own bytes:\n got %s\nwant %s", changes[0].Payload, event)
	}

	tenant, err := tenancy.Parse("acme")
	if err != nil {
		t.Fatalf("tenancy.Parse: %v", err)
	}
	hydrated, err := p.Hydrate(t.Context(), tenant, changes[0])
	if err != nil {
		t.Fatalf("Hydrate: %v", err)
	}
	recs, err := p.Normalize(hydrated, changes[0])
	if err != nil {
		t.Fatalf("Normalize: %v", err)
	}
	if len(recs) != 1 {
		t.Fatalf("want one record, got %d", len(recs))
	}
	sealed, err := recs[0].Seal(p.Key(), tenant)
	if err != nil {
		t.Fatalf("the double must produce a record the format accepts: %v", err)
	}
	if _, err := json.Marshal(sealed); err != nil {
		t.Fatalf("Marshal: %v", err)
	}
	if sealed.Visibility.Scope != "fake:list:L1" {
		t.Fatalf("scope = %q", sealed.Visibility.Scope)
	}
}

func TestHydrateFailsClosed(t *testing.T) {
	t.Parallel()

	p := fake.New(fake.DefaultKey)
	changes, err := p.Parse([]byte(delivery()))
	if err != nil {
		t.Fatalf("Parse: %v", err)
	}
	tenant, err := tenancy.Parse("acme")
	if err != nil {
		t.Fatalf("tenancy.Parse: %v", err)
	}

	if _, err := p.Hydrate(t.Context(), "", changes[0]); err == nil {
		t.Fatal("no tenant is a refusal, never a default")
	}
	cancelled, cancel := context.WithCancel(t.Context())
	cancel()
	if _, err := p.Hydrate(cancelled, tenant, changes[0]); err == nil {
		t.Fatal("a cancelled context must fail, as a real API client would")
	}
	other := provider.Change{ExternalID: "fake:task:99", Payload: changes[0].Payload}
	if _, err := p.Hydrate(t.Context(), tenant, other); err == nil {
		t.Fatal("a payload that belongs to another change must be refused")
	}
	if _, err := p.Hydrate(t.Context(), tenant, provider.Change{ExternalID: "fake:task:1", Payload: []byte("{")}); err == nil {
		t.Fatal("a payload that is not an event must be refused")
	}
	if _, err := p.Normalize("not an object", changes[0]); err == nil {
		t.Fatal("Normalize must refuse something it did not hydrate")
	}
}

// TestNormalizeRefusesAnObjectItCannotTurnIntoARecord: a scope id it cannot build, and an object
// that belongs to another change, are both refusals and never a record with a guessed field.
func TestNormalizeRefusesAnObjectItCannotTurnIntoARecord(t *testing.T) {
	t.Parallel()

	p := fake.New(fake.DefaultKey)
	changes, err := p.Parse([]byte(delivery()))
	if err != nil {
		t.Fatalf("Parse: %v", err)
	}
	tenant, err := tenancy.Parse("acme")
	if err != nil {
		t.Fatalf("tenancy.Parse: %v", err)
	}
	hydrated, err := p.Hydrate(t.Context(), tenant, changes[0])
	if err != nil {
		t.Fatalf("Hydrate: %v", err)
	}

	other := provider.Change{ExternalID: "fake:task:99"}
	if _, err := p.Normalize(hydrated, other); err == nil {
		t.Fatal("an object from another change must be refused")
	}

	// A provider key the scope id grammar refuses (ADR 3) cannot produce a scope, so the record
	// is refused here rather than later in Seal.
	hyphened := fake.New("ms-graph")
	body := strings.ReplaceAll(delivery(), "fake:task:1", "ms-graph:task:1")
	hyphenedChanges, err := hyphened.Parse([]byte(body))
	if err != nil {
		t.Fatalf("Parse: %v", err)
	}
	hydrated, err = hyphened.Hydrate(t.Context(), tenant, hyphenedChanges[0])
	if err != nil {
		t.Fatalf("Hydrate: %v", err)
	}
	if _, err := hyphened.Normalize(hydrated, hyphenedChanges[0]); err == nil {
		t.Fatal("a provider key the scope id grammar refuses must not produce a record")
	}
}

// Package provider holds the interfaces a SaaS integration implements and the registry that wires
// them up once at startup. Nothing here knows about any particular provider: each one lives in a
// package of its own under this one, and the rest of Lawang reaches it only through these
// interfaces (docs/architecture.md, section 7).
//
// Provider is what every integration implements. The others are optional capabilities, discovered
// with a type assertion rather than stubbed out, so a provider that has no webhook does not carry
// a method that returns "not supported".
package provider

import (
	"context"
	"net/http"
	"slices"

	"github.com/gablooge/lawang/internal/record"
	"github.com/gablooge/lawang/internal/tenancy"
)

// Provider is one SaaS integration.
type Provider interface {
	// Key is the internal provider key ("slack", "ms_graph"): a lowercase letter followed by up
	// to 31 of a-z, 0-9 and underscore, and never a hyphen (record.ValidProviderKey, ADR 3). It
	// is a constant of the program, never a name a sink or a request chooses: it is the first
	// segment of every scope id and of every external id, and it is hashed into every record id,
	// so changing it re-keys everything the provider has ever delivered. A Registry calls Key
	// once, at registration, and uses its own copy of the result from then on.
	Key() string

	// Hydrate fetches the full object a Change is about. It is the only place a provider talks
	// to its API, it runs in the worker and never on the accept path, and it must honour ctx.
	// The pipeline degrades to a minimal record when it fails, so an error here is not a lost
	// change (architecture 3.2, step 4).
	Hydrate(ctx context.Context, t tenancy.ID, c Change) (Hydrated, error)

	// Normalize turns what Hydrate returned into the records of one change: usually one, and
	// more when a delivery carries an entity and its parent. The records are complete but
	// unsealed, because sealing needs the tenant and is the pipeline's step: Normalize fills
	// everything record.Seal then checks. It does no I/O.
	Normalize(h Hydrated, c Change) ([]record.Record, error)
}

// Change is one thing that happened at a provider, as its webhook body or a reconciliation page
// reported it. The same type carries the live path and the backfill path, so both end up in the
// same pipeline (architecture 3.2 and 3.3).
type Change struct {
	// ExternalID identifies the entity that changed, in the record format's namespaced form
	// ("clickup:task:86a1b2"): the provider key, a colon, and the provider's own id. It becomes
	// Record.ExternalID, and the outbox orders by the entity, so two versions of one entity must
	// give the same string.
	ExternalID string
	// Op is what happened to the entity.
	Op record.Op
	// Payload is the part of the delivery this change was read from, exactly as the provider
	// wrote it. It is what a record degraded from the webhook body is built out of, so a
	// provider keeps here what it would need if its own API were unreachable.
	Payload []byte
}

// Hydrated is the full object a provider fetched for a Change. It is deliberately opaque: only
// the provider that produced it reads it again, in its own Normalize, and no two providers'
// objects have a field in common, so an interface with methods here would be a shape every
// provider bends to and nothing else uses.
type Hydrated any

// WebhookSource is the optional capability of a provider that receives deliveries at
// /ingress/{provider}. Its four methods are the accept path in order: handshake, delivery keys,
// verification, parse (architecture 3.1).
//
// Everything they are handed arrives from the public internet, signed or not. body is the exact
// bytes of the request, and no method may assume it is JSON, or UTF-8, or anything else.
type WebhookSource interface {
	// Handshake answers a challenge the provider sends to prove the endpoint is ours, and
	// reports whether it did. It runs before any tenant is resolved and before anything is
	// verified or stored, because a challenge arrives when no subscription exists yet.
	//
	// The reply is bytes and a content type, not JSON: Slack echoes its challenge inside a JSON
	// object and Microsoft Graph echoes a validationToken as text/plain, so the interface cannot
	// assume a shape. Returning false means "this is not a handshake", and the delivery goes on
	// down the accept path.
	//
	// r is the request with its body already read and replaced by http.NoBody: read body, never
	// r.Body. r is there for the URL and the headers, which is where a challenge often is.
	Handshake(r *http.Request, body []byte) (Reply, bool)

	// DeliveryKeys reads the provider's own identifiers out of a delivery, which are what the
	// hub looks subscriptions up by. They are untrusted: they say which rows are candidates,
	// never which tenant this is. The tenant comes from the candidate whose secret verifies the
	// body (principle 2).
	//
	// It takes the body and the headers rather than a Request, because the identifiers are in the
	// delivery's own content: no provider puts them somewhere only a Request would carry, and a
	// lookup key read from configuration rather than from the delivery would select candidates
	// for the wrong delivery.
	DeliveryKeys(body []byte, h Header) (DeliveryKeys, error)

	// Verify reports whether the delivery is signed with secret, compared in constant time. It
	// never errors and never panics: a missing secret, a missing or malformed signature, a
	// missing r.URL that this scheme needs, and a body that is not what the provider sends are
	// all a plain false (principle 1). It is called once per candidate subscription, so it does
	// no I/O.
	Verify(r Request, secret []byte) bool

	// Parse turns a verified delivery into its changes. It runs in the worker, on the stored
	// bytes, never on the accept path.
	Parse(body []byte) ([]Change, error)
}

// Request is one delivery as a signature scheme sees it: the parts of the HTTP request a
// provider's signing scheme can cover. It is a struct rather than a longer parameter list because
// the schemes disagree about what a signature is over, and the next one to need a field it does
// not have must not break every implementation that came before it. ClickUp signs the body alone,
// Slack v0 signs a timestamp header and the body, and HubSpot v3 signs the method, the full
// request URL, the body and a timestamp header, so the union is what is here.
//
// Everything in it arrived from the public internet except URL, which is configuration.
type Request struct {
	// Method is the request method, and it is always "POST": the ingress route fixes the method, so
	// the mux answers anything else itself and no other method reaches a provider. It is carried
	// because HubSpot v3 puts the method in its base string, and an implementation that builds
	// that string from this field rather than from a literal keeps saying the truth if the edge
	// ever routes a second method. There is nothing here to branch on.
	Method string

	// URL is the absolute public URL the provider posted to: the deployment's configured public
	// base URL, then this request's own escaped path, then its raw query if it has one.
	//
	// It is deliberately not built from Host, X-Forwarded-Host or X-Forwarded-Proto. Every one of
	// those is chosen by whoever sent the request (a tunnel or a reverse proxy passes them
	// through), and a sender that chooses part of its own signed input can make a signature
	// verify over content it picked, which is not a signature check at all.
	//
	// It is the empty string when the deployment set no public base URL. A scheme that signs the
	// URL must then return false rather than guess one, because a signature verified against a
	// URL Lawang invented proves nothing (fail closed). A scheme that does not sign the URL, which
	// is most of them, ignores this field and is unaffected.
	URL string

	// Header is the request's header fields. A scheme's timestamp and its signature are here, and
	// a header the sender did not send is the empty string, never an error.
	Header Header

	// Body is the exact bytes of the request, the ones a signature is over. An implementation
	// must not re-serialize them, and must not modify the slice.
	//
	// This one is a rule and not a guarantee, which is the difference between it and Header. The
	// slice is handed out by value and aliases the edge's own buffer, so an implementation that
	// normalized the bytes in place (trimming a byte order mark, lower casing, blanking a field
	// before hashing) would change what every later candidate verifies and what B07 then stores
	// in the outbox. Nothing in the type system stops that, and a review of a provider package
	// has to look for it.
	//
	// Making it a guarantee is cheap and belongs where the per-candidate loop is, which is the
	// hub (#7): copying the slice per candidate costs 0.9 microseconds for an 8 KiB delivery and
	// 57 microseconds at the 1 MiB cap on this machine, against an accept path that targets 200
	// ms. It is not done here, because the edge builds one Request and has no candidate loop to
	// copy in.
	Body []byte
}

// Header is the header fields of one delivery, as a provider sees them: readable, and with no way
// to change what anything else will read.
//
// It is not an http.Header, and that is the point. The hub hands one Request to Verify once per
// candidate subscription (B07), so with a map an implementation that normalized a header in place
// (a Set or a Del on the way to building a base string) would change what every later candidate
// sees, and the symptom would be a signature that fails only for the second candidate and only
// when a tenant has more than one. A comment asking implementations not to do that is not a
// guard, and cloning the map per request does not help either, since every candidate is handed
// the same Request. A type with no mutating method takes the mistake off the table and copies
// nothing: the edge wraps the request's own map once, and reading through the wrapper costs a
// method call that inlines away.
type Header struct {
	h http.Header
}

// NewHeader wraps h, which the caller must not write to afterwards. The edge passes the request's
// own map, which net/http does not touch once the handler has been called.
func NewHeader(h http.Header) Header { return Header{h: h} }

// Get returns the first value of the named field, matching the name case-insensitively the way
// http.Header.Get does, and the empty string when the sender sent no such field. The zero Header
// has no fields, so Get on it is the empty string rather than a panic.
func (h Header) Get(name string) string { return h.h.Get(name) }

// Values returns every value of the named field, in the order the sender sent them, and nil when
// there is none. A scheme that refuses a delivery carrying two signature headers, which is two
// claims where the protocol allows one, needs the count and not just the first value.
//
// The slice is a copy, so writing to it changes nothing another candidate will read.
func (h Header) Values(name string) []string { return slices.Clone(h.h.Values(name)) }

// Reply is a handshake answer. The zero Reply is an empty 200.
type Reply struct {
	// Status is the HTTP status, and 0 means 200. The edge accepts a 2xx and a 4xx and treats
	// anything else as a bug in the provider: a handshake is not a delivery, so a 4xx for a
	// malformed challenge is a legitimate answer, while a redirect (which would let a provider
	// point a stranger somewhere) and a 5xx (which asks for a retry) are not.
	Status int
	// ContentType is the Content-Type header, and empty means text/plain; charset=utf-8. The edge
	// refuses anything outside a closed allowlist (text/plain and application/json, optionally
	// with charset=utf-8), because a handshake echoes a stranger's text and a provider that could
	// name the type could make this origin serve something a browser executes.
	ContentType string
	// Body is written as it stands. A provider that echoes a challenge is echoing text a
	// stranger sent, so it checks that text before putting it here.
	Body []byte
}

// DeliveryKeys are the provider's own identifiers on a delivery that say which subscriptions
// could own it. Both fields are optional, because providers differ: Slack sends a team id and
// ClickUp a webhook id, Microsoft Graph sends a subscription id per notification, and HubSpot
// sends a portal id. A key the provider did not send is the empty string, and the hub narrows
// candidates by the keys it has.
//
// Nothing in here establishes a tenant. It is text from a stranger until a candidate's secret
// verifies the body.
type DeliveryKeys struct {
	// Workspace is the provider's id of the workspace, team, portal or account.
	Workspace string
	// Subscription is the provider's id of the webhook registration itself.
	Subscription string
}

package provider

import (
	"errors"
	"fmt"

	"github.com/gablooge/lawang/internal/record"
)

// ErrBadKey reports a provider whose Key is not a provider key. It names the key, which is safe:
// a provider key is a constant of this program and never text from a request.
var ErrBadKey = errors.New("provider: not a provider key")

// ErrDuplicateKey reports two providers registered under one key.
var ErrDuplicateKey = errors.New("provider: key registered twice")

// ErrNilProvider reports a nil in the list handed to NewRegistry.
var ErrNilProvider = errors.New("provider: nil provider")

// Registry is the set of providers this process serves. It is built once, at startup, from a list
// known at compile time, and it never changes afterwards: there is no Add, so every read of it is
// safe from any number of goroutines with no lock, which is what the accept path needs.
//
// Its job on the accept path is to turn one path segment, which is text a stranger sent, into a
// provider and into that provider's key as this program spells it. Those are two different
// strings: the segment is whatever arrived (net/http decodes %00 in /ingress/{provider} into a NUL
// byte), and the key is the one validated at registration. Everything downstream is handed the
// key, never the segment, because outbox.Delivery.Provider must be a constant of the program.
type Registry struct {
	byKey map[string]Entry
}

// Entry is one provider in a Registry, together with the key the registry validated and keeps.
// The zero Entry names no provider: its Key is empty and its Provider is nil.
type Entry struct {
	key string
	p   Provider
}

// Key is the provider key as this program spells it: validated at registration, and the string to
// hand to the outbox, the ledger and every record. It is never the string a caller looked up with,
// even when the two hold the same bytes.
func (e Entry) Key() string { return e.key }

// Provider is the registered provider. Backlog item B08 calls Hydrate and Normalize through it:
// the drain path has the outbox row's provider key and needs the provider itself, while the
// accept path only ever needs WebhookSource.
func (e Entry) Provider() Provider { return e.p }

// WebhookSource reports whether the provider receives webhooks, and returns that capability. It
// is the type assertion of architecture section 7, in one place, so a caller does not repeat it.
func (e Entry) WebhookSource() (WebhookSource, bool) {
	ws, ok := e.p.(WebhookSource)
	return ws, ok
}

// NewRegistry validates every provider and returns the registry, or the first thing wrong with
// the list. It refuses a nil provider, a key that record.ValidProviderKey refuses, and a key
// registered twice.
//
// The key grammar is not written down here. It is ADR 3's, and record.ValidProviderKey owns it,
// because the same string is the first segment of every scope id and of every external id: a
// registry that accepted "ms-graph" would register a provider whose every record fails in
// record.Seal, far from here. TestTheRegistryCannotDriftFromTheRecordFormat holds the two to the
// same verdict.
//
// Key is called exactly once per provider, and the result is copied into the registry, so a
// provider whose Key changes later cannot change what is stored or what the edge answers.
func NewRegistry(providers ...Provider) (*Registry, error) {
	r := &Registry{byKey: make(map[string]Entry, len(providers))}
	for _, p := range providers {
		if p == nil {
			return nil, ErrNilProvider
		}
		key := p.Key()
		if !record.ValidProviderKey(key) {
			// The key is a program constant, so quoting it points at the bug. %q also keeps a
			// stray control character out of the log as an escape.
			return nil, fmt.Errorf("%w: %q", ErrBadKey, key)
		}
		if _, dup := r.byKey[key]; dup {
			return nil, fmt.Errorf("%w: %q", ErrDuplicateKey, key)
		}
		r.byKey[key] = Entry{key: key, p: p}
	}
	return r, nil
}

// Lookup finds the provider registered under key. key may be anything at all, path segment
// included: a miss is the only thing an unregistered string can produce, and the Entry that comes
// back carries the registry's own copy of the key.
func (r *Registry) Lookup(key string) (Entry, bool) {
	e, ok := r.byKey[key]
	return e, ok
}

package provider_test

import (
	"context"
	"errors"
	"net/http"
	"strings"
	"testing"
	"unsafe"

	"github.com/gablooge/lawang/internal/provider"
	"github.com/gablooge/lawang/internal/provider/fake"
	"github.com/gablooge/lawang/internal/record"
	"github.com/gablooge/lawang/internal/tenancy"
)

// TestTheRegistryCannotDriftFromTheRecordFormat is the test the provider key grammar exists for.
// ADR 3 freezes the grammar, record.ValidProviderKey owns it, and the registry must call that
// function and not carry a copy of the pattern: a registry that accepted "ms-graph" would register
// a provider whose every record fails in record.Seal, and a registry that refused something Seal
// accepts would make a provider unreachable.
//
// So the two are asked about every candidate, and must always agree. The candidates cover every
// byte in the first and in a later position, which is where a hand-written pattern differs from
// this one.
func TestTheRegistryCannotDriftFromTheRecordFormat(t *testing.T) {
	t.Parallel()

	var candidates []string
	for b := range 256 {
		candidates = append(candidates, string(rune(b)), "a"+string(rune(b)), "a"+string(rune(b))+"b")
	}
	candidates = append(candidates,
		"", "a", "clickup", "slack", "ms_graph", "hubspot", "fake",
		"ms-graph", "9lives", "Slack", "_leading", "with space", "a.b", "a:b",
		strings.Repeat("a", 31), strings.Repeat("a", 32), strings.Repeat("a", 33),
		"a"+strings.Repeat("0", 31), "a"+strings.Repeat("0", 32),
	)

	for _, key := range candidates {
		want := record.ValidProviderKey(key)
		_, err := provider.NewRegistry(fake.New(key))
		got := err == nil
		if got != want {
			t.Fatalf("key %q: registry accepts %v, record.ValidProviderKey says %v", key, got, want)
		}
		if !want && !errors.Is(err, provider.ErrBadKey) {
			t.Fatalf("key %q: want ErrBadKey, got %v", key, err)
		}
	}
}

// TestNewRegistryRefusesTheListItCannotServe covers the two other ways a list is wrong. Both are
// bugs in the wiring, so both are caught at startup and never at the first request.
func TestNewRegistryRefusesTheListItCannotServe(t *testing.T) {
	t.Parallel()

	if _, err := provider.NewRegistry(fake.New("a"), nil); !errors.Is(err, provider.ErrNilProvider) {
		t.Fatalf("nil provider: want ErrNilProvider, got %v", err)
	}
	_, err := provider.NewRegistry(fake.New("clickup"), fake.New("clickup"))
	if !errors.Is(err, provider.ErrDuplicateKey) {
		t.Fatalf("duplicate: want ErrDuplicateKey, got %v", err)
	}
	if !strings.Contains(err.Error(), "clickup") {
		t.Fatalf("the error should name the key, which is a program constant: %v", err)
	}
}

// shifty returns a different key every time it is asked. Nothing legitimate does that; the point
// is that the registry asks once and keeps its own copy, so nothing downstream can be steered by
// a provider that answers differently later.
type shifty struct{ asked int }

func (s *shifty) Key() string {
	s.asked++
	if s.asked == 1 {
		return "first"
	}
	return "second"
}

func (s *shifty) Hydrate(_ context.Context, _ tenancy.ID, _ provider.Change) (provider.Hydrated, error) {
	return nil, errors.New("not used")
}

func (s *shifty) Normalize(_ provider.Hydrated, _ provider.Change) ([]record.Record, error) {
	return nil, errors.New("not used")
}

func TestTheRegistryAsksForAKeyOnceAndKeepsItsOwnCopy(t *testing.T) {
	t.Parallel()

	p := &shifty{}
	reg, err := provider.NewRegistry(p)
	if err != nil {
		t.Fatalf("NewRegistry: %v", err)
	}
	if p.asked != 1 {
		t.Fatalf("Key was asked %d times, want exactly 1", p.asked)
	}
	if _, ok := reg.Lookup("second"); ok {
		t.Fatal("the registry followed the provider's second answer")
	}
	entry, ok := reg.Lookup("first")
	if !ok || entry.Key() != "first" {
		t.Fatalf("Lookup(first) = %q, %v", entry.Key(), ok)
	}
	if p.asked != 1 {
		t.Fatalf("Key was asked again after registration (%d times)", p.asked)
	}
}

// TestLookupReturnsTheRegistrysStringAndNotTheCallers is decision 2 of issue #6, at the level it
// actually matters: outbox.Delivery.Provider must be a constant of the program, so the key that
// comes back out of a lookup has to be the registry's own string and not the one the caller
// looked up with, even though the two hold the same bytes today. Comparing the string data
// pointers is the only way to tell them apart.
func TestLookupReturnsTheRegistrysStringAndNotTheCallers(t *testing.T) {
	t.Parallel()

	reg, err := provider.NewRegistry(fake.New("clickup"))
	if err != nil {
		t.Fatalf("NewRegistry: %v", err)
	}
	// A distinct allocation with the same bytes, as a decoded path segment would be.
	lookedUpWith := string([]byte("clickup"))
	entry, ok := reg.Lookup(lookedUpWith)
	if !ok {
		t.Fatal("Lookup missed")
	}
	if entry.Key() != lookedUpWith {
		t.Fatalf("Key() = %q, want the same bytes", entry.Key())
	}
	if unsafe.StringData(entry.Key()) == unsafe.StringData(lookedUpWith) {
		t.Fatal("Key() handed back the caller's own string, so request text could travel on")
	}
}

// TestWebhookSourceIsFoundByTypeAssertion covers the optional-capability rule of architecture
// section 7: a provider that has no webhook must not be reachable at the ingress edge.
func TestWebhookSourceIsFoundByTypeAssertion(t *testing.T) {
	t.Parallel()

	reg, err := provider.NewRegistry(fake.New("fake"), &shifty{})
	if err != nil {
		t.Fatalf("NewRegistry: %v", err)
	}
	withWebhook, _ := reg.Lookup("fake")
	if _, ok := withWebhook.WebhookSource(); !ok {
		t.Fatal("the fake provider is a WebhookSource")
	}
	withoutWebhook, _ := reg.Lookup("first")
	if _, ok := withoutWebhook.WebhookSource(); ok {
		t.Fatal("a provider with no webhook methods must not pass for a WebhookSource")
	}
}

// TestTheZeroEntryNamesNoProvider pins what a caller sees if it ever keeps an Entry from a failed
// lookup.
func TestTheZeroEntryNamesNoProvider(t *testing.T) {
	t.Parallel()

	var e provider.Entry
	if e.Key() != "" || e.Provider() != nil {
		t.Fatalf("zero Entry = %q, %v", e.Key(), e.Provider())
	}
	if _, ok := e.WebhookSource(); ok {
		t.Fatal("the zero Entry is not a WebhookSource")
	}
}

// TestAHeaderCannotBeUsedToChangeWhatTheNextCandidateReads is why Request.Header is a type of this
// package and not an http.Header.
//
// The hub hands one Request to Verify once per candidate subscription (B07), so anything an
// implementation could write to would be read by every candidate after it. A tenant with two
// subscriptions on one workspace would then see a signature fail for the second candidate only,
// and only sometimes, which is about the worst failure shape available. There is no Set and no
// Del to call here, and the one method that returns something a caller could write to returns a
// copy.
func TestAHeaderCannotBeUsedToChangeWhatTheNextCandidateReads(t *testing.T) {
	t.Parallel()

	live := http.Header{}
	live.Set("X-Signature", "first")
	live.Add("X-Signature", "second")
	h := provider.NewHeader(live)

	// What one candidate can reach: the slice Values returned, and nothing else.
	got := h.Values("X-Signature")
	if len(got) != 2 || got[0] != "first" || got[1] != "second" {
		t.Fatalf("Values = %q, want both values in order", got)
	}
	got[0] = "tampered"

	// What every candidate after it reads.
	if again := h.Values("X-Signature"); len(again) != 2 || again[0] != "first" || again[1] != "second" {
		t.Fatalf("a candidate changed what the next one reads: Values = %q", again)
	}
	if v := h.Get("x-signature"); v != "first" {
		t.Fatalf("Get = %q, want the first value, matched without regard to case", v)
	}
	if live.Get("X-Signature") != "first" {
		t.Fatalf("the request's own header was changed through the wrapper: %q", live)
	}

	// The zero value reads as a request that sent no header at all, rather than panicking on a
	// nil map: a Request built by hand in a test, or by a later caller, must not be a trap.
	var zero provider.Header
	if zero.Get("X-Signature") != "" || zero.Values("X-Signature") != nil {
		t.Fatal("the zero Header must read as empty")
	}
}

package record

import (
	"encoding/json"
	"fmt"
	"regexp"
	"testing"
	"unicode/utf8"
)

// Which characters a field may hold (ADR 4), stated here as tables of code point ranges and not
// taken from validate.go, so that the test below holds the rule and not the code's copy of it.
// Every code point in this file is written as a number: an editor or a tool that turns an escape
// into the character itself would otherwise put an invisible character into the source.

type runeRange struct{ first, last rune }

var (
	controlRanges = []runeRange{{0x0000, 0x001F}, {0x007F, 0x009F}}

	refusedInAnIdentifier = append([]runeRange{
		{0x00AD, 0x00AD}, // soft hyphen
		{0x061C, 0x061C}, // Arabic letter mark
		{0x200B, 0x200F}, // zero-width space, non-joiner, joiner, left-to-right and right-to-left mark
		{0x2028, 0x202E}, // line and paragraph separator, the embeddings and overrides
		{0x2060, 0x206F}, // word joiner, invisible operators, the isolates, deprecated format characters
		{0xFEFF, 0xFEFF}, // byte order mark
	}, controlRanges...)

	// A display name keeps the zero-width non-joiner and joiner, U+200C and U+200D.
	refusedInADisplayName = append([]runeRange{
		{0x00AD, 0x00AD}, {0x061C, 0x061C}, {0x200B, 0x200B}, {0x200E, 0x200F},
		{0x2028, 0x202E}, {0x2060, 0x206F}, {0xFEFF, 0xFEFF},
	}, controlRanges...)

	refusedOnOneLine = append([]runeRange{{0x2028, 0x2029}}, controlRanges...)

	refusedInContent = []runeRange{{0x0000, 0x0000}}
)

type charField struct {
	path    string
	refused []runeRange
	// value puts the character under test into a value that is otherwise fine for the field.
	value func(c string) string
	// assign puts the value into a Go record.
	assign func(r *Record, v string)
}

func charFields() []charField {
	plain := func(c string) string { return "a" + c + "b" }
	prefixed := func(c string) string { return "slack:a" + c + "b" }
	return []charField{
		{"external_id", refusedInAnIdentifier, prefixed, func(r *Record, v string) { r.ExternalID = v }},
		{"version", refusedInAnIdentifier, plain, func(r *Record, v string) { r.Version = v }},
		{"author.id", refusedInAnIdentifier, plain, func(r *Record, v string) { r.Author.ID = v }},
		{"container.id", refusedInAnIdentifier, plain, func(r *Record, v string) { r.Container.ID = v }},
		{"edges.reply_parent", refusedInAnIdentifier, prefixed, func(r *Record, v string) { r.Edges.ReplyParent = Ref(v) }},
		{"meta.delivery", refusedInAnIdentifier, plain, func(r *Record, v string) { r.Meta.Delivery = v }},
		{"author.display", refusedInADisplayName, plain, func(r *Record, v string) { r.Author.Display = v }},
		{"title", refusedOnOneLine, plain, func(r *Record, v string) { r.Title = v }},
		{"text", refusedInContent, plain, func(r *Record, v string) { r.Text = v }},
	}
}

// charsUnderTest is every code point near a rule, and then some: all of U+0000 to U+02FF (ASCII,
// the C1 controls, the soft hyphen), the Arabic block, the Mongolian vowel separator's
// neighbourhood, all of General Punctuation and what follows it (U+2000 to U+20FF), the last two
// hundred code points of the BMP (the byte order mark, the specials), and astral characters: an
// emoji, a tag character, the last code point.
func charsUnderTest() []rune {
	var out []rune
	for _, r := range []runeRange{{0x0000, 0x02FF}, {0x0600, 0x06FF}, {0x1800, 0x180F}, {0x2000, 0x20FF}, {0xFE00, 0xFFFF}} {
		for c := r.first; c <= r.last; c++ {
			out = append(out, c)
		}
	}
	return append(out, 0xD7FF, 0xE000, 0x1F600, 0xE0001, 0xE0041, 0x10FFFF)
}

func inRanges(c rune, ranges []runeRange) bool {
	for _, r := range ranges {
		if c >= r.first && c <= r.last {
			return true
		}
	}
	return false
}

// Every character under test, in every field that has a character rule, through the schema, the
// strict decoder and Validate. One character per document, because a refusal hides every other
// character in the same value. This is a sample, and what it proves is the wiring: that each
// field is held to its own rule on all three sides. That the rules themselves agree on every
// code point there is, and not only on the sample, is TestEveryCodePointInGoAndInThePatterns.
func TestEveryCharacterRuleInGoAndInTheSchema(t *testing.T) {
	// One compilation is enough here: a character rule is a pattern, which does not depend on
	// whether formats are asserted.
	with, _ := schemas(t)
	chars := charsUnderTest()
	base := sealed(t)
	for _, field := range charFields() {
		t.Run(field.path, func(t *testing.T) {
			t.Parallel()
			refusals := 0
			for _, c := range chars {
				want := !inRanges(c, field.refused)
				if !want {
					refusals++
				}
				what := fmt.Sprintf("U+%04X", c)
				value := field.value(string(c))

				doc := exampleDoc(t)
				set(field.path, value)(doc)
				data, err := json.Marshal(doc)
				if err != nil {
					t.Fatalf("%s: %v", what, err)
				}
				if err := schemaError(t, with, data); (err == nil) != want {
					t.Errorf("%s: the schema accepted = %v, want %v", what, err == nil, want)
				}
				var decoded Record
				if err := json.Unmarshal(data, &decoded); (err == nil) != want {
					t.Errorf("%s: the decoder accepted = %v, want %v (%v)", what, err == nil, want, err)
				}

				r := base
				field.assign(&r, value)
				if err := r.Validate(); (err == nil) != want {
					t.Errorf("%s: Validate accepted = %v, want %v (%v)", what, err == nil, want, err)
				}
			}
			// The ranges above, counted by hand, so that a table that lost a row is noticed.
			wantRefusals := map[string]int{"text": 1, "title": 67, "author.display": 94}[field.path]
			if wantRefusals == 0 {
				wantRefusals = 96 // an identifier
			}
			if refusals != wantRefusals {
				t.Errorf("%d of the characters under test are refused, want %d", refusals, wantRefusals)
			}
		})
	}
}

// The four character rules over all of Unicode, which ADR 4 promises is run in full: for every
// code point the schema's pattern (compiled as it is after JSON decoding, which is what a sink's
// validator is handed), the Go rule and the table of this file give one verdict. A rule tightened
// or loosened on one side only, anywhere from U+0000 to U+10FFFF, fails here. After v0.1.0 that
// would be a silent break of a frozen contract: a document the schema refuses that Go accepts,
// or the reverse.
//
// The surrogates U+D800 to U+DFFF are left out because no string holds one: a Go string, a
// regular expression and a record document are all UTF-8 (ADR 4 decision 8 refuses the escape of
// a lone one before anything is parsed).
func TestEveryCodePointInGoAndInThePatterns(t *testing.T) {
	var schema struct {
		Defs       map[string]struct{ Not struct{ Pattern string } } `json:"$defs"`
		Properties map[string]struct{ Not struct{ Pattern string } }
	}
	if err := json.Unmarshal(Schema(), &schema); err != nil {
		t.Fatal(err)
	}
	rules := []struct {
		name    string
		pattern string
		rule    charRule
		refused []runeRange
		// wantRefused is the size of the table, counted by hand from ADR 4 (32 C0 controls, DEL
		// and 32 C1 controls, then for an identifier 1, 1, 5, 7, 16 and 1), so that a table and
		// both implementations changed together are still noticed.
		wantRefused int
	}{
		{"identifier", schema.Defs["identifier"].Not.Pattern, identifierChars, refusedInAnIdentifier, 96},
		{"displayName", schema.Defs["displayName"].Not.Pattern, displayChars, refusedInADisplayName, 94},
		{"oneLine", schema.Defs["oneLine"].Not.Pattern, oneLineChars, refusedOnOneLine, 67},
		{"text", schema.Properties["text"].Not.Pattern, contentChars, refusedInContent, 1},
	}
	for _, rule := range rules {
		t.Run(rule.name, func(t *testing.T) {
			t.Parallel()
			if rule.pattern == "" {
				t.Fatal("the schema has no such pattern, the test is not seeing the schema")
			}
			pattern, err := regexp.Compile(rule.pattern)
			if err != nil {
				t.Fatal(err)
			}
			refused, failures := 0, 0
			buf := make([]byte, 0, utf8.UTFMax)
			for c := rune(0); c <= utf8.MaxRune; c++ {
				if c >= 0xD800 && c <= 0xDFFF {
					continue
				}
				buf = utf8.AppendRune(buf[:0], c)
				want := inRanges(c, rule.refused)
				if want {
					refused++
				}
				bySchema := pattern.Match(buf)
				byGo := checkString("field", string(buf), 1, 1, rule.rule) != nil
				if bySchema != want || byGo != want {
					t.Errorf("U+%04X: the schema refuses = %v, Go refuses = %v, ADR 4 refuses = %v", c, bySchema, byGo, want)
					if failures++; failures == 20 {
						t.Fatal("and more")
					}
				}
			}
			if refused != rule.wantRefused {
				t.Errorf("the table refuses %d code points, want %d", refused, rule.wantRefused)
			}
		})
	}
}

// notRefused is what ADR 4 says the character rules deliberately do NOT refuse ("The lists are
// fixed code points, never a Unicode category"), each as a case with a name. They are invisible
// or nearly so, which makes each of them an invitation to "close the gap" later, and within v1
// that is forbidden in both directions: refusing one on the Go side only makes Go refuse what
// the schema accepts, and refusing one in the schema narrows a frozen pattern. Whoever wants to
// tighten a rule has to delete a test with a name first, and read this comment on the way.
//
// Every code point is a number, see the top of this file.
func notRefused() []struct {
	name   string
	assign func(*Record)
} {
	const (
		tagBegin, tagA, tagCancel = rune(0xE0001), rune(0xE0041), rune(0xE007F)
		blackFlag                 = rune(0x1F3F4)
		variation16, variation17  = rune(0xFE0F), rune(0xE0100) // the emoji selector, and the first of the supplement
		heart, ideograph          = rune(0x2764), rune(0x8FBB)
		choseongFiller            = rune(0x115F)
		jungseongFiller           = rune(0x1160)
		hangulFiller              = rune(0x3164)
		halfwidthFiller           = rune(0xFFA0)
		ideographicSpace          = rune(0x3000)
		zwj                       = rune(0x200D)
		woman, laptop             = rune(0x1F469), rune(0x1F4BB)
	)
	id := func(c ...rune) string { return "slack:C" + string(c) + "1" }
	return []struct {
		name   string
		assign func(*Record)
	}{
		{"tag characters in an external id", func(r *Record) { r.ExternalID = id(tagBegin, tagA, tagCancel) }},
		{"tag characters in a version", func(r *Record) { r.Version = string([]rune{'1', tagA, '2'}) }},
		{"the flag of Scotland in a display name, which is spelled with tag characters", func(r *Record) {
			r.Author.Display = string([]rune{blackFlag, 0xE0067, 0xE0062, 0xE0073, 0xE0063, 0xE0074, tagCancel})
		}},
		{"a tag character in a title", func(r *Record) { r.Title = string([]rune{'a', tagA, 'b'}) }},
		{"a variation selector in an external id", func(r *Record) { r.ExternalID = id(variation16) }},
		{"a variation selector in an author id", func(r *Record) { r.Author.ID = string([]rune{'U', variation16, '1'}) }},
		{"an emoji with its variation selector in a display name", func(r *Record) { r.Author.Display = string([]rune{'b', 'e', 'n', ' ', heart, variation16}) }},
		{"an ideographic variation sequence in a display name", func(r *Record) { r.Author.Display = string([]rune{ideograph, variation17}) }},
		{"a variation selector in a title", func(r *Record) { r.Title = string([]rune{heart, variation16}) }},
		{"the Hangul filler U+3164 in an external id", func(r *Record) { r.ExternalID = id(hangulFiller) }},
		{"the Hangul choseong and jungseong fillers in a container id", func(r *Record) {
			r.Container.ID = string([]rune{'C', choseongFiller, jungseongFiller, '1'})
		}},
		{"the halfwidth Hangul filler in a delivery id", func(r *Record) { r.Meta.Delivery = string([]rune{'d', halfwidthFiller, '1'}) }},
		{"the Hangul filler U+3164 in a display name", func(r *Record) { r.Author.Display = string([]rune{'b', hangulFiller, 'n'}) }},
		{"the Hangul filler U+3164 in a title", func(r *Record) { r.Title = string([]rune{'a', hangulFiller, 'b'}) }},
		{"the ideographic space U+3000 in an external id", func(r *Record) { r.ExternalID = id(ideographicSpace) }},
		{"the ideographic space U+3000 in a reply parent", func(r *Record) { r.Edges.ReplyParent = Ref(id(ideographicSpace)) }},
		{"the ideographic space U+3000 in a display name", func(r *Record) { r.Author.Display = string([]rune{'a', ideographicSpace, 'b'}) }},
		{"the ideographic space U+3000 in a title", func(r *Record) { r.Title = string([]rune{'a', ideographicSpace, 'b'}) }},
		{"the zero-width joiner in a display name, in a profession emoji", func(r *Record) { r.Author.Display = string([]rune{woman, zwj, laptop}) }},
	}
}

// The rules the tables cannot show: the characters a rule must leave alone, by name.
func TestWhatTheCharacterRulesLeaveAlone(t *testing.T) {
	const (
		zwnj, zwj           = rune(0x200C), rune(0x200D)
		lrm, rlm            = rune(0x200E), rune(0x200F)
		rlo, pdf, rli, pdi  = rune(0x202E), rune(0x202C), rune(0x2067), rune(0x2069)
		alef, bet           = rune(0x05D0), rune(0x05D1)
		heh, alefAr         = rune(0x0647), rune(0x0627)
		emojiMan, emojiGirl = rune(0x1F468), rune(0x1F467)
	)
	keeps := []struct {
		name   string
		assign func(*Record)
	}{
		{"a Persian name with a zero-width non-joiner", func(r *Record) { r.Author.Display = string([]rune{heh, zwnj, alefAr}) }},
		{"a display name with a family emoji", func(r *Record) { r.Author.Display = string([]rune{emojiMan, zwj, emojiGirl}) }},
		{"a right-to-left title with marks and isolates", func(r *Record) { r.Title = string([]rune{rli, alef, bet, pdi, lrm, ' ', rlm, '1'}) }},
		{"a title with an override, which is content", func(r *Record) { r.Title = string([]rune{'a', rlo, 'b', pdf}) }},
		{"a text with every kind of line break and an escape character", func(r *Record) {
			r.Text = string([]rune{'a', '\n', '\r', '\t', 0x0B, 0x0C, 0x1B, 0x85, 0x2028, 0x2029, rlo, 0xFEFF, 'b'})
		}},
	}
	for _, k := range keeps {
		r := sealed(t)
		k.assign(&r)
		if err := r.Validate(); err != nil {
			t.Errorf("%s: %v", k.name, err)
		}
	}
	with, _ := schemas(t)
	for _, k := range notRefused() {
		t.Run(k.name, func(t *testing.T) {
			r := draft()
			k.assign(&r)
			r, err := r.Seal(testProvider, testTenant)
			if err != nil {
				t.Fatalf("Seal refuses it: %v", err)
			}
			data, err := json.Marshal(r)
			if err != nil {
				t.Fatalf("Marshal refuses it: %v", err)
			}
			if err := schemaError(t, with, data); err != nil {
				t.Errorf("the schema refuses it: %v", err)
			}
			var back Record
			if err := json.Unmarshal(data, &back); err != nil {
				t.Errorf("the decoder refuses it: %v", err)
			}
		})
	}
	refuses := []struct {
		name   string
		assign func(*Record)
	}{
		{"an override in a display name", func(r *Record) { r.Author.Display = string([]rune{'b', 'e', 'n', rlo, 'n', 'i', 'm', 'd', 'a'}) }},
		{"an isolate in a display name", func(r *Record) { r.Author.Display = string([]rune{rli, 'b', 'e', 'n', pdi}) }},
		{"a zero-width joiner in an author id", func(r *Record) { r.Author.ID = string([]rune{'U', zwj, '1'}) }},
		{"a zero-width non-joiner in an external id", func(r *Record) { r.ExternalID = "slack:" + string([]rune{'C', zwnj, '1'}) }},
		{"a next line character in an external id", func(r *Record) { r.ExternalID = "slack:" + string([]rune{'C', 0x85, '1'}) }},
		{"a line separator in a version", func(r *Record) { r.Version = string([]rune{'1', 0x2028, '2'}) }},
		{"a tab in a title", func(r *Record) { r.Title = "a\tb" }},
		{"a line feed in a title", func(r *Record) { r.Title = "a\nb" }},
		{"a next line character in a title", func(r *Record) { r.Title = string([]rune{'a', 0x85, 'b'}) }},
	}
	for _, k := range refuses {
		r := sealed(t)
		k.assign(&r)
		if err := r.Validate(); err == nil {
			t.Errorf("%s: accepted", k.name)
		}
	}
}

package record

import (
	"bytes"
	"encoding/json"
	"errors"
	"io"
	"slices"
	"unicode/utf8"
)

// objectRule is what decoding demands of one JSON object of the envelope, beyond the types of
// its values. It mirrors "required", "additionalProperties" and the nullable fields of the
// schema, and the agreement tests hold the two together.
type objectRule struct {
	required []string
	optional []string
	// nullable names the required fields whose value may be null.
	nullable []string
	// closed refuses a field that is neither required nor optional.
	closed bool
}

var recordRule = objectRule{
	required: []string{
		"format", "id", "op", "source", "kind", "external_id", "version", "supersedes",
		"occurred_at", "title", "text", "author", "container", "visibility", "origin", "edges",
	},
	optional: []string{"meta"},
	nullable: []string{"supersedes"},
}

// nestedRules has an entry for every object inside the envelope.
var nestedRules = []struct {
	name string
	rule objectRule
}{
	{"author", objectRule{required: []string{"id", "display"}}},
	{"container", objectRule{required: []string{"kind", "id"}}},
	{"visibility", objectRule{required: []string{"scope", "audience"}, closed: true}},
	{"origin", objectRule{required: []string{"automation", "untrusted"}}},
	{"edges", objectRule{required: []string{"reply_parent"}, nullable: []string{"reply_parent"}}},
	{"meta", objectRule{optional: []string{"delivery"}}},
}

// UnmarshalJSON decodes a record and refuses whatever the schema refuses, so that a Go consumer
// which decodes into a Record has validated it. encoding/json alone would not do: it reads an
// absent field as its zero value, which would turn a record with no origin into one that says
// "trusted", and it matches field names without regard to case, which would let "ID" beside "id"
// reach the struct while a schema validator looked at "id". So this checks that every required
// field is present and not null, that every field name is lowercase (the format has no other),
// that Visibility holds nothing unknown, and that occurred_at is spelled the way the format
// spells it, and then runs Validate. Unknown fields outside Visibility are ignored, which is
// what lets v1 grow.
//
// One refusal goes beyond the schema, because no schema can make it: a field name that occurs
// twice in one object. Decoders disagree on which of the two counts, so a validator that keeps
// the first and a consumer that keeps the last would see two different scopes in one record.
//
// Two more refusals are about the bytes of the document, below the level a schema works at (ADR
// 4, "The bytes of a document"): a document that is not valid UTF-8, and a \u escape that names
// half of a surrogate pair. encoding/json accepts both and writes U+FFFD in their place, so two
// different documents would decode to one identity, while another consumer of the same bytes
// refuses the document or keeps the two apart.
//
// The error says which field, never what was in it.
func (r *Record) UnmarshalJSON(data []byte) error {
	if !utf8.Valid(data) {
		return invalid("the record", "is not valid UTF-8")
	}
	if err := checkNoDuplicateNames(data); err != nil {
		return err
	}
	if hasUnpairedSurrogate(data) {
		return invalid("the record", "has an escape for half of a surrogate pair")
	}
	top, err := checkObject("the record", data, recordRule)
	if err != nil {
		return err
	}
	for _, nested := range nestedRules {
		raw, ok := top[nested.name]
		if !ok {
			continue
		}
		if _, err := checkObject(nested.name, raw, nested.rule); err != nil {
			return err
		}
	}
	var occurredAt string
	if err := json.Unmarshal(top["occurred_at"], &occurredAt); err != nil || !validTimestamp(occurredAt) {
		return invalid("occurred_at", "is not an RFC 3339 time in UTC with the Z suffix")
	}

	var w wire
	if err := json.Unmarshal(data, &w); err != nil {
		// The error of encoding/json quotes numbers and times it could not decode.
		var typeErr *json.UnmarshalTypeError
		if errors.As(err, &typeErr) {
			return invalid(typeErr.Field, "has the wrong JSON type")
		}
		if errors.Is(err, ErrInvalid) {
			return err
		}
		return invalid("the record", "has a value that cannot be decoded")
	}
	decoded := Record(w)
	if err := decoded.Validate(); err != nil {
		return err
	}
	// A decoded record was sealed by whoever wrote the document. What was read is pinned, so
	// that writing it out again after a change to what the id stands for is refused. It is
	// sealed for no tenant, because a document does not say whose it is: SealedFor is false.
	decoded.sealed = decoded.currentSeal()
	*r = decoded
	return nil
}

func checkObject(name string, data []byte, rule objectRule) (map[string]json.RawMessage, error) {
	var fields map[string]json.RawMessage
	if err := json.Unmarshal(data, &fields); err != nil || fields == nil {
		return nil, invalid(name, "is not a JSON object")
	}
	for field, raw := range fields {
		if !validName(field, len(field), false) {
			return nil, invalid(name, "has a field name that is not lowercase a-z, 0-9 and underscore")
		}
		known := slices.Contains(rule.required, field) || slices.Contains(rule.optional, field)
		if !known && rule.closed {
			return nil, invalid(name, "has a field this format does not know")
		}
		if known && string(raw) == "null" && !slices.Contains(rule.nullable, field) {
			return nil, invalid(name+"."+field, "is null")
		}
	}
	for _, field := range rule.required {
		if _, ok := fields[field]; !ok {
			return nil, invalid(name+"."+field, "is missing")
		}
	}
	return fields, nil
}

// checkNoDuplicateNames walks the document once and refuses an object, at any depth, that uses
// one name twice. It also refuses anything that is not a single JSON value.
func checkNoDuplicateNames(data []byte) error {
	type frame struct {
		names   map[string]struct{} // nil for an array
		wantKey bool
	}
	var stack []frame
	valueDone := func() {
		if n := len(stack); n > 0 && stack[n-1].names != nil {
			stack[n-1].wantKey = true
		}
	}

	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	for {
		tok, err := dec.Token()
		if errors.Is(err, io.EOF) {
			return nil
		}
		if err != nil {
			return invalid("the record", "is not valid JSON")
		}
		if delim, ok := tok.(json.Delim); ok {
			switch delim {
			case '{':
				stack = append(stack, frame{names: map[string]struct{}{}, wantKey: true})
			case '[':
				stack = append(stack, frame{})
			default:
				stack = stack[:len(stack)-1]
				valueDone()
			}
			continue
		}
		if n := len(stack); n > 0 && stack[n-1].wantKey {
			name, _ := tok.(string)
			if _, seen := stack[n-1].names[name]; seen {
				return invalid("the record", "uses a field name twice in one object")
			}
			stack[n-1].names[name] = struct{}{}
			stack[n-1].wantKey = false
			continue
		}
		valueDone()
	}
}

// hasUnpairedSurrogate reports whether a \u escape in a JSON document names half of a surrogate
// pair with the other half missing: a high surrogate (D800 to DBFF) that is not followed at once
// by an escaped low surrogate (DC00 to DFFF), or a low surrogate with no high one before it.
//
// data must be valid JSON. A backslash then occurs only inside a string, and every escape is
// either one character after the backslash or 'u' and four hex digits, so the escapes can be
// read in order without following the structure of the document.
func hasUnpairedSurrogate(data []byte) bool {
	const escapeLen = 6 // a backslash, 'u' and four hex digits
	// surrogate returns 'h' or 'l' if an escape for a high or a low surrogate starts at i.
	surrogate := func(i int) byte {
		if i+escapeLen > len(data) || data[i] != '\\' || data[i+1] != 'u' || data[i+2]|0x20 != 'd' {
			return 0
		}
		switch c := data[i+3] | 0x20; {
		case c == '8' || c == '9' || c == 'a' || c == 'b':
			return 'h'
		case c >= 'c' && c <= 'f':
			return 'l'
		}
		return 0
	}
	for i := 0; i < len(data); i++ {
		if data[i] != '\\' {
			continue
		}
		switch surrogate(i) {
		case 'l':
			return true
		case 'h':
			if surrogate(i+escapeLen) != 'l' {
				return true
			}
			i += 2*escapeLen - 1
		default:
			i++ // the escaped character, which may be a backslash
		}
	}
	return false
}

// validTimestamp is the occurred_at pattern of the schema, by hand:
// YYYY-MM-DDTHH:MM:SS, an optional fraction of 1 to 9 digits, and Z. Years 1000 to 9999, no
// leap second. Whether the day exists in the month is left to the time package.
func validTimestamp(s string) bool {
	const base = len("2006-01-02T15:04:05")
	if len(s) < base+1 || len(s) > base+11 || s[len(s)-1] != 'Z' {
		return false
	}
	for i := range base {
		c := s[i]
		switch i {
		case 4, 7:
			if c != '-' {
				return false
			}
		case 10:
			if c != 'T' {
				return false
			}
		case 13, 16:
			if c != ':' {
				return false
			}
		default:
			if c < '0' || c > '9' {
				return false
			}
		}
	}
	two := func(i int) int { return int(s[i]-'0')*10 + int(s[i+1]-'0') }
	month, day, hour, minute, second := two(5), two(8), two(11), two(14), two(17)
	if s[0] == '0' || month < 1 || month > 12 || day < 1 || day > 31 || hour > 23 || minute > 59 || second > 59 {
		return false
	}
	frac := s[base : len(s)-1]
	if frac == "" {
		return true
	}
	if frac[0] != '.' || len(frac) < 2 {
		return false
	}
	for i := 1; i < len(frac); i++ {
		if frac[i] < '0' || frac[i] > '9' {
			return false
		}
	}
	return true
}

package record

import (
	"bytes"
	"encoding/json"
	"os"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/santhosh-tekuri/jsonschema/v6"

	"github.com/gablooge/lawang/internal/tenancy"
)

const examplePath = "testdata/example.json"

// The schema is compiled from Schema(), the embedded bytes, and never from the file: what the
// tests prove is then true of what the binary carries.
var (
	compileOnce sync.Once
	asserting   *jsonschema.Schema // formats asserted, which is how a careful sink validates
	annotating  *jsonschema.Schema // "format" is an annotation, which is the default of many validators
	errCompile  error
)

func compile(assertFormat bool) (*jsonschema.Schema, error) {
	doc, err := jsonschema.UnmarshalJSON(bytes.NewReader(Schema()))
	if err != nil {
		return nil, err
	}
	c := jsonschema.NewCompiler()
	if assertFormat {
		c.AssertFormat()
	}
	if err := c.AddResource(SchemaID, doc); err != nil {
		return nil, err
	}
	return c.Compile(SchemaID)
}

func schemas(t testing.TB) (withFormat, withoutFormat *jsonschema.Schema) {
	t.Helper()
	compileOnce.Do(func() {
		if asserting, errCompile = compile(true); errCompile != nil {
			return
		}
		annotating, errCompile = compile(false)
	})
	if errCompile != nil {
		t.Fatalf("the schema does not compile: %v", errCompile)
	}
	return asserting, annotating
}

// schemaError validates one JSON document and returns what the schema has against it, or nil.
func schemaError(t testing.TB, sch *jsonschema.Schema, data []byte) error {
	t.Helper()
	inst, err := jsonschema.UnmarshalJSON(bytes.NewReader(data))
	if err != nil {
		t.Fatalf("the document is not JSON: %v", err)
	}
	return sch.Validate(inst)
}

func exampleBytes(t testing.TB) []byte {
	t.Helper()
	data, err := os.ReadFile(examplePath)
	if err != nil {
		t.Fatal(err)
	}
	return data
}

// exampleDoc is the architecture's example as a generic document, for tests that break it.
func exampleDoc(t testing.TB) map[string]any {
	t.Helper()
	var doc map[string]any
	if err := json.Unmarshal(exampleBytes(t), &doc); err != nil {
		t.Fatal(err)
	}
	return doc
}

// set returns an edit that puts v at a dotted path, and del one that removes the path.
func set(path string, v any) func(map[string]any) {
	return func(doc map[string]any) {
		parent, last := walk(doc, path)
		parent[last] = v
	}
}

func del(path string) func(map[string]any) {
	return func(doc map[string]any) {
		parent, last := walk(doc, path)
		delete(parent, last)
	}
}

func walk(doc map[string]any, path string) (map[string]any, string) {
	parts := strings.Split(path, ".")
	for _, p := range parts[:len(parts)-1] {
		doc = doc[p].(map[string]any)
	}
	return doc, parts[len(parts)-1]
}

const (
	testProvider = "slack"
	testTenant   = tenancy.ID("tenant_a")
)

// draft is what a normalizer hands over: everything but Format, Source and ID. It is the
// architecture's example.
func draft() Record {
	return Record{
		Op:         OpUpsert,
		Kind:       KindMessage,
		ExternalID: "slack:C0GENERAL:1752064245.000200",
		Version:    "1752064245.000200",
		OccurredAt: time.Date(2026, 7, 9, 12, 30, 45, 0, time.UTC),
		Text:       "Numbers are in, call me at [PHONE]",
		Author:     Author{ID: "U0BEN", Display: "ben"},
		Container:  Container{Kind: "channel", ID: "C0GENERAL"},
		Visibility: Visibility{Scope: "slack:channel:C0GENERAL", Audience: AudienceGroup},
		Meta:       Meta{Delivery: "01JZXA8Q2K4M7N9P0R3S5T6V8W"},
	}
}

func sealed(t testing.TB) Record {
	t.Helper()
	r, err := draft().Seal(testProvider, testTenant)
	if err != nil {
		t.Fatal(err)
	}
	return r
}

// onTheWire is r as it comes back from a document: the same record in every field, sealed for no
// tenant, because the tenant is not on the wire (see SealedFor).
func onTheWire(r Record) Record {
	r.sealedFor = ""
	return r
}

// Package record is the record format: the envelope every sink receives, as Go types, and the
// JSON Schema that is its public contract (record.v1.schema.json, embedded as Schema).
//
// The format is settled in docs/adr/0004-record-format-v1.md and the scope id inside it in
// docs/adr/0003-scope-id-format.md. What a sink author needs to know is in the schema's
// descriptions and on the fields below. In short:
//
//   - One Record is one version of one entity, in one scope, for one tenant. Its ID is the
//     idempotency key. An edit, and a move to another scope, are each a new Record that names
//     the one it replaces in Supersedes.
//   - Access is decided on Visibility.Scope and on nothing else. A record carries its scope and
//     never the scope's members: membership travels through access sync, so a membership change
//     never re-delivers a record.
//   - The tenant is not in the envelope. It reaches the sink beside the records (Sink.Deliver
//     takes it), it is hashed into the ID, and a sink keys what it stores by tenant and scope
//     together.
//
// A Record that does not pass Validate cannot be marshalled, and a document the schema refuses
// cannot be unmarshalled into one, so nothing the format forbids passes through encoding/json
// in either direction. The Go side and the schema refuse the same things, and the tests run
// every case through both. The exceptions are the three rules no JSON Schema can express: a
// record that supersedes itself (Validate), and in UnmarshalJSON a field name used twice in one
// object and a document whose bytes are not UTF-8 or that escapes half of a surrogate pair.
package record

import (
	"encoding/json"
	"fmt"
	"strings"
	"time"

	"github.com/gablooge/lawang/internal/ids"
	"github.com/gablooge/lawang/internal/tenancy"
)

// FormatV1 is the value of Record.Format. A sink learns which format it is reading from this
// field, because it is the only thing that is still there when a record sits in a file or a
// queue. Within v1 every record Lawang produces validates against every earlier v1 schema. So
// only fields a reader may ignore are added, and anything else is a new format with a new value:
// a field removed, renamed or made optional, a changed meaning, a limit or a pattern changed in
// either direction, a new Op, Kind or Audience, any change inside Visibility.
const FormatV1 = "lawang.record/v1"

// Op says what the sink does with the record.
type Op string

const (
	// OpUpsert stores this version, replacing the one named by Supersedes if there is one.
	OpUpsert Op = "upsert"
	// OpDelete is a tombstone: the entity is gone at the source, and every stored version of
	// its ExternalID goes with it. Title and Text are empty. It is part of v1 so that shipping
	// deletions later does not change the format, and v0.1 never produces one. A sink that
	// cannot honour a delete refuses the record, it never ignores it.
	OpDelete Op = "delete"
)

// Kind says what the entity is. The set is closed: a new kind is a new format version.
type Kind string

// The kinds of v1.
const (
	KindTask     Kind = "task"
	KindMessage  Kind = "message"
	KindTicket   Kind = "ticket"
	KindDocument Kind = "document"
	KindPage     Kind = "page"
)

// Audience describes a scope. It is informational only: it grants and denies nothing, and a sink
// that reads it as "private" repeats the defect behind principle 9 of the architecture.
type Audience string

const (
	// AudienceDirect is a conversation or a mailbox of named participants.
	AudienceDirect Audience = "direct"
	// AudienceGroup is a shared space: a channel, a list, a portal.
	AudienceGroup Audience = "group"
)

// Record is the envelope. Every field that carries meaning is always present on the wire, with
// null or "" for "none", so a sink never has to tell an absent field from an empty one. Only
// Meta and what is inside it may be absent.
//
// A Record is a plain value with assignable fields, and what holds it to the format is its
// methods: MarshalJSON validates and checks the seal (see Seal), UnmarshalJSON is strict. That
// guards against accidents: a stage that reassigns a scope after sealing, a Record built by hand,
// a record delivered under the wrong tenant (SealedFor). It does NOT defend against a caller
// determined to get around it, and does not try to: a conversion to a type of the caller's own
// (type w record.Record, then json.Marshal(w(r))) sheds the methods, and with them Validate and
// the seal. So "cannot be marshalled" is a statement about the type Record, never about its
// fields, and code that converts a Record away has taken the format's duties on itself.
type Record struct {
	// Format is FormatV1. Seal sets it.
	Format string `json:"format"`
	// ID is "rec_" and 32 lowercase hex characters, minted by Seal from the provider key, the
	// ExternalID, the Version, the Visibility.Scope and the tenant. The format cannot check that
	// an id was minted that way, because the tenant is deliberately not in the envelope.
	ID string `json:"id"`
	Op Op     `json:"op"`
	// Source is the name the sink knows the source by. Seal sets it to the provider key, and a
	// sink configured with another wire name replaces it on the way out. It is in no id, and it
	// need not equal the first segment of Visibility.Scope, which is always the provider key.
	Source string `json:"source"`
	Kind   Kind   `json:"kind"`
	// ExternalID is the entity's identity, the same for every version of it, and unique within
	// one tenant across all of the tenant's sources: it begins with the provider key and a colon
	// ("slack:C0GENERAL:1752064245.000200"), and Seal refuses one that does not. A sink keys an
	// entity by tenant and ExternalID together, never by Source. 1 to MaxExternalID characters of
	// an identifier (see identifierChars for what that excludes). Opaque beyond the prefix.
	ExternalID string `json:"external_id"`
	// Version names this version of the entity: 1 to MaxVersion characters of an identifier.
	// The provider's normalizer promises that it changes whenever the entity
	// changes, and that for one ExternalID it never goes backwards. Nothing in the format can
	// check that promise. To a sink a version is opaque: equal or not equal, and the order of
	// versions is what Supersedes says.
	Version string `json:"version"`
	// Supersedes is the ID of the record this one replaces, or none (null on the wire). Links
	// point forward only, and a record never supersedes itself.
	Supersedes Ref `json:"supersedes"`
	// OccurredAt is when it happened at the source, never when it was ingested. It must be in
	// time.UTC (call UTC() on a parsed time) and in the years 1000 to 9999, which also refuses
	// the zero time.
	OccurredAt time.Time `json:"occurred_at"`
	// Title and Text may be empty, and are empty on a delete. Both are PII-masked before they
	// get here. At most MaxTitle and MaxText characters. Text holds anything but NUL, which a
	// Postgres text column cannot hold. Title is one line: no control character (so no tab and
	// no line break) and no line or paragraph separator. Both keep bidirectional formatting,
	// which right-to-left text uses, so neither is safe to display as it stands. The format
	// refuses and never repairs: cutting a text down, and turning the line breaks of a title
	// into spaces, is the normalizer's job.
	Title string `json:"title"`
	Text  string `json:"text"`
	// Author is informational. Access is never decided on it.
	Author    Author    `json:"author"`
	Container Container `json:"container"`
	// Visibility is everything access is decided on.
	Visibility Visibility `json:"visibility"`
	Origin     Origin     `json:"origin"`
	Edges      Edges      `json:"edges"`
	// Meta is diagnostics and not part of the record's content: the same ID may arrive again
	// with a different Meta.
	Meta Meta `json:"meta"`

	// sealed is what the ID stands for, as Seal minted it or as UnmarshalJSON read it. The
	// fields it copies stay assignable, because a Record is a plain value, and MarshalJSON
	// refuses a record in which they no longer say what was sealed. No other package can set
	// this, so outside this package the only ways to a record that can be marshalled are Seal
	// and decoding one. The doc comment of Record says what that does not defend against.
	sealed seal
	// sealedFor is the tenant Seal minted the ID for, and empty in a decoded record, because
	// the tenant is not on the wire. See SealedFor.
	sealedFor tenancy.ID
}

// seal is the ID, the three fields of the envelope that are hashed into it, and Op and Kind. The
// provider and the tenant are hashed too and are not in the envelope, which is why the check is
// a comparison with what Seal saw and not a second hash. Op and Kind are not hashed, and are
// held for another reason: one id is one version of one entity, and an upsert turned into a
// tombstone after sealing (or a message into a task) would go out under the id of what it was,
// where a sink that is idempotent on the id drops it as a repeat. A tombstone is a new version
// (ADR 4), so it is built as one and sealed as one.
type seal struct {
	id, externalID, version, scope string
	op                             Op
	kind                           Kind
}

func (r Record) currentSeal() seal {
	return seal{
		id: r.ID, externalID: r.ExternalID, version: r.Version, scope: r.Visibility.Scope,
		op: r.Op, kind: r.Kind,
	}
}

// SealedFor reports whether Seal minted this record's ID for tenant, and the record still says
// what was sealed. It is for the one place where a tenant and a record meet again after Seal: the
// stage that writes the ledger and hands records to Sink.Deliver. The tenant is in no field of
// the envelope, so a record sealed for tenant A marshals exactly the same when it is delivered
// under tenant B, and neither MarshalJSON nor any sink can notice. That stage can: it calls
// SealedFor with the tenant it is about to deliver under, and treats false as a refusal.
//
// A consequence to know about: a sealed Record and the same record decoded from its own document
// are not equal under == or reflect.DeepEqual, because only the sealed one knows its tenant,
// although they marshal to identical bytes. Compare documents, or compare field by field. Never
// compare Record values.
//
// It fails closed. It is false for a record that was decoded and not sealed here (a document
// does not say whose it is), for the zero Record, for an empty tenant, and for a record whose
// ID, ExternalID, Version, Visibility.Scope, Op or Kind was changed after Seal.
func (r Record) SealedFor(tenant tenancy.ID) bool {
	return tenant != "" && r.sealedFor == tenant && r.sealed == r.currentSeal()
}

// Author is who wrote the entity, in the source's own terms. Both fields may be empty when the
// source does not say (a record degraded to the webhook body, a system event). At most MaxAuthor
// characters each.
type Author struct {
	// ID is an identifier (identifierChars).
	ID string `json:"id"`
	// Display is a name somebody chose for themselves, so it is where a line break or a
	// right-to-left override would be planted to forge a log line or to pass for somebody else
	// in a sink's UI. It holds what an identifier holds, and the zero-width joiner and
	// non-joiner, which names and emoji are spelled with (displayChars). The format refuses and
	// never repairs: a normalizer removes the refused characters from the name the source gave.
	Display string `json:"display"`
}

// Container is where the entity lives at the source: the channel of a message, the task of a
// comment. It is often the container the scope is made of, and need not be (a comment lives in
// a task and is decided on the task's list).
type Container struct {
	// Kind follows the container kind grammar of a scope id: a lowercase letter, then up to 31
	// of a-z 0-9 _.
	Kind string `json:"kind"`
	// ID is the source's id exactly as the source spells it, not escaped: 1 to MaxContainerID
	// characters of an identifier (identifierChars).
	ID string `json:"id"`
}

// Visibility is closed. Unmarshalling a Record refuses a field it does not know in here, because
// a field added here could only be one a sink must not ignore.
type Visibility struct {
	// Scope is a scope id, built with ScopeID: a person may see the record if they are a member
	// of this scope, for the record's tenant.
	Scope    string   `json:"scope"`
	Audience Audience `json:"audience"`
}

// Origin is what Lawang knows about where the content came from. Both fields are signals and
// never clearances: true means there is a positive signal, false means there is NO SIGNAL (the
// source did not say, the provider cannot tell, or this version does not look). False is never
// the opposite of true. A sink treats every text as untrusted content whatever Origin says, and
// uses true to be stricter, never false to be laxer. A normalizer sets a field to true only on a
// positive signal from the source, and leaves it false otherwise.
type Origin struct {
	// Automation true: the source marks the author as a bot or an integration. False: no
	// signal, never a statement that a person wrote it.
	Automation bool `json:"automation"`
	// Untrusted true: there is a positive signal that the author is outside the tenant (inbound
	// mail from a stranger, an external guest). Such text may be written to steer an AI agent
	// that reads it. False: no signal, never a statement that the author is inside the tenant
	// or that the text is safe to follow. v0.1 sets it for no provider (the roadmap has the
	// marking after v0.1), so in v0.1 mail from a stranger says false.
	Untrusted bool `json:"untrusted"`
}

// Edges are relations to other entities, taken from fields of the source, never from the text.
type Edges struct {
	// ReplyParent is the ExternalID of the entity this one replies to, or none.
	ReplyParent Ref `json:"reply_parent"`
}

// Meta is diagnostics.
type Meta struct {
	// Delivery is Lawang's id of the accepted delivery the record was made from. Optional,
	// at most MaxDelivery characters.
	Delivery string `json:"delivery,omitempty"`
}

// Ref is a reference that may be missing. The zero value is "none" and is null on the wire. The
// empty string is not a reference, so unmarshalling refuses "".
type Ref string

// MarshalJSON writes null for no reference.
func (r Ref) MarshalJSON() ([]byte, error) {
	if r == "" {
		return []byte("null"), nil
	}
	return json.Marshal(string(r))
}

// UnmarshalJSON reads null as no reference and refuses an empty string.
func (r *Ref) UnmarshalJSON(data []byte) error {
	if string(data) == "null" {
		*r = ""
		return nil
	}
	var s string
	if err := json.Unmarshal(data, &s); err != nil {
		return fmt.Errorf("%w: a reference is a string or null", ErrInvalid)
	}
	if s == "" {
		return fmt.Errorf("%w: a reference is null, never an empty string", ErrInvalid)
	}
	*r = Ref(s)
	return nil
}

// wire has Record's fields and none of its methods, so marshalling it does not come back here.
type wire Record

// MarshalJSON refuses a record that does not pass Validate, and a record whose ID is not the one
// that was sealed for the ExternalID, Version, Visibility.Scope, Op and Kind it now carries: one
// that was never sealed, or one that was changed afterwards. A sink is promised that one id never
// appears with two scopes, and without this a pipeline stage that reassigned the scope after
// sealing would break the promise far from where anybody would look. Seal again after such a
// change. Supersedes, Source, the content and everything else may be set after sealing.
//
// It cannot check the tenant, which is in no field: SealedFor does, where the tenant is known.
//
// The error says which field, never what was in it.
func (r Record) MarshalJSON() ([]byte, error) {
	if err := r.Validate(); err != nil {
		return nil, err
	}
	if r.sealed != r.currentSeal() {
		return nil, invalid("id", "was not sealed for the external_id, version, visibility.scope, op and kind the record carries")
	}
	return json.Marshal(wire(r))
}

// Seal finishes a record a normalizer built: it sets Format, sets Source to the provider key,
// mints the ID, and validates the result. It is the only way to an ID, so an id always hashes
// the scope the record carries, and a record with no tenant or no scope never gets one. Two
// things hold that: a test in internal/ids fails when anything outside this package calls the id
// recipe (a tripwire), and MarshalJSON refuses a record whose ID, ExternalID, Version,
// Visibility.Scope, Op or Kind is not what Seal left there (the guard). Seal also remembers the
// tenant, which is in no field, so that the stage that delivers can ask SealedFor.
//
// provider is the internal provider key (Provider.Key), never a wire name. Seal refuses a scope
// that is not in that provider's namespace, so one provider cannot stamp a record into the scope
// of another, and for the same reason an ExternalID or an Edges.ReplyParent that does not begin
// with the provider key and a colon. It refuses a Source that was already set to anything else,
// and a tenant that tenancy.Parse would refuse.
//
// Supersedes is usually set after sealing, once the ledger has been asked which record the new
// ID replaces. Nothing is lost by that order: marshalling validates again.
func (r Record) Seal(provider string, tenant tenancy.ID) (Record, error) {
	if !ValidProviderKey(provider) {
		return Record{}, invalid("provider", "is not a provider key")
	}
	if r.Source != "" && r.Source != provider {
		return Record{}, invalid("source", "is set by Seal, a wire name is the sink's to set")
	}
	scope := r.Visibility.Scope
	if err := checkScopeID(scope); err != nil {
		return Record{}, invalid("visibility.scope", "is not a scope id")
	}
	if !strings.HasPrefix(scope, provider+":") {
		return Record{}, invalid("visibility.scope", "belongs to another provider")
	}
	// The same namespace holds the entity: an external id is unique within a tenant because it
	// begins with the provider key, so a normalizer that handed over the source's bare id would
	// let two providers share one entity at the sink, and a delete for one would remove the other.
	if !strings.HasPrefix(r.ExternalID, provider+":") {
		return Record{}, invalid("external_id", "does not begin with the provider key and a colon")
	}
	if parent := string(r.Edges.ReplyParent); parent != "" && !strings.HasPrefix(parent, provider+":") {
		return Record{}, invalid("edges.reply_parent", "does not begin with the provider key and a colon")
	}
	if _, err := tenancy.Parse(tenant.String()); err != nil {
		return Record{}, invalid("tenant", "is not a tenant id")
	}
	id, err := ids.RecordID(provider, r.ExternalID, r.Version, scope, tenant.String())
	if err != nil {
		return Record{}, invalid("id", "cannot be minted: "+err.Error())
	}
	r.Format = FormatV1
	r.Source = provider
	r.ID = id
	r.sealed = r.currentSeal()
	r.sealedFor = tenant
	if err := r.Validate(); err != nil {
		return Record{}, err
	}
	return r, nil
}

