func BenchmarkUnmarshal(b *testing.B) {
	data := exampleBytes(b)
	b.ReportAllocs()
	for b.Loop() {
		var r Record
		if err := json.Unmarshal(data, &r); err != nil {
			b.Fatal(err)
		}
	}
}

