// In some regular expression dialects '$' also matches before a trailing newline, so a schema
// that leaned on the anchor alone would accept "rec_...\n" in a validator built on one. Go's
// dialect is not one of them, so no Go test can show the difference by validating. This checks
// the schema's structure: every subschema with an anchored pattern also has a fixed length, or
// a "not" with an unanchored character class, which does not depend on the anchor.
func TestEveryAnchoredPatternHasACompanion(t *testing.T) {
	var schema any
	if err := json.Unmarshal(Schema(), &schema); err != nil {
		t.Fatal(err)
	}
	patterns := 0
	var visit func(path string, node any)
	visit = func(path string, node any) {
		switch n := node.(type) {
		case []any:
			for _, v := range n {
				visit(path+"[]", v)
			}
		case map[string]any:
			for k, v := range n {
				visit(path+"/"+k, v)
			}
			pattern, ok := n["pattern"].(string)
			if !ok || !strings.HasSuffix(pattern, "$") {
				return
			}
			patterns++
			minLen, hasMin := n["minLength"]
			maxLen, hasMax := n["maxLength"]
			fixed := hasMin && hasMax && reflect.DeepEqual(minLen, maxLen)
			not, _ := n["not"].(map[string]any)
			class, _ := not["pattern"].(string)
			unanchored := strings.HasPrefix(class, "[^") && strings.HasSuffix(class, "]")
			if !fixed && !unanchored {
				t.Errorf("%s: the anchored pattern %q has no fixed length and no unanchored companion", path, pattern)
			}
		}
	}
	visit("", schema)
	if patterns < 6 {
		t.Errorf("found %d anchored patterns, the walk is not seeing the schema", patterns)
	}
}

// The schema is a contract for validators in any language, and each hands "pattern" to its own
// regular expression engine. The escapes those engines share stop at ASCII: Ruby's engine refuses
// a two-digit hex escape of 0x80 or above in a UTF-8 pattern ("invalid multibyte escape"), so a
// schema that spelled U+009F that way could not be loaded there at all, and the brace form of a
// hex escape, the four-digit form and a property class are each unknown to one of Go, Python and
// ECMAScript. So a pattern escapes ASCII only and holds every other character as itself, which
// the FILE spells with a JSON escape (ADR 4, "Portability of the patterns"). This pins the
// spelling, so that the unportable one cannot come back. It reads the patterns as they are after
// JSON decoding, which is what an engine is handed.
func TestNoPatternUsesAnEscapeThatOnlySomeEnginesRead(t *testing.T) {
	file, err := os.ReadFile("record.v1.schema.json")
	if err != nil {
		t.Fatal(err)
	}
	for i, b := range file {
		if b >= 0x80 {
			t.Fatalf("byte %d of the schema file is not ASCII: a character above U+007F is written as a JSON escape", i)
		}
	}
	var schema any
	if err := json.Unmarshal(Schema(), &schema); err != nil {
		t.Fatal(err)
	}
	// A backslash, then: x and a hex byte of 0x80 or above, or x and a brace, or one of u, p, P.
	unportable := regexp.MustCompile(`[\\](?:x[89A-Fa-f][0-9A-Fa-f]|x[{]|[upP])`)
	patterns, literal := 0, 0
	var visit func(path string, node any)
	visit = func(path string, node any) {
		switch n := node.(type) {
		case []any:
			for _, v := range n {
				visit(path+"[]", v)
			}
		case map[string]any:
			for k, v := range n {
				visit(path+"/"+k, v)
			}
			pattern, ok := n["pattern"].(string)
			if !ok {
				return
			}
			patterns++
			if found := unportable.FindString(pattern); found != "" {
				t.Errorf("%s: the pattern uses the escape %s, which not every engine reads: write the character itself, as a JSON escape in the file", path, found)
			}
			if strings.ContainsRune(pattern, 0x0080) && strings.ContainsRune(pattern, 0x009F) {
				literal++
			}
		}
	}
	visit("", schema)
	if patterns < 16 {
		t.Errorf("found %d patterns, the walk is not seeing the schema", patterns)
	}
	// identifier, displayName and oneLine name the C1 controls, and they do it with the characters.
	if literal != 3 {
		t.Errorf("%d patterns hold U+0080 and U+009F as themselves, want 3", literal)
	}
}

func TestSchemaIsTheEmbeddedFileAndNamesItself(t *testing.T) {
	file, err := os.ReadFile("record.v1.schema.json")
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(file, Schema()) {
		t.Error("Schema() is not record.v1.schema.json")
	}
	var head struct {
		Schema     string `json:"$schema"`
		ID         string `json:"$id"`
		Properties struct {
			Format struct {
				Const string `json:"const"`
			} `json:"format"`
		} `json:"properties"`
	}
	if err := json.Unmarshal(file, &head); err != nil {
		t.Fatal(err)
	}
	if head.Schema != "https://json-schema.org/draft/2020-12/schema" {
		t.Errorf("$schema = %q, want draft 2020-12", head.Schema)
	}
	if head.ID != SchemaID {
		t.Errorf("$id = %q, SchemaID = %q", head.ID, SchemaID)
	}
	if head.Properties.Format.Const != FormatV1 {
		t.Errorf("format const = %q, FormatV1 = %q", head.Properties.Format.Const, FormatV1)
	}

	// A caller that scribbles on the result does not reach the embedded bytes.
	got := Schema()
	got[0] = 'X'
	if Schema()[0] == 'X' {
		t.Error("Schema() hands out the embedded slice itself")
	}
}

package record

import (
	"errors"
	"fmt"
	"strings"
)

// MaxScopeID is the longest scope id, in bytes. A scope id is ASCII, so bytes and characters are
// the same count.
const MaxScopeID = 512

// ErrBadScopeID reports parts that cannot make a scope id, or a string that is not one. The
// message never quotes the input.
var ErrBadScopeID = errors.New("record: bad scope id")

// Scope is a scope id taken apart.
type Scope struct {
	// Provider is the internal provider key, never a sink's wire name.
	Provider string
	// ContainerKind is the provider's word for the kind of container: channel, list, mailbox.
	ContainerKind string
	// ContainerID is the provider's id of the container, decoded: exactly the bytes the
	// provider uses.
	ContainerID string
}

// ScopeID builds the scope id of a container:
//
//	{provider}:{container_kind}:{container_id}
//
// It is the one thing access is decided on, and it is a join key: a record carries it in
// Visibility.Scope, and the membership that access sync pushes for the same container carries
// the same string. Both sides therefore build it here, from the same three parts, and never by
// hand (ADR 3).
//
// provider is the internal provider key, not a wire name: a wire name is per sink and may
// change, and a scope id that changed with it would cut every delivered record off from its
// members. provider and containerKind are a lowercase letter followed by up to 31 of a-z, 0-9
// and underscore. containerID is the provider's id byte for byte, never case-folded or trimmed.
// The characters A-Z a-z 0-9 . _ ~ - stay as they are, every other byte becomes %XX with
// uppercase hex (so a Microsoft Graph id keeps its ':', '/', '=' and '+' and the result still
// has exactly two colons), and an id that is empty or holds a control character is refused. The
// result is ASCII and at most MaxScopeID bytes. The tenant is deliberately not part of it.
func ScopeID(provider, containerKind, containerID string) (string, error) {
	if !ValidProviderKey(provider) {
		return "", fmt.Errorf("%w: the provider key", ErrBadScopeID)
	}
	if !validName(containerKind, maxKind, false) {
		return "", fmt.Errorf("%w: the container kind", ErrBadScopeID)
	}
	if containerID == "" {
		return "", fmt.Errorf("%w: the container id is empty", ErrBadScopeID)
	}
	var b strings.Builder
	b.Grow(len(provider) + len(containerKind) + len(containerID) + 2)
	b.WriteString(provider)
	b.WriteByte(':')
	b.WriteString(containerKind)
	b.WriteByte(':')
	for i := range len(containerID) {
		c := containerID[i]
		switch {
		case unreserved(c):
			b.WriteByte(c)
		case control(c):
			return "", fmt.Errorf("%w: the container id holds a control character", ErrBadScopeID)
		default:
			b.WriteByte('%')
			b.WriteByte(upperHex[c>>4])
			b.WriteByte(upperHex[c&0x0F])
		}
		if b.Len() > MaxScopeID {
			return "", fmt.Errorf("%w: longer than %d bytes", ErrBadScopeID, MaxScopeID)
		}
	}
	return b.String(), nil
}

// ParseScopeID takes a scope id apart. It accepts exactly the strings ScopeID produces, so
// ScopeID(ParseScopeID(s)) is s again, and no two different strings name one scope: an escape of
// a character that needs none, a lowercase hex digit and an escaped control character are all
// refused.
//
// Lawang parses its own scope ids. A sink does not need to: to a sink a scope id is opaque,
// and two of them name the same scope exactly when they are equal byte for byte.
func ParseScopeID(s string) (Scope, error) {
	if err := checkScopeID(s); err != nil {
		return Scope{}, err
	}
	first := strings.IndexByte(s, ':')
	second := first + 1 + strings.IndexByte(s[first+1:], ':')
	enc := s[second+1:]

	id := make([]byte, 0, len(enc))
	for i := 0; i < len(enc); i++ {
		if enc[i] == '%' {
			id = append(id, unhex(enc[i+1])<<4|unhex(enc[i+2]))
			i += 2
			continue
		}
		id = append(id, enc[i])
	}
	return Scope{Provider: s[:first], ContainerKind: s[first+1 : second], ContainerID: string(id)}, nil
}

// checkScopeID is the whole grammar, without allocating. Validate runs it for every record.
func checkScopeID(s string) error {
	if len(s) > MaxScopeID {
		return fmt.Errorf("%w: longer than %d bytes", ErrBadScopeID, MaxScopeID)
	}
	first := strings.IndexByte(s, ':')
	if first < 0 || !ValidProviderKey(s[:first]) {
		return fmt.Errorf("%w: the provider key", ErrBadScopeID)
	}
	rest := s[first+1:]
	second := strings.IndexByte(rest, ':')
	if second < 0 || !validName(rest[:second], maxKind, false) {
		return fmt.Errorf("%w: the container kind", ErrBadScopeID)
	}
	enc := rest[second+1:]
	if enc == "" {
		return fmt.Errorf("%w: the container id is empty", ErrBadScopeID)
	}
	for i := 0; i < len(enc); i++ {
		c := enc[i]
		if unreserved(c) {
			continue
		}
		if c != '%' || i+2 >= len(enc) || !isUpperHex(enc[i+1]) || !isUpperHex(enc[i+2]) {
			return fmt.Errorf("%w: the container id holds a character that is not escaped", ErrBadScopeID)
		}
		decoded := unhex(enc[i+1])<<4 | unhex(enc[i+2])
		if unreserved(decoded) || control(decoded) {
			return fmt.Errorf("%w: the container id holds an escape the format does not write", ErrBadScopeID)
		}
		i += 2
	}
	return nil
}

const upperHex = "0123456789ABCDEF"

// unreserved is the set RFC 3986 calls unreserved: the bytes a scope id carries as they are.
func unreserved(c byte) bool {
	return c >= 'A' && c <= 'Z' || c >= 'a' && c <= 'z' || c >= '0' && c <= '9' ||
		c == '.' || c == '_' || c == '~' || c == '-'
}

func control(c byte) bool { return c < 0x20 || c == 0x7F }

func isUpperHex(c byte) bool { return c >= '0' && c <= '9' || c >= 'A' && c <= 'F' }

func unhex(c byte) byte {
	if c >= 'A' {
		return c - 'A' + 10
	}
	return c - '0'
}

package record

import (
	"encoding/json"
	"errors"
	"fmt"
	"math/rand/v2"
	"net/http"
	"net/http/httptest"
	"net/url"
	"strings"
	"testing"

	"github.com/santhosh-tekuri/jsonschema/v6"
)

func TestScopeID(t *testing.T) {
	tests := []struct {
		provider, kind, id string
		want               string
	}{
		{"slack", "channel", "C0GENERAL", "slack:channel:C0GENERAL"},
		{"slack", "dm", "D024BE91L", "slack:dm:D024BE91L"},
		{"clickup", "list", "901100", "clickup:list:901100"},
		{"hubspot", "portal", "62515", "hubspot:portal:62515"},
		{"outlook", "mailbox", "ben@example.com", "outlook:mailbox:ben%40example.com"},
		// A Microsoft Graph channel id: a colon and an at sign.
		{"teams", "channel", "19:abc123@thread.tacv2", "teams:channel:19%3Aabc123%40thread.tacv2"},
		// A Graph id in base64: slash, plus, equals. Hyphen and underscore stay.
		{"outlook", "mailbox", "AAMkAGI2/x+y-z_w==", "outlook:mailbox:AAMkAGI2%2Fx%2By-z_w%3D%3D"},
		// Every unreserved character stays, the percent sign and the space do not.
		{"p", "k", "Az09._~-", "p:k:Az09._~-"},
		{"p", "k", "100% sure", "p:k:100%25%20sure"},
		// Case is the provider's and is kept.
		{"slack", "channel", "c0general", "slack:channel:c0general"},
		// UTF-8 goes byte by byte.
		{"p", "k", "é☕", "p:k:%C3%A9%E2%98%95"},
		// Bytes that are not UTF-8 are bytes like any other: an id is opaque.
		{"p", "k", "\xff\x80", "p:k:%FF%80"},
		{"p2_x", "k_2", "1", "p2_x:k_2:1"},
	}
	for _, tt := range tests {
		got, err := ScopeID(tt.provider, tt.kind, tt.id)
		if err != nil {
			t.Errorf("ScopeID(%q, %q, %q): %v", tt.provider, tt.kind, tt.id, err)
			continue
		}
		if got != tt.want {
			t.Errorf("ScopeID(%q, %q, %q) = %q, want %q", tt.provider, tt.kind, tt.id, got, tt.want)
		}
		if n := strings.Count(got, ":"); n != 2 {
			t.Errorf("%q has %d colons, want exactly 2", got, n)
		}
		back, err := ParseScopeID(got)
		if err != nil {
			t.Errorf("ParseScopeID(%q): %v", got, err)
			continue
		}
		if back != (Scope{Provider: tt.provider, ContainerKind: tt.kind, ContainerID: tt.id}) {
			t.Errorf("ParseScopeID(%q) = %+v", got, back)
		}
	}
}

func TestScopeIDRefusesBadParts(t *testing.T) {
	tests := []struct{ name, provider, kind, id string }{
		{"no provider", "", "channel", "C1"},
		{"a capital in the provider", "Slack", "channel", "C1"},
		{"a colon in the provider", "sla:ck", "channel", "C1"},
		{"a hyphen in the provider", "ms-teams", "channel", "C1"},
		{"a provider starting with a digit", "1up", "channel", "C1"},
		{"a provider of 33 characters", "p" + strings.Repeat("a", 32), "channel", "C1"},
		{"no kind", "slack", "", "C1"},
		{"a capital in the kind", "slack", "Channel", "C1"},
		{"a colon in the kind", "slack", "chan:nel", "C1"},
		{"a kind of 33 characters", "slack", "k" + strings.Repeat("a", 32), "C1"},
		{"no id", "slack", "channel", ""},
		{"a NUL in the id", "slack", "channel", "C1\x00"},
		{"a newline in the id", "slack", "channel", "C1\nslack:channel:C2"},
		{"the 0x1F separator in the id", "slack", "channel", "C\x1f1"},
		{"DEL in the id", "slack", "channel", "C1\x7f"},
		{"an id that is too long", "slack", "channel", strings.Repeat("a", longest+1)},
		{"an id that is too long once escaped", "slack", "channel", strings.Repeat("=", longest/3+1)},
	}
	for _, tt := range tests {
		got, err := ScopeID(tt.provider, tt.kind, tt.id)
		if !errors.Is(err, ErrBadScopeID) {
			t.Errorf("%s: err = %v, want ErrBadScopeID", tt.name, err)
		}
		if got != "" {
			t.Errorf("%s: returned %q alongside the error", tt.name, got)
		}
		if err != nil && tt.id != "" && strings.Contains(err.Error(), tt.id) {
			t.Errorf("%s: the error quotes the id", tt.name)
		}
	}

	// The longest ids that fit, plain and escaped.
	if _, err := ScopeID("slack", "channel", strings.Repeat("a", longest)); err != nil {
		t.Errorf("an id that makes exactly MaxScopeID bytes: %v", err)
	}
	if _, err := ScopeID("slack", "channel", strings.Repeat("=", longest/3)); err != nil {
		t.Errorf("an escaped id that fits: %v", err)
	}
}

type namedScope struct{ name, id string }

// badScopeIDs is every way a string can fail to be a scope id. The agreement test runs the same
// list through the schema, so the pattern there and the parser here cannot drift apart.
func badScopeIDs() []namedScope {
	return []namedScope{
		{"empty", ""},
		{"one segment", "slack"},
		{"two segments", "slack:channel"},
		{"no container id", "slack:channel:"},
		{"no container kind", "slack::C1"},
		{"no provider", ":channel:C1"},
		{"a capital in the provider", "Slack:channel:C1"},
		{"a capital in the kind", "slack:Channel:C1"},
		{"a hyphen in the provider", "ms-teams:channel:C1"},
		{"a provider that starts with a digit", "1up:channel:C1"},
		{"a kind that starts with a digit", "slack:1list:C1"},
		{"a provider that starts with an underscore", "_up:channel:C1"},
		{"an escaped lowercase letter", "slack:channel:%61"},
		{"lowercase hex in an escaped UTF-8 byte", "slack:channel:%c3%a9"},
		{"a provider of 33 characters", "p" + strings.Repeat("a", 32) + ":channel:C1"},
		{"a kind of 33 characters", "slack:k" + strings.Repeat("a", 32) + ":C1"},
		{"a third colon", "teams:channel:19:abc"},
		{"a trailing colon", "slack:channel:C1:"},
		{"a space", "slack:channel:C 1"},
		{"a slash", "slack:channel:a/b"},
		{"an at sign", "outlook:mailbox:ben@example.com"},
		{"a plus", "slack:channel:a+b"},
		{"an equals sign", "slack:channel:ab=="},
		{"raw UTF-8", "slack:channel:é"},
		{"a lowercase escape", "slack:channel:a%3ab"},
		{"a mixed case escape", "slack:channel:a%3aB%3A"},
		{"an escaped letter", "slack:channel:%41"},
		{"an escaped digit", "slack:channel:%30"},
		{"an escaped hyphen", "slack:channel:a%2Db"},
		{"an escaped dot", "slack:channel:a%2Eb"},
		{"an escaped underscore", "slack:channel:a%5Fb"},
		{"an escaped tilde", "slack:channel:a%7Eb"},
		{"an escaped NUL", "slack:channel:a%00"},
		{"an escaped newline", "slack:channel:a%0Ab"},
		{"an escaped 0x1F", "slack:channel:a%1Fb"},
		{"an escaped DEL", "slack:channel:a%7F"},
		{"a bare percent", "slack:channel:100%"},
		{"half an escape", "slack:channel:a%4"},
		{"an escape that is not hex", "slack:channel:a%ZZ"},
		{"a percent before another escape", "slack:channel:%%41"},
		{"a raw newline at the end", "slack:channel:C1\n"},
		{"a raw NUL", "slack:channel:C1\x00"},
		{"a raw tab", "slack:channel:C\t1"},
		{"one byte too long", scope3 + strings.Repeat("a", longest+1)},
