package record

import (
	"errors"
	"fmt"
	"strings"
	"time"
	"unicode/utf8"

	"github.com/gablooge/lawang/internal/ids"
)

// ErrInvalid reports a record, or a part of one, that the format forbids. The message names the
// field and the rule, never the value: a title, a text and an author are personal data, and an
// error ends up in a log or in an outbox row.
var ErrInvalid = errors.New("record: invalid")

// Limits, in characters (Unicode code points, which is what a JSON Schema maxLength counts).
// They exist so that nothing a sender controls is unbounded. A normalizer cuts a text down to
// MaxText itself: Validate refuses a longer one, it does not truncate.
const (
	MaxExternalID  = 1024
	MaxVersion     = 256
	MaxTitle       = 1024
	MaxText        = 1 << 20
	MaxAuthor      = 256
	MaxContainerID = 512
	MaxDelivery    = 128
)

const (
	// maxSource bounds Source, which may also hold a sink's wire name.
	maxSource = 64
	// maxKind bounds a provider key and a container kind, the first two segments of a scope id.
	maxKind = 32
	// recordIDLen is "rec_" and 32 hex characters.
	recordIDLen = len(ids.RecordPrefix) + 32
	minYear     = 1000
	maxYear     = 9999
)

func invalid(field, rule string) error {
	return fmt.Errorf("%w: %s %s", ErrInvalid, field, rule)
}

// Validate reports the first thing about r that the format forbids, as an error that wraps
// ErrInvalid. A record that passes is one the schema accepts.
//
// It checks exactly what the schema checks, and one rule the schema cannot express: Supersedes
// is not the record's own ID (JSON Schema cannot compare two fields). A sink that validates with
// the schema alone should add that check itself.
//
// It also refuses two Go values that have no faithful form on the wire, where encoding/json
// would quietly write something else: a string that is not valid UTF-8 (written with U+FFFD in
// place of the bad bytes), and an OccurredAt whose Location is not time.UTC. The second is
// refused even at offset zero, where the wire form would happen to be right, so that a
// normalizer which forgot UTC() fails on every record and not only in summer.
//
// It does not and cannot check that ID was minted by Seal, that Version moves forward, or that
// Supersedes names a record that exists.
func (r Record) Validate() error {
	if r.Format != FormatV1 {
		return invalid("format", "is not "+FormatV1)
	}
	if !validRecordID(r.ID) {
		return invalid("id", "is not a record id")
	}
	if r.Op != OpUpsert && r.Op != OpDelete {
		return invalid("op", "is not one of upsert, delete")
	}
	if !validName(r.Source, maxSource, true) {
		return invalid("source", "is not a source name")
	}
	switch r.Kind {
	case KindTask, KindMessage, KindTicket, KindDocument, KindPage:
	default:
		return invalid("kind", "is not one of task, message, ticket, document, page")
	}
	if err := checkExternalID("external_id", r.ExternalID); err != nil {
		return err
	}
	if err := checkString("version", r.Version, 1, MaxVersion, identifierChars); err != nil {
		return err
	}
	if r.Supersedes != "" {
		if !validRecordID(string(r.Supersedes)) {
			return invalid("supersedes", "is not a record id")
		}
		if string(r.Supersedes) == r.ID {
			return invalid("supersedes", "names the record itself")
		}
	}
	if err := checkTime(r.OccurredAt); err != nil {
		return err
	}
	if err := checkString("title", r.Title, 0, MaxTitle, oneLineChars); err != nil {
		return err
	}
	if err := checkString("text", r.Text, 0, MaxText, contentChars); err != nil {
		return err
	}
	if r.Op == OpDelete && (r.Title != "" || r.Text != "") {
		return invalid("title and text", "are empty on a delete")
	}
	if err := checkString("author.id", r.Author.ID, 0, MaxAuthor, identifierChars); err != nil {
		return err
	}
	if err := checkString("author.display", r.Author.Display, 0, MaxAuthor, displayChars); err != nil {
		return err
	}
	if !validName(r.Container.Kind, maxKind, false) {
		return invalid("container.kind", "is not a container kind")
	}
	if err := checkString("container.id", r.Container.ID, 1, MaxContainerID, identifierChars); err != nil {
		return err
	}
	if err := checkScopeID(r.Visibility.Scope); err != nil {
		return invalid("visibility.scope", "is not a scope id")
	}
	if r.Visibility.Audience != AudienceDirect && r.Visibility.Audience != AudienceGroup {
		return invalid("visibility.audience", "is not one of direct, group")
	}
	if r.Edges.ReplyParent != "" {
		if err := checkExternalID("edges.reply_parent", string(r.Edges.ReplyParent)); err != nil {
			return err
		}
	}
	return checkString("meta.delivery", r.Meta.Delivery, 0, MaxDelivery, identifierChars)
}

// charRule says which characters a string may not contain. The four rules are the same four in
// the schema ($defs identifier, displayName and oneLine, and the pattern of text), and ADR 4 has
// the reasons ("Which characters a field may hold"). Each is a fixed list of code points and
// never a Unicode category, because a category grows with every Unicode version and the format
// may not.
type charRule int

const (
	// identifierChars is for what a program compares and an operator reads in a log:
	// ExternalID, Version, Author.ID, Container.ID, Edges.ReplyParent, Meta.Delivery. Refused:
	// every control character (C0, DEL, C1), the line and paragraph separators, every
	// bidirectional formatting character, and the zero-width and invisible format characters
	// listed at invisible.
	identifierChars charRule = iota
	// displayChars is for Author.Display: identifierChars, less the zero-width non-joiner and
	// joiner (U+200C, U+200D), which Persian and Indic names are spelled with and emoji are built
	// with.
	displayChars
	// oneLineChars is for Title, which is content in any language, on a single line: every
	// control character and the line and paragraph separators are refused. Bidirectional
	// formatting stays, because right-to-left titles use it.
	oneLineChars
	// contentChars is for Text: only NUL is refused, which a Postgres text column cannot hold.
	// Newlines, tabs and everything else are content.
	contentChars
)

// refuses reports whether the rule forbids c. It is for the three rules that read characters:
// contentChars refuses one byte, and checkString looks for that byte without decoding the text.
func (rule charRule) refuses(c rune) bool {
	switch {
	case c < 0x20, c >= 0x7F && c <= 0x9F, c == 0x2028, c == 0x2029:
		return true
	case rule == oneLineChars:
		return false
	case rule == displayChars && (c == 0x200C || c == 0x200D):
		return false
	}
	return invisible(c)
}

// invisible is the soft hyphen, the Arabic letter mark, U+200B to U+200F (the zero-width space,
// non-joiner and joiner, and the left-to-right and right-to-left marks), U+202A to U+202E (the
// embeddings and overrides), U+2060 to U+206F (the word joiner, the invisible operators, the
// isolates and the deprecated format characters) and the byte order mark.
func invisible(c rune) bool {
	return c == 0x00AD || c == 0x061C || c >= 0x200B && c <= 0x200F || c >= 0x202A && c <= 0x202E ||
		c >= 0x2060 && c <= 0x206F || c == 0xFEFF
}

func checkString(field, s string, minChars, maxChars int, rule charRule) error {
	if len(s) < minChars {
		return invalid(field, "is empty")
	}
	// A string has at most as many characters as bytes, so the count is only taken when the
	// byte length leaves the question open.
	if len(s) > maxChars && utf8.RuneCountInString(s) > maxChars {
		return invalid(field, fmt.Sprintf("is longer than %d characters", maxChars))
	}
	if rule == contentChars {
		// A text may be a megabyte, and in UTF-8 a zero byte is always NUL.
		if strings.IndexByte(s, 0) >= 0 {
			return invalid(field, "contains a NUL")
		}
	} else {
		for _, c := range s {
			if rule.refuses(c) {
				return invalid(field, "contains a character this field does not allow")
			}
		}
	}
	if !utf8.ValidString(s) {
		return invalid(field, "is not valid UTF-8")
	}
	return nil
}

// checkExternalID is for ExternalID and for Edges.ReplyParent, which is one: an identifier of 1
// to MaxExternalID characters that begins with a provider key and a colon, with something after
// the colon. Seal checks that the key is the sealing provider's.
func checkExternalID(field, s string) error {
	if err := checkString(field, s, 1, MaxExternalID, identifierChars); err != nil {
		return err
	}
	colon := strings.IndexByte(s, ':')
	if colon < 0 || colon == len(s)-1 || !ValidProviderKey(s[:colon]) {
		return invalid(field, "does not begin with a provider key and a colon")
	}
	return nil
}

func checkTime(t time.Time) error {
	if t.Location() != time.UTC {
		return invalid("occurred_at", "is not in UTC")
	}
	if y := t.Year(); y < minYear || y > maxYear {
		return invalid("occurred_at", "is not set, or its year is outside 1000 to 9999")
	}
	return nil
}

func validRecordID(s string) bool {
	if len(s) != recordIDLen || s[:len(ids.RecordPrefix)] != ids.RecordPrefix {
		return false
	}
	for i := len(ids.RecordPrefix); i < len(s); i++ {
		c := s[i]
		if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
			return false
		}
	}
	return true
}

// validName reports whether s is a lowercase letter followed by a-z, 0-9 and underscore (and the
// hyphen, where a wire name may have one), maxLen bytes at most.
func validName(s string, maxLen int, hyphen bool) bool {
	if s == "" || len(s) > maxLen || s[0] < 'a' || s[0] > 'z' {
		return false
	}
	for i := 1; i < len(s); i++ {
		c := s[i]
		ok := c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '_' || hyphen && c == '-'
		if !ok {
			return false
		}
	}
	return true
}

// ValidProviderKey reports whether s is an internal provider key: a lowercase letter followed by
// up to 31 of a-z, 0-9 and underscore, so at most 32 bytes, and never a hyphen
// ([ADR 3](../../docs/adr/0003-scope-id-format.md)).
//
// This function owns that rule for the whole program. The provider key is the first segment of
// every scope id and of every external id, so a key this refuses produces records that all fail
// in Seal, and a second copy of the pattern anywhere else is a way for the two to drift apart:
// the provider registry calls this, and a test holds the two to the same verdict on every
// candidate. ADR 3 freezes the grammar at v0.1.0 in both directions, hyphen included.
func ValidProviderKey(s string) bool { return validName(s, maxKind, false) }

package store

import (
	"context"
	"crypto/tls"
	"crypto/x509"
	"errors"
	"fmt"
	"net"
	"strings"
	"syscall"

	"github.com/jackc/pgx/v5/pgconn"
)

// connErrPrefix names the variable the operator has to look at, never its value.
const connErrPrefix = "LAWANG_DATABASE_URL: cannot use the database"

// connError turns a failure to reach or to talk to the database into an error that is safe to
// log.
//
// pgx quotes the connection target in what it returns ("failed to connect to `user=app
// database=prod`: ... lookup db.internal: no such host", "10.0.0.5:5432 (db.internal): failed SASL
// auth"), and the server does the same in its own messages (`password authentication failed for
// user "app"`, `database "prod" does not exist`, `no pg_hba.conf entry for host ...`). Every one
// of those is a part of LAWANG_DATABASE_URL. So the original error is never returned, wrapped
// or formatted: only a classification that cannot carry a value is kept, which is still enough to
// tell "does not resolve" from "refused" from "wrong password" from "no such database".
//
// The order matters. The server's verdict comes first, because with sslmode=prefer pgx joins the
// error of the TLS attempt to the error of the plain one, and the SQLSTATE is the one that says
// what is wrong.
func connError(ctx context.Context, err error) error {
	var pgErr *pgconn.PgError
	if errors.As(err, &pgErr) {
		return errors.New(connErrPrefix + ": " + describeSQLState(pgErr.Code))
	}
	// Cancelled or out of time, for example a signal during a slow connect. Wrapped, so that
	// errors.Is(err, context.Canceled) keeps working; the text of a context error is constant.
	if ctxErr := ctx.Err(); ctxErr != nil {
		return fmt.Errorf("%s: %w", connErrPrefix, ctxErr)
	}
	var dnsErr *net.DNSError
	if errors.As(err, &dnsErr) {
		// DNSError.Error() quotes the name, so only its classification is used.
		switch {
		case dnsErr.IsNotFound:
			return errors.New(connErrPrefix + ": the host name does not resolve")
		case dnsErr.IsTimeout:
			return errors.New(connErrPrefix + ": the host name lookup timed out")
		default:
			return errors.New(connErrPrefix + ": the host name lookup failed")
		}
	}
	var netErr net.Error
	if pgconn.Timeout(err) || errors.Is(err, context.DeadlineExceeded) || (errors.As(err, &netErr) && netErr.Timeout()) {
		return errors.New(connErrPrefix + ": the connection attempt timed out (the host drops packets, or connect_timeout is too short)")
	}
	// An errno's text comes from the operating system's table ("connection refused", "network is
	// unreachable"), never from the input. Wrapping it alone keeps errors.Is(err,
	// syscall.ECONNREFUSED) working.
	var errno syscall.Errno
	if errors.As(err, &errno) {
		return fmt.Errorf("%s: %w", connErrPrefix, errno)
	}
	if isTLSFailure(err) {
		return errors.New(connErrPrefix + ": TLS negotiation failed (check sslmode and the certificates)")
	}
	return errors.New(connErrPrefix + ": the connection failed")
}

// scrub is connError for the paths where most errors are not about the connection at all: a
// transaction body, a migration. An error is replaced only when it carries the connection target
// (pgx's connect error, or a net error with its addresses); anything else, a constraint violation
// for example, reaches the caller untouched, SQLSTATE and all.
//
// It judges the error and not its origin, so a net error that a transaction function produced by
// itself is replaced as well, wrapping and sentinels included. That is deliberate: see begin.
func scrub(ctx context.Context, err error) error {
	if err == nil {
		return nil
	}
	var (
		connectErr *pgconn.ConnectError
		opErr      *net.OpError
		dnsErr     *net.DNSError
	)
	if errors.As(err, &connectErr) || errors.As(err, &opErr) || errors.As(err, &dnsErr) {
		return connError(ctx, err)
	}
	return err
}

// describeSQLState words a server refusal from its SQLSTATE alone. The message, detail and hint of
// the server are never used: at connection time they quote the role, the database and the client
// address.
func describeSQLState(code string) string {
	// The code is five characters from the server. It is checked anyway, so that nothing but a
	// code can ever be printed here, whatever is on the other end of the connection.
	if !validSQLState(code) {
		return "the server refused, with no usable SQLSTATE"
	}
	switch {
	case strings.HasPrefix(code, "28"):
		return "authentication failed, check the user, the password and pg_hba.conf (SQLSTATE " + code + ")"
	case code == "3D000":
		return "the database does not exist (SQLSTATE 3D000)"
	case code == "42501":
		return "the role may not connect to the database (SQLSTATE 42501)"
	case code == "53300":
		return "the server has no connection slot left (SQLSTATE 53300)"
	case code == "57P03":
		return "the server is not accepting connections yet (SQLSTATE 57P03)"
	default:
		return "the server refused (SQLSTATE " + code + ")"
	}
}

func validSQLState(code string) bool {
	if len(code) != 5 {
		return false
	}
	for i := range len(code) {
		c := code[i]
		if (c < '0' || c > '9') && (c < 'A' || c > 'Z') {
			return false
		}
	}
	return true
}

// isTLSFailure recognizes a failed TLS setup. The typed errors of crypto/tls and crypto/x509 come
// first. pgx reports a server that declines TLS, and a handshake it could not finish, only as
// text, so that text is read as well: read, to classify, and never repeated.
func isTLSFailure(err error) bool {
	var (
		certErr      *tls.CertificateVerificationError
		recordErr    tls.RecordHeaderError
		alertErr     tls.AlertError
		authorityErr x509.UnknownAuthorityError
		hostErr      x509.HostnameError
		invalidErr   x509.CertificateInvalidError
	)
	if errors.As(err, &certErr) || errors.As(err, &recordErr) || errors.As(err, &alertErr) ||
		errors.As(err, &authorityErr) || errors.As(err, &hostErr) || errors.As(err, &invalidErr) {
		return true
	}
	text := err.Error()
	return strings.Contains(text, "tls error") || strings.Contains(text, "server refused TLS connection")
}

package store

import (
	"context"
	"crypto/x509"
	"errors"
	"fmt"
	"net"
	"os"
	"strings"
	"syscall"
	"testing"
	"time"

	"github.com/jackc/pgx/v5/pgconn"
)

// marker stands in for a part of the database URL, carried the way the real errors carry it.
const marker = "leakvalue"

// markerAddr stands in for the address a net.OpError carries and prints.
type markerAddr string

func (markerAddr) Network() string  { return "tcp" }
func (a markerAddr) String() string { return string(a) }

// timeoutErr is a net.Error that reports a timeout and quotes the marker.
type timeoutErr struct{}

func (timeoutErr) Error() string   { return "dial tcp " + marker + ": i/o timeout" }
func (timeoutErr) Timeout() bool   { return true }
func (timeoutErr) Temporary() bool { return false }

func TestConnErrorKeepsOnlyTheClassification(t *testing.T) {
	bg := context.Background()
	cancelled, cancel := context.WithCancel(bg)
	cancel()

	dial := func(inner error) error {
		return fmt.Errorf("failed to connect to `user=%s database=%s`: %w", marker, marker,
			&net.OpError{Op: "dial", Net: "tcp", Addr: markerAddr(marker), Err: inner})
	}
	server := func(code, msg string) error {
		return fmt.Errorf("failed to connect to `user=%s`: server error: %w", marker,
			&pgconn.PgError{Severity: "FATAL", Code: code, Message: msg, Detail: marker, Hint: marker})
	}

	cases := []struct {
		name string
		ctx  context.Context
		err  error
		want string
	}{
		{"wrong password", bg, server("28P01", `password authentication failed for user "`+marker+`"`), "authentication failed, check the user, the password and pg_hba.conf (SQLSTATE 28P01)"},
		{"no pg_hba entry", bg, server("28000", `no pg_hba.conf entry for host "`+marker+`"`), "authentication failed, check the user, the password and pg_hba.conf (SQLSTATE 28000)"},
		{"missing database", bg, server("3D000", `database "`+marker+`" does not exist`), "the database does not exist (SQLSTATE 3D000)"},
		{"no CONNECT privilege", bg, server("42501", `permission denied for database "`+marker+`"`), "may not connect to the database (SQLSTATE 42501)"},
		{"too many connections", bg, server("53300", `too many connections for role "`+marker+`"`), "no connection slot left (SQLSTATE 53300)"},
		{"starting up", bg, server("57P03", "the database system is starting up "+marker), "not accepting connections yet (SQLSTATE 57P03)"},
		{"any other SQLSTATE", bg, server("XX000", marker), "the server refused (SQLSTATE XX000)"},
		{"a SQLSTATE that is not one", bg, server(marker, marker), "no usable SQLSTATE"},
		{"a SQLSTATE of the right length that is not one", bg, server("leak!", marker), "no usable SQLSTATE"},
		// The server's verdict wins over the network error pgx joins to it under sslmode=prefer.
		{"server verdict joined to a TLS refusal", bg, errors.Join(errors.New("server refused TLS connection"), server("28P01", marker)), "SQLSTATE 28P01"},
		{"refused", bg, dial(os.NewSyscallError("connect", syscall.ECONNREFUSED)), "connection refused"},
		{"unreachable", bg, dial(os.NewSyscallError("connect", syscall.ENETUNREACH)), "network is unreachable"},
		{"no such host", bg, dial(&net.DNSError{Err: "no such host", Name: marker, IsNotFound: true}), "the host name does not resolve"},
		{"lookup timeout", bg, dial(&net.DNSError{Err: "i/o timeout", Name: marker, IsTimeout: true}), "the host name lookup timed out"},
		{"lookup failure", bg, dial(&net.DNSError{Err: "server misbehaving", Name: marker, Server: marker}), "the host name lookup failed"},
		{"connect timeout", bg, dial(timeoutErr{}), "timed out"},
		{"deadline of pgx's connect_timeout", bg, fmt.Errorf("%s: dial error: %w", marker, context.DeadlineExceeded), "timed out"},
		{"cancelled", cancelled, dial(errors.New("operation was canceled " + marker)), "context canceled"},
		{"certificate not trusted", bg, fmt.Errorf("%s: %w", marker, x509.UnknownAuthorityError{}), "TLS negotiation failed"},
		{"certificate for another host", bg, fmt.Errorf("%s: %w", marker, x509.HostnameError{Certificate: &x509.Certificate{}, Host: marker}), "TLS negotiation failed"},
		{"server declines TLS", bg, fmt.Errorf("%s: %w", marker, errors.New("server refused TLS connection")), "TLS negotiation failed"},
		{"handshake failure as pgx words it", bg, fmt.Errorf("%s: tls error: %w", marker, errors.New("EOF")), "TLS negotiation failed"},
		{"anything else", bg, errors.New("unexpected " + marker), "the connection failed"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if !strings.Contains(tc.err.Error(), marker) {
				t.Fatalf("the input does not carry the marker, so the case proves nothing: %v", tc.err)
			}
			got := connError(tc.ctx, tc.err).Error()
			if !strings.HasPrefix(got, "LAWANG_DATABASE_URL: ") || !strings.Contains(got, tc.want) {
				t.Errorf("got %q, want it to name the variable and say %q", got, tc.want)
			}
			if strings.Contains(got, marker) {
				t.Errorf("error leaks %q: %s", marker, got)
			}
		})
	}
}

func TestConnErrorKeepsWhatCallersMatchOn(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	if err := connError(ctx, errors.New(marker)); !errors.Is(err, context.Canceled) {
		t.Errorf("err = %v, want context.Canceled to survive", err)
	}
	refused := &net.OpError{Op: "dial", Net: "tcp", Addr: markerAddr(marker), Err: os.NewSyscallError("connect", syscall.ECONNREFUSED)}
	if err := connError(context.Background(), refused); !errors.Is(err, syscall.ECONNREFUSED) {
		t.Errorf("err = %v, want ECONNREFUSED to survive", err)
	}
}

func TestScrubReplacesOnlyWhatCarriesTheConnectionTarget(t *testing.T) {
	ctx := context.Background()
	if err := scrub(ctx, nil); err != nil {
		t.Errorf("scrub(nil) = %v", err)
	}

	// What a transaction body returns has to reach the caller as it is: callers match on the
	// SQLSTATE, and tests on the message.
	violation := fmt.Errorf("insert: %w", &pgconn.PgError{Code: "23505", Message: "duplicate key"})
	got := scrub(ctx, violation)
	var pgErr *pgconn.PgError
	if !errors.Is(got, violation) || got.Error() != violation.Error() || !errors.As(got, &pgErr) || pgErr.Code != "23505" {
		t.Errorf("scrub changed a constraint violation into %v", got)
	}
	own := errors.New("store: something of our own")
	if got := scrub(ctx, own); !errors.Is(got, own) || got.Error() != own.Error() {
		t.Errorf("scrub changed a plain error into %v", got)
	}

	// What carries an address does not. A real connect error from pgx, against a port nothing
	// listens on: its cause cannot be set from outside the package.
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	addr := ln.Addr().String()
	_ = ln.Close()
	dialCtx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	_, connectErr := pgconn.Connect(dialCtx, "postgres://"+marker+"@"+addr+"/"+marker+"?sslmode=disable")
	var asConnect *pgconn.ConnectError
	if !errors.As(connectErr, &asConnect) || !strings.Contains(connectErr.Error(), marker) {
		t.Fatalf("pgconn.Connect to a closed port returned %v, want a ConnectError that carries the marker", connectErr)
	}

	for name, err := range map[string]error{
		"pgx connect error": fmt.Errorf("begin: %w", connectErr),
		"net error mid-transaction": fmt.Errorf("commit: %w",
			&net.OpError{Op: "write", Net: "tcp", Addr: markerAddr(marker), Err: os.NewSyscallError("write", syscall.EPIPE)}),
		"lookup": &net.DNSError{Err: "no such host", Name: marker, IsNotFound: true},
	} {
		got := scrub(ctx, err)
		if got == nil || strings.Contains(got.Error(), marker) || !strings.HasPrefix(got.Error(), "LAWANG_DATABASE_URL: ") {
			t.Errorf("%s: scrub returned %v, want a classified error without %q", name, got, marker)
		}
	}
}

func TestPoolConfigSetsAConnectTimeout(t *testing.T) {
	cfg, err := poolConfig("postgres://app@db.example:5432/lawang")
	if err != nil {
		t.Fatal(err)
	}
	if got := cfg.ConnConfig.ConnectTimeout; got != 10*time.Second {
		t.Errorf("with no connect_timeout in the URL, ConnectTimeout = %s, want 10s", got)
	}
	if got := cfg.ConnConfig.RuntimeParams["search_path"]; got != Schema {
		t.Errorf("search_path = %q, want %q", got, Schema)
	}

	cfg, err = poolConfig("postgres://app@db.example:5432/lawang?connect_timeout=3")
	if err != nil {
		t.Fatal(err)
	}
	if got := cfg.ConnConfig.ConnectTimeout; got != 3*time.Second {
		t.Errorf("with connect_timeout=3 in the URL, ConnectTimeout = %s, want the operator's 3s", got)
	}

	// Deliberate: 0 is "wait forever" in libpq, and here it is the default. pgx parses it to the
	// same zero as a missing parameter, and an unbounded start is what the default exists to
	// prevent. If pgx ever starts telling the two apart, this row is where that gets noticed.
	cfg, err = poolConfig("postgres://app@db.example:5432/lawang?connect_timeout=0")
	if err != nil {
		t.Fatal(err)
	}
	if got := cfg.ConnConfig.ConnectTimeout; got != 10*time.Second {
		t.Errorf("with connect_timeout=0 in the URL, ConnectTimeout = %s, want the 10s default: 0 must not lift the bound", got)
	}
}

func TestCheckVersion(t *testing.T) {
	for _, tc := range []struct {
		version int
		ok      bool
	}{
		{90624, false},
		{150019, false},
		{159999, false},
		{160000, true},
		{160015, true},
