		}
	}
}

package store_test

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net"
	"net/url"
	"os"
	"strings"
	"sync"
	"syscall"
	"testing"
	"time"

	"github.com/jackc/pgx/v5"

	"github.com/gablooge/lawang/internal/store"
	"github.com/gablooge/lawang/internal/testdb"
)

// forwarder is a TCP listener on the loopback that relays every connection to target. It stands
// between a pool and the test database so that a test can take the database away after Open has
// succeeded, which is what a restart or a failover looks like from inside the process.
type forwarder struct {
	ln     net.Listener
	target string

	mu    sync.Mutex
	conns []net.Conn
	gone  bool

	wg      sync.WaitGroup
	cutOnce sync.Once
}

func newForwarder(t *testing.T, target string) *forwarder {
	t.Helper()
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	f := &forwarder{ln: ln, target: target}
	f.wg.Add(1)
	go f.accept()
	t.Cleanup(func() { f.cut(t) })
	return f
}

func (f *forwarder) addr() string { return f.ln.Addr().String() }

// track remembers a connection so that cut can close it, and refuses it once cut has run.
func (f *forwarder) track(c net.Conn) bool {
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.gone {
		_ = c.Close()
		return false
	}
	f.conns = append(f.conns, c)
	return true
}

func (f *forwarder) accept() {
	defer f.wg.Done()
	for {
		client, err := f.ln.Accept()
		if err != nil {
			return // the listener was closed
		}
		if !f.track(client) {
			continue
		}
		server, err := net.DialTimeout("tcp", f.target, 10*time.Second)
		if err != nil {
			_ = client.Close()
			continue
		}
		if !f.track(server) {
			_ = client.Close()
			continue
		}
		f.wg.Add(2)
		go f.relay(server, client)
		go f.relay(client, server)
	}
}

func (f *forwarder) relay(dst, src net.Conn) {
	defer f.wg.Done()
	_, _ = io.Copy(dst, src)
	// One direction ending ends the pair, which is what unblocks the other relay.
	_ = dst.Close()
	_ = src.Close()
}

// cut stops listening and closes every relayed connection, both halves, then waits (bounded) for
// the relays to end. From then on a connect to addr is refused, and a connection the pool still
// holds is dead. It is safe to call twice.
func (f *forwarder) cut(t *testing.T) {
	t.Helper()
	f.cutOnce.Do(func() {
		_ = f.ln.Close()
		f.mu.Lock()
		f.gone = true
		for _, c := range f.conns {
			_ = c.Close()
		}
		f.mu.Unlock()

		done := make(chan struct{})
		go func() {
			f.wg.Wait()
			close(done)
		}()
		select {
		case <-done:
		case <-time.After(10 * time.Second):
			t.Error("the forwarder's relays were still running 10s after the cut")
		}
	})
}

// errorTexts walks err to every depth, through Unwrap() error and Unwrap() []error, and returns
// each node printed the two ways a log line prints an error. A marker that survives only on an
// inner error is still one errors.Unwrap away from a log. %#v is left out on purpose: it prints
// pointer values, and a port number can turn up inside one by chance.
func errorTexts(err error) []string {
	var texts []string
	var walk func(error, int)
	walk = func(e error, depth int) {
		if e == nil || depth > 32 {
			return
		}
		texts = append(texts, fmt.Sprintf("%v", e), fmt.Sprintf("%+v", e))
		switch u := e.(type) { //nolint:errorlint // the walk needs the node itself, not a match somewhere below it
		case interface{ Unwrap() error }:
			walk(u.Unwrap(), depth+1)
		case interface{ Unwrap() []error }:
			for _, inner := range u.Unwrap() {
				walk(inner, depth+1)
			}
		}
	}
	walk(err, 0)
	return texts
}

func assertNoLeakAtAnyDepth(t *testing.T, name string, err error, markers ...string) {
	t.Helper()
	var leaked []string
	for _, m := range markers {
		if m == "" {
			continue
		}
		for _, text := range errorTexts(err) {
			if strings.Contains(text, m) {
				leaked = append(leaked, m)
				break
			}
		}
	}
	if len(leaked) > 0 {
		// One line per error, not one per marker and depth: a leak trips nearly all of them.
		t.Errorf("%s: the error, or one it wraps, leaks %q: %v", name, leaked, err)
	}
}

// TestALostDatabaseNeverEchoesTheURL pins that every entry point that can be the first to meet a
// database that has gone away (Tx, TenantTx, RoleTx and Migrate) replaces the driver's error.
//
// The leak tests of Open cannot see this. Open fails in its preflight, before begin or Migrate is
// ever reached, and the pool connects lazily: after a restart of the database it is the next
// transaction, not Open, that gets pgx's "failed to connect to `user=... database=...`: dial tcp
// host:port". A begin rewritten without its scrub, or a new entry point that forgets it, would
// put that line into the worker's log with every other test green.
func TestALostDatabaseNeverEchoesTheURL(t *testing.T) {
	tdb := testdb.New(t)
	target, err := url.Parse(tdb.URL)
	if err != nil {
		t.Fatal("the test database URL does not parse")
	}
	fwd := newForwarder(t, target.Host)
	fwdHost, fwdPort, err := net.SplitHostPort(fwd.addr())
	if err != nil {
		t.Fatal(err)
	}

	through := *target
	through.Host = fwd.addr()
	query := through.Query()
	// One connection, so that one failed call is enough to empty the pool after the cut. A short
	// connect timeout, so that a connect that hangs where it should be refused fails the test.
	query.Set("pool_max_conns", "1")
	query.Set("connect_timeout", "5")
	through.RawQuery = query.Encode()

	openCtx, cancelOpen := context.WithTimeout(context.Background(), time.Minute)
	defer cancelOpen()
	db, err := store.Open(openCtx, through.String())
	if err != nil {
		t.Fatalf("Open through the forwarder: %v", err)
	}
	t.Cleanup(func() { closeWithin(t, db, 10*time.Second) })

	// Everything the pool was told, and everything it could learn: pgx quotes the user and the
	// database, the dialer quotes the address. The variable name is upper case, so the role name
	// in lower case is a marker too, as are the labels pgx puts in front of the values.
	password, _ := target.User.Password()
	markers := []string{
		target.User.Username(), password, strings.TrimPrefix(target.Path, "/"),
		fwd.addr(), fwdHost, fwdPort, target.Host, target.Port(),
		"user=", "database=", "dial tcp",
	}

	fwd.cut(t)

	mustNotRun := func(name string) func(pgx.Tx) error {
		return func(pgx.Tx) error {
			t.Errorf("%s ran its function with no database behind the pool", name)
			return nil
		}
	}
	call := func(run func(context.Context) error) error {
		ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
		defer cancel()
		err := run(ctx)
		if ctx.Err() != nil {
			t.Fatalf("the call was still going at its 20s deadline: %v", err)
		}
		return err
	}

	// The pool still holds the connection Open used, and that connection is dead. Whatever the
	// call that finds it returns (a reset, an EOF, a broken pipe, each of them in the middle of a
	// transaction) must not leak either. That call also removes the connection from the pool, so
	// the calls after it have to connect, and are refused. Bounded, and no sleep: a pool of one
	// connection needs one call.
	drained := false
	for attempt := 1; attempt <= 5 && !drained; attempt++ {
		err := call(func(ctx context.Context) error { return db.Tx(ctx, mustNotRun("Tx")) })
		if err == nil {
			t.Fatal("Tx succeeded with no database behind the pool")
		}
		assertNoLeakAtAnyDepth(t, fmt.Sprintf("Tx on the dead connection (attempt %d)", attempt), err, markers...)
		drained = errors.Is(err, syscall.ECONNREFUSED)
	}
	if !drained {
		t.Fatal("after 5 calls the pool was still not trying to connect, so the refused connect was never exercised")
	}

	for _, entry := range []struct {
		name string
		run  func(context.Context) error
	}{
		{"Tx", func(ctx context.Context) error { return db.Tx(ctx, mustNotRun("Tx")) }},
		{"TenantTx", func(ctx context.Context) error { return db.TenantTx(ctx, tenantA, mustNotRun("TenantTx")) }},
		{"RoleTx", func(ctx context.Context) error { return db.RoleTx(ctx, store.RoleWorker, mustNotRun("RoleTx")) }},
		{"Migrate", func(ctx context.Context) error {
			_, err := db.Migrate(ctx, quiet)
			return err
		}},
	} {
		err := call(entry.run)
		if err == nil {
			t.Errorf("%s succeeded with no database behind the pool", entry.name)
			continue
		}
		assertNoLeakAtAnyDepth(t, entry.name, err, markers...)
		if !strings.Contains(err.Error(), "LAWANG_DATABASE_URL") || !strings.Contains(err.Error(), "refused") {
			t.Errorf("%s: the error does not name the variable and the cause: %v", entry.name, err)
		}
		// What a caller may match on has to survive: a retry loop tells "refused" from the rest.
		if !errors.Is(err, syscall.ECONNREFUSED) {
			t.Errorf("%s: err = %v, want ECONNREFUSED to survive the replacement", entry.name, err)
		}
	}
}

// TestANetErrorFromTheTransactionFunctionIsReplacedToo documents a decision, it does not defend a
// nicety. The replacement judges the error and not where it came from (see begin), so a network
// error of the function's own comes back as a database connection error and loses what was wrapped
// around it. Network I/O inside a transaction is forbidden anyway. Whoever changes this has to
// keep the other half true: a statement that fails inside the function on a dead connection is
// returned BY the function, carries the address, and must still be replaced.
func TestANetErrorFromTheTransactionFunctionIsReplacedToo(t *testing.T) {
	db := open(t, "")
	ctx := testCtx(t)

	const farEnd = "provider.leakhost.example:443"
	sentinel := errors.New("a sentinel of the caller")
	ownNetErr := fmt.Errorf("%w: %w", sentinel, &net.OpError{
		Op: "read", Net: "tcp", Addr: addrOf(farEnd), Err: os.NewSyscallError("read", syscall.ECONNRESET),
	})

	for name, run := range map[string]func(func(pgx.Tx) error) error{
		"Tx":       func(fn func(pgx.Tx) error) error { return db.Tx(ctx, fn) },
		"TenantTx": func(fn func(pgx.Tx) error) error { return db.TenantTx(ctx, tenantA, fn) },
		"RoleTx":   func(fn func(pgx.Tx) error) error { return db.RoleTx(ctx, store.RoleWorker, fn) },
	} {
		err := run(func(pgx.Tx) error { return ownNetErr })
		if err == nil || !strings.HasPrefix(err.Error(), "LAWANG_DATABASE_URL: ") {
			t.Errorf("%s: err = %v, want the net error replaced", name, err)
			continue
		}
		if errors.Is(err, sentinel) {
			t.Errorf("%s: the caller's sentinel survived. If that is now intended, update the doc comment of begin and docs/architecture.md section 4", name)
		}
		if !errors.Is(err, syscall.ECONNRESET) {
			t.Errorf("%s: err = %v, want the errno to survive", name, err)
		}
		assertNoLeakAtAnyDepth(t, name, err, farEnd, "leakhost")

		// The contrast: an error that is not a net error is the caller's, sentinel and text.
		plain := fmt.Errorf("lookup failed: %w", sentinel)
		if err := run(func(pgx.Tx) error { return plain }); !errors.Is(err, sentinel) || err.Error() != plain.Error() {
			t.Errorf("%s: a plain error came back as %v, want it untouched", name, err)
		}
	}
}

// addrOf is a net.Addr with a chosen text.
type addrOf string

func (addrOf) Network() string  { return "tcp" }
func (a addrOf) String() string { return string(a) }

package store

import (
	"context"
	"fmt"
	"log/slog"

	"github.com/jackc/pgx/v5/stdlib"
	"github.com/pressly/goose/v3"
	"github.com/pressly/goose/v3/lock"

	"github.com/gablooge/lawang/migrations"
)

// How a Migrate that finds the advisory lock taken waits for it: one attempt per second, 300
// times, so the ceiling stays at the five minutes of the goose default.
const (
	lockRetrySeconds = 1
	lockRetries      = 300
)

// provider builds the goose provider over the pool, and so over its search path. The returned
// function closes the database/sql handle the provider borrowed the pool through, which leaves the
// pool itself open.
func (db *DB) provider(logger *slog.Logger) (*goose.Provider, func(), error) {
	locker, err := lock.NewPostgresSessionLocker(lock.WithLockTimeout(lockRetrySeconds, lockRetries))
	if err != nil {
		return nil, nil, err
	}
	sqlDB := stdlib.OpenDBFromPool(db.pool)
	provider, err := goose.NewProvider(goose.DialectPostgres, sqlDB, migrations.FS,
		goose.WithSessionLocker(locker),
		goose.WithSlog(logger),
	)
	if err != nil {
		_ = sqlDB.Close()
		return nil, nil, err
	}
	return provider, func() { _ = sqlDB.Close() }, nil
}

// Migrate applies every pending migration and returns how many it applied. It runs as the same
// non-superuser role as everything else (Open has already refused anything stronger), so the
// tables end up owned by the role that will use them.
//
// A session-level advisory lock serializes concurrent callers, so several replicas may run
// "lawang migrate" at once. A caller that finds the lock taken asks again every second for up to
// five minutes. The goose default asks every five seconds, so the k-th of N replicas started
// together slept about 5(k-1) seconds, usually for a lock that was released within milliseconds
// because there was nothing left to apply. One second is the shortest period goose accepts.
func (db *DB) Migrate(ctx context.Context, logger *slog.Logger) (int, error) {
	provider, closeProvider, err := db.provider(logger)
	if err != nil {
		// goose does not connect while it builds a provider (it first touches the database in Up),
		// so nothing can reach this scrub today and no test can fail without it. It stays so that a
		// goose release that does connect here cannot put the connection target into the log.
		return 0, fmt.Errorf("store: migrate: %w", scrub(ctx, err))
	}
	defer closeProvider()

	results, err := provider.Up(ctx)
	if err != nil {
		// A migration that fails keeps the server's message: that is what the operator needs. A
		// connection that fails does not, because it would repeat the database URL.
		return len(results), fmt.Errorf("store: migrate: %w", scrub(ctx, err))
	}
	return len(results), nil
}

package store

import (
	"context"
	"io"
	"log/slog"
	"testing"
	"time"

	"github.com/jackc/pgx/v5"

	"github.com/gablooge/lawang/internal/testdb"
)

// TestMigrationsGoDownToZeroAndUpAgain runs every Down section, as the application role, on a
// database of its own. No command exposes Down, so nothing else ever executes those statements,
// and a Down that nobody runs rots as migrations are added: it drops things in the wrong order,
// or forgets one. Going back up proves Down left nothing behind that Up trips over.
func TestMigrationsGoDownToZeroAndUpAgain(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), time.Minute)
	defer cancel()
	quiet := slog.New(slog.NewTextHandler(io.Discard, nil))

	tdb := testdb.New(t)
	db, err := Open(ctx, tdb.URL)
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	defer db.Close()

	applied, err := db.Migrate(ctx, quiet)
	if err != nil || applied == 0 {
		t.Fatalf("Migrate: applied %d, err = %v", applied, err)
	}

	provider, closeProvider, err := db.provider(quiet)
	if err != nil {
		t.Fatal(err)
	}
	defer closeProvider()
	down, err := provider.DownTo(ctx, 0)
	if err != nil {
		t.Fatalf("down to zero: %v", err)
	}
	if len(down) != applied {
		t.Errorf("rolled back %d migrations, want the %d that were applied", len(down), applied)
	}

	// Everything the migrations made is gone: what is left in the schema is goose's own table.
	err = db.Tx(ctx, func(tx pgx.Tx) error {
		rows, err := tx.Query(ctx, `
			SELECT 'relation ' || c.relname FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
			 WHERE n.nspname = $1 AND c.relkind IN ('r', 'p', 'v', 'm', 'f', 'S') AND c.relname NOT LIKE 'goose_db_version%'
			UNION ALL
			SELECT 'function ' || p.proname FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
			 WHERE n.nspname = $1
			UNION ALL
			SELECT 'type ' || t.typname FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace
			 WHERE n.nspname = $1 AND t.typtype = 'd'`, Schema)
		if err != nil {
			return err
		}
		left, err := pgx.CollectRows(rows, pgx.RowTo[string])
		if err != nil {
			return err
		}
		if len(left) != 0 {
			t.Errorf("after down to zero the schema still holds %v", left)
		}
		var helperCanUseSchema bool
		if err := tx.QueryRow(ctx, "SELECT has_schema_privilege('lawang_worker', $1, 'USAGE')", Schema).Scan(&helperCanUseSchema); err != nil {
			return err
		}
		if helperCanUseSchema {
			t.Error("after down to zero lawang_worker still has USAGE on the schema")
		}
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}

	again, err := db.Migrate(ctx, quiet)
	if err != nil {
		t.Fatalf("Migrate after down to zero: %v", err)
	}
	if again != applied {
		t.Errorf("Migrate after down to zero applied %d, want %d", again, applied)
	}
}

package store_test

import (
	"context"
	"errors"
	"net"
	"net/url"
	"strings"
	"syscall"
	"testing"
	"time"

	"github.com/gablooge/lawang/internal/store"
	"github.com/gablooge/lawang/internal/testdb"
)

// Markers that stand in for the parts of LAWANG_DATABASE_URL. None may reach an error, because
// the binary logs what Open returns.
const (
	leakUser = "leakuser"
	leakPass = "hunter2"
	leakHost = "leakhost"
	leakDB   = "leakdb"
)

// failOpen runs Open, which must fail, under a deadline of its own: a connect that hangs fails the
// test instead of stalling the package.
func failOpen(t *testing.T, databaseURL string, deadline time.Duration) error {
	t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), deadline)
	defer cancel()
	db, err := store.Open(ctx, databaseURL)
	if db != nil {
		db.Close()
	}
	if err == nil {
		t.Fatal("Open succeeded, want a refusal")
	}
	if ctx.Err() != nil {
		t.Fatalf("Open was still going at the %s deadline: %v", deadline, err)
	}
	return err
}

func assertNoLeak(t *testing.T, err error, markers ...string) {
	t.Helper()
	for _, m := range markers {
		if m != "" && strings.Contains(err.Error(), m) {
			t.Errorf("error leaks %q: %v", m, err)
		}
	}
}

func TestOpenNeverEchoesTheURL(t *testing.T) {
	// pgx masks the password in its parse error and nothing else, so the user, the host and the
	// database are what tell a wrapped parse error from a replaced one.
	err := failOpen(t, "postgres://"+leakUser+":"+leakPass+"@"+leakHost+":5432/"+leakDB+"?pool_max_conns=banana", 5*time.Second)
	assertNoLeak(t, err, leakUser, leakPass, leakHost, leakDB, "banana")
	if !strings.Contains(err.Error(), "LAWANG_DATABASE_URL") {
		t.Errorf("error does not name the variable: %v", err)
	}
}

// TestOpenConnectFailuresNeverEchoTheURL drives the failures an operator really meets. pgx and the
// server both quote the connection target in every one of them; Open must keep the classification
// and drop the rest.
func TestOpenConnectFailuresNeverEchoTheURL(t *testing.T) {
	t.Run("host that does not resolve", func(t *testing.T) {
		// ".invalid" is reserved and never resolves (RFC 6761), with or without a network.
		err := failOpen(t, "postgres://"+leakUser+":"+leakPass+"@"+leakHost+".invalid:5432/"+leakDB+"?sslmode=disable&connect_timeout=5", 15*time.Second)
		assertNoLeak(t, err, leakUser, leakPass, leakHost, leakDB, "5432")
		if !strings.Contains(err.Error(), "LAWANG_DATABASE_URL") || !strings.Contains(err.Error(), "host name") {
			t.Errorf("error does not name the variable and the cause: %v", err)
		}
	})

	t.Run("closed local port", func(t *testing.T) {
		ln, err := net.Listen("tcp", "127.0.0.1:0")
		if err != nil {
			t.Fatal(err)
		}
		addr := ln.Addr().String()
		_, port, _ := net.SplitHostPort(addr)
		_ = ln.Close()

		err = failOpen(t, "postgres://"+leakUser+":"+leakPass+"@"+addr+"/"+leakDB+"?sslmode=disable&connect_timeout=5", 15*time.Second)
		assertNoLeak(t, err, leakUser, leakPass, leakDB, port, "127.0.0.1")
		if !errors.Is(err, syscall.ECONNREFUSED) {
			t.Errorf("err = %v, want ECONNREFUSED to survive the classification", err)
		}
		if !strings.Contains(err.Error(), "LAWANG_DATABASE_URL") || !strings.Contains(err.Error(), "refused") {
			t.Errorf("error does not name the variable and the cause: %v", err)
		}
	})

	tdb := testdb.New(t)
	target, err := url.Parse(tdb.URL)
	if err != nil {
		t.Fatal("the test database URL does not parse")
	}
	realDB := strings.TrimPrefix(target.Path, "/")

	t.Run("wrong password", func(t *testing.T) {
		u := *target
		// A role that does not exist is answered exactly like a wrong password, and lets the user
		// be a marker too.
		u.User = url.UserPassword(leakUser, leakPass)
		err := failOpen(t, u.String(), 15*time.Second)
		assertNoLeak(t, err, leakUser, leakPass, realDB, target.Port(), target.Hostname())
		if !strings.Contains(err.Error(), "LAWANG_DATABASE_URL") || !strings.Contains(err.Error(), "authentication failed") ||
			!strings.Contains(err.Error(), "28P01") {
			t.Errorf("error does not name the variable, the cause and the SQLSTATE: %v", err)
		}
	})

	t.Run("missing database", func(t *testing.T) {
		u := *target
		u.Path = "/" + leakDB
		err := failOpen(t, u.String(), 15*time.Second)
		assertNoLeak(t, err, leakDB, "lawang_test", target.Port(), target.Hostname())
		// The user here is "lawang", which is also the schema and the variable prefix, so it
		// cannot be searched for. The wrong password case covers the user.
		if !strings.Contains(err.Error(), "LAWANG_DATABASE_URL") || !strings.Contains(err.Error(), "database does not exist") ||
			!strings.Contains(err.Error(), "3D000") {
			t.Errorf("error does not name the variable, the cause and the SQLSTATE: %v", err)
		}
	})
}

// A refusal that is about the login role must not repeat its name either: the name is the user
// half of the URL.
func TestPreflightRefusalsNeverNameTheLogin(t *testing.T) {
	tdb := testdb.New(t)
	testdb.Exec(t, tdb.AdminURL, "CREATE ROLE "+leakUser+" LOGIN BYPASSRLS PASSWORD '"+leakPass+"'")
	t.Cleanup(func() { testdb.Exec(t, tdb.AdminURL, "DROP ROLE "+leakUser) })

	err := failOpen(t, testdb.As(t, tdb.URL, leakUser, leakPass), 15*time.Second)
	if !errors.Is(err, store.ErrUnsafeRole) {
		t.Fatalf("Open as a BYPASSRLS role: err = %v, want ErrUnsafeRole", err)
	}
	assertNoLeak(t, err, leakUser, leakPass)
}

// TestOpenGivesUpOnAHostThatDropsPackets pins that a connect timeout reaches the dialer and comes
// back classified. 192.0.2.0/24 is a documentation range that is routed nowhere (RFC 5737), so a
// SYN sent to it is normally never answered: without a timeout Open would sit there for the TCP
// timeout of the operating system, 75 seconds or more, with nothing logged. That Open applies a
// default when the URL sets none is pinned by TestPoolConfigSetsAConnectTimeout, which needs no
// network; this test uses a short one from the URL so that it takes a second and not ten.
func TestOpenGivesUpOnAHostThatDropsPackets(t *testing.T) {
	start := time.Now()
	err := failOpen(t, "postgres://"+leakUser+":"+leakPass+"@192.0.2.1:5432/"+leakDB+"?sslmode=disable&connect_timeout=1", 8*time.Second)
	elapsed := time.Since(start)

	assertNoLeak(t, err, leakUser, leakPass, leakDB, "192.0.2.1", "5432")
	if !strings.Contains(err.Error(), "timed out") {
		// Some environments answer for the documentation range at once (no route, an unreachable
		// reply from a gateway, a sandbox without a network). Then nothing was dropped and there
		// is no hang to bound. The point here is only that Open does not hang.
		t.Skipf("this environment answered for 192.0.2.1 after %s instead of dropping the packets, so the timeout was not exercised: %v", elapsed.Round(time.Millisecond), err)
	}
	if elapsed > 5*time.Second {
		t.Errorf("Open took %s with connect_timeout=1", elapsed.Round(time.Millisecond))
	}
}

package store_test

import (
	"errors"
	"fmt"
	"testing"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"

	"github.com/gablooge/lawang/internal/store"
	"github.com/gablooge/lawang/internal/testdb"
)

// The tests in this file change roles and memberships, which are cluster-wide. Each takes a
// Postgres of its own from testdb.NewRawCluster, so nothing it breaks, and nothing a failed
// cleanup leaves behind, can reach another test. Do not move them onto the shared container, and
// do not make them parallel: the cases inside one test share that test's cluster.

// TestOpenRefusesUnsafeHelperRoles breaks one thing at a time about the helper roles and expects
// the preflight to refuse the start. What it must catch is the effective state, however it came
// about: a plain transaction of the application role must never hold a helper role's privileges.
func TestOpenRefusesUnsafeHelperRoles(t *testing.T) {
	tdb := testdb.NewRawCluster(t)
	testdb.Bootstrap(t, tdb.AdminURL)
	// A second administrator, so that memberships can be granted by someone other than the role
	// that ran the bootstrap. Postgres keeps one membership row per grantor.
	testdb.Exec(t, tdb.AdminURL, `
		CREATE ROLE second_admin NOLOGIN;
		GRANT lawang_resolver, lawang_worker TO second_admin WITH ADMIN OPTION`)

	cases := []struct {
		name    string
		breakIt string
		restore string
		// inherits is what pg_has_role(helper, 'USAGE') must report for the application role
		// while broken, to prove the case builds the state it claims to.
		helper   store.Role
		inherits bool
		// escalate, if set, is run as the APPLICATION role once Open has given its verdict, and
		// must leave it inheriting the helper role. It proves the refused state is one the
		// application role could turn into inheritance by itself, with no administrator involved.
		escalate string
		wantErr  error
	}{
		{
			name:    "helper role is BYPASSRLS",
			breakIt: "ALTER ROLE lawang_worker BYPASSRLS",
			restore: "ALTER ROLE lawang_worker NOBYPASSRLS",
			helper:  store.RoleWorker,
			wantErr: store.ErrUnsafeRole,
		},
		{
			name:    "helper role is SUPERUSER",
			breakIt: "ALTER ROLE lawang_resolver SUPERUSER",
			restore: "ALTER ROLE lawang_resolver NOSUPERUSER",
			helper:  store.RoleResolver,
			wantErr: store.ErrUnsafeRole,
		},
		{
			name:     "membership is INHERIT TRUE",
			breakIt:  "GRANT lawang_worker TO lawang WITH INHERIT TRUE",
			restore:  "GRANT lawang_worker TO lawang WITH INHERIT FALSE",
			helper:   store.RoleWorker,
			inherits: true,
			wantErr:  store.ErrUnsafeRole,
		},
		{
			name: "helper role is inherited through an intermediate role",
			breakIt: `CREATE ROLE ops NOLOGIN;
				GRANT lawang_worker TO ops;
				GRANT ops TO lawang`,
			restore:  "DROP ROLE ops",
			helper:   store.RoleWorker,
			inherits: true,
			wantErr:  store.ErrUnsafeRole,
		},
		{
			name:     "a second grantor adds an INHERIT TRUE membership beside the correct one",
			breakIt:  "GRANT lawang_resolver TO lawang WITH INHERIT TRUE GRANTED BY second_admin",
			restore:  "REVOKE lawang_resolver FROM lawang GRANTED BY second_admin",
			helper:   store.RoleResolver,
			inherits: true,
			wantErr:  store.ErrUnsafeRole,
		},
		{
			name:    "membership is SET FALSE",
			breakIt: "GRANT lawang_resolver TO lawang WITH SET FALSE",
			restore: "GRANT lawang_resolver TO lawang WITH SET TRUE",
			helper:  store.RoleResolver,
			wantErr: store.ErrUnsafeRole,
		},
		{
			name:    "membership is missing",
			breakIt: "REVOKE lawang_worker FROM lawang",
			restore: "GRANT lawang_worker TO lawang WITH INHERIT FALSE, SET TRUE",
			helper:  store.RoleWorker,
			wantErr: store.ErrUnsafeRole,
		},
		{
			// For the same grantor this only adds ADMIN to the correct row: USAGE stays false and
			// SET stays true. But a role that administers a helper role can grant it to itself
			// again WITH INHERIT TRUE, after the preflight has run.
			name:     "membership carries ADMIN OPTION",
			breakIt:  "GRANT lawang_worker TO lawang WITH ADMIN OPTION",
			restore:  "REVOKE ADMIN OPTION FOR lawang_worker FROM lawang CASCADE",
			helper:   store.RoleWorker,
			escalate: "GRANT lawang_worker TO lawang WITH INHERIT TRUE",
			wantErr:  store.ErrUnsafeRole,
		},
		{
			// The same through a role the login does not even inherit: it can SET ROLE to it.
			name: "ADMIN OPTION is held through an intermediate role that is not inherited",
			breakIt: `CREATE ROLE ops NOLOGIN;
				GRANT lawang_resolver TO ops WITH ADMIN OPTION;
				GRANT ops TO lawang WITH INHERIT FALSE, SET TRUE`,
			restore: `REVOKE lawang_resolver FROM ops CASCADE;
				DROP ROLE ops`,
			helper: store.RoleResolver,
			escalate: `SET ROLE ops;
				GRANT lawang_resolver TO lawang WITH INHERIT TRUE`,
			wantErr: store.ErrUnsafeRole,
		},
		{
			// Not a broken setup at all: two administrators have each run the bootstrap grants, so
			// there are two correct membership rows per helper role. It must start.
			name: "two grantors, every membership correct",
			breakIt: `GRANT lawang_resolver TO lawang WITH INHERIT FALSE, SET TRUE GRANTED BY second_admin;
				GRANT lawang_worker TO lawang WITH INHERIT FALSE, SET TRUE GRANTED BY second_admin`,
			restore: `REVOKE lawang_resolver FROM lawang GRANTED BY second_admin;
				REVOKE lawang_worker FROM lawang GRANTED BY second_admin`,
			helper:  store.RoleWorker,
			wantErr: nil,
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			// The state every case starts from is a correct one. This also proves the previous
			// case's restore worked, so a refusal below is caused by this case and nothing else.
			mustOpen(t, tdb.URL).Close()

			// Registered before breaking anything, so a break that fails halfway is still undone.
			t.Cleanup(func() { testdb.Exec(t, tdb.AdminURL, tc.restore) })
			testdb.Exec(t, tdb.AdminURL, tc.breakIt)

			if got := inheritsHelper(t, tdb.URL, tc.helper); got != tc.inherits {
				t.Fatalf("while broken, pg_has_role(%s, 'USAGE') = %v, want %v: the case does not build the state it names",
					tc.helper, got, tc.inherits)
			}

			db, err := store.Open(testCtx(t), tdb.URL)
			if db != nil {
				db.Close()
			}
			if tc.wantErr == nil {
				if err != nil {
					t.Fatalf("Open: %v, want a correct setup to be accepted", err)
				}
				return
			}
			if !errors.Is(err, tc.wantErr) {
				t.Errorf("Open: err = %v, want %v", err, tc.wantErr)
			}
			if tc.escalate != "" {
				testdb.Exec(t, tdb.URL, tc.escalate)
				if !inheritsHelper(t, tdb.URL, tc.helper) {
					t.Fatalf("the application role could not make itself inherit %s: the case does not build the state it names", tc.helper)
				}
			}
		})
	}

	// And the cluster is left correct.
	mustOpen(t, tdb.URL).Close()
}

// TestBootstrapRunsAsACreateroleAdmin runs the bootstrap the way managed Postgres makes you run
// it: as a non-superuser administrator that has CREATEROLE, and CREATE on the database. It needs
// a cluster of its own because the roles must not exist yet: a CREATEROLE role may only grant
// roles it created, or was given ADMIN OPTION on.
func TestBootstrapRunsAsACreateroleAdmin(t *testing.T) {
	tdb := testdb.NewRawCluster(t)
	ctx := testCtx(t)

	testdb.Exec(t, tdb.AdminURL, "CREATE ROLE dba LOGIN CREATEROLE NOSUPERUSER PASSWORD 'dba'")
	dbaURL := testdb.As(t, tdb.AdminURL, "dba", "dba")

	// Without CREATE on the database the script fails at its last step, the schema. It must leave
	// nothing behind, least of all an application role holding its memberships in a database
	// that has no schema for it.
	var denied *pgconn.PgError
	if err := testdb.TryBootstrap(t, dbaURL); !errors.As(err, &denied) || denied.Code != "42501" {
		t.Fatalf("bootstrap without CREATE on the database: err = %v, want permission denied (42501): the premise of this check is gone", err)
	}
	var leftBehind int
	queryRow(t, tdb.AdminURL, "SELECT count(*) FROM pg_roles WHERE rolname LIKE 'lawang%'", &leftBehind)
	if leftBehind != 0 {
		t.Fatalf("a failed bootstrap left %d roles behind, want it to apply completely or not at all", leftBehind)
	}

	testdb.Exec(t, tdb.AdminURL,
		"DO $$ BEGIN EXECUTE format('GRANT CREATE ON DATABASE %I TO dba', current_database()); END $$")

	testdb.Bootstrap(t, dbaURL)
	testdb.Bootstrap(t, dbaURL) // and it is safe to run again as the same administrator

	db := mustOpen(t, tdb.URL)
	if _, err := db.Migrate(ctx, quiet); err != nil {
		t.Fatalf("Migrate after a CREATEROLE bootstrap: %v", err)
	}
	for _, role := range []store.Role{store.RoleResolver, store.RoleWorker} {
		if err := db.RoleTx(ctx, role, func(pgx.Tx) error { return nil }); err != nil {
			t.Errorf("RoleTx(%s) after a CREATEROLE bootstrap: %v", role, err)
		}
	}
	db.Close()

	// The schema belongs to the application role, and the script leaves the administrator with
	// nothing it did not have before: it cannot act as the application role.
	conn, err := pgx.Connect(ctx, dbaURL)
	if err != nil {
		t.Fatal("connect as dba failed")
	}
	defer func() { _ = conn.Close(ctx) }()
	var owner string
	var dbaCanSet, dbaInherits bool
	err = conn.QueryRow(ctx, `
		SELECT (SELECT r.rolname FROM pg_namespace n JOIN pg_roles r ON r.oid = n.nspowner
		         WHERE n.nspname = $1),
		       pg_has_role('lawang', 'SET'), pg_has_role('lawang', 'USAGE')`, store.Schema).
		Scan(&owner, &dbaCanSet, &dbaInherits)
	if err != nil {
		t.Fatal(err)
	}
	if owner != "lawang" {
		t.Errorf("schema owner = %q, want lawang", owner)
	}
	if dbaCanSet || dbaInherits {
		t.Errorf("after the bootstrap the administrator can SET ROLE lawang (%v) or inherits it (%v), want neither",
			dbaCanSet, dbaInherits)
	}

	// A second administrator, here the superuser, runs it again. Every membership now exists once
	// per grantor, all of them correct, and the service must still start.
	testdb.Bootstrap(t, tdb.AdminURL)
	var rows int
	if err := conn.QueryRow(ctx, `
		SELECT count(*) FROM pg_auth_members m
		 WHERE m.member = 'lawang'::regrole
		   AND m.roleid IN ('lawang_resolver'::regrole, 'lawang_worker'::regrole)`).Scan(&rows); err != nil {
		t.Fatal(err)
	}
	if rows != 4 {
		t.Fatalf("found %d helper membership rows, want 4 (two grantors): the premise of this check is gone", rows)
	}
	mustOpen(t, tdb.URL).Close()
}

// TestBootstrapLeavesTheAdministratorsMembershipAsItWas pins the promise in the script's header:
// the administrator ends with exactly the membership in "lawang" it started with. The script
// has to take SET on that role to create the schema, and Postgres keeps one membership row per
// grantor, so taking SET rewrites a row the administrator already granted itself instead of
// adding one. Giving it back must restore that row, not delete it.
func TestBootstrapLeavesTheAdministratorsMembershipAsItWas(t *testing.T) {
	tdb := testdb.NewRawCluster(t)

	// createrole_self_grant is how an administrator ends up with such a row without ever asking
	// for one: every role it creates is granted back to it, by itself, with these options.
	testdb.Exec(t, tdb.AdminURL, `
		CREATE ROLE dba LOGIN CREATEROLE NOSUPERUSER PASSWORD 'dba';
		ALTER ROLE dba SET createrole_self_grant = 'inherit';
		DO $$ BEGIN EXECUTE format('GRANT CREATE ON DATABASE %I TO dba', current_database()); END $$`)

	// The first run creates the roles, so there is no "before" to compare with. The helper roles
	// are never borrowed, so their rows show what the row for "lawang" must still look like.
	testdb.Bootstrap(t, testdb.As(t, tdb.AdminURL, "dba", "dba"))
	const selfGrantedInheritOnly = "dba: inherit=t set=f; postgres: inherit=f set=f"
	if got := membershipOf(t, tdb.AdminURL, "dba", "lawang_resolver"); got != selfGrantedInheritOnly {
		t.Fatalf("dba in lawang_resolver = %q, want %q: the premise of this check is gone", got, selfGrantedInheritOnly)
	}
	if got := membershipOf(t, tdb.AdminURL, "dba", "lawang"); got != selfGrantedInheritOnly {
		t.Errorf("after the first bootstrap, dba in lawang = %q, want %q", got, selfGrantedInheritOnly)
	}
	mustOpen(t, tdb.URL).Close()

	// A second administrator who administers the roles only through the first, so the grantor of
	// what the script borrows is not the role that runs it.
	testdb.Exec(t, tdb.AdminURL, `
		CREATE ROLE dba2 LOGIN CREATEROLE NOSUPERUSER PASSWORD 'dba2';
		GRANT dba TO dba2 WITH INHERIT TRUE;
		DO $$ BEGIN EXECUTE format('GRANT CREATE ON DATABASE %I TO dba2', current_database()); END $$`)

	// And one who was delegated exactly what the script needs and no more: ADMIN OPTION on the
	// helper roles to grant them, SET on "lawang" to create its schema, and no way to grant
	// "lawang" to anyone. If the script tried to borrow what it already has, it would fail here.
	testdb.Exec(t, tdb.AdminURL, `
		CREATE ROLE delegate LOGIN NOSUPERUSER PASSWORD 'delegate';
		GRANT lawang_resolver, lawang_worker TO delegate WITH ADMIN OPTION, INHERIT FALSE, SET FALSE;
		GRANT lawang TO delegate WITH INHERIT FALSE, SET TRUE;
		DO $$ BEGIN EXECUTE format('GRANT CREATE ON DATABASE %I TO delegate', current_database()); END $$`)

	cases := []struct {
		name  string
		admin string
		// setup runs as that administrator and puts its own membership row in the state named.
		setup string
		// want is the membership the case starts from, to prove setup built it, and must end with.
		want string
	}{
		{
			name:  "own grant WITH INHERIT TRUE, SET FALSE",
			admin: "dba",
			setup: "GRANT lawang TO dba WITH INHERIT TRUE, SET FALSE",
			want:  selfGrantedInheritOnly,
		},
		{
			name:  "own grant that already has SET",
			admin: "dba",
			setup: "GRANT lawang TO dba WITH INHERIT FALSE, SET TRUE",
			want:  "dba: inherit=f set=t; postgres: inherit=f set=f",
		},
		{
			name:  "own grant with both",
			admin: "dba",
			setup: "GRANT lawang TO dba WITH INHERIT TRUE, SET TRUE",
			want:  "dba: inherit=t set=t; postgres: inherit=f set=f",
		},
		{
			name:  "no grant of its own",
			admin: "dba",
			setup: "REVOKE lawang FROM dba",
			want:  "postgres: inherit=f set=f",
		},
		{
			name:  "no membership at all, borrowing through another administrator's ADMIN OPTION",
			admin: "dba2",
			setup: "SELECT 1",
			want:  "",
		},
		{
			name:  "SET but no ADMIN OPTION: nothing to borrow, and no right to",
			admin: "delegate",
			setup: "SELECT 1",
			want:  "postgres: inherit=f set=t",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			adminURL := testdb.As(t, tdb.AdminURL, tc.admin, tc.admin)
			// Only creating the schema needs SET, so it has to be missing for the script to borrow.
			testdb.Exec(t, tdb.AdminURL, "DROP SCHEMA IF EXISTS lawang CASCADE")
			testdb.Exec(t, adminURL, tc.setup)
			if got := membershipOf(t, tdb.AdminURL, tc.admin, "lawang"); got != tc.want {
				t.Fatalf("before the bootstrap, %s in lawang = %q, want %q: the case does not build the state it names", tc.admin, got, tc.want)
			}

			if err := testdb.TryBootstrap(t, adminURL); err != nil {
				t.Fatalf("bootstrap as %s: %v", tc.admin, err)
			}

			if got := membershipOf(t, tdb.AdminURL, tc.admin, "lawang"); got != tc.want {
				t.Errorf("after the bootstrap, %s in lawang = %q, want it unchanged: %q", tc.admin, got, tc.want)
			}
			var owner string
			queryRow(t, tdb.AdminURL, `SELECT r.rolname FROM pg_namespace n JOIN pg_roles r ON r.oid = n.nspowner
				WHERE n.nspname = 'lawang'`, &owner)
			if owner != "lawang" {
				t.Errorf("schema owner = %q, want lawang: the script did not create the schema", owner)
			}
			mustOpen(t, tdb.URL).Close()
		})
	}
}

// membershipOf renders every membership row of member in role, one per grantor. ADMIN OPTION is
// left out: the script never touches it.
func membershipOf(t *testing.T, adminURL, member, role string) string {
	t.Helper()
	var got string
	queryRow(t, adminURL, fmt.Sprintf(`
		SELECT coalesce(string_agg(format('%%s: inherit=%%s set=%%s', g.rolname, m.inherit_option, m.set_option),
		                           '; ' ORDER BY g.rolname), '')
		  FROM pg_auth_members m JOIN pg_roles g ON g.oid = m.grantor
		 WHERE m.roleid = '%s'::regrole AND m.member = '%s'::regrole`, role, member), &got)
	return got
}

func queryRow(t *testing.T, connURL, sql string, dest ...any) {
	t.Helper()
	ctx := testCtx(t)
	conn, err := pgx.Connect(ctx, connURL)
	if err != nil {
		t.Fatal("connect failed")
	}
	defer func() { _ = conn.Close(ctx) }()
	if err := conn.QueryRow(ctx, sql).Scan(dest...); err != nil {
		t.Fatal(err)
	}
}

func mustOpen(t *testing.T, url string) *store.DB {
	t.Helper()
	db, err := store.Open(testCtx(t), url)
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	return db
}

// inheritsHelper asks, as the application role and outside store.Open, whether the privileges of
// a helper role are available without SET ROLE.
func inheritsHelper(t *testing.T, appURL string, helper store.Role) bool {
	t.Helper()
	ctx := testCtx(t)
	conn, err := pgx.Connect(ctx, appURL)
	if err != nil {
		t.Fatal("connect as the application role failed")
	}
	defer func() { _ = conn.Close(ctx) }()
	var inherits bool
	if err := conn.QueryRow(ctx, "SELECT pg_has_role($1, 'USAGE')", string(helper)).Scan(&inherits); err != nil {
		t.Fatal(err)
	}
	return inherits
}

package store_test

import (
	"context"
	"errors"
	"testing"
	"time"

	"github.com/jackc/pgx/v5"

	"github.com/gablooge/lawang/internal/store"
	"github.com/gablooge/lawang/internal/tenancy"
)

// scratchJobs builds what B04 onwards really build: a tenant table that a helper role may read
// across tenants. The tenant policy is the one every table has; the second one is permissive and
// names the worker role. One row per tenant.
func scratchJobs(t *testing.T, db *store.DB) {
	t.Helper()
	ctx := testCtx(t)
	err := db.Tx(ctx, func(tx pgx.Tx) error {
		for _, stmt := range []string{
			"CREATE TABLE scratch_jobs (tenant tenant_id NOT NULL, note text NOT NULL DEFAULT '')",
			"ALTER TABLE scratch_jobs ENABLE ROW LEVEL SECURITY",
			"ALTER TABLE scratch_jobs FORCE ROW LEVEL SECURITY",
			"CREATE POLICY tenant_isolation ON scratch_jobs USING (tenant = current_tenant()) WITH CHECK (tenant = current_tenant())",
			"CREATE POLICY worker_claims ON scratch_jobs FOR SELECT TO lawang_worker USING (true)",
			"GRANT SELECT ON scratch_jobs TO lawang_worker",
		} {
			if _, err := tx.Exec(ctx, stmt); err != nil {
				return err
			}
		}
		return nil
	})
	if err != nil {
		t.Fatalf("scratch table: %v", err)
	}
	for _, id := range []tenancy.ID{tenantA, tenantB} {
		err := db.TenantTx(ctx, id, func(tx pgx.Tx) error {
			_, err := tx.Exec(ctx, "INSERT INTO scratch_jobs (tenant) VALUES ($1)", id.String())
			return err
		})
		if err != nil {
			t.Fatalf("seed %s: %v", id, err)
		}
	}
}

func visibleJobs(ctx context.Context, t *testing.T, tx pgx.Tx) []string {
	t.Helper()
	rows, err := tx.Query(ctx, "SELECT tenant::text FROM scratch_jobs ORDER BY tenant")
	if err != nil {
		t.Fatalf("query: %v", err)
	}
	got, err := pgx.CollectRows(rows, pgx.RowTo[string])
	if err != nil {
		t.Fatalf("collect: %v", err)
	}
	return got
}

// TestAHelperRoleTransactionIsCrossTenantWhateverIsBound pins what Postgres does, because it is
// not what one would guess. Permissive policies are ORed together: once the worker role's
// "USING (true)" applies, a bound tenant takes nothing away. So per-tenant work may never happen
// inside RoleTx, and RoleTx makes that hard to do by accident: tenancy.Bind refuses its
// transaction.
func TestAHelperRoleTransactionIsCrossTenantWhateverIsBound(t *testing.T) {
	db := open(t, "")
	scratchJobs(t, db)
	ctx := testCtx(t)

	err := db.RoleTx(ctx, store.RoleWorker, func(tx pgx.Tx) error {
		if got := visibleJobs(ctx, t, tx); len(got) != 2 {
			t.Fatalf("the worker role saw %v, want the rows of both tenants: the case does not build the state it names", got)
		}

		if err := tenancy.Bind(ctx, tx, tenantA); !errors.Is(err, tenancy.ErrCrossTenantTx) {
			t.Errorf("Bind inside RoleTx: err = %v, want ErrCrossTenantTx", err)
		}
		sp, err := tx.Begin(ctx)
		if err != nil {
			return err
		}
		if err := tenancy.Bind(ctx, sp, tenantA); !errors.Is(err, tenancy.ErrCrossTenantTx) {
			t.Errorf("Bind inside a savepoint of RoleTx: err = %v, want ErrCrossTenantTx", err)
		}
		if err := sp.Rollback(ctx); err != nil {
			return err
		}

		// The reason for the refusal, shown by going around it: with tenant_a bound the hard way,
		// tenant_b's row is still there.
		if _, err := tx.Exec(ctx, "SELECT set_config('lawang.tenant', $1, true)", tenantA.String()); err != nil {
			return err
		}
		if got := visibleJobs(ctx, t, tx); len(got) != 2 {
			t.Errorf("under the worker role with tenant_a bound, saw %v. Postgres used to show both tenants here; "+
				"if that has changed, the comments on store.RoleTx and tenancy.Bind are out of date", got)
		}
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}

	// The second transaction, as the application role, is the one that is narrow.
	err = db.TenantTx(ctx, tenantA, func(tx pgx.Tx) error {
		if got := visibleJobs(ctx, t, tx); len(got) != 1 || got[0] != tenantA.String() {
			t.Errorf("TenantTx(tenant_a) saw %v, want only its own row", got)
		}
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
}

// assertCleanConnection runs the next transaction on a pool of one connection and fails if it
// carries a role or a tenant. It has a deadline of its own: a connection that was never given back
// makes this wait, and it must fail instead of stalling the package.
func assertCleanConnection(t *testing.T, db *store.DB, after string) {
	t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	err := db.Tx(ctx, func(tx pgx.Tx) error {
		var user string
		var tenant *string
		if err := tx.QueryRow(ctx, "SELECT current_user, current_setting('lawang.tenant', true)").Scan(&user, &tenant); err != nil {
			return err
		}
		if user != "lawang" {
			t.Errorf("after %s, the next transaction runs as %q", after, user)
		}
		if tenant != nil && *tenant != "" {
			t.Errorf("after %s, the next transaction has tenant %q bound", after, *tenant)
		}
		if got := visibleJobs(ctx, t, tx); len(got) != 0 {
			t.Errorf("after %s, the next transaction saw %v", after, got)
		}
		return nil
	})
	if err != nil {
		t.Fatalf("after %s, the next transaction failed: %v", after, err)
	}
}

// bindAround binds a tenant inside RoleTx the way tenancy.Bind refuses to, so that the leak tests
// below leave both a role and a tenant behind for the next transaction to find.
func bindAround(ctx context.Context, tx pgx.Tx) error {
	_, err := tx.Exec(ctx, "SELECT set_config('lawang.tenant', $1, true)", tenantA.String())
	return err
}

// The three tests below pin a property that rests on pgx internals: the deferred rollback in
// pgx.BeginFunc, and the pool destroying a connection that comes back in the middle of something.
// A pgx upgrade, or a move away from BeginFunc, must not be able to leave a role or a tenant on a
// pooled connection with the rest of the suite still green.
//
// They do not have the same teeth, and the difference is worth knowing before trusting them:
//
//   - The panic test can be failed from this package: a begin written by hand without the deferred
//     rollback fails it.
//   - The two cancellation tests CANNOT be failed by any mutation of this package. What they pin
//     belongs to pgxpool, not to store: a connection that is released in the middle of an operation
//     (a transaction still open, a statement interrupted by the cancel) is destroyed and never
//     handed out again, so no SET LOCAL or set_config can ride along, whatever begin does. Nothing
//     here implements that and nothing here can break it. They exist for one reason: to notice the
//     pgx upgrade that changes it. If one of them goes red, read the pgx changelog first.

func TestAPanicLeavesNoRoleOrTenantOnTheConnection(t *testing.T) {
	db := open(t, "&pool_max_conns=1")
	scratchJobs(t, db)
	ctx := testCtx(t)

	panics := func(name string, run func() error) {
		t.Helper()
		defer func() {
			if recover() == nil {
				t.Errorf("%s: the panic did not reach the caller", name)
			}
			assertCleanConnection(t, db, "a panic inside "+name)
		}()
		_ = run()
	}
	panics("Tx", func() error {
		return db.Tx(ctx, func(tx pgx.Tx) error {
			if err := bindAround(ctx, tx); err != nil {
				t.Fatal(err)
			}
			panic("boom")
		})
	})
	panics("TenantTx", func() error {
		return db.TenantTx(ctx, tenantA, func(pgx.Tx) error { panic("boom") })
	})
	panics("RoleTx", func() error {
		return db.RoleTx(ctx, store.RoleWorker, func(tx pgx.Tx) error {
			if err := bindAround(ctx, tx); err != nil {
				t.Fatal(err)
			}
			panic("boom")
		})
	})
}

// Pins pgxpool behaviour, not code of this package (see the comment above the panic test): no
// mutation of store fails it. It is here to catch a pgx upgrade.
func TestACancelledContextLeavesNoRoleOrTenantOnTheConnection(t *testing.T) {
	db := open(t, "&pool_max_conns=1")
	scratchJobs(t, db)

	// Cancelled after the work and before the commit.
	for name, run := range map[string]func(context.Context, context.CancelFunc) error{
		"TenantTx": func(ctx context.Context, cancel context.CancelFunc) error {
			return db.TenantTx(ctx, tenantA, func(pgx.Tx) error { cancel(); return nil })
		},
		"RoleTx": func(ctx context.Context, cancel context.CancelFunc) error {
			return db.RoleTx(ctx, store.RoleWorker, func(tx pgx.Tx) error {
				err := bindAround(ctx, tx)
				cancel()
				return err
			})
		},
	} {
		ctx, cancel := context.WithCancel(testCtx(t))
		if err := run(ctx, cancel); !errors.Is(err, context.Canceled) {
			t.Errorf("%s cancelled before commit: err = %v, want context.Canceled", name, err)
		}
		cancel()
		assertCleanConnection(t, db, name+" cancelled before its commit")
	}
}

// Like the test above it, this pins pgxpool behaviour (a connection released while a statement was
// being interrupted is destroyed), which no mutation of store can break. It is here to catch a pgx
// upgrade.
func TestACancelInFlightLeavesNoRoleOrTenantOnTheConnection(t *testing.T) {
	db := open(t, "&pool_max_conns=1")
	scratchJobs(t, db)

	ctx, cancel := context.WithCancel(testCtx(t))
	defer cancel()
	timer := time.AfterFunc(300*time.Millisecond, cancel)
	defer timer.Stop()

	start := time.Now()
	err := db.RoleTx(ctx, store.RoleWorker, func(tx pgx.Tx) error {
		if err := bindAround(ctx, tx); err != nil {
			return err
		}
		// Bounded by the server as well, so a cancel that never arrives fails the test in seconds.
		_, err := tx.Exec(ctx, "SELECT pg_sleep(10)")
		return err
	})
	if !errors.Is(err, context.Canceled) {
		t.Errorf("RoleTx cancelled while a statement was running: err = %v, want context.Canceled", err)
	}
	if elapsed := time.Since(start); elapsed > 5*time.Second {
		t.Errorf("RoleTx returned %s after the cancel, the statement was not interrupted", elapsed.Round(time.Millisecond))
	}
	assertCleanConnection(t, db, "RoleTx cancelled while a statement was running")
}

// Package store owns the Postgres connection pool, the transaction helpers that make row-level
// security apply, and the embedded migrations.
package store

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/gablooge/lawang/internal/tenancy"
)

// Schema is where every Lawang object lives. It is set as the search path on every connection
// explicitly, because the default "$user" entry follows SET ROLE and would stop resolving the
// moment a transaction enters a helper role.
const Schema = "lawang"

// minServerVersion is Postgres 16, the first with GRANT ... WITH INHERIT FALSE.
const minServerVersion = 160000

// Role is a helper database role the application role can enter for one transaction.
type Role string

// The helper roles. Their policies arrive with the tables they act on.
const (
	RoleResolver Role = "lawang_resolver"
	RoleWorker   Role = "lawang_worker"
)

// ErrUnsafeRole reports a database login under which row-level security would not apply, or whose
// helper roles are not set up as docs/architecture.md section 4 requires.
var ErrUnsafeRole = errors.New("store: unsafe database role")

// ErrNotBootstrapped reports a database where the one-time bootstrap script has not been run.
var ErrNotBootstrapped = errors.New(`store: database is not bootstrapped, run "lawang migrate bootstrap" and apply its output as an administrator`)

// ErrSchemaNotOwned reports a schema of the right name that the login role does not own, so it is
// not the one the bootstrap script creates. It is a sentinel of its own because neither of the
// others tells the operator the truth: tenant isolation is not at stake, and applying the
// bootstrap script again does not change who owns a schema that already exists.
var ErrSchemaNotOwned = errors.New(`store: schema "lawang" is not owned by the login role`)

// DB is the connection pool.
type DB struct {
	pool *pgxpool.Pool
}

// defaultConnectTimeout bounds one connection attempt when the URL has no connect_timeout of its
// own. Without it a host that drops packets (a firewall or a security group, the usual mistake on
// managed Postgres) holds Open for the TCP timeout of the operating system, 75 seconds or more,
// with nothing logged. An operator overrides it with connect_timeout=N (seconds) in the URL, for
// N of 1 or more.
//
// connect_timeout=0 does NOT lift the bound, and that is deliberate. In libpq 0 means "wait for as
// long as it takes", but pgx parses an explicit 0 to the same zero value as a missing parameter, so
// the two cannot be told apart here, and of the two readings the bounded one is the safe one: a
// start that hangs with nothing logged is the failure this constant exists to prevent. An operator
// who needs a long wait (a slow failover proxy, a debugger on the server) writes a large number.
const defaultConnectTimeout = 10 * time.Second

// Open connects and then refuses to return a pool that is not safe to use: see preflight.
//
// No error it returns repeats any part of databaseURL: not the password, and not the user, host,
// port or database either. See connError.
func Open(ctx context.Context, databaseURL string) (*DB, error) {
	cfg, err := poolConfig(databaseURL)
	if err != nil {
		return nil, err
	}
	// The pool connects lazily, so an unreachable or refusing server is first met by preflight.
	pool, err := pgxpool.NewWithConfig(ctx, cfg)
	if err != nil {
		return nil, connError(ctx, err)
	}
	db := &DB{pool: pool}
	if err := db.preflight(ctx); err != nil {
		pool.Close()
		return nil, err
	}
	return db, nil
}

// poolConfig parses the URL and applies what every Lawang connection needs.
func poolConfig(databaseURL string) (*pgxpool.Config, error) {
	cfg, err := pgxpool.ParseConfig(databaseURL)
	if err != nil {
		// Deliberately not wrapped: pgx's parse error repeats the URL with only the password masked.
		return nil, errors.New("LAWANG_DATABASE_URL: not a valid Postgres connection URL")
	}
	cfg.ConnConfig.RuntimeParams["search_path"] = Schema
	cfg.ConnConfig.RuntimeParams["application_name"] = "lawang"
	// Zero is "not set" and also an explicit connect_timeout=0: see defaultConnectTimeout.
	if cfg.ConnConfig.ConnectTimeout == 0 {
		cfg.ConnConfig.ConnectTimeout = defaultConnectTimeout
	}
	return cfg, nil
}

// checkVersion refuses a server older than Postgres 16. version is server_version_num.
func checkVersion(version int) error {
	if version < minServerVersion {
		return fmt.Errorf("store: Postgres 16 or newer is required, server reports %d", version)
	}
	return nil
}

// Close releases every connection.
func (db *DB) Close() { db.pool.Close() }

// preflight fails closed on anything that would make tenant isolation silently not apply. Tests
// that only ever connect as a superuser pass without isolation being real, so this runs on every
// start, in every environment. It runs once per process: a membership changed by an administrator
// afterwards is not seen until the next start.
//
// Its refusals never name the login role: that name is the user half of the database URL.
func (db *DB) preflight(ctx context.Context) error {
	var version int
	if err := db.pool.QueryRow(ctx, "SELECT current_setting('server_version_num')::int").Scan(&version); err != nil {
		return connError(ctx, err)
	}
	if err := checkVersion(version); err != nil {
		return err
	}

	var super, bypass, hasSchema, ownSchema bool
	err := db.pool.QueryRow(ctx, `
		SELECT r.rolsuper, r.rolbypassrls,
		       EXISTS (SELECT FROM pg_namespace WHERE nspname = $1),
		       EXISTS (SELECT FROM pg_namespace WHERE nspname = $1 AND nspowner = r.oid)
		  FROM pg_roles r
		 WHERE r.rolname = current_user`, Schema,
	).Scan(&super, &bypass, &hasSchema, &ownSchema)
	if err != nil {
		return connError(ctx, err)
	}
	if super || bypass {
		return fmt.Errorf("%w: the login role is SUPERUSER or BYPASSRLS, so row-level security would not apply to it", ErrUnsafeRole)
	}

	helpers, err := db.helperStates(ctx)
	if err != nil {
		return err
	}
	for _, h := range helpers {
		if h.exists && h.unsafe {
			return fmt.Errorf("%w: helper role %s is SUPERUSER or BYPASSRLS", ErrUnsafeRole, h.name)
		}
	}
	if !hasSchema {
		return ErrNotBootstrapped
	}
	// Ownership itself, not membership in the owner: the bootstrap creates the schema for exactly
	// this role, and migrations create and alter everything in it as this role.
	if !ownSchema {
		return fmt.Errorf("%w: it was not created by the bootstrap script; an administrator can hand it over with ALTER SCHEMA %s OWNER TO the login role, or use another database",
			ErrSchemaNotOwned, Schema)
	}
	for _, h := range helpers {
		switch {
		case !h.exists:
			return fmt.Errorf("%w: helper role %s does not exist, apply the bootstrap script again", ErrUnsafeRole, h.name)
		case h.inherited:
			return fmt.Errorf("%w: the login role inherits %s, directly or through another role, so its cross-tenant policies would apply without SET ROLE; every membership on the path must be WITH INHERIT FALSE",
				ErrUnsafeRole, h.name)
		case h.administers:
			return fmt.Errorf("%w: the login role holds ADMIN OPTION on %s, directly or through another role, so it could grant itself that role WITH INHERIT TRUE while running; revoke the ADMIN OPTION",
				ErrUnsafeRole, h.name)
		case !h.canSet:
			return fmt.Errorf("%w: the login role cannot SET ROLE %s, it must be a member WITH INHERIT FALSE, SET TRUE", ErrUnsafeRole, h.name)
		}
	}
	return nil
}

// helperState is what the preflight learns about one helper role.
type helperState struct {
	name string
	// exists is false when the role is missing, and then the other fields are all false.
	exists bool
	// unsafe: the role is SUPERUSER or BYPASSRLS.
	unsafe bool
	// inherited: the login holds the role's privileges, and is subject to its policies, WITHOUT
	// SET ROLE. A plain transaction with no tenant bound would then see across tenants.
	inherited bool
	// administers: the login may grant the role, to itself included. That is the one membership
	// state it could turn into inheritance by itself, after this check has run.
	administers bool
	// canSet: the login may SET ROLE to it, which RoleTx depends on.
	canSet bool
}

// helperStates asks Postgres the question Postgres itself answers when it evaluates a policy or
// a privilege, instead of reading pg_auth_members. A membership has one row per grantor, and
// inheritance also arrives through intermediate roles, so no count of rows that look right says
// what the login can actually do. pg_has_role follows every path: 'USAGE' is "without SET ROLE",
// 'SET' is "may SET ROLE", and 'MEMBER WITH ADMIN OPTION' is "may grant this role". Postgres
// answers the last one identically for 'USAGE WITH ADMIN OPTION' and 'SET WITH ADMIN OPTION':
// all three ask is_admin_of_role, which follows every membership whether or not it is inherited.
// That is the right reach, because ADMIN OPTION held by a role the login can only SET ROLE to is
// just as usable. All of these are only meaningful for a login that is not a superuser, which the
// caller has already established.
func (db *DB) helperStates(ctx context.Context) ([]helperState, error) {
	want := []string{string(RoleResolver), string(RoleWorker)}
	rows, err := db.pool.Query(ctx, `
		SELECT n.name, h.oid IS NOT NULL,
		       coalesce(h.rolsuper OR h.rolbypassrls, false),
		       coalesce(pg_has_role(h.oid, 'USAGE'), false),
		       coalesce(pg_has_role(h.oid, 'MEMBER WITH ADMIN OPTION'), false),
		       coalesce(pg_has_role(h.oid, 'SET'), false)
		  FROM unnest($1::text[]) WITH ORDINALITY AS n(name, ord)
		  LEFT JOIN pg_roles h ON h.rolname = n.name
		 ORDER BY n.ord`, want)
	if err != nil {
		return nil, connError(ctx, err)
	}
	states, err := pgx.CollectRows(rows, func(row pgx.CollectableRow) (helperState, error) {
		var h helperState
		err := row.Scan(&h.name, &h.exists, &h.unsafe, &h.inherited, &h.administers, &h.canSet)
		return h, err
	})
	if err != nil {
		return nil, connError(ctx, err)
	}
	// Fail closed: an answer that came back short has verified nothing.
	if len(states) != len(want) {
		return nil, fmt.Errorf("%w: preflight saw %d helper roles, want %d", ErrUnsafeRole, len(states), len(want))
	}
	return states, nil
}

// Tx runs fn in a transaction with no tenant bound. Every tenant-scoped table reads as empty and
// refuses writes. It is for the few things that are not tenant data.
//
// fn does database work and nothing else: see begin for what happens to a network error that fn
// returns.
func (db *DB) Tx(ctx context.Context, fn func(pgx.Tx) error) error {
	return db.begin(ctx, fn)
}

// begin is pgx.BeginTxFunc (commit when fn returns nil, roll back on an error or a panic) with a
// fixed isolation level (see the end of this comment) and one addition. The pool connects lazily, so any transaction can be the one that meets an unreachable
// server, and a network error in the middle of one carries addresses too: those errors are
// replaced the way Open replaces them. Every other error, from fn or from the server, reaches the
// caller untouched.
//
// The replacement looks at the error and not at where it came from, ON PURPOSE. An error that fn
// returns is replaced too when it wraps a *net.OpError, a *net.DNSError or a *pgconn.ConnectError,
// and then nothing fn wrapped around it survives: errors.Is(err, aSentinelOfTheCaller) is false
// and the text points at LAWANG_DATABASE_URL. It has to work on what fn returns, because a
// statement that fn runs on a connection that has just died fails with exactly such an error, and
// fn is the one that returns it. Telling that error from a network error of the caller's own would
// mean trusting a side channel (is the connection marked closed?) on every failure path of pgx,
// and a miss there puts the connection target back into the log. The wrong label costs less.
//
// So fn must not do network I/O of its own (a provider call, a sink delivery, a lookup), and must
// not return a net error that is not the database's. That is already the rule for other reasons:
// a transaction that waits on the far end of a network call holds a pooled connection and its row
// locks for as long as that takes (docs/architecture.md section 10, principle 6). Do the call
// before or after the transaction and pass in what it returned.
//
// The transaction is READ COMMITTED, asked for by name and not inherited. Callers depend on it:
// a statement that follows a wait for a lock must see what the transaction it waited for
// committed, and only READ COMMITTED takes a new snapshot per statement. The outbox is the first
// such caller (docs/adr/0010-outbox-head-marker.md): under REPEATABLE READ its writers wait for the
// ordering key's lock and then decide on a snapshot from before the wait, which leaves a row that
// is never delivered, with no error anywhere. default_transaction_isolation can be set on the
// server, the database or the role, by an administrator who has never heard of this package, so
// the default is not something to rely on. This is the only place the application opens a
// transaction. (The preflight runs single statements, for which the levels do not differ, and
// goose opens its own transactions for DDL, which the session lock in Migrate already serializes.)
func (db *DB) begin(ctx context.Context, fn func(pgx.Tx) error) error {
	return scrub(ctx, pgx.BeginTxFunc(ctx, db.pool, pgx.TxOptions{IsoLevel: pgx.ReadCommitted}, fn))
}

// TenantTx runs fn in a transaction scoped to one tenant. It is the only way to do a tenant's
// work.
//
// fn does database work and nothing else. No network I/O inside it: a net error that fn returns
// comes back as a database connection error, without whatever fn wrapped around it (see begin).
func (db *DB) TenantTx(ctx context.Context, id tenancy.ID, fn func(pgx.Tx) error) error {
	return db.begin(ctx, func(tx pgx.Tx) error {
		if err := tenancy.Bind(ctx, tx, id); err != nil {
			return err
		}
		return fn(tx)
	})
}

// RoleTx runs fn in a transaction under a helper role. SET LOCAL ends with the transaction, so the
// wider policies of that role never outlive it on a pooled connection.
//
// THE TRANSACTION IS CROSS-TENANT FOR ITS WHOLE LIFE. Binding a tenant inside it does not narrow
// it: Postgres ORs permissive policies together, so a policy of the helper role (for example
// "TO lawang_worker USING (true)") keeps admitting every tenant's rows whatever
// lawang.tenant says. A bind could only ever add rows, on tables where the role has no policy
// of its own. So fn does the role's cross-tenant step and nothing else (resolve an owner, claim a
// row), returns what it learned, and the work for that tenant happens in a SECOND transaction
// under TenantTx, as the application role.
//
// To keep that from being forgotten, the transaction handed to fn refuses tenancy.Bind with
// tenancy.ErrCrossTenantTx, savepoints included. An item that really wants a helper role and a
// tenant in one transaction has to add that on purpose, with a test of what is visible inside it.
//
// As in Tx and TenantTx, fn does database work and nothing else. No network I/O inside it: a net
// error that fn returns comes back as a database connection error, without whatever fn wrapped
// around it (see begin).
func (db *DB) RoleTx(ctx context.Context, role Role, fn func(pgx.Tx) error) error {
	// A role name cannot be a query parameter, so each statement is a literal. Nothing here is
	// ever built from input.
	var stmt string
	switch role {
	case RoleResolver:
		stmt = "SET LOCAL ROLE lawang_resolver"
	case RoleWorker:
		stmt = "SET LOCAL ROLE lawang_worker"
	default:
		return fmt.Errorf("store: unknown role %q", role)
	}
	return db.begin(ctx, func(tx pgx.Tx) error {
		if _, err := tx.Exec(ctx, stmt); err != nil {
			return fmt.Errorf("store: enter role %s: %w", role, err)
		}
		return fn(crossTenantTx{tx})
	})
}

// crossTenantTx is the transaction RoleTx hands out. It carries the marker tenancy.Bind refuses.
type crossTenantTx struct{ pgx.Tx }

var _ tenancy.CrossTenantTx = crossTenantTx{}

// CrossTenant implements tenancy.CrossTenantTx.
func (crossTenantTx) CrossTenant() {}

// Begin opens a savepoint that is just as cross-tenant as the transaction around it.
func (tx crossTenantTx) Begin(ctx context.Context) (pgx.Tx, error) {
	sp, err := tx.Tx.Begin(ctx)
	if err != nil {
		return nil, err
	}
	return crossTenantTx{sp}, nil
}

package store_test

import (
	"context"
	"errors"
	"io"
	"log/slog"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/jackc/pgx/v5"
