// domainVerdict asks the tenant_id domain, and nothing else, about one value: a cast, as the
// application role, with no table and so no policy anywhere near it. It returns the SQLSTATE, or
// "" when the domain accepts the value.
func domainVerdict(t *testing.T, db *store.DB, value string) string {
	t.Helper()
	ctx := testCtx(t)
	err := db.Tx(ctx, func(tx pgx.Tx) error {
		var got string
		if err := tx.QueryRow(ctx, "SELECT ($1::text::tenant_id)::text", value).Scan(&got); err != nil {
			return err
		}
		if got != value {
			t.Errorf("the domain accepted %q and handed back %q", value, got)
		}
		return nil
	})
	if err == nil {
		return ""
	}
	var pgErr *pgconn.PgError
	if !errors.As(err, &pgErr) {
		t.Fatalf("casting %q to tenant_id: %v, want an answer from the server", value, err)
	}
	return pgErr.Code
}

func TestTenantIDDomainRejectsMalformedIDs(t *testing.T) {
	db := open(t, "")
	ctx := testCtx(t)
	bad := []string{"", "tenant a", strings.Repeat("x", 65)}

	// The domain by itself. An insert cannot show this for the empty id: with '' bound,
	// current_tenant() is NULL and the policy refuses the row (42501) whatever the domain thinks
	// of it. 23514 is a check violation, and the domain's check is the only one in reach.
	for _, id := range bad {
		if got := domainVerdict(t, db, id); got != "23514" {
			t.Errorf("casting %q to tenant_id: SQLSTATE %q, want 23514 from the domain's check", id, got)
		}
	}

	// And the column really is of that domain. Bind would refuse these ids first, so go around it;
	// the policy is content (the id equals the bound tenant), which leaves the domain as the only
	// thing that can refuse. The empty id is left out for the reason above.
	for _, id := range bad[1:] {
		err := db.Tx(ctx, func(tx pgx.Tx) error {
			if _, err := tx.Exec(ctx, "SELECT set_config('lawang.tenant', $1, true)", id); err != nil {
				return err
			}
			_, err := tx.Exec(ctx, "INSERT INTO tenants (id) VALUES ($1)", id)
			return err
		})
		var pgErr *pgconn.PgError
		if !errors.As(err, &pgErr) || pgErr.Code != "23514" {
			t.Errorf("inserting tenant id %q: err = %v, want a check violation (23514)", id, err)
		}
	}
}

// TestTheGoRuleAndTheDomainAgree ties tenancy.Parse to the tenant_id domain. The rule is written
// twice, as a byte loop in Go and as a regular expression in SQL, and the places where those two
// dialects usually part ways are the cases here. If this fails after a change to one of them, the
// other one needs the same change.
func TestTheGoRuleAndTheDomainAgree(t *testing.T) {
	db := open(t, "")
	cases := []struct {
		name, id string
		// notText: Postgres cannot hold the value in a text at all (22021), so it never reaches
		// the domain. That is a refusal too, and the only other one allowed.
		notText bool
	}{
		{name: "plain", id: "tenant_a"},
		{name: "a ULID", id: "01JZXA8Q2KTENANT0000000000"},
		{name: "one character", id: "a"},
		{name: "every class", id: "A-b_9"},
		{name: "only a hyphen", id: "-"},
		{name: "only an underscore", id: "_"},
		{name: "64 characters", id: strings.Repeat("x", 64)},
		{name: "65 characters", id: strings.Repeat("x", 65)},
		{name: "empty", id: ""},
		{name: "space", id: " "},
		{name: "inner space", id: "tenant a"},
		{name: "trailing newline", id: "tenant_a\n"},
		{name: "leading newline", id: "\ntenant_a"},
		{name: "only a newline", id: "\n"},
		{name: "carriage return", id: "tenant\ra"},
		{name: "tab", id: "tenant\ta"},
		{name: "the separator byte of the id recipes", id: "tenant\x1fa"},
		{name: "dot", id: "a.b"},
		{name: "semicolon", id: "a;b"},
		{name: "quote", id: "tenant'a"},
		{name: "backslash", id: `a\b`},
		{name: "accented letter", id: "ténant"},
		{name: "fullwidth letters", id: "ｔｅｎａｎｔ"},
		{name: "64 characters that are 128 bytes", id: strings.Repeat("é", 64)},
		{name: "a digit from another script", id: "tenant٣"},
		{name: "invalid UTF-8", id: "tenant\xff", notText: true},
		{name: "NUL", id: "tenant\x00a", notText: true},
	}
	accepted := 0
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			_, goErr := tenancy.Parse(tc.id)
			verdict := domainVerdict(t, db, tc.id)

			switch verdict {
			case "", "23514":
			case "22021":
				if !tc.notText {
					t.Fatalf("%q: Postgres refused it as text (22021), which only the cases marked notText may be", tc.id)
				}
			default:
				t.Fatalf("%q: SQLSTATE %s, want the domain's verdict", tc.id, verdict)
			}
			if goAccepts, sqlAccepts := goErr == nil, verdict == ""; goAccepts != sqlAccepts {
				t.Errorf("%q: tenancy.Parse accepts=%v, the tenant_id domain accepts=%v (SQLSTATE %q)", tc.id, goAccepts, sqlAccepts, verdict)
			}
			if verdict == "" {
				accepted++
			}
		})
	}
	// Guards the test itself: a domainVerdict that always refused would agree with nothing valid.
	if accepted != 7 {
		t.Errorf("the domain accepted %d of the cases, want exactly the 7 valid ones", accepted)
	}
}

// TestEveryTableForcesRowLevelSecurity guards every future migration: a new table either forces
// row-level security or is named here with a reason. A relation that holds rows but cannot have
// row-level security at all (a materialized view, a foreign table) is refused outright unless it
// is named here: a materialized view over a tenant table would hand every tenant's rows to
// whoever may read it.
func TestEveryTableForcesRowLevelSecurity(t *testing.T) {
	notTenantScoped := map[string]string{
		"goose_db_version": "migration bookkeeping, no tenant data",
	}

	db := open(t, "")
	ctx := testCtx(t)
	err := db.Tx(ctx, func(tx pgx.Tx) error {
		// Every kind of relation that stores or serves rows of its own: tables, partitioned
		// tables, materialized views, foreign tables. Views are left out: they hold nothing, and
		// one owned by the application role reads its tables under that role's forced policies.
		rows, err := tx.Query(ctx, `
			SELECT c.relname, c.relkind::text, c.relrowsecurity, c.relforcerowsecurity,
			       (SELECT count(*) FROM pg_policy p WHERE p.polrelid = c.oid)
			  FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
			 WHERE n.nspname = $1 AND c.relkind IN ('r', 'p', 'm', 'f')`, store.Schema)
		if err != nil {
			return err
		}
		defer rows.Close()
		seen := 0
		for rows.Next() {
			var name, kind string
			var enabled, forced bool
			var policies int
			if err := rows.Scan(&name, &kind, &enabled, &forced, &policies); err != nil {
				return err
			}
			seen++
			if _, ok := notTenantScoped[name]; ok {
				continue
			}
			if kind != "r" && kind != "p" {
				t.Errorf("%s (relkind %q) holds rows but cannot have row-level security: keep tenant data in tables, or name it in notTenantScoped with a reason",
					name, kind)
				continue
			}
			if !enabled || !forced || policies == 0 {
				t.Errorf("table %s: rls enabled=%v forced=%v policies=%d, want enabled, forced, and at least one policy",
					name, enabled, forced, policies)
			}
		}
		if seen < 2 {
			t.Errorf("found %d tables in schema %s, the query is not seeing the schema", seen, store.Schema)
		}
		return rows.Err()
	})
	if err != nil {
		t.Fatal(err)
	}
}

func assertRLSViolation(t *testing.T, err error) {
	t.Helper()
	var pgErr *pgconn.PgError
	if !errors.As(err, &pgErr) || pgErr.Code != "42501" {
		t.Errorf("err = %v, want a row-level security violation (42501)", err)
	}
}

// Package tenancy carries the tenant identity and binds it to a database transaction so row-level
// security applies.
//
// A tenant only ever comes from one of the three trust roots in docs/architecture.md section 4.
// It is never read from a payload.
package tenancy

import (
	"context"
	"errors"
	"fmt"

	"github.com/jackc/pgx/v5"
)

// setting is the transaction-local Postgres setting every row-level security policy reads.
const setting = "lawang.tenant"

const maxIDLen = 64

// ErrInvalidID reports a tenant id that is empty or malformed.
var ErrInvalidID = errors.New("tenancy: invalid tenant id")

// ErrCrossTenantTx reports a Bind on a transaction that runs under a helper role. Binding would
// not narrow such a transaction, so it is refused instead of giving a false sense of isolation.
var ErrCrossTenantTx = errors.New("tenancy: this transaction runs under a cross-tenant helper role and a bind would not narrow it, do the tenant's work in a second transaction under store.TenantTx")

// CrossTenantTx marks a transaction that runs under a helper database role, whose policies admit
// rows of every tenant. store.RoleTx hands out transactions that implement it.
type CrossTenantTx interface {
	pgx.Tx
	CrossTenant()
}

// ID identifies a tenant. The zero value is invalid; build one with Parse.
type ID string

// Parse validates s as a tenant id: 1 to 64 characters of A-Z, a-z, 0-9, underscore and hyphen.
// The tenant_id domain in the database enforces the same rule, and the two are held together by
// TestTheGoRuleAndTheDomainAgree in internal/store: change one and that test names the other.
func Parse(s string) (ID, error) {
	if s == "" || len(s) > maxIDLen {
		return "", ErrInvalidID
	}
	for i := range len(s) {
		c := s[i]
		ok := c >= 'A' && c <= 'Z' || c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '_' || c == '-'
		if !ok {
			return "", ErrInvalidID
		}
	}
	return ID(s), nil
}

// String returns the id as stored.
func (id ID) String() string { return string(id) }

// Bind scopes tx to the tenant. The setting is transaction-local: it is gone at commit or
// rollback, so a pooled connection never carries one tenant into the next transaction. Callers
// outside internal/store want store.TenantTx, which binds before anything else runs.
//
// Binding again inside the same transaction replaces the tenant.
//
// A bind narrows only a transaction of the application role. Under a helper role
// (store.RoleTx) the role's own cross-tenant policies keep applying, because Postgres ORs
// permissive policies together, so Bind refuses such a transaction with ErrCrossTenantTx. The
// worker therefore claims rows in one transaction under its role and does each row's work in a
// second one under store.TenantTx.
func Bind(ctx context.Context, tx pgx.Tx, id ID) error {
	// Re-validate: ID is a string type, so a caller can build one without Parse.
	if _, err := Parse(string(id)); err != nil {
		return err
	}
	if _, ok := tx.(CrossTenantTx); ok {
		return ErrCrossTenantTx
	}
	if _, err := tx.Exec(ctx, "SELECT set_config($1, $2, true)", setting, string(id)); err != nil {
		return fmt.Errorf("tenancy: bind: %w", err)
	}
	return nil
}

package tenancy

import (
	"context"
	"errors"
	"strings"
	"testing"

	"github.com/jackc/pgx/v5"
)

func TestParse(t *testing.T) {
	for _, s := range []string{"tenant_a", "01JZXA8Q2KTENANT0000000000", "a", "A-b_9", strings.Repeat("x", 64)} {
		if id, err := Parse(s); err != nil || id.String() != s {
			t.Errorf("Parse(%q) = %q, %v", s, id, err)
		}
	}
	for _, s := range []string{"", " ", "tenant a", "tenant\x1fa", "tenant'a", "ténant", "a;b", strings.Repeat("x", 65)} {
		if id, err := Parse(s); !errors.Is(err, ErrInvalidID) || id != "" {
			t.Errorf("Parse(%q) = %q, %v, want ErrInvalidID", s, id, err)
		}
	}
}

// markedTx stands in for the transaction store.RoleTx hands out. Its embedded pgx.Tx is nil, so
// reaching the database would panic: the refusal has to come first.
type markedTx struct{ pgx.Tx }

func (markedTx) CrossTenant() {}

func TestBindRefusesACrossTenantTransaction(t *testing.T) {
	if err := Bind(context.Background(), markedTx{}, ID("tenant_a")); !errors.Is(err, ErrCrossTenantTx) {
		t.Errorf("err = %v, want ErrCrossTenantTx", err)
	}
}

func TestBindRefusesAnInvalidIDBeforeTouchingTheDatabase(t *testing.T) {
	// A nil transaction proves the refusal happens first: reaching the database would panic.
	if err := Bind(context.Background(), nil, ID("")); !errors.Is(err, ErrInvalidID) {
		t.Errorf("err = %v, want ErrInvalidID", err)
	}
	if err := Bind(context.Background(), nil, ID("a b")); !errors.Is(err, ErrInvalidID) {
		t.Errorf("err = %v, want ErrInvalidID", err)
	}
}

// Package testdb gives integration tests a real Postgres.
//
// One container is started per test process. Each test gets its own bootstrapped database inside
// it, and connects as the non-superuser application role, because tests that run as a superuser
// pass without row-level security ever applying (docs/architecture.md, principle 12).
//
// Roles, unlike databases, are cluster-wide. A test that changes a role or a membership would
// change it for every other test in the process, so it takes a Postgres of its own from
// NewRawCluster instead of the shared one.
package testdb

import (
	"context"
	"errors"
	"fmt"
	"net/url"
	"os"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/testcontainers/testcontainers-go"
	"github.com/testcontainers/testcontainers-go/modules/postgres"
	"github.com/testcontainers/testcontainers-go/wait"

	"github.com/gablooge/lawang/internal/ids"
	"github.com/gablooge/lawang/migrations"
)

const (
	image       = "postgres:17-alpine"
	appPassword = "lawang_test" //nolint:gosec // a throwaway container that lives as long as the test process
)

var (
	once     sync.Once
	adminURL *url.URL
	startErr error

	// Roles are cluster-wide, so two databases bootstrapping at once would race on CREATE ROLE.
	bootstrapMu sync.Mutex
)

// Database is one test's database.
type Database struct {
	// URL connects as the application role. Use this one.
	URL string
	// AdminURL connects as the superuser, for setup and for proving what a superuser is refused.
	AdminURL string
}

// New returns a fresh database with the bootstrap script applied and no migrations run.
func New(t testing.TB) Database {
	t.Helper()
	db := NewRaw(t)
	Bootstrap(t, db.AdminURL)
	return db
}

// Bootstrap applies the bootstrap script over connURL, as whichever administrator that URL logs
// in as, and gives the application role the password that Database.URL uses.
func Bootstrap(t testing.TB, connURL string) {
	t.Helper()
	if err := TryBootstrap(t, connURL); err != nil {
		t.Fatalf("testdb: bootstrap: %v", err)
	}
	Exec(t, connURL, fmt.Sprintf("ALTER ROLE lawang PASSWORD '%s'", appPassword))
}

// TryBootstrap applies the bootstrap script and returns the server's verdict, for tests that
// expect a refusal.
//
// It uses the extended protocol, which takes exactly one statement. The script promises to apply
// completely or not at all under any client, psql included, which sends statements one by one
// and carries on after an error. That only holds while the script is a single statement, and the
// simple protocol would hide a second one by wrapping the lot in one implicit transaction.
func TryBootstrap(t testing.TB, connURL string) error {
	t.Helper()
	bootstrapMu.Lock()
	defer bootstrapMu.Unlock()
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	conn, err := pgx.Connect(ctx, connURL)
	if err != nil {
		t.Fatalf("testdb: connect: %v", err)
	}
	defer func() { _ = conn.Close(ctx) }()
	_, err = conn.PgConn().ExecParams(ctx, migrations.Bootstrap, nil, nil, nil, nil).Close()
	return err
}

// NewRaw returns a fresh database with nothing in it, not even the bootstrap.
func NewRaw(t testing.TB) Database {
	t.Helper()
	once.Do(start)
	if startErr != nil {
		// A developer without Docker can still run the unit tests. CI may never skip these.
		if os.Getenv("CI") == "" {
			t.Skipf("no Postgres container (is Docker running?): %v", startErr)
		}
		t.Fatalf("no Postgres container: %v", startErr)
	}

	return newDatabase(t, adminURL)
}

// NewRawCluster returns a fresh database, with nothing in it, in a Postgres container of its own
// that is removed when the test ends. It costs a container start, so it is only for tests that
// change cluster-wide state: role attributes, memberships, or who runs the bootstrap. No role
// exists in it yet, not even the application role, until the test calls Bootstrap.
func NewRawCluster(t testing.TB) Database {
	t.Helper()
	once.Do(start)
	if startErr != nil {
		// Same rule as NewRaw. Asking the shared container first keeps the skip in one place.
		if os.Getenv("CI") == "" {
			t.Skipf("no Postgres container (is Docker running?): %v", startErr)
		}
		t.Fatalf("no Postgres container: %v", startErr)
	}

	ctx, cancel := context.WithTimeout(context.Background(), 3*time.Minute)
	defer cancel()
	c, clusterURL, err := run(ctx)
	if c != nil {
		t.Cleanup(func() { _ = testcontainers.TerminateContainer(c) })
	}
	if err != nil {
		t.Fatalf("testdb: private Postgres container: %v", err)
	}
	return newDatabase(t, clusterURL)
}

func newDatabase(t testing.TB, cluster *url.URL) Database {
	t.Helper()
	name := "t_" + strings.ToLower(ids.New())
	Exec(t, cluster.String(), "CREATE DATABASE "+name)

	admin := *cluster
	admin.Path = "/" + name
	app := admin
	app.User = url.UserPassword("lawang", appPassword)
	return Database{URL: app.String(), AdminURL: admin.String()}
}

// As returns connURL with the login replaced, for tests that connect as a role of their own.
func As(t testing.TB, connURL, user, password string) string {
	t.Helper()
	u, err := url.Parse(connURL)
	if err != nil {
		// Not wrapped: the error would quote the URL.
		t.Fatal("testdb: invalid connection URL")
	}
	u.User = url.UserPassword(user, password)
	return u.String()
}

// Exec runs SQL, which may hold several statements, over a one-off connection.
func Exec(t testing.TB, connURL, sql string) {
	t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	conn, err := pgx.Connect(ctx, connURL)
	if err != nil {
		t.Fatalf("testdb: connect: %v", err)
	}
	defer func() { _ = conn.Close(ctx) }()
	// The simple protocol, because the extended one takes a single statement.
	if _, err := conn.PgConn().Exec(ctx, sql).ReadAll(); err != nil {
		t.Fatalf("testdb: exec: %v", err)
	}
}

func start() {
	defer func() {
		// testcontainers panics, rather than returning an error, when it finds no Docker host.
		if r := recover(); r != nil {
			startErr = fmt.Errorf("%v", r)
		}
	}()
	ctx, cancel := context.WithTimeout(context.Background(), 3*time.Minute)
	defer cancel()

	// Not terminated here: the testcontainers reaper removes it when the test process exits.
	_, adminURL, startErr = run(ctx)
}

// run starts one Postgres container and returns the superuser URL of its "postgres" database.
func run(ctx context.Context) (testcontainers.Container, *url.URL, error) {
	c, err := postgres.Run(ctx, image,
		postgres.WithDatabase("postgres"),
		postgres.WithUsername("postgres"),
		postgres.WithPassword("postgres"),
		testcontainers.WithWaitStrategy(
			wait.ForLog("database system is ready to accept connections").
				WithOccurrence(2).WithStartupTimeout(2*time.Minute)),
	)
	if err != nil {
		// A container that started but never became ready is still returned, so it can be removed.
		if c == nil {
			return nil, nil, err
		}
		return c, nil, err
	}
	raw, err := c.ConnectionString(ctx, "sslmode=disable")
	if err != nil {
		return c, nil, err
	}
	u, err := url.Parse(raw)
	if err != nil {
		return c, nil, errors.New("testdb: the container returned an unparsable connection string")
	}
	return c, u, nil
}

-- +goose Up

-- Every tenant-scoped column uses this domain, so an empty or malformed tenant id cannot be stored
-- anywhere. The empty string matters: a transaction-local setting reads back as '' (not NULL) on a
-- pooled connection once its transaction has ended, and no row may ever match that.
CREATE DOMAIN tenant_id AS text
  CHECK (VALUE ~ '^[A-Za-z0-9_-]{1,64}$');

-- The tenant bound to the current transaction, or NULL when none is bound. Every row-level
-- security policy compares against this, and a comparison with NULL matches no rows: a query with
-- no tenant bound fails closed.
-- +goose StatementBegin
CREATE FUNCTION current_tenant() RETURNS text
  LANGUAGE sql STABLE PARALLEL SAFE
AS $$ SELECT NULLIF(current_setting('lawang.tenant', true), '') $$;
-- +goose StatementEnd

CREATE TABLE tenants (
  id         tenant_id   PRIMARY KEY,
  name       text        NOT NULL DEFAULT '',
  created_at timestamptz NOT NULL DEFAULT now()
);

-- FORCE matters as much as ENABLE: the application role owns the table, and an owner is exempt
-- from row-level security unless it is forced.
ALTER TABLE tenants ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenants FORCE ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON tenants
  USING (id = current_tenant())
  WITH CHECK (id = current_tenant());

-- The helper roles can reach the schema, and nothing in it until a later migration grants it.
GRANT USAGE ON SCHEMA lawang TO lawang_resolver, lawang_worker;

-- +goose Down
REVOKE USAGE ON SCHEMA lawang FROM lawang_resolver, lawang_worker;
DROP TABLE tenants;
DROP FUNCTION current_tenant();
DROP DOMAIN tenant_id;

// Package migrations embeds the SQL that defines Lawang's database.
package migrations

import "embed"

// FS holds the goose migrations, applied by "lawang migrate" as the application role.
//
//go:embed *.sql
var FS embed.FS

// Bootstrap is the one-time script an administrator runs before the first migration. It creates
// the three roles and the schema, which the non-superuser application role cannot do for itself.
//
//go:embed bootstrap/roles.sql
var Bootstrap string
